import { Book } from "@/lib/types";

export const genesis: Book = {
  id: "genesis",
  name: "1. Mose",
  shortName: "1.Mose",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Im Anfang schuf Gott den Himmel* und die Erde*.", heading: "Die Schöpfung: Siebentagewerk", footnotes: ["Im Hebr. gibt es das Wort für »Himmel« (schamajim) nur in der Mehrzahl, wie im Deutschen z.B. das Wort »Ferien«.", "℘ 2Kö 19,15; 2Chr 2,11; Ps 8,4; 33,6; 115,15; Jer 10,12.16; Apg 4,24; Hebr 11,3; Offb 4,11"] },
      { number: 2, text: "Und die Erde war wüst* und leer*, und Finsternis war über der* Tiefe*; und der Geist* Gottes schwebte über dem Wasser*.", footnotes: ["o. Wüste, Nichtiges", "w. Öde, Leere\n℘ Jer 4,23", "w. über dem Angesicht der", "o. Flut", "Das hebr. Wort ruach kann auch Hauch, Wind bedeuten.", "w. über dem Angesicht des Wassers. — Im Hebr. gibt es das Wort für »Wasser« (majim) nur in der Mehrzahl, wie im Deutschen z.B. das Wort »Ferien«.\n℘ Ps 104,6; 2Petr 3,5"] },
      { number: 3, text: "Und Gott sprach: Es werde Licht*! Und es wurde Licht.", footnotes: ["℘ Ps 33,9; Jes 45,7; 2Kor 4,6"] },
      { number: 4, text: "Und Gott sah das Licht, dass es gut war; und Gott schied das Licht von der Finsternis*.", footnotes: ["℘ 2Kor 6,14"] },
      { number: 5, text: "Und Gott nannte das Licht Tag, und die Finsternis nannte er Nacht. Und es wurde Abend, und es wurde Morgen: ein Tag." },
      { number: 6, text: "Und Gott sprach: Es werde eine Wölbung* mitten im Wasser, und es sei eine Scheidung zwischen dem Wasser und dem Wasser!", footnotes: ["Das hebr. Wort ist von einem Verbum »feststampfen, breithämmern« abgeleitet und meint eine gehämmerte Platte oder Schale, eine nach allen Seiten ausgeweitete Fläche o. Wölbung.\n℘ Ps 19,2"] },
      { number: 7, text: "Und Gott machte die Wölbung* und schied das Wasser, das unterhalb der Wölbung*, von dem Wasser, das oberhalb der Wölbung* war*. Und es geschah so.", footnotes: ["℘ Ps 19,2", "Das hebr. Wort ist von einem Verbum »feststampfen, breithämmern« abgeleitet und meint eine gehämmerte Platte oder Schale, eine nach allen Seiten ausgeweitete Fläche o. Wölbung.", "Das hebr. Wort ist von einem Verbum »feststampfen, breithämmern« abgeleitet und meint eine gehämmerte Platte oder Schale, eine nach allen Seiten ausgeweitete Fläche o. Wölbung.", "℘ Hi 26,8; Ps 148,4"] },
      { number: 8, text: "Und Gott nannte die Wölbung* Himmel*. Und es wurde Abend, und es wurde Morgen: ein zweiter Tag.", footnotes: ["Das hebr. Wort ist von einem Verbum »feststampfen, breithämmern« abgeleitet und meint eine gehämmerte Platte oder Schale, eine nach allen Seiten ausgeweitete Fläche o. Wölbung.", "℘ Ps 136,5; Sach 12,1"] },
      { number: 9, text: "Und Gott sprach: Es soll sich das Wasser unterhalb des Himmels an einen Ort sammeln, und es werde das Trockene sichtbar!* Und es geschah so.", footnotes: ["℘ Hi 38,8-11; Ps 24,2; 95,5; Spr 8,29; Neh 9,6"] },
      { number: 10, text: "Und Gott nannte das Trockene Erde, und die Ansammlung des Wassers nannte er Meere*. Und Gott sah, dass es gut war.", footnotes: ["℘ Jon 1,9; 2Petr 3,5"] },
      { number: 11, text: "Und Gott sprach: Die Erde lasse Gras hervorsprossen, Kraut, das Samen hervorbringt, Fruchtbäume, die auf der Erde Früchte tragen nach ihrer Art, in denen ihr Same ist*! Und es geschah so.", footnotes: ["℘ Ps 104,14; Jes 61,11"] },
      { number: 12, text: "Und die Erde brachte Gras hervor, Kraut, das Samen hervorbringt nach seiner Art*, und Bäume, die Früchte tragen, in denen ihr Same ist nach ihrer Art. Und Gott sah, dass es gut war.", footnotes: ["℘ 1Kor 15,38.39"] },
      { number: 13, text: "Und es wurde Abend, und es wurde Morgen: ein dritter Tag." },
      { number: 14, text: "Und Gott sprach: Es sollen Lichter an der Wölbung* des Himmels werden*, um zu scheiden zwischen Tag und Nacht, und sie sollen dienen als Zeichen und zur Bestimmung von Zeiten* und Tagen und Jahren*;", footnotes: ["Das hebr. Wort ist von einem Verbum »feststampfen, breithämmern« abgeleitet und meint eine gehämmerte Platte oder Schale, eine nach allen Seiten ausgeweitete Fläche o. Wölbung.", "℘ Jes 40,26", "o. Festzeiten, Festen", "℘ Ps 104,19"] },
      { number: 15, text: "und sie sollen als Lichter an der Wölbung* des Himmels dienen, um auf die Erde zu leuchten! Und es geschah so.", footnotes: ["Das hebr. Wort ist von einem Verbum »feststampfen, breithämmern« abgeleitet und meint eine gehämmerte Platte oder Schale, eine nach allen Seiten ausgeweitete Fläche o. Wölbung."] },
      { number: 16, text: "Und Gott machte die beiden großen Lichter: das größere Licht zur Beherrschung des Tages und das kleinere Licht zur Beherrschung der Nacht und die Sterne*.", footnotes: ["℘ Ps 136,7-9; Jer 31,35"] },
      { number: 17, text: "Und Gott setzte sie an die Wölbung* des Himmels, über die Erde zu leuchten", footnotes: ["Das hebr. Wort ist von einem Verbum »feststampfen, breithämmern« abgeleitet und meint eine gehämmerte Platte oder Schale, eine nach allen Seiten ausgeweitete Fläche o. Wölbung."] },
      { number: 18, text: "und zu herrschen über den Tag und über die Nacht und zwischen dem Licht und der Finsternis zu scheiden. Und Gott sah, dass es gut war." },
      { number: 19, text: "Und es wurde Abend, und es wurde Morgen: ein vierter Tag." },
      { number: 20, text: "Und Gott sprach: Es soll das Wasser vom Gewimmel lebender Wesen* wimmeln*, und Vögel sollen über der Erde fliegen unter der Wölbung* des Himmels!", footnotes: ["o. Seelen", "℘ Ps 104,25", "w. auf dem Angesicht der Wölbung"] },
      { number: 21, text: "Und Gott schuf die großen Seeungeheuer* und alle sich regenden lebenden Wesen*, von denen das Wasser wimmelt, nach ihrer Art*, und alle geflügelten Vögel, nach ihrer Art*. Und Gott sah, dass es gut war.", footnotes: ["℘ Ps 148,7", "o. Seelen", "℘ Ps 104,25", "℘ Kap. 2,19; Hi 12,7-9"] },
      { number: 22, text: "Und Gott segnete sie und sprach: Seid fruchtbar und vermehrt euch, und füllt das Wasser in den Meeren, und die Vögel sollen sich vermehren auf der Erde!*", footnotes: ["℘ Kap. 8,17"] },
      { number: 23, text: "Und es wurde Abend, und es wurde Morgen: ein fünfter Tag." },
      { number: 24, text: "Und Gott sprach: Die Erde bringe lebende Wesen* hervor nach ihrer Art: Vieh und kriechende Tiere und wilde Tiere der Erde nach ihrer Art! Und es geschah so.", footnotes: ["o. Seelen"] },
      { number: 25, text: "Und Gott machte die wilden Tiere der Erde nach ihrer Art und das Vieh nach seiner Art und alle kriechenden Tiere auf dem Erdboden nach ihrer Art*. Und Gott sah, dass es gut war.", footnotes: ["℘ Kap. 2,19; Hi 12,7-9"] },
      { number: 26, text: "Und Gott sprach: Lasst uns* Menschen* machen in unserm Bild, uns ähnlich*! Sie sollen herrschen über die Fische des Meeres und über die Vögel des Himmels und über das Vieh und über die ganze Erde* und über alle kriechenden Tiere, die auf der Erde kriechen*!", footnotes: ["℘ Kap. 11,7", "hebr. adam; d. h. von der Erde (adama = Erdboden)", "w. nach unserem Abbild o. Aussehen", "Die syr. Üs. liest mit V. 24f: und über alle Tiere der Erde", "℘ Kap. 9,2"] },
      { number: 27, text: "Und Gott schuf den Menschen* nach seinem Bild, nach dem Bild Gottes schuf er ihn*; als Mann und Frau* schuf er sie*.", footnotes: ["℘ Kap. 2,7; Lk 3,38", "℘ Kap. 5,1; 9,6; 1Kor 11,7; Kol 3,10; Jak 3,9", "w. männlich und weiblich", "℘ Kap. 5,2; Mt 19,4; Mk 10,6; Apg 17,29"] },
      { number: 28, text: "Und Gott segnete sie, und Gott sprach zu ihnen: Seid fruchtbar und vermehrt euch, und füllt die Erde*, und macht sie euch untertan; und herrscht über die Fische des Meeres und über die Vögel des Himmels und über alle Tiere, die sich auf der Erde regen*!", footnotes: ["℘ Kap. 6,1; 9,1", "℘ Ps 8,7-9; 115,16"] },
      { number: 29, text: "Und Gott sprach: Siehe, ich habe euch alles Samen tragende Kraut gegeben, das auf der Fläche der ganzen Erde ist, und jeden Baum, an dem Samen tragende Baumfrucht ist: es soll euch zur Nahrung dienen*;", footnotes: ["℘ Kap. 2,16; 9,3; Ps 104,14"] },
      { number: 30, text: "aber allen Tieren der Erde und allen Vögeln des Himmels und allem, was sich auf der Erde regt, in dem eine lebende Seele ist, habe ich alles grüne Kraut zur Speise gegeben*. Und es geschah so.", footnotes: ["℘ Kap. 6,21"] },
      { number: 31, text: "Und Gott sah alles, was er gemacht hatte, und siehe, es war sehr gut*. Und es wurde Abend, und es wurde Morgen: der sechste Tag*.", footnotes: ["℘ 5Mo 32,4; Pred 3,11; 1Tim 4,4", "℘ 2Mo 20,11"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "So wurden der Himmel und die Erde und all ihr Heer vollendet*.", footnotes: ["℘ Neh 9,6"] },
      { number: 2, text: "Und Gott vollendete am siebten Tag sein Werk*, das er gemacht hatte; und er ruhte am siebten Tag von all seinem Werk, das er gemacht hatte*.", footnotes: ["o. hatte am siebten Tag sein Werk vollendet", "℘ Hebr 4,4.10"] },
      { number: 3, text: "Und Gott segnete den siebten Tag und heiligte ihn; denn an ihm ruhte er von all seinem Werk, das Gott geschaffen hatte, indem er es machte*.", footnotes: ["℘ Kap. 1,31"] },
      { number: 4, text: "Dies ist die Entstehungsgeschichte* des Himmels und der Erde, als sie geschaffen wurden.An dem Tag, als Gott, der HERR, Erde und Himmel machte", heading: "Der Mensch im Garten Eden", footnotes: ["hebr. toledot; d. h. w. Erzeugungen; es bedeutet im AT Nachkommen, Generationenfolge, Entstehungsgeschichte"] },
      { number: 5, text: "— noch war all das Gesträuch des Feldes nicht auf der Erde, und noch war all das Kraut des Feldes nicht gesprosst, denn Gott, der HERR, hatte es noch nicht auf die Erde regnen lassen, und noch gab es keinen Menschen, den Erdboden zu bebauen;" },
      { number: 6, text: "ein Dunst* aber stieg von der Erde auf* und bewässerte die ganze Oberfläche des Erdbodens", footnotes: ["o. ein Grundwasser, unterirdischer Quellstrom; LXX: eine Quelle", "℘ Ps 135,7"] },
      { number: 7, text: "—, da bildete Gott, der HERR, den Menschen*, aus Staub vom Erdboden* und hauchte in seine Nase Atem des Lebens*; so wurde der Mensch eine lebende Seele*.", footnotes: ["℘ Kap. 1,27", "℘ Kap. 3,19.23; 1Kor 15,47", "℘ Hi 33,4; Sach 12,1; Apg 17,25", "℘ Hes 37,5.6; 1Kor 15,45"] },
      { number: 8, text: "Und Gott, der HERR, pflanzte einen Garten in Eden* im Osten, und er setzte dorthin den Menschen, den er gebildet hatte.", footnotes: ["d. h. Wonne\n℘ Kap. 3,23; Hes 28,13; Joe 2,3"] },
      { number: 9, text: "Und Gott, der HERR, ließ aus dem Erdboden allerlei Bäume wachsen, begehrenswert anzusehen und gut zur Nahrung, und den Baum des Lebens* in der Mitte des Gartens, und den Baum der Erkenntnis des Guten und Bösen*.", footnotes: ["℘ Kap. 3,22; Offb 2,7", "℘ Kap. 3,5"] },
      { number: 10, text: "Und ein Strom geht von Eden* aus, den Garten zu bewässern; und von dort aus teilt er sich und wird zu vier Armen*.", footnotes: ["d. h. Wonne", "w. Häuptern, Abteilungen"] },
      { number: 11, text: "Der Name des ersten ist Pischon; der fließt um das ganze Land Hawila, wo das Gold ist;" },
      { number: 12, text: "und das Gold dieses Landes ist gut; dort gibt es Bedolach-Harz* und den Schoham-Stein*.", footnotes: ["ein wohlriechendes, gelbliches und durchscheinendes Harz\n℘ 4Mo 11,7", "d. i. Onyx, o. Karneol\n℘ 2Mo 25,7"] },
      { number: 13, text: "Und der Name des zweiten Flusses ist Gihon; der fließt um das ganze Land Kusch*.", footnotes: ["℘ Kap. 10,6-8"] },
      { number: 14, text: "Und der Name des dritten Flusses ist Hiddekel*; der fließt gegenüber von* Assur. Und der vierte Fluss, das ist der Euphrat*.", footnotes: ["d. i. der Tigris\n℘ Dan 10,4", "o. östlich von", "℘ Kap. 15,18"] },
      { number: 15, text: "Und Gott, der HERR, nahm den Menschen und setzte ihn in den Garten Eden, ihn zu bebauen und ihn zu bewahren." },
      { number: 16, text: "Und Gott, der HERR, gebot dem Menschen und sprach: Von jedem Baum des Gartens darfst du essen*;", footnotes: ["℘ Kap. 1,29"] },
      { number: 17, text: "aber vom Baum der Erkenntnis des Guten und Bösen, davon darfst du nicht essen; denn an dem Tag, da du davon isst, musst du sterben!*", footnotes: ["℘ Kap. 3,3; Röm 5,12; 1Kor 15,21"] },
      { number: 18, text: "Und Gott, der HERR, sprach: Es ist nicht gut, dass der Mensch allein sei*; ich will ihm eine Hilfe machen, die ihm entspricht*.", footnotes: ["℘ Pred 4,9", "o. als sein Gegenüber; w. wie seine Entsprechung\n℘ 1Kor 11,9"] },
      { number: 19, text: "Und Gott, der HERR, bildete aus dem Erdboden alle Tiere des Feldes und alle Vögel des Himmels*, und er brachte sie zu dem Menschen, um zu sehen, wie er sie nennen würde; und genau so wie der Mensch sie, die lebenden Wesen*, nennen würde, so sollte ihr Name sein.", footnotes: ["℘ Kap. 1,25", "o. Seelen"] },
      { number: 20, text: "Und der Mensch gab Namen allem Vieh und den Vögeln des Himmels und allen Tieren des Feldes. Aber für Adam* fand er keine Hilfe, ihm entsprechend*.", footnotes: ["o. für einen Menschen", "o. als sein Gegenüber; w. wie seine Entsprechung"] },
      { number: 21, text: "Da ließ Gott, der HERR, einen tiefen Schlaf auf den Menschen fallen*, so dass er einschlief. Und er nahm eine von seinen Rippen und verschloss ihre Stelle mit Fleisch;", footnotes: ["℘ Kap. 15,12; 1Sam 26,12"] },
      { number: 22, text: "und Gott, der HERR, baute die Rippe, die er von dem Menschen genommen hatte, zu einer Frau*, und er brachte sie zum Menschen.", footnotes: ["℘ 1Tim 2,13"] },
      { number: 23, text: "Da sagte der Mensch: Diese endlich ist Gebein von meinem Gebein und Fleisch von meinem Fleisch; diese soll Männin* heißen, denn vom Mann ist sie genommen*.", footnotes: ["dasselbe Wort wie Frau in V. 22 und 24; im Hebr. ist das Wort für »Frau« durch Anhängen der weiblichen Endung an das für »Mann« gebildet", "℘ 1Kor 11,8"] },
      { number: 24, text: "Darum wird ein Mann seinen Vater und seine Mutter verlassen und seiner Frau anhängen, und sie werden zu einem Fleisch werden*.", footnotes: ["℘ Mt 19,4.5; 1Kor 6,16; Eph 5,31"] },
      { number: 25, text: "Und sie waren beide nackt, der Mensch und seine Frau, und sie schämten sich nicht*.", footnotes: ["℘ Kap. 3,7"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und die Schlange* war listiger als alle Tiere des Feldes, die Gott, der HERR, gemacht hatte; und sie sprach zu der Frau*: Hat Gott wirklich gesagt: Von allen Bäumen* des Gartens dürft ihr nicht essen?", heading: "Der Sündenfall und dessen Folgen", footnotes: ["℘ Offb 12,9; 20,2", "℘ Mt 4,3", "d. h. von keinem einzigen Baum"] },
      { number: 2, text: "Da sagte die Frau zur Schlange: Von den Früchten der Bäume des Gartens essen wir;" },
      { number: 3, text: "aber von den Früchten des Baumes, der in der Mitte des Gartens steht, hat Gott gesagt: Ihr sollt nicht davon essen und sollt sie nicht berühren, damit ihr nicht sterbt!*", footnotes: ["℘ Kap. 2,17"] },
      { number: 4, text: "Da sagte die Schlange zur Frau: Keineswegs werdet ihr sterben!" },
      { number: 5, text: "Sondern Gott weiß, dass an dem Tag, da ihr davon esst, eure Augen aufgetan werden und ihr sein werdet wie Gott*, erkennend Gutes und Böses*.", footnotes: ["℘ Jes 14,14", "℘ Kap. 2,9; Joh 8,44"] },
      { number: 6, text: "Und die Frau sah, dass der Baum gut zur Speise und dass er eine Lust für die Augen* und dass der Baum begehrenswert war*, Einsicht zu geben; und sie nahm von seiner Frucht und aß, und sie gab auch ihrem Mann bei ihr, und er aß*.", footnotes: ["℘ Jak 1,14.15; 1Jo 2,16", "℘ Jos 7,21", "℘ 1Kö 13,19; Röm 5,12; 2Kor 11,3; 1Tim 2,14; Jak 1,15"] },
      { number: 7, text: "Da wurden ihrer beider Augen aufgetan, und sie erkannten, dass sie nackt waren*; und sie hefteten Feigenblätter zusammen und machten sich Schurze.", footnotes: ["℘ Kap. 2,25"] },
      { number: 8, text: "Und sie hörten die Stimme* Gottes, des HERRN, der im Garten wandelte bei der Kühle des Tages*. Da versteckten sich der Mensch und seine Frau vor dem Angesicht Gottes, des HERRN, mitten zwischen den Bäumen des Gartens*.", footnotes: ["o. das Geräusch", "w. beim Wind des Tages", "℘ Hi 31,33"] },
      { number: 9, text: "Und Gott, der HERR, rief den Menschen und sprach zu ihm: Wo bist du?*", footnotes: ["℘ Kap. 4,9; 2Kö 5,25"] },
      { number: 10, text: "Da sagte er: Ich hörte deine Stimme* im Garten, und ich fürchtete mich, weil ich nackt bin*, und ich versteckte mich.", footnotes: ["o. dein Geräusch", "℘ Offb 16,15"] },
      { number: 11, text: "Und er sprach: Wer hat dir erzählt, dass du nackt bist? Hast du etwa von dem Baum gegessen, von dem ich dir geboten habe, du solltest nicht davon essen?" },
      { number: 12, text: "Da sagte der Mensch: Die Frau, die du mir zur Seite gegeben hast, sie gab mir* von dem Baum, und ich aß.", footnotes: ["℘ 1Sam 15,15.21"] },
      { number: 13, text: "Und Gott, der HERR, sprach zur Frau: Was hast du da getan*! Und die Frau sagte: Die Schlange hat mich getäuscht*, da aß ich.", footnotes: ["℘ Kap. 12,18; Jon 1,10", "o. betrogen, verführt\n℘ 1Kö 13,18; Joh 8,44; Röm 7,11"] },
      { number: 14, text: "Und Gott, der HERR, sprach zur Schlange: Weil du das getan hast, sollst du verflucht sein unter allem Vieh und unter* allen Tieren des Feldes! Auf deinem Bauch sollst du kriechen, und Staub sollst du fressen alle Tage deines Lebens!*", footnotes: ["w. aus . . . heraus", "℘ Ps 72,9; Jes 65,25; Mi 7,17"] },
      { number: 15, text: "Und ich werde Feindschaft setzen zwischen dir und der Frau, zwischen deinem Samen und ihrem Samen*; er wird dir den Kopf zermalmen, und du, du wirst ihm die Ferse zermalmen*.", footnotes: ["℘ Offb 12,17", "℘ Joh 5,46; Hebr 2,14"] },
      { number: 16, text: "Zu der Frau sprach er: Ich werde sehr vermehren die Mühsal deiner Schwangerschaft*, mit Schmerzen sollst du Kinder gebären!* Nach deinem Mann wird dein Verlangen sein, er aber wird über dich herrschen!*", footnotes: ["w. Überaus zahlreich werde ich deine Beschwerden und deine Schwangerschaft machen", "℘ Kap. 35,16.17; 1Chr 4,9; Jes 26,17; 1Tim 2,15", "℘ 1Kor 11,3; 14,34"] },
      { number: 17, text: "Und zu Adam* sprach er: Weil du auf die Stimme deiner Frau gehört und gegessen hast von dem Baum, von dem ich dir geboten habe: Du sollst davon nicht essen! — so sei der Erdboden deinetwegen verflucht*: Mit Mühsal sollst du davon essen alle Tage deines Lebens*;", footnotes: ["o. zum Menschen", "℘ Kap. 5,29", "℘ Hi 5,7"] },
      { number: 18, text: "und Dornen und Disteln wird er dir sprossen lassen*, und du wirst das Kraut des Feldes essen*!", footnotes: ["℘ Hi 31,40; Jes 7,23.24; Röm 8,20; Hebr 6,8", "℘ 2Thes 3,10"] },
      { number: 19, text: "Im Schweiße deines Angesichts wirst du dein Brot essen, bis du zurückkehrst zum Erdboden*, denn von ihm bist du genommen. Denn Staub bist du, und zum Staub wirst du zurückkehren!*", footnotes: ["s. erste Anm. zu Kap. 1,26", "℘ Kap. 2,7; 5,5; Hi 10,9; Ps 90,3; Pred 3,20; Hebr 9,27"] },
      { number: 20, text: "Und der Mensch gab seiner Frau den Namen Eva, denn sie wurde die Mutter aller Lebenden*.", footnotes: ["℘ Apg 17,26"] },
      { number: 21, text: "Und Gott, der HERR, machte Adam und seiner Frau Leibröcke aus Fell und bekleidete sie." },
      { number: 22, text: "Und Gott, der HERR, sprach: Siehe, der Mensch ist geworden wie einer von uns, zu erkennen Gutes und Böses. Und nun, dass er nicht etwa seine Hand ausstrecke und auch noch von dem Baum des Lebens* nehme und esse und ewig lebe!", footnotes: ["℘ Kap. 2,9"] },
      { number: 23, text: "Und Gott, der HERR, schickte ihn aus dem Garten Eden* hinaus, den Erdboden zu bebauen*, von dem er genommen war*.", footnotes: ["℘ Kap. 2,8", "℘ Kap. 4,2", "℘ Kap. 2,7"] },
      { number: 24, text: "Und er trieb den Menschen aus und ließ östlich vom Garten Eden die Cherubim sich lagern und die Flamme des zuckenden Schwertes, den Weg zum Baum des Lebens zu bewachen." },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und der Mensch erkannte seine Frau Eva, und sie wurde schwanger und gebar Kain*; und sie sagte: Ich habe einen Mann hervorgebracht* mit dem HERRN*.", heading: "Kain und Abel", footnotes: ["d. h. so viel wie Erworbenes, Gewinn", "o. erworben", "℘ Ps 127,3"] },
      { number: 2, text: "Und sie gebar noch einmal, und zwar seinen Bruder, den Abel*. Und Abel wurde ein Schafhirt, Kain aber wurde ein Ackerbauer*.", footnotes: ["hebr. hevel; d. h. Hauch, Nichtigkeit", "℘ Kap. 3,23; 9,20"] },
      { number: 3, text: "Und es geschah nach einiger Zeit, da brachte Kain von den Früchten des Ackerbodens dem HERRN eine Opfergabe." },
      { number: 4, text: "Und Abel, auch er brachte von den Erstlingen seiner Herde und von ihrem Fett*. Und der HERR blickte auf Abel und auf seine Opfergabe*;", footnotes: ["℘ 3Mo 3,16", "℘ Hebr 11,4"] },
      { number: 5, text: "aber auf Kain und auf seine Opfergabe blickte er nicht. Da wurde Kain sehr zornig*, und sein Gesicht senkte sich.", footnotes: ["℘ Spr 19,3; Pred 4,4"] },
      { number: 6, text: "Und der HERR sprach zu Kain: Warum bist du zornig, und warum hat sich dein Gesicht gesenkt?*", footnotes: ["℘ Jon 4,4"] },
      { number: 7, text: "Ist es nicht so, wenn du recht tust, erhebt es sich*? Wenn du aber nicht recht tust, lagert die Sünde vor der Tür. Und nach dir wird ihr Verlangen sein, du aber sollst über sie herrschen.*", footnotes: ["w. Ist nicht, wenn du recht tust, Erhebung; vgl. Hi 11,15", "w. Wenn du aber nicht recht tust, lagert er — die Sünde — zur Tür hin. Und nach dir wird sein Verlangen sein, du aber sollst über ihn herrschen. — Der Wechsel des Geschlechts (Sünde — er) ist nicht befriedigend zu erklären.\n℘ Röm 6,12"] },
      { number: 8, text: "Und Kain sprach zu seinem Bruder Abel*. Und es geschah, als sie auf dem Feld waren, da erhob sich Kain gegen seinen Bruder Abel und erschlug ihn*.", footnotes: ["SamPent, LXX, syr. und die alte lat. Üs. lesen hier noch: Lass uns aufs Feld gehen!", "℘ Mt 23,35; 1Jo 3,12; Jud 11"] },
      { number: 9, text: "Und der HERR sprach zu Kain: Wo ist dein Bruder Abel*? Und er sagte: Ich weiß* nicht. Bin ich meines Bruders Hüter?*", footnotes: ["℘ Kap. 3,9", "o. erkenne", "℘ Kap. 37,26"] },
      { number: 10, text: "Und er sprach: Was hast du getan!* Horch! Das Blut* deines Bruders schreit zu mir vom Ackerboden her*.", footnotes: ["℘ 1Sam 13,11", "w. Die Stimme des Blutes", "℘ 2Chr 28,9; Hi 24,12; Ps 9,13; Lk 11,51; Hebr 12,24; Jak 5,4"] },
      { number: 11, text: "Und nun, verflucht seist du von dem Ackerboden hinweg, der seinen Mund aufgerissen hat, das Blut deines Bruders von deiner Hand zu empfangen!" },
      { number: 12, text: "Wenn du den Ackerboden bebaust, soll er dir nicht länger seine Kraft geben*; unstet und flüchtig sollst du sein auf der Erde*!", footnotes: ["℘ 3Mo 26,20; Ps 107,34", "℘ Spr 28,17"] },
      { number: 13, text: "Da sagte Kain zu dem HERRN: Zu groß ist meine Strafe*, als dass ich sie tragen könnte.", footnotes: ["o. Schuld"] },
      { number: 14, text: "Siehe, du hast mich heute von der Fläche des Ackerbodens vertrieben, und vor deinem Angesicht muss ich mich verbergen und werde unstet und flüchtig sein auf der Erde; und es wird geschehen: jeder, der mich findet, wird mich erschlagen*.", footnotes: ["℘ Hi 15,20-22"] },
      { number: 15, text: "Der HERR aber sprach zu ihm: Nicht so*, jeder, der Kain erschlägt — siebenfach soll er gerächt werden! Und der HERR machte an Kain ein Zeichen, damit ihn nicht jeder erschlüge, der ihn fände.", footnotes: ["so mit LXX, Vulg., der syr. und anderen alten Üs.; Mas. T.: Darum"] },
      { number: 16, text: "So ging Kain weg vom Angesicht des HERRN und wohnte im Land Nod*, östlich von Eden.", footnotes: ["d. h. Land der Heimatlosigkeit"] },
      { number: 17, text: "Und Kain erkannte seine Frau, und sie wurde schwanger und gebar Henoch. Und er wurde der Erbauer einer Stadt und benannte die Stadt nach dem Namen seines Sohnes Henoch*.", heading: "Nachkommenschaft Kains — Sets Geburt und Nachkomme", footnotes: ["℘ Ps 49,12"] },
      { number: 18, text: "Dem Henoch aber wurde Irad geboren; und Irad zeugte Mehujaël, und Mehujaël zeugte Metuschaël, und Metuschaël zeugte Lamech." },
      { number: 19, text: "Lamech aber nahm sich zwei Frauen; der Name der einen war Ada und der Name der andern Zilla." },
      { number: 20, text: "Und Ada gebar Jabal; dieser wurde der Vater derer, die in Zelten und unter Herden wohnen." },
      { number: 21, text: "Und der Name seines Bruders war Jubal; dieser wurde der Vater all derer, die mit der Zither und der Flöte umgehen." },
      { number: 22, text: "Und Zilla, auch sie gebar, und zwar den Tubal-Kain, den Vater all derer, die Kupfer und Eisen schmieden*. Und die Schwester Tubal-Kains war Naama.", footnotes: ["so mit einer aram. Üs.; Mas. T.: den Hämmernden jedes Arbeiters in Kupfer und Eisen"] },
      { number: 23, text: "Und Lamech sprach zu seinen Frauen: Ada und Zilla, hört meine Stimme! Frauen Lamechs, horcht auf meine Rede! Fürwahr, einen Mann erschlug ich für meine Wunde und einen Knaben für meine Strieme." },
      { number: 24, text: "Wenn Kain siebenfach gerächt wird, so Lamech siebenundsiebzigfach." },
      { number: 25, text: "Und Adam erkannte noch einmal seine Frau, und sie gebar einen Sohn und gab ihm den Namen Set*: Denn Gott hat mir einen anderen Nachkommen* gesetzt anstelle Abels, weil Kain ihn erschlagen hat.", footnotes: ["hebr. schet; d. h. Ersatz\n℘ Kap. 5,3.6; Lk 3,38", "w. Samen"] },
      { number: 26, text: "Und dem Set, auch ihm wurde ein Sohn geboren, und er gab ihm den Namen Enosch*. Damals fing man an, den Namen des HERRN anzurufen*.", footnotes: ["d. h. Mensch. — Das Wort steht häufig im Zusammenhang mit der Hinfälligkeit des Menschen.", "℘ Kap. 12,8"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Dies ist das Buch der Generationenfolge* Adams*. An dem Tag, als Gott Adam schuf, machte er ihn Gott ähnlich*.", heading: "Stammbaum von Adam bis Noah", footnotes: ["℘ V. 3-32: 1Chr 1,1-4; Lk 3,36-38", "hebr. toledot; d. h. w. Erzeugungen; bedeutet im AT Nachkommen, Generationenfolge, Entstehung, Entstehungsgeschichte", "℘ Mt 1,1", "w. nach dem Abbild Gottes, o. nach dem Aussehen Gottes\n℘ Kap. 1,27"] },
      { number: 2, text: "Als Mann und Frau* schuf er sie*, und er segnete sie und gab ihnen den Namen Mensch*, an dem Tag, als sie geschaffen wurden. —", footnotes: ["w. Männlich und weiblich", "℘ Kap. 1,27", "hebr. adam; d. h. von der Erde (adama = Erdboden)"] },
      { number: 3, text: "Und Adam lebte 130 Jahre und zeugte einen Sohn ihm ähnlich*, nach seinem Bild*, und gab ihm den Namen Set*.", footnotes: ["w. nach seinem Abbild", "℘ 1Kor 15,49", "℘ Kap. 4,25.26"] },
      { number: 4, text: "Und die Tage Adams, nachdem er Set gezeugt hatte, betrugen 800 Jahre, und er zeugte Söhne und Töchter." },
      { number: 5, text: "Und alle Tage Adams, die er lebte, betrugen 930 Jahre, dann starb er*. —", footnotes: ["℘ Kap. 3,19"] },
      { number: 6, text: "Und Set lebte 105 Jahre und zeugte Enosch*.", footnotes: ["℘ Kap. 4,25.26"] },
      { number: 7, text: "Und Set lebte, nachdem er Enosch gezeugt hatte, 807 Jahre und zeugte Söhne und Töchter." },
      { number: 8, text: "Und alle Tage Sets betrugen 912 Jahre, dann starb er. —" },
      { number: 9, text: "Und Enosch lebte 90 Jahre und zeugte Kenan." },
      { number: 10, text: "Und Enosch lebte, nachdem er Kenan gezeugt hatte, 815 Jahre und zeugte Söhne und Töchter." },
      { number: 11, text: "Und alle Tage von Enosch betrugen 905 Jahre, dann starb er. —" },
      { number: 12, text: "Und Kenan lebte 70 Jahre und zeugte Mahalalel." },
      { number: 13, text: "Und Kenan lebte, nachdem er Mahalalel gezeugt hatte, 840 Jahre und zeugte Söhne und Töchter." },
      { number: 14, text: "Und alle Tage Kenans betrugen 910 Jahre, dann starb er. —" },
      { number: 15, text: "Und Mahalalel lebte 65 Jahre und zeugte Jered." },
      { number: 16, text: "Und Mahalalel lebte, nachdem er Jered gezeugt hatte, 830 Jahre und zeugte Söhne und Töchter." },
      { number: 17, text: "Und alle Tage Mahalalels betrugen 895 Jahre, dann starb er. —" },
      { number: 18, text: "Und Jered lebte 162 Jahre und zeugte Henoch*.", footnotes: ["hebr. chanok; d. h. eingeweiht\n℘ Jud 14"] },
      { number: 19, text: "Und Jered lebte, nachdem er Henoch gezeugt hatte, 800 Jahre und zeugte Söhne und Töchter." },
      { number: 20, text: "Und alle Tage Jereds betrugen 962 Jahre, dann starb er. —" },
      { number: 21, text: "Und Henoch* lebte 65 Jahre und zeugte Metuschelach.", footnotes: ["hebr. chanok; d. h. eingeweiht"] },
      { number: 22, text: "Und Henoch wandelte* mit Gott*, nachdem er Metuschelach gezeugt hatte, 300 Jahre und zeugte Söhne und Töchter.", footnotes: ["o. ging beständig", "℘ Kap. 6,9; Mal 2,6"] },
      { number: 23, text: "Und alle Tage Henochs betrugen 365 Jahre." },
      { number: 24, text: "Und Henoch wandelte* mit Gott; und er war nicht mehr da, denn Gott nahm ihn hinweg*. —", footnotes: ["o. ging beständig", "℘ 2Kö 2,12; Hebr 11,5"] },
      { number: 25, text: "Und Metuschelach lebte 187 Jahre und zeugte Lamech." },
      { number: 26, text: "Und Metuschelach lebte, nachdem er Lamech gezeugt hatte, 782 Jahre und zeugte Söhne und Töchter." },
      { number: 27, text: "Und alle Tage Metuschelachs betrugen 969 Jahre, dann starb er. —" },
      { number: 28, text: "Und Lamech lebte 182 Jahre und zeugte einen Sohn." },
      { number: 29, text: "Und er gab ihm den Namen Noah, indem er sagte: Dieser wird uns trösten über unserer Arbeit und über* der Mühsal unserer Hände von dem Erdboden, den der HERR verflucht hat*.", footnotes: ["LXX: Dieser wird uns Erquickung schaffen von unserer Arbeit und von", "℘ Kap. 3,17"] },
      { number: 30, text: "Und Lamech lebte, nachdem er Noah gezeugt hatte, 595 Jahre und zeugte Söhne und Töchter." },
      { number: 31, text: "Und alle Tage Lamechs betrugen 777 Jahre, dann starb er. —" },
      { number: 32, text: "Und Noah war 500 Jahre alt; und Noah zeugte Sem, Ham und Jafet*.", footnotes: ["℘ Kap. 6,10; 7,13; 9,18; 10,1"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und es geschah, als die Menschen begannen, sich zu vermehren auf der Fläche des Erdbodens*, und ihnen Töchter geboren wurden,", heading: "Die Riesen — Gottes Entschluss zur Vernichtung der Kreatur", footnotes: ["℘ Kap. 1,28"] },
      { number: 2, text: "da sahen die Söhne Gottes* die Töchter der Menschen, dass sie gut waren*, und sie nahmen sich von ihnen allen zu Frauen, welche sie wollten*.", footnotes: ["℘ Hi 1,6", "℘ Kap. 12,11", "w. sich erwählten"] },
      { number: 3, text: "Da sprach der HERR: Mein Geist soll nicht ewig im Menschen bleiben*, *da er ja auch Fleisch ist*. Seine Tage sollen 120 Jahre betragen.", footnotes: ["so mit LXX; die Bedeutung des Wortes im Mas. T. ist nicht geklärt", "o. wegen ihrer Verfehlungen; er ist ja Fleisch", "o. wegen ihrer Verfehlungen; er ist ja Fleisch\n℘ Ps 78,39; 90,10; Röm 7,14"] },
      { number: 4, text: "In jenen Tagen waren die Riesen* auf der Erde, und auch danach, als die Söhne Gottes zu den Töchtern der Menschen eingingen* und sie ihnen Kinder gebaren. Das sind die Helden, die in der Vorzeit waren, die berühmten Männer.", footnotes: ["℘ 4Mo 13,33; 5Mo 2,11", "℘ Jud 6"] },
      { number: 5, text: "Und der HERR sah, dass die Bosheit des Menschen auf der Erde groß war und alles Sinnen der Gedanken seines Herzens nur böse den ganzen Tag*.", footnotes: ["℘ Kap. 8,21; Pred 9,3; Jer 17,9; Mt 7,11; 15,19; Röm 7,18"] },
      { number: 6, text: "Und es reute den HERRN*, dass er den Menschen auf der Erde gemacht hatte, und es bekümmerte ihn in sein Herz hinein.", footnotes: ["℘ 2Mo 32,14; 1Sam 15,11.35"] },
      { number: 7, text: "Und der HERR sprach: Ich will den Menschen, den ich geschaffen habe, von der Fläche des Erdbodens auslöschen*, vom Menschen bis zum Vieh, bis zu den kriechenden Tieren und bis zu den Vögeln des Himmels; denn es reut mich, dass ich sie gemacht habe*.", footnotes: ["o. wegwischen", "℘ Jes 27,11; Zef 1,3"] },
      { number: 8, text: "Noah aber fand Gunst in den Augen des HERRN*.", footnotes: ["℘ Kap. 19,19; Apg 7,46"] },
      { number: 9, text: "Dies ist die Generationenfolge* Noahs: Noah war ein gerechter Mann*, untadelig war er unter seinen Zeitgenossen*; Noah lebte* mit Gott*.", heading: "Ankündigung der Sintflut — Bau der Arche", footnotes: ["s. Anm. zu Kap. 5,1", "℘ Kap. 17,1; Hi 1,1", "w. Generationen\n℘ Kap. 7,1", "o. ging beständig", "℘ Kap. 5,22"] },
      { number: 10, text: "Und Noah zeugte drei Söhne: Sem, Ham und Jafet*.", footnotes: ["℘ Kap. 5,32"] },
      { number: 11, text: "Die Erde aber war verdorben vor Gott, und die Erde war erfüllt mit Gewalttat." },
      { number: 12, text: "Und Gott sah die Erde*, und siehe, sie war verdorben; denn alles Fleisch hatte seinen Weg verdorben auf Erden*.", footnotes: ["℘ Kap. 18,20.21; Ps 33,13.14", "℘ Hi 22,15; Ps 14,2.3; Mt 24,37; Röm 3,12"] },
      { number: 13, text: "Da sprach Gott zu Noah: Das Ende alles Fleisches ist vor mich gekommen*; denn die Erde ist durch sie erfüllt von Gewalttat; und siehe, ich will sie verderben mit der Erde.", footnotes: ["℘ Am 8,2"] },
      { number: 14, text: "Mache dir eine Arche aus Goferholz; mit Zellen* sollst du die Arche machen und sie von innen und von außen mit Pech verpichen!", footnotes: ["w. mit Nestern"] },
      { number: 15, text: "Und so sollst du sie machen: Dreihundert Ellen sei die Länge der Arche, fünfzig Ellen ihre Breite und dreißig Ellen ihre Höhe." },
      { number: 16, text: "Ein Dach* sollst du der Arche machen, und zwar nach der Elle sollst du sie* von unten nach oben fertigstellen; und die Tür der Arche sollst du in ihrer Seite anbringen; mit einem unteren, einem zweiten und dritten Stockwerk sollst du sie* machen!", footnotes: ["nach anderen: Eine Lichtöffnung", "d. h. die Arche", "d. h. die Arche"] },
      { number: 17, text: "Denn ich, siehe, ich bringe die Wasserflut über die Erde, um alles Fleisch unter dem Himmel, in dem Lebensodem ist, zu vernichten; alles, was auf der Erde ist, soll umkommen*.", footnotes: ["℘ Kap. 7,21-23"] },
      { number: 18, text: "Aber mit dir will ich meinen Bund aufrichten*, und du sollst in die Arche gehen, du und deine Söhne und deine Frau und die Frauen deiner Söhne mit dir*.", footnotes: ["℘ Kap. 9,9", "℘ Kap. 7,1.7"] },
      { number: 19, text: "Und von allem Lebendigen, von allem Fleisch, sollst du je zwei von allen in die Arche bringen, um sie mit dir am Leben zu erhalten; ein Männliches und ein Weibliches sollen sie sein!" },
      { number: 20, text: "Von den Vögeln nach ihrer Art und von dem Vieh nach seiner Art, von allen kriechenden Tieren des Erdbodens nach ihrer Art: je zwei von allen sollen zu dir hineingehen, um am Leben zu bleiben!" },
      { number: 21, text: "Und du, nimm dir von aller Speise, die man isst, und sammle sie bei dir, dass sie dir und ihnen zur Nahrung diene!*", footnotes: ["℘ Kap. 1,29.30"] },
      { number: 22, text: "Und Noah tat es; nach allem, was Gott ihm geboten hatte, so tat er*.", footnotes: ["℘ Kap. 7,5.9; 2Mo 40,16; Hebr 11,7"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und der HERR sprach zu Noah: Geh in die Arche, du und dein ganzes Haus; denn dich habe ich gerecht vor mir erfunden in dieser Generation*.", heading: "Noah und seine Familie gehen in die Arche", footnotes: ["℘ Kap. 6,9; Hes 14,14; Lk 1,6"] },
      { number: 2, text: "Von allem reinen Vieh* sollst du je sieben zu dir nehmen, ein Männchen und sein Weibchen; und von dem Vieh, das nicht rein ist*, je zwei, ein Männchen und sein Weibchen;", footnotes: ["℘ Kap. 8,20; 3Mo 11", "℘ Kap. 8,20; 3Mo 11"] },
      { number: 3, text: "auch von den Vögeln des Himmels je sieben, ein Männliches und ein Weibliches*: um Nachwuchs* am Leben zu erhalten auf der Fläche der ganzen Erde!", footnotes: ["℘ Kap. 8,20; 3Mo 11", "w. Samen"] },
      { number: 4, text: "Denn noch sieben Tage, dann lasse ich auf die Erde regnen vierzig Tage und vierzig Nächte lang und lösche von der Fläche des Erdbodens alles Bestehende aus, das ich gemacht habe. —" },
      { number: 5, text: "Und Noah tat nach allem, was der HERR ihm geboten hatte*.", footnotes: ["℘ V. 16; Kap. 6,22"] },
      { number: 6, text: "Und Noah war 600 Jahre alt, als die Flut kam, Wasser über die Erde." },
      { number: 7, text: "Und Noah und seine Söhne und seine Frau und die Frauen seiner Söhne gingen mit ihm vor dem Wasser der Flut in die Arche*.", footnotes: ["℘ Kap. 6,18; Mt 24,38; Hebr 11,7; 1Petr 3,20"] },
      { number: 8, text: "Von dem reinen Vieh und von dem Vieh, das nicht rein ist, und von den Vögeln und von allem, was auf dem Erdboden kriecht," },
      { number: 9, text: "kamen je zwei zu Noah in die Arche, ein Männliches und ein Weibliches, wie Gott dem Noah geboten hatte*.", footnotes: ["℘ V. 16; Kap. 6,22"] },
      { number: 10, text: "Und es geschah nach sieben Tagen, da kam das Wasser der Flut über die Erde.", heading: "Überschwemmung der Erde" },
      { number: 11, text: "Im 600. Lebensjahr Noahs, im zweiten Monat, am siebzehnten Tag des Monats, an diesem Tag brachen alle Quellen der großen Tiefe* auf*, und die Fenster des Himmels öffneten sich.", footnotes: ["o. Flut; dasselbe Wort wie Kap. 1,2", "℘ Kap. 8,2; Hi 38,37; Spr 8,28; Jes 24,18"] },
      { number: 12, text: "Und der Regen fiel auf die Erde vierzig Tage und vierzig Nächte lang." },
      { number: 13, text: "An ebendiesem Tag gingen Noah und Sem und Ham und Jafet, die Söhne Noahs*, und die Frau Noahs und die drei Frauen seiner Söhne mit ihnen in die Arche,", footnotes: ["℘ Kap. 5,32"] },
      { number: 14, text: "sie und alle Tiere nach ihrer Art und alles Vieh nach seiner Art und alle kriechenden Tiere, die auf der Erde kriechen, nach ihrer Art und alle Vögel nach ihrer Art, jeder Vogel jeglichen Gefieders." },
      { number: 15, text: "Und sie gingen zu Noah in die Arche, je zwei und zwei von allem Fleisch, in dem Lebensodem war." },
      { number: 16, text: "Und die, die hineingingen, waren* je ein Männliches und ein Weibliches von allem Fleisch, wie Gott ihm geboten hatte*. Und der HERR schloss hinter ihm zu*.", footnotes: ["w. gingen hinein als", "℘ V. 5.9", "℘ Hi 12,14; Mt 25,10"] },
      { number: 17, text: "Und die Flut kam vierzig Tage lang über die Erde*. Und das Wasser wuchs und hob die Arche empor, so dass sie sich über die Erde erhob.", footnotes: ["℘ Am 9,6"] },
      { number: 18, text: "Und das Wasser schwoll an und wuchs gewaltig auf der Erde; und die Arche fuhr auf der Fläche des Wassers." },
      { number: 19, text: "Und das Wasser schwoll sehr, sehr an auf der Erde, so dass alle hohen Berge, die unter dem ganzen Himmel sind, bedeckt wurden*.", footnotes: ["℘ Ps 104,6"] },
      { number: 20, text: "Fünfzehn Ellen darüber hinaus schwoll das Wasser an; so wurden die Berge bedeckt*.", footnotes: ["℘ Ps 104,6"] },
      { number: 21, text: "Da kam alles Fleisch um, das sich auf der Erde regte, alles an Vögeln und an Vieh und an Tieren und an allem Gewimmel, das auf der Erde wimmelte, und alle Menschen;" },
      { number: 22, text: "alles starb, in dessen Nase ein Hauch von Lebensodem war, von allem, was auf dem trockenen Land lebte." },
      { number: 23, text: "So löschte er alles Bestehende aus, das auf der Fläche des Erdbodens war, vom Menschen bis zum Vieh, bis zu den kriechenden Tieren und bis zu den Vögeln des Himmels; und sie wurden von der Erde ausgelöscht*. Nur Noah blieb übrig und das, was mit ihm in der Arche war*.", footnotes: ["℘ Mt 24,39; Lk 17,27; 2Petr 3,6", "℘ Kap. 6,17; 8,18; 2Petr 2,5"] },
      { number: 24, text: "Und das Wasser schwoll an auf der Erde 150 Tage lang*.", footnotes: ["℘ Kap. 8,3"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und Gott gedachte des Noah* und aller Tiere und alles Viehs, das mit ihm in der Arche war; und Gott ließ einen Wind über die Erde fahren, da sank das Wasser*.", heading: "Versiegen des Wassers", footnotes: ["℘ Kap. 19,29; Ps 115,12", "℘ 2Mo 14,21; Hi 12,15; Jes 44,27; Jer 50,38; Sach 10,11"] },
      { number: 2, text: "Und es schlossen sich die Quellen der Tiefe und die Fenster des Himmels, und der Regen vom Himmel her wurde zurückgehalten*.", footnotes: ["℘ Kap. 7,11"] },
      { number: 3, text: "Und das Wasser verlief sich von der Erde, allmählich zurückgehend; und das Wasser nahm ab nach Verlauf von 150 Tagen*.", footnotes: ["℘ Kap. 7,24"] },
      { number: 4, text: "Und im siebten Monat, am siebzehnten Tag des Monats, ließ sich die Arche auf dem Gebirge Ararat* nieder.", footnotes: ["℘ 2Kö 19,37; Jer 51,27"] },
      { number: 5, text: "Und das Wasser nahm immer weiter ab bis zum zehnten Monat; im zehnten Monat, am Ersten des Monats, wurden die Spitzen der Berge sichtbar." },
      { number: 6, text: "Und es geschah am Ende von vierzig Tagen, da öffnete Noah das Fenster der Arche, das er gemacht hatte, und ließ den Raben hinaus;" },
      { number: 7, text: "und der flog aus, hin und her, bis das Wasser von der Erde vertrocknet war." },
      { number: 8, text: "Und er ließ die Taube von sich hinaus, um zu sehen, ob das Wasser weniger geworden sei auf der Fläche des Erdbodens;" },
      { number: 9, text: "aber die Taube fand keinen Ruheplatz für ihren Fuß und kehrte zu ihm in die Arche zurück; denn noch war Wasser auf der Fläche der ganzen Erde; da streckte er seine Hand aus, nahm sie und holte sie zu sich in die Arche." },
      { number: 10, text: "Und er wartete noch sieben weitere Tage, dann ließ er die Taube noch einmal aus der Arche;" },
      { number: 11, text: "und die Taube kam um die Abendzeit zu ihm zurück, und siehe, ein frisches Olivenblatt war in ihrem Schnabel. Da erkannte Noah, dass das Wasser auf der Erde weniger geworden war." },
      { number: 12, text: "Und er wartete noch weitere sieben Tage und ließ die Taube hinaus; da kehrte sie nicht mehr wieder zu ihm zurück." },
      { number: 13, text: "Und es geschah im 601. Jahr*, im ersten Monat, am Ersten des Monats, da war das Wasser von der Erde weggetrocknet. Und Noah entfernte das Dach* von der Arche und sah: und siehe, die Fläche des Erdbodens war trocken.", footnotes: ["LXX: im 601. Lebensjahr Noahs\n℘ Kap. 7,6", "w. die Decke"] },
      { number: 14, text: "Im zweiten Monat, am 27. Tag des Monats, war die Erde trocken." },
      { number: 15, text: "Und Gott redete zu Noah und sprach:", heading: "Noahs Opfer — Gottes Verheißung" },
      { number: 16, text: "Geh aus der Arche heraus, du und deine Frau und deine Söhne und die Frauen deiner Söhne mit dir!" },
      { number: 17, text: "Alle Tiere, die bei dir sind, von allem Fleisch, an Vögeln und an Vieh und an allen kriechenden Tieren, die auf der Erde kriechen, lass mit dir hinausgehen, dass sie wimmeln auf Erden und fruchtbar seien und sich mehren auf Erden*!", footnotes: ["℘ Kap. 1,22"] },
      { number: 18, text: "Da ging Noah hinaus, er und seine Söhne und seine Frau und die Frauen seiner Söhne mit ihm*.", footnotes: ["℘ Kap. 7,23"] },
      { number: 19, text: "Alle Tiere, alle kriechenden Tiere und alle Vögel, alles was kriecht auf der Erde nach ihren Arten, gingen aus der Arche*.", footnotes: ["℘ Kap. 9,10"] },
      { number: 20, text: "Und Noah baute dem HERRN einen Altar*; und er nahm von allem reinen Vieh und von allen reinen Vögeln* und opferte Brandopfer auf dem Altar*.", footnotes: ["℘ Kap. 12,7", "℘ Kap. 7,2.3", "℘ 3Mo 1,3"] },
      { number: 21, text: "Und der HERR roch den wohlgefälligen Geruch*, und der HERR sprach in seinem Herzen: Nicht noch einmal will ich den Erdboden verfluchen wegen des Menschen; denn das Sinnen des menschlichen Herzens ist böse von seiner Jugend an*; und nicht noch einmal will ich alles Lebendige schlagen, wie ich getan habe*.", footnotes: ["o. Geruch der Befriedigung o. der Beschwichtigung\n℘ 3Mo 1,9.13.17; 1Sam 26,19; Eph 5,2", "℘ Kap. 6,5; Ps 58,4; Mk 7,22.23", "℘ Kap. 9,11.15; Jes 54,9"] },
      { number: 22, text: "Von nun an, alle Tage der Erde, sollen nicht aufhören Saat und Ernte, Frost und Hitze, Sommer und Winter, Tag und Nacht*.", footnotes: ["℘ Jer 33,25"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und Gott segnete Noah und seine Söhne und sprach zu ihnen: Seid fruchtbar, und vermehrt euch, und füllt die Erde!*", heading: "Gottes Bund mit Noah", footnotes: ["℘ Kap. 1,28"] },
      { number: 2, text: "Und Furcht und Schrecken vor euch sei auf allen Tieren der Erde und auf allen Vögeln des Himmels! Mit allem, was sich auf dem Erdboden regt, mit allen Fischen des Meeres sind sie in eure Hände gegeben*.", footnotes: ["℘ Kap. 1,26"] },
      { number: 3, text: "Alles, was sich regt*, was da lebt, soll euch zur Speise sein*; wie das grüne Kraut gebe ich es euch alles.", footnotes: ["w. Alle kriechenden Tiere", "℘ Kap. 1,29; 1Tim 4,3.4"] },
      { number: 4, text: "Nur Fleisch mit seiner Seele*, seinem Blut, sollt ihr nicht essen*!", footnotes: ["o. mit seinem Leben", "℘ 3Mo 3,17; 1Sam 14,33.34; Hes 33,25; Apg 15,20.29"] },
      { number: 5, text: "Jedoch euer eigenes Blut* werde ich einfordern; von jedem Tiere* werde ich es einfordern, und von der Hand des Menschen, von der Hand eines jeden, nämlich seines Bruders, werde ich die Seele* des Menschen einfordern*.", footnotes: ["w. euer Blut für eure Seelen", "w. von der Hand jedes Tieres", "o. das Leben", "℘ Kap. 42,22; 2Mo 21,12.28; 3Mo 24,17; 4Mo 35,16-21.31; 5Mo 19,11.12; 2Sam 4,11; 1Kö 2,6.9; 2Kö 11,1.16.20; 2Chr 33,24.25; Mt 26,52"] },
      { number: 6, text: "Wer Menschenblut vergießt, dessen Blut soll durch Menschen vergossen werden*; denn nach dem Bilde Gottes hat er den Menschen gemacht*.", footnotes: ["℘ Kap. 42,22; 2Mo 21,12.28; 3Mo 24,17; 4Mo 35,16-21.31; 5Mo 19,11.12; 2Sam 4,11; 1Kö 2,6.9; 2Kö 11,1.16.20; 2Chr 33,24.25; Mt 26,52", "℘ Kap. 1,27"] },
      { number: 7, text: "Ihr nun, seid fruchtbar, und vermehrt euch, wimmelt auf der Erde, und vermehrt euch auf ihr!" },
      { number: 8, text: "Und Gott sprach zu Noah und zu seinen Söhnen mit ihm:" },
      { number: 9, text: "Und ich, siehe, ich richte meinen Bund mit euch auf und mit euren Nachkommen nach euch*", footnotes: ["℘ Kap. 6,18"] },
      { number: 10, text: "und mit jedem lebenden Wesen, das* bei euch ist, an Vögeln, an Vieh und an allen Tieren der Erde bei euch, von allem, was aus der Arche gegangen ist, von allen Tieren der Erde*.", footnotes: ["o. jeder lebenden Seele, die", "℘ Kap. 8,19; Hos 2,20"] },
      { number: 11, text: "Ich richte meinen Bund mit euch auf, dass nie mehr alles Fleisch ausgerottet werden soll durch das Wasser der Flut, und nie mehr soll es eine Flut geben, die Erde zu vernichten*.", footnotes: ["℘ Kap. 8,21"] },
      { number: 12, text: "Und Gott sprach: Dies ist das Zeichen des Bundes, den ich stifte zwischen mir und euch und jedem lebenden Wesen, das* bei euch ist, auf ewige Generationen hin:", footnotes: ["o. jeder lebenden Seele, die"] },
      { number: 13, text: "Meinen Bogen setze ich in die Wolken*, und er sei das Zeichen des Bundes zwischen mir und der Erde.", footnotes: ["℘ Hes 1,28"] },
      { number: 14, text: "Und es wird geschehen, wenn ich Wolken über die Erde aufwölke, und der Bogen in den Wolken erscheint," },
      { number: 15, text: "dann werde ich an meinen Bund denken, der zwischen mir und euch und jedem lebenden Wesen* unter allem Fleisch besteht; und nie mehr soll das Wasser zu einer Flut werden, alles Fleisch zu vernichten*.", footnotes: ["o. jeder lebenden Seele", "℘ Kap. 8,21"] },
      { number: 16, text: "Wenn der Bogen in den Wolken steht, werde ich ihn ansehen, um an den ewigen Bund zu denken* zwischen Gott und jedem lebenden Wesen* unter allem Fleisch, das auf Erden ist.", footnotes: ["℘ Kap. 17,7.13.19; 2Sam 23,5; Hes 37,26", "o. jeder lebenden Seele"] },
      { number: 17, text: "Und Gott sprach zu Noah: Das ist das Zeichen des Bundes, den ich aufgerichtet habe zwischen mir und allem Fleisch, das auf Erden ist." },
      { number: 18, text: "Und die Söhne Noahs, die aus der Arche gingen, waren Sem und Ham und Jafet*. Und Ham, das ist der Vater Kanaans*.", heading: "Noahs Fluch und Segen", footnotes: ["℘ Kap. 5,32", "℘ Kap. 10,6.15"] },
      { number: 19, text: "Diese drei sind die Söhne Noahs, und von ihnen ist die ganze Erde bevölkert worden*.", footnotes: ["w. hat sich die ganze Erde (Erdbevölkerung) zerstreut\n℘ Kap. 10,1.32; Apg 17,26"] },
      { number: 20, text: "Und Noah, ein Landmann, begann auch, Weinberge zu pflanzen*.", footnotes: ["o. Noah, ein Landmann, war der Erste, der einen Weinberg pflanzte\n℘ Kap. 4,2"] },
      { number: 21, text: "Und er trank von dem Wein und wurde betrunken und lag entblößt im Innern seines Zeltes*.", footnotes: ["℘ Spr 20,1; Eph 5,18"] },
      { number: 22, text: "Und Ham, der Vater Kanaans, sah die Blöße seines Vaters und berichtete es seinen beiden Brüdern draußen." },
      { number: 23, text: "Da nahmen Sem und Jafet das Obergewand und legten es beide auf ihre Schultern und gingen damit rückwärts und bedeckten so die Blöße ihres Vaters; ihre Gesichter aber hielten sie so rückwärts gewandt, dass sie die Blöße ihres Vaters nicht sahen." },
      { number: 24, text: "Und Noah erwachte von seinem Weinrausch und erkannte, was sein jüngster Sohn ihm angetan hatte." },
      { number: 25, text: "Und er sprach: Verflucht sei Kanaan! Ein Knecht der Knechte sei er seinen Brüdern!" },
      { number: 26, text: "Und er sprach: Gepriesen* sei der HERR, der Gott Sems; und Kanaan sei sein Knecht!*", footnotes: ["o. Gesegnet", "℘ Jos 9,23; Ri 1,28"] },
      { number: 27, text: "Weiten Raum schaffe Gott dem Jafet*, und er wohne in den Zelten Sems; und Kanaan sei sein Knecht!", footnotes: ["Im Hebr. klingt das Wort für »weiten Raum schaffen« (jaft) an den Namen Jafet an."] },
      { number: 28, text: "Und Noah lebte nach der Flut noch 350 Jahre;" },
      { number: 29, text: "und alle Tage Noahs betrugen 950 Jahre, dann starb er." },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und dies ist die Generationenfolge* der Söhne Noahs: Sem, Ham und Jafet* — ihnen wurden Söhne geboren nach der Flut*.", heading: "Stammbaum der Söhne Noahs", footnotes: ["℘ V. 1-5: 1Chr 1,4-7", "o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ Kap. 5,32", "℘ Kap. 9,19"] },
      { number: 2, text: "Die Söhne Jafets: Gomer und Magog* und Madai und Jawan und Tubal und Meschech und Tiras*.", footnotes: ["℘ Hes 38,2", "℘ Jes 66,19; Hes 27,13"] },
      { number: 3, text: "Und die Söhne Gomers: Aschkenas* und Rifat und Togarma*.", footnotes: ["℘ Jer 51,27", "℘ Hes 27,14"] },
      { number: 4, text: "Und die Söhne Jawans: Elischa und Tarsis, die Kittäer* und die Rodaniter.", footnotes: ["℘ 4Mo 24,24; Jes 23,1.12; Hes 27,6; Dan 11,30"] },
      { number: 5, text: "Von diesen verzweigten sich die Inseln* der Nationen. Das sind die Söhne Jafets* in ihren Ländern, je nach ihrer Sprache, nach ihren Sippen, in ihren Nationen*.", footnotes: ["Das hebr. Wort bezeichnet überall im AT die Inseln und Küstengebiete des Mittelmeeres von Kleinasien bis Spanien.", "Dieser Satz hat wohl ursprünglich im Mas. T. gestanden; vgl. V. 20.31.", "℘ V. 25.32; Kap. 9,19; 11,8.9; 5Mo 32,8; Jes 11,11"] },
      { number: 6, text: "*Und die Söhne Hams*: Kusch* und Mizrajim und Put* und Kanaan*.", footnotes: ["℘ V. 6-18: 1Chr 1,8-16", "℘ Kap. 5,32", "℘ Jer 46,9", "Äthiopien und Ägypten und Mauretanien\n℘ Kap. 8,21", "℘ Kap. 9,18"] },
      { number: 7, text: "Und die Söhne Kuschs: Seba* und Hawila und Sabta und Ragma* und Sabtecha. Und die Söhne Ragmas: Saba und Dedan*.", footnotes: ["℘ Hi 1,15", "℘ Hes 27,22", "℘ Hes 27,15.20"] },
      { number: 8, text: "Und Kusch* zeugte Nimrod; der war der erste Gewaltige auf der Erde.", footnotes: ["℘ Kap. 2,13"] },
      { number: 9, text: "Er war ein gewaltiger Jäger vor dem HERRN; darum sagt man: Wie Nimrod, ein gewaltiger Jäger vor dem HERRN!" },
      { number: 10, text: "Und der Anfang seines Königreiches war Babel und Erech und Akkad und Kalne* im Land Schinar*.", footnotes: ["℘ Jes 10,9; Hes 27,23", "℘ Kap. 11,2; Dan 1,2; Sach 5,11"] },
      { number: 11, text: "Von diesem Land zog er aus nach Assur* und baute Ninive* und Rehobot-Ir und Kelach", footnotes: ["o. Von diesem Land zog Assur aus", "℘ Jon 1,2; Nah 1,1"] },
      { number: 12, text: "und Resen zwischen Ninive und Kelach: das ist die große Stadt. —" },
      { number: 13, text: "Und Mizrajim zeugte die Luditer und die Anamiter und die Lehabiter und die Naftuhiter" },
      { number: 14, text: "und die Patrositer und die Kasluhiter, von denen die Philister ausgegangen sind*, und die Kaftoriter*. —", footnotes: ["Nach anderen gehört dieser Satz hinter »und die Kaftoriter«; vgl. Am 9,7.", "℘ 5Mo 2,23; Jer 47,4"] },
      { number: 15, text: "Und Kanaan zeugte Sidon*, seinen Erstgeborenen, und Het*", footnotes: ["℘ Hes 27,8", "℘ Kap. 23,3; 1Sam 26,6"] },
      { number: 16, text: "und den Jebusiter und den Amoriter* und den Girgaschiter", footnotes: ["℘ Kap. 15,16"] },
      { number: 17, text: "und den Hewiter* und den Arkiter und den Siniter", footnotes: ["℘ Jos 9,7"] },
      { number: 18, text: "und den Arwaditer* und den Zemariter und den Hamatiter. Später haben sich die Sippen der Kanaaniter zerstreut.", footnotes: ["℘ Hes 27,8"] },
      { number: 19, text: "Und das Gebiet der Kanaaniter erstreckte sich von Sidon nach Gerar* hin*, bis nach Gaza*, nach Sodom und Gomorra und Adma und Zebojim* hin*, bis nach Lescha. —", footnotes: ["℘ 2Chr 14,12", "w. bis man nach Gerar kommt", "℘ 5Mo 2,23; Ri 6,4", "℘ 1Sam 13,18", "w. bis man nach Sodom und . . . Zebojim kommt"] },
      { number: 20, text: "Das sind die Söhne Hams nach ihren Sippen, nach ihren Sprachen, in ihren Ländern, in ihren Nationen." },
      { number: 21, text: "*Und dem Sem*, dem Vater aller Söhne Ebers, dem älteren Bruder Jafets, auch ihm wurden Söhne geboren.", footnotes: ["℘ V. 21-25: Kap. 11,10-16; V. 21-29: 1Chr 1,17-23", "℘ Kap. 5,32"] },
      { number: 22, text: "Die Söhne Sems: Elam* und Assur und Arpachschad und Lud und Aram.", footnotes: ["℘ Jes 21,2"] },
      { number: 23, text: "Und die Söhne Arams: Uz* und Hul und Geter und Masch.", footnotes: ["℘ Hi 1,1"] },
      { number: 24, text: "Und Arpachschad zeugte Schelach, und Schelach zeugte Eber." },
      { number: 25, text: "Und dem Eber wurden zwei Söhne geboren: Der Name des einen war Peleg*, denn in seinen Tagen wurde das Land geteilt*; und der Name seines Bruders war Joktan.", footnotes: ["d. h. Teilung, Spaltung", "o. verteilte sich die Bevölkerung der Erde\n℘ V. 5"] },
      { number: 26, text: "Und Joktan zeugte Almodad und Schelef und Hazarmawet und Jerach" },
      { number: 27, text: "und Hadoram und Usal und Dikla" },
      { number: 28, text: "und Obal und Abimaël und Saba*", footnotes: ["℘ Hes 27,23"] },
      { number: 29, text: "und Ofir* und Hawila und Jobab; diese alle waren Söhne Joktans.", footnotes: ["℘ 1Kö 9,28"] },
      { number: 30, text: "Und ihre Wohnsitze sind von Mescha bis nach Sefar hin*, bis an das Gebirge des Ostens. —", footnotes: ["w. bis man nach Sefar kommt"] },
      { number: 31, text: "Das sind die Söhne Sems nach ihren Sippen, nach ihren Sprachen, in ihren Ländern, nach ihren Nationen." },
      { number: 32, text: "Das sind die Sippen der Söhne Noahs nach ihrer Generationenfolge*, in ihren Nationen; und von diesen aus haben sich nach der Flut die Nationen auf der Erde verzweigt*.", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ V. 5"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und die ganze Erde hatte ein und dieselbe Sprache* und ein und dieselben Wörter.", heading: "Der Turmbau zu Babel", footnotes: ["w. eine Lippe"] },
      { number: 2, text: "Und es geschah, als sie von Osten aufbrachen*, da fanden sie eine Ebene im Land Schinar* und ließen sich dort nieder.", footnotes: ["o. im Osten umherzogen; o. in der Urzeit umherzogen", "℘ Kap. 10,10; Dan 1,2; Sach 5,11"] },
      { number: 3, text: "Und sie sagten einer zum anderen: Auf, lasst uns Ziegel streichen und hart brennen! Und der Ziegel diente ihnen als Stein, und der Asphalt* diente ihnen als Mörtel.", footnotes: ["℘ Kap. 14,10"] },
      { number: 4, text: "Und sie sprachen: Auf, wir wollen uns eine Stadt und einen Turm bauen, und seine Spitze bis an den Himmel! So wollen wir uns einen Namen machen*, damit wir uns nicht über die ganze Fläche der Erde zerstreuen!", footnotes: ["℘ Dan 4,27"] },
      { number: 5, text: "Und der HERR fuhr herab, um die Stadt und den Turm anzusehen, die die Menschenkinder bauten*.", footnotes: ["℘ Kap. 18,21"] },
      { number: 6, text: "Und der HERR sprach: Siehe, ein Volk sind sie, und eine Sprache haben sie alle, und dies ist erst der Anfang ihres Tuns. Jetzt wird ihnen nichts unmöglich sein, was sie zu tun ersinnen." },
      { number: 7, text: "Auf, lasst uns* herabfahren und dort ihre Sprache verwirren, dass sie einer des anderen Sprache nicht mehr verstehen!", footnotes: ["℘ Kap. 1,26"] },
      { number: 8, text: "Und der HERR zerstreute sie von dort über die ganze Erde*; und sie hörten auf, die Stadt zu bauen*.", footnotes: ["℘ Kap. 10,5.25.32; Apg 2,6", "℘ Ps 33,10"] },
      { number: 9, text: "Darum gab man ihr den Namen Babel; denn dort verwirrte der HERR die Sprache der ganzen Erde, und von dort zerstreute sie der HERR über die ganze Erde*.", footnotes: ["℘ Kap. 10,5.25.32; Apg 2,6"] },
      { number: 10, text: "*Das ist die Generationenfolge* Sems: Sem war 100 Jahre alt und zeugte Arpachschad, zwei Jahre nach der Flut.", heading: "Stammbaum von Sem bis Abram", footnotes: ["℘ V. 10-16: Kap. 10,21-25; V. 10-26: 1Chr 1,17-27; Lk 3,34-36", "o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1"] },
      { number: 11, text: "Und Sem lebte, nachdem er Arpachschad gezeugt hatte, 500 Jahre und zeugte Söhne und Töchter. —" },
      { number: 12, text: "Und Arpachschad lebte 35 Jahre und zeugte Schelach." },
      { number: 13, text: "Und Arpachschad lebte, nachdem er Schelach gezeugt hatte, 403 Jahre und zeugte Söhne und Töchter. —" },
      { number: 14, text: "Und Schelach lebte 30 Jahre und zeugte Eber." },
      { number: 15, text: "Und Schelach lebte, nachdem er Eber gezeugt hatte, 403 Jahre und zeugte Söhne und Töchter. —" },
      { number: 16, text: "Und Eber lebte 34 Jahre und zeugte Peleg." },
      { number: 17, text: "Und Eber lebte, nachdem er Peleg gezeugt hatte, 430 Jahre und zeugte Söhne und Töchter. —" },
      { number: 18, text: "Und Peleg lebte 30 Jahre und zeugte Regu." },
      { number: 19, text: "Und Peleg lebte, nachdem er Regu gezeugt hatte, 209 Jahre und zeugte Söhne und Töchter. —" },
      { number: 20, text: "Und Regu lebte 32 Jahre und zeugte Serug." },
      { number: 21, text: "Und Regu lebte, nachdem er Serug gezeugt hatte, 207 Jahre und zeugte Söhne und Töchter. —" },
      { number: 22, text: "Und Serug lebte 30 Jahre und zeugte Nahor." },
      { number: 23, text: "Und Serug lebte, nachdem er Nahor gezeugt hatte, 200 Jahre und zeugte Söhne und Töchter. —" },
      { number: 24, text: "Und Nahor lebte 29 Jahre und zeugte Terach." },
      { number: 25, text: "Und Nahor lebte, nachdem er Terach gezeugt hatte, 119 Jahre und zeugte Söhne und Töchter. —" },
      { number: 26, text: "Und Terach lebte 70 Jahre und zeugte Abram, Nahor und Haran*.", footnotes: ["℘ Jos 24,2"] },
      { number: 27, text: "Und das ist die Generationenfolge* Terachs: Terach zeugte Abram, Nahor und Haran*; und Haran zeugte Lot*.", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ Jos 24,2", "℘ Kap. 12,5; 14,12"] },
      { number: 28, text: "Haran aber starb zu Lebzeiten* seines Vaters Terach im Land seiner Verwandtschaft, in Ur, der Stadt der Chaldäer*.", footnotes: ["w. angesichts", "℘ Kap. 15,7"] },
      { number: 29, text: "Und Abram und Nahor nahmen sich Frauen; der Name von Abrams Frau war Sarai, und der Name von Nahors Frau war Milka*, die Tochter Harans, des Vaters der Milka und des Vaters der Jiska.", footnotes: ["℘ Kap. 22,20-23; 24,15"] },
      { number: 30, text: "Sarai aber war unfruchtbar, sie hatte kein Kind*.", footnotes: ["℘ Kap. 16,1.2; 25,21; 29,31; Ri 13,2; 1Sam 1,5; Lk 1,7"] },
      { number: 31, text: "Und Terach nahm seinen Sohn Abram und Lot, den Sohn Harans, seines Sohnes Sohn*, und Sarai, seine Schwiegertochter, die Frau seines Sohnes Abram; und sie zogen miteinander* aus Ur, der Stadt der Chaldäer, um in das Land Kanaan zu gehen*; und sie kamen nach Haran und wohnten dort*.", footnotes: ["℘ Kap. 12,5; 14,12", "w. mit ihnen. — SamPent, LXX und Vulg. lesen: und führte sie hinweg", "℘ Kap. 15,7; Neh 9,7; Apg 7,2.3", "℘ Kap. 27,43; 28,10; 29,4"] },
      { number: 32, text: "Und die Tage Terachs betrugen 205 Jahre, und Terach starb in Haran*.", footnotes: ["℘ 2Kö 19,12; Jes 37,12; Apg 7,4"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und der HERR sprach zu Abram: Geh aus deinem Land und aus deiner Verwandtschaft und aus dem Haus deines Vaters* in das Land, das ich dir zeigen werde!*", heading: "Abrams Berufung und Auszug nach Kanaan", footnotes: ["℘ Kap. 24,7", "℘ Kap. 15,7; Jos 24,3; Apg 7,3"] },
      { number: 2, text: "Und ich will dich zu einer großen Nation machen*, und ich will dich segnen, und ich will deinen Namen groß machen*, und du sollst ein Segen sein*!", footnotes: ["℘ Kap. 17,4-6.20; 46,3; 2Mo 32,10; Jes 51,2", "℘ Kap. 24,35; 2Sam 7,9", "℘ Sach 8,13"] },
      { number: 3, text: "Und ich will segnen, die dich segnen, und wer dir flucht, den werde ich verfluchen*; und in dir sollen gesegnet werden alle Geschlechter* der Erde!*", footnotes: ["℘ Kap. 27,29; 2Mo 23,22; 4Mo 24,9", "o. sollen sich Segen wünschen alle Sippen", "℘ Kap. 18,18; 22,18; 26,4; 28,14; Gal 3,8"] },
      { number: 4, text: "Und Abram ging hin, wie der HERR zu ihm geredet hatte*, und Lot ging mit ihm*. Abram aber war 75 Jahre alt, als er aus Haran zog.", footnotes: ["℘ Hebr 11,8", "℘ Kap. 11,27.31; 13,5"] },
      { number: 5, text: "Und Abram nahm seine Frau Sarai und Lot, den Sohn seines Bruders*, und all ihre Habe, die sie erworben, und die Leute*, die sie in Haran gewonnen hatten, und sie zogen aus, um in das Land Kanaan zu gehen; und sie kamen in das Land Kanaan*.", footnotes: ["℘ Kap. 11,27.31; 13,5", "w. Seelen", "℘ Apg 7,4"] },
      { number: 6, text: "Und Abram durchzog das Land bis zur Stätte von Sichem*, bis zur Terebinthe More*. Damals waren die Kanaaniter im Land*.", footnotes: ["℘ Kap. 33,18; Hos 6,9", "d. h. Orakelterebinthe\n℘ 5Mo 11,30", "℘ Kap. 13,7; 34,30"] },
      { number: 7, text: "Und der HERR erschien* dem Abram und sprach: Deinen Nachkommen will ich dieses Land geben*. Und er baute dort dem HERRN, der ihm erschienen war, einen Altar*.", footnotes: ["℘ Kap. 17,1; 18,1", "℘ Kap. 13,15; 15,18; 17,8; 24,7; 26,3; 28,4.13; 35,12; 50,24; 2Mo 6,4; 4Mo 26,53; Jos 1,6; Jer 3,18", "℘ Kap. 8,20; 13,4.18; 26,25; 33,20; 35,7; 2Mo 17,15; Jos 8,30; 22,10; Ri 6,24"] },
      { number: 8, text: "Und er brach von dort auf zu dem Gebirge östlich von Bethel* und schlug sein Zelt auf, Bethel im Westen und Ai* im Osten; und er baute dort dem HERRN einen Altar* und rief den Namen des HERRN an*.", footnotes: ["℘ Kap. 28,19", "℘ Jos 7,2", "℘ Kap. 8,20; 13,4.18; 26,25; 33,20; 35,7; 2Mo 17,15; Jos 8,30; 22,10; Ri 6,24", "℘ Kap. 4,26; 13,4; 21,33"] },
      { number: 9, text: "Dann brach Abram auf und zog immer weiter nach Süden*.", footnotes: ["o. in das Südland. — Das hebr. Wort negev bezeichnet auch die Südgegend Palästinas.\n℘ Kap. 13,1; 20,1; 24,62"] },
      { number: 10, text: "Es entstand aber eine Hungersnot im Land*; da zog Abram nach Ägypten hinab, um dort als Fremder zu leben, denn die Hungersnot lag schwer auf dem Land.", heading: "Abram in Ägypten", footnotes: ["℘ Kap. 26,1; 41,57; 42,5; 43,1; Rt 1,1"] },
      { number: 11, text: "Und es geschah, als er nahe daran war, nach Ägypten hineinzukommen, sagte er zu seiner Frau Sarai: Siehe doch, ich weiß*, dass du eine Frau von schönem Aussehen bist*;", footnotes: ["o. erkenne", "℘ Kap. 24,16; 26,7; 29,17; 1Sam 25,3; 2Sam 11,2; 1Kö 1,4"] },
      { number: 12, text: "und es wird geschehen, wenn die Ägypter dich sehen, werden sie sagen: Sie ist seine Frau. Dann werden sie mich erschlagen und dich leben lassen*.", footnotes: ["℘ Kap. 20,11; Spr 29,25"] },
      { number: 13, text: "Sage doch, du seist meine Schwester*, damit es mir gut geht um deinetwillen und meine Seele deinetwegen am Leben bleibt!", footnotes: ["℘ Kap. 20,2; 26,7"] },
      { number: 14, text: "Und es geschah, als Abram nach Ägypten kam, da sahen die Ägypter, dass die Frau sehr schön war." },
      { number: 15, text: "Und die Hofbeamten* des Pharao sahen sie und rühmten sie vor dem Pharao; und die Frau wurde in das Haus des Pharao geholt*.", footnotes: ["w. die Obersten", "℘ Kap. 20,2; 26,7"] },
      { number: 16, text: "Und er tat Abram ihretwegen Gutes; und er bekam Schafe und Rinder und Esel, Knechte und Mägde*, Eselinnen und Kamele*.", footnotes: ["℘ Kap. 16,1", "℘ Kap. 20,14"] },
      { number: 17, text: "Der HERR aber schlug den Pharao und sein Haus mit großen Plagen um Sarais willen, der Frau Abrams*.", footnotes: ["℘ Kap. 20,17; Ps 105,14"] },
      { number: 18, text: "Da ließ der Pharao Abram rufen und sagte: Was hast du mir da angetan*! Warum hast du mir nicht mitgeteilt, dass sie deine Frau ist?", footnotes: ["℘ Kap. 3,13; 20,9; 26,10; 29,25; Ri 2,2; 2Sam 3,24"] },
      { number: 19, text: "Warum hast du gesagt: Sie ist meine Schwester, so dass ich sie mir zur Frau nahm? Und nun siehe, da ist deine Frau, nimm sie und geh!" },
      { number: 20, text: "Und der Pharao entbot seinetwegen Männer, die geleiteten ihn und seine Frau und alles, was er hatte." },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Und Abram zog aus Ägypten herauf, er und seine Frau und alles, was er hatte, und Lot mit ihm, nach dem Süden*.", heading: "Abrams Trennung von Lot", footnotes: ["o. in das Südland. — Das hebr. Wort negev bezeichnet auch die Südgegend Palästinas.\n℘ Kap. 12,9"] },
      { number: 2, text: "Und Abram war sehr reich an Vieh, an Silber und an Gold*.", footnotes: ["℘ Kap. 24,1.35; 26,13.14; 30,43"] },
      { number: 3, text: "Und er ging auf seinen Tagemärschen* vom Süden* bis nach Bethel, bis zu der Stätte, wo im Anfang sein Zelt gewesen war, zwischen Bethel und Ai,", footnotes: ["w. Aufbrüchen des Lagers", "o. Südland. — Das hebr. Wort negev bezeichnet auch die Südgegend Palästinas."] },
      { number: 4, text: "zu der Stätte des Altars, den er vorher dort gemacht hatte*. Und Abram rief dort den Namen des HERRN an*.", footnotes: ["℘ Kap. 12,7.8", "℘ Kap. 20,2; 26,7"] },
      { number: 5, text: "Und auch Lot, der mit Abram zog*, hatte Schafe und Rinder und Zelte.", footnotes: ["℘ Kap. 12,4"] },
      { number: 6, text: "Und das Land ertrug es nicht, dass sie zusammen wohnten; denn ihre Habe war groß, und sie konnten nicht zusammen wohnen*.", footnotes: ["℘ Kap. 36,7"] },
      { number: 7, text: "So gab es Streit zwischen den Hirten von Abrams Vieh und den Hirten von Lots Vieh. Und die Kanaaniter und die Perisiter wohnten damals im Land*.", footnotes: ["℘ Kap. 12,6"] },
      { number: 8, text: "Da sprach Abram zu Lot: Lass doch keinen Streit sein zwischen mir und dir und zwischen meinen Hirten und deinen Hirten; wir sind doch Brüder!*", footnotes: ["℘ Kap. 14,14"] },
      { number: 9, text: "Ist nicht das ganze Land vor dir*? Trenne dich doch von mir! Willst du nach links, dann gehe ich nach rechts, und willst du nach rechts, dann gehe ich nach links.", footnotes: ["℘ Kap. 20,15"] },
      { number: 10, text: "Da erhob Lot seine Augen und sah die ganze Ebene* des Jordan, dass sie ganz bewässert war — bevor der HERR Sodom und Gomorra zerstört hatte* — wie der Garten des HERRN, wie das Land Ägypten, bis nach Zoar hin.", footnotes: ["w. die Umgebung, o. den Umkreis", "℘ Kap. 19,24.25; Ps 107,34"] },
      { number: 11, text: "Da wählte sich Lot die ganze Ebene* des Jordan, und Lot brach auf nach Osten; so trennten sie sich voneinander.", footnotes: ["w. die Umgebung, o. den Umkreis"] },
      { number: 12, text: "Abram wohnte im Land Kanaan, und Lot wohnte in den Städten der Ebene* des Jordan und schlug seine Zelte auf bis nach Sodom*.", footnotes: ["w. der Umgebung, o. des Umkreises", "℘ Kap. 14,12; 19,1; Offb 11,8"] },
      { number: 13, text: "Die Leute von Sodom aber waren sehr böse und sündig vor dem HERRN*.", footnotes: ["℘ Kap. 18,20; 19,13; 1Sam 2,17; Jer 23,14; 2Petr 2,7.8"] },
      { number: 14, text: "Und der HERR sprach zu Abram, nachdem Lot sich von ihm getrennt hatte: Erheb doch deine Augen, und schaue von dem Ort, wo du bist, nach Norden und nach Süden, nach Osten und nach Westen!" },
      { number: 15, text: "Denn das ganze Land, das du siehst, dir will ich es geben und deinen Nachkommen für ewig*.", footnotes: ["℘ Kap. 12,7"] },
      { number: 16, text: "Und ich will deine Nachkommen machen wie den Staub der Erde, so dass, wenn jemand den Staub der Erde zählen kann, auch deine Nachkommen gezählt werden*.", footnotes: ["℘ Kap. 17,2.6; 22,17; 28,14; 4Mo 23,10; 2Chr 1,9; Hi 5,25"] },
      { number: 17, text: "Mache dich auf, und durchwandere das Land seiner Länge nach und seiner Breite nach! Denn dir will ich es geben*.", footnotes: ["℘ Kap. 12,7"] },
      { number: 18, text: "Und Abram schlug seine Zelte auf* und ging hin und ließ sich nieder unter den Terebinthen von Mamre, die bei Hebron* sind; und er baute dort dem HERRN einen Altar*.", footnotes: ["o. erhielt Weiderechte\n℘ Hebr 11,9", "℘ Kap. 14,13; 18,1; 23,2; 35,27; 4Mo 13,22; Jos 15,13", "℘ Kap. 12,7.8"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und es geschah in den Tagen Amrafels, des Königs von Schinar, Arjochs, des Königs von Ellasar, Kedor-Laomers, des Königs von Elam, und Tidals, des Königs von Gojim*,", heading: "Abrams Einsatz zur Rettung Lots", footnotes: ["o. der Nationen"] },
      { number: 2, text: "dass sie Krieg führten mit Bera, dem König von Sodom, und mit Birscha, dem König von Gomorra, Schinab, dem König von Adma, und Schemeber, dem König von Zebojim, und mit dem König von Bela, das ist Zoar." },
      { number: 3, text: "Alle diese verbündeten sich und kamen in das Tal Siddim, das ist das Salzmeer." },
      { number: 4, text: "Zwölf Jahre hatten sie Kedor-Laomer gedient, im dreizehnten Jahr aber empörten sie sich." },
      { number: 5, text: "Und im vierzehnten Jahr kamen Kedor-Laomer und die Könige, die mit ihm waren, und schlugen die Refaïter* bei Aschterot-Karnajim und die Susiter* bei Ham und die Emiter* in der Ebene von Kirjatajim*", footnotes: ["℘ Kap. 15,20; 5Mo 3,11", "℘ 5Mo 2,10.20", "℘ Kap. 12,7", "℘ Jer 48,1"] },
      { number: 6, text: "und die Horiter* auf ihrem Gebirge Seïr bis El-Paran, das an der Wüste liegt.", footnotes: ["℘ Kap. 36,20"] },
      { number: 7, text: "Dann wandten sie sich und kamen nach En-Mischpat, das ist Kadesch*; und sie schlugen das ganze Gebiet der Amalekiter* und auch die Amoriter, die zu Hazezon-Tamar* wohnten*.", footnotes: ["℘ 4Mo 20,1", "℘ 2Mo 17,8", "℘ 2Chr 20,2", "w. den Amalekiter und . . . den Amoriter, der in . . . wohnte"] },
      { number: 8, text: "Und es zogen aus der König von Sodom und der König von Gomorra und der König von Adma und der König von Zebojim und der König von Bela, das ist Zoar; und sie ordneten sich zur Schlacht gegen sie im Tal Siddim:" },
      { number: 9, text: "gegen Kedor-Laomer, den König von Elam, und Tidal, den König von Gojim*, und Amrafel, den König von Schinar, und Arjoch, den König von Ellasar, vier Könige gegen die fünf.", footnotes: ["o. der Nationen"] },
      { number: 10, text: "Im Tal Siddim aber war Asphaltgrube neben Asphaltgrube*; und die Könige von Sodom und Gomorra flohen und fielen dort hinein, die übrigen aber flohen ins Gebirge.", footnotes: ["℘ Kap. 11,3"] },
      { number: 11, text: "Da nahmen sie alle Habe von Sodom und Gomorra und all ihre Nahrungsmittel und zogen davon." },
      { number: 12, text: "Und sie nahmen Lot mit, den Sohn von Abrams Bruder*, und seine Habe und zogen davon; denn er wohnte in Sodom*.", footnotes: ["℘ Kap. 11,27", "℘ Kap. 13,12"] },
      { number: 13, text: "Und es kam ein Entkommener und berichtete es Abram, dem Hebräer*; er wohnte aber unter den Terebinthen Mamres*, des Amoriters, des Bruders von Eschkol und des Bruders von Aner; die waren Abrams Bundesgenossen.", footnotes: ["℘ Kap. 40,15; 1Sam 29,3; Jon 1,9", "℘ Kap. 13,18"] },
      { number: 14, text: "Und als Abram hörte, dass sein Bruder* gefangen weggeführt war, ließ er seine bewährten Männer, die in seinem Haus geborenen Sklaven, ausrücken*, 318 Mann, und jagte ihnen nach bis nach Dan*.", footnotes: ["℘ Kap. 13,8", "w. schüttete er seine bewährten Männer . . . aus. — SamPent und LXX lesen: musterte er seine bewährten Männer", "℘ Ri 18,29"] },
      { number: 15, text: "Und nachts teilte er sich und fiel über sie her, er und seine Knechte, und schlug sie und jagte ihnen nach bis nach Hoba, das links* von Damaskus liegt.", footnotes: ["d. h. nördlich"] },
      { number: 16, text: "Und er brachte die ganze Habe zurück; und auch Lot, seinen Neffen*, und dessen Habe brachte er zurück* und auch die Frauen und das Volk.", footnotes: ["w. Bruder", "℘ 1Sam 30,19"] },
      { number: 17, text: "Und als er zurückkehrte, nachdem er Kedor-Laomer und die Könige, die mit ihm gewesen, geschlagen hatte, zog der König von Sodom aus, ihm entgegen, in das Tal Schawe, das ist das Königstal*.", footnotes: ["℘ 2Sam 18,18"] },
      { number: 18, text: "Und Melchisedek*, König von Salem*, brachte Brot und Wein heraus; und er war Priester Gottes, des Höchsten*.", footnotes: ["d. h. König der Gerechtigkeit", "d. h. Friede\n℘ Ps 76,3", "hebr. el eljon\n℘ 4Mo 24,16; Ps 110,4; Dan 4,31"] },
      { number: 19, text: "Und er segnete ihn* und sprach: Gesegnet* sei Abram von Gott, dem Höchsten, der Himmel und Erde geschaffen hat*!", footnotes: ["℘ Kap. 47,7; Ps 115,15; Hebr 7,1", "o. Gepriesen", "o. besitzt\n℘ Kap. 24,3; 5Mo 10,14; 2Sam 2,5; 1Chr 29,11; Offb 10,6"] },
      { number: 20, text: "Und gesegnet* sei Gott, der Höchste, der deine Bedränger* in deine Hand ausgeliefert hat!* — Und Abram gab ihm den Zehnten von allem*.", footnotes: ["o. Gepriesen", "o. Gegner", "℘ 2Sam 18,28", "℘ Kap. 28,22; Hebr 7,2"] },
      { number: 21, text: "Und der König von Sodom sagte zu Abram: Gib mir die Seelen, die Habe aber nimm für dich!*", footnotes: ["℘ Kap. 47,24"] },
      { number: 22, text: "Da sagte Abram zum König von Sodom: Ich hebe meine Hand auf zu dem HERRN, zu Gott, dem Höchsten, der Himmel und Erde geschaffen hat*:", footnotes: ["o. besitzt\n℘ Kap. 24,3; 5Mo 10,14; 2Sam 2,5; 1Chr 29,11; Offb 10,6"] },
      { number: 23, text: "Wenn ich vom Faden bis zum Schuhriemen, ja, wenn ich irgendetwas nehme von dem, was dein ist . . .*!* Damit du später nicht sagst: Ich habe Abram reich gemacht.", footnotes: ["℘ 2Kö 5,16", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 24, text: "Nichts für mich! Nur was die Knechte* verzehrt haben, und der Anteil der Männer, die mit mir gezogen sind: Aner, Eschkol und Mamre, die sollen ihren Anteil nehmen!", footnotes: ["w. jungen Männer"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Nach diesen Dingen* geschah das Wort des HERRN zu Abram in einem Gesicht* so: Fürchte dich nicht*, Abram; ich bin dir ein Schild*, ich werde deinen Lohn* sehr groß machen*.", heading: "Gottes Bund mit Abram", footnotes: ["℘ Kap. 22,1.20", "℘ Kap. 46,2", "℘ Kap. 26,24; 2Kö 1,15", "℘ Ps 3,4; 115,10.11", "℘ Jes 40,10", "o. ein Schild, dein sehr großer Lohn"] },
      { number: 2, text: "Da sagte Abram: Herr, HERR, was willst du mir geben? Ich gehe ja doch kinderlos dahin, und Erbe* meines Hauses, das wird Eliëser von Damaskus.", footnotes: ["w. Sohn des Besitzes"] },
      { number: 3, text: "Und Abram sagte: Siehe, mir hast du keinen Nachkommen gegeben, und siehe, der Sohn meines Hauses* wird mich beerben.", footnotes: ["d. h. mein im Haus geborener Sklave"] },
      { number: 4, text: "Und siehe, das Wort des HERRN geschah zu ihm: Nicht dieser wird dich beerben, sondern der aus deinem Leibe hervorgeht, der wird dich beerben*.", footnotes: ["℘ Kap. 17,16"] },
      { number: 5, text: "Und er führte ihn hinaus und sprach: Blicke doch auf zum Himmel, und zähle die Sterne, wenn du sie zählen kannst!* Und er sprach zu ihm: So zahlreich wird deine Nachkommenschaft sein*!", footnotes: ["℘ Jer 33,22", "℘ Kap. 22,17; 32,13; Röm 4,18; Hebr 11,12"] },
      { number: 6, text: "Und er glaubte dem* HERRN; und er rechnete es ihm als Gerechtigkeit an*.", footnotes: ["w. er vertraute auf den", "℘ Ps 106,31; Röm 4,3; Gal 3,6; Jak 2,23"] },
      { number: 7, text: "Und er sprach zu ihm: Ich bin der HERR, der ich dich herausgeführt habe aus Ur, der Stadt der Chaldäer*, um dir dieses Land zu geben, es in Besitz zu nehmen*.", footnotes: ["℘ Kap. 11,28", "℘ Kap. 11,31; 12,1; 2Mo 32,13; 4Mo 33,53; 5Mo 3,18"] },
      { number: 8, text: "Und er sagte: Herr, HERR, woran soll ich erkennen, dass ich es in Besitz nehmen werde*?", footnotes: ["℘ Ri 6,17; 2Kö 20,8; Lk 1,18"] },
      { number: 9, text: "Da sprach er zu ihm: Bring mir eine dreijährige Jungkuh, eine dreijährige Ziege und einen dreijährigen Widder, eine Turteltaube und eine junge Taube." },
      { number: 10, text: "Und er brachte ihm alle diese. Und er zerteilte sie in der Mitte und legte je einen Teil dem anderen gegenüber. Die Vögel aber zerteilte er nicht*.", footnotes: ["℘ 3Mo 1,17"] },
      { number: 11, text: "Da stießen die Raubvögel auf die toten Tiere* herab; aber Abram verscheuchte sie.", footnotes: ["w. auf die Leichen"] },
      { number: 12, text: "Und es geschah beim Untergang der Sonne, da fiel ein tiefer Schlaf auf Abram*; und siehe, Schrecken, dichte Finsternis überfiel ihn*.", footnotes: ["℘ 1Sam 26,12", "℘ Hi 4,13.14"] },
      { number: 13, text: "Und er sprach zu Abram: Ganz gewiss sollst du wissen*, dass deine Nachkommenschaft Fremdling sein wird in einem Land, das ihnen nicht gehört; und sie werden ihnen dienen, und man wird sie unterdrücken* vierhundert Jahre lang*.", footnotes: ["o. erkennen", "℘ 2Mo 1,11-14; 4Mo 20,15", "℘ 2Mo 12,40"] },
      { number: 14, text: "Aber ich werde die Nation auch richten, der sie dienen*; und danach werden sie ausziehen mit großer Habe*.", footnotes: ["℘ 2Mo 12,29", "℘ 2Mo 3,21.22; Apg 7,6.7"] },
      { number: 15, text: "Du aber, du wirst in Frieden zu deinen Vätern eingehen, wirst in gutem Alter begraben werden*.", footnotes: ["℘ Kap. 25,8"] },
      { number: 16, text: "Und in der vierten Generation werden sie hierher zurückkehren*; denn das Maß der Schuld des Amoriters* ist bis jetzt noch nicht voll*.", footnotes: ["℘ Kap. 48,21; 50,24; 2Mo 13,4.5; Ps 105,43", "℘ Kap. 10,16", "℘ 5Mo 9,4.5; 1Thes 2,16"] },
      { number: 17, text: "Und es geschah, als die Sonne untergegangen und Finsternis eingetreten war, siehe da, ein rauchender Ofen und eine Feuerfackel*, die zwischen diesen Stücken hindurchfuhr*.", footnotes: ["℘ 2Mo 20,18", "o. die zwischen diesen Stücken hindurchfuhren\n℘ Jer 34,18.19"] },
      { number: 18, text: "An jenem Tag schloss der HERR einen Bund* mit Abram und sprach: Deinen Nachkommen habe ich dieses Land gegeben*, vom Strom Ägyptens an bis zum großen Strom, dem Euphratstrom*:", footnotes: ["℘ Kap. 17,2.10; 2Mo 2,24; 3Mo 26,42; Gal 3,17", "℘ Kap. 12,7; Neh 9,8; Jer 32,22", "℘ Kap. 2,14; 2Mo 23,31; 34,24; 5Mo 1,7; 19,8; Jos 1,4; 1Kö 5,1"] },
      { number: 19, text: "die Keniter* und die Kenasiter und die Kadmoniter", footnotes: ["℘ 1Sam 15,6"] },
      { number: 20, text: "und die Hetiter und die Perisiter und die Refaïter*", footnotes: ["℘ Kap. 14,5; Jos 17,15"] },
      { number: 21, text: "und die Amoriter und die Kanaaniter und die Girgaschiter und die Jebusiter*.", footnotes: ["℘ 2Mo 3,8.17; 23,23; 33,2; 34,11; 4Mo 13,29; 21,32; 5Mo 20,17"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und Sarai, Abrams Frau, gebar ihm keine Kinder*. Sie hatte aber eine ägyptische Magd*, deren Name war Hagar.", heading: "Hagar und Ismael", footnotes: ["℘ Apg 7,5", "℘ Kap. 12,16"] },
      { number: 2, text: "Und Sarai sagte zu Abram: Siehe doch, der HERR hat mich verschlossen, dass ich nicht gebäre*. Geh doch zu meiner Magd ein! Vielleicht werde ich aus ihr erbaut werden*. Und Abram hörte auf Sarais Stimme.", footnotes: ["℘ Kap. 11,30", "d. h. durch sie zu einem Kind kommen\n℘ Kap. 30,3"] },
      { number: 3, text: "Da nahm Sarai, Abrams Frau, ihre Magd, die Ägypterin Hagar, nachdem Abram zehn Jahre im Land Kanaan gewohnt hatte, und gab sie Abram, ihrem Mann, ihm zur Frau*.", footnotes: ["℘ Kap. 30,4.9"] },
      { number: 4, text: "Und er ging zu Hagar ein, und sie wurde schwanger. Als sie aber sah, dass sie schwanger war, da wurde ihre Herrin gering in ihren Augen." },
      { number: 5, text: "Und Sarai sagte zu Abram: Das Unrecht an mir* liegt auf dir!* Ich selbst habe meine Magd in deinen Schoß gegeben; und nun, da sie sieht, dass sie schwanger ist, bin ich gering in ihren Augen. Der HERR richte zwischen mir und dir!", footnotes: ["w. Meine Unterdrückung", "℘ Kap. 31,53; Ri 11,27; 1Sam 24,13"] },
      { number: 6, text: "Und Abram sagte zu Sarai: Siehe, deine Magd ist in deiner Hand. Mache mit ihr, was gut ist in deinen Augen! Als Sarai sie aber demütigte*, da floh sie vor ihr.", footnotes: ["o. schlecht behandelte, unterdrückte"] },
      { number: 7, text: "Und der Engel des HERRN fand sie an einer Wasserquelle in der Wüste, an der Quelle auf dem Weg nach Schur*.", footnotes: ["℘ Kap. 20,1; 25,18; 1Sam 15,7"] },
      { number: 8, text: "Und er sprach: Hagar, Magd Sarais, woher kommst du, und wohin gehst du*? Und sie sagte: Vor Sarai, meiner Herrin, bin ich auf der Flucht.", footnotes: ["℘ Kap. 21,17; Ri 19,17; 1Kö 19,9; 2Kö 5,25"] },
      { number: 9, text: "Da sprach der Engel des HERRN zu ihr: Kehre zu deiner Herrin zurück, und demütige dich unter ihre Hände!*", footnotes: ["℘ 1Petr 2,18"] },
      { number: 10, text: "Und der Engel des HERRN sprach zu ihr: Ich will deine Nachkommen so sehr mehren, dass man sie nicht zählen kann vor Menge*.", footnotes: ["℘ Kap. 17,20; 21,13"] },
      { number: 11, text: "Und der Engel des HERRN sprach weiter zu ihr: Siehe, du bist schwanger und wirst einen Sohn gebären; dem sollst du den Namen Ismael* geben*, denn der HERR hat auf dein Elend gehört.", footnotes: ["d. h. Gott hört", "℘ Kap. 17,19; 21,17; Mt 1,21; Lk 1,13.31"] },
      { number: 12, text: "Und er, er wird ein Mensch wie ein Wildesel* sein; seine Hand gegen alle und die Hand aller gegen ihn, und allen seinen Brüdern setzt er sich vors Gesicht*.", footnotes: ["℘ Hi 39,5", "℘ Kap. 25,18"] },
      { number: 13, text: "Da nannte sie den Namen des HERRN, der zu ihr geredet hatte: Du bist ein Gott, der mich sieht*! Denn sie sagte: Habe ich nicht auch hier hinter dem hergesehen, der mich angesehen hat?*", footnotes: ["w. ein Gott des Sehens; hebr. el roi", "Andere meinen, der Text habe ursprünglich gelautet: Wahrlich, ich habe Gott gesehen und bin am Leben geblieben, nachdem ich ihn gesehen habe.\n℘ Kap. 32,31"] },
      { number: 14, text: "Darum nennt man den Brunnen: Beer-Lachai-Roi*; siehe, er ist zwischen Kadesch und Bered.", footnotes: ["d. h. Brunnen des Lebendigen, der mich gesehen hat\n℘ Kap. 24,62; 25,11"] },
      { number: 15, text: "Und Hagar gebar dem Abram einen Sohn*; und Abram gab seinem Sohn, den Hagar geboren hatte, den Namen Ismael*.", footnotes: ["℘ Kap. 21,9; Gal 4,22", "℘ Kap. 25,12; 1Chr 1,28"] },
      { number: 16, text: "Und Abram war 86 Jahre alt, als Hagar dem Abram Ismael gebar*.", footnotes: ["℘ Kap. 21,5"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und Abram war 99 Jahre alt, da erschien* der HERR dem Abram und sprach zu ihm: Ich bin Gott, der Allmächtige*. Lebe* vor meinem Angesicht*, und sei untadelig*!*", heading: "Bundesschluss mit Namensänderungen und Beschneidung", footnotes: ["℘ Kap. 12,7", "hebr. el schaddaj\n℘ Kap. 35,11; 43,14; 48,3; 2Mo 6,3; 4Mo 24,16; Lk 1,49; Offb 1,8", "w. Gehe", "℘ Kap. 24,40", "w. sei ganz mit mir", "℘ Kap. 6,9; Spr 10,9; 1Petr 5,10"] },
      { number: 2, text: "Und ich will meinen Bund zwischen mir und dir setzen* und will dich sehr, sehr mehren*.", footnotes: ["℘ Kap. 15,18; 1Chr 16,16", "℘ Kap. 13,16; 28,3"] },
      { number: 3, text: "Da fiel Abram auf sein Angesicht, und Gott redete mit ihm und sprach:" },
      { number: 4, text: "Ich, siehe, das ist mein Bund mit dir: Du wirst zum Vater einer Menge von Nationen werden*.", footnotes: ["℘ Kap. 12,2"] },
      { number: 5, text: "Und nicht mehr soll dein Name Abram* heißen, sondern Abraham* soll dein Name sein*! Denn zum Vater einer Menge von Nationen habe ich dich gemacht*.", footnotes: ["d. h. mein Vater ist erhaben", "d. h. Vater einer Menge", "℘ Kap. 32,29; 1Chr 1,27; Neh 9,7; Mt 1,1", "℘ Röm 4,17"] },
      { number: 6, text: "Und ich werde dich sehr, sehr fruchtbar machen*, und ich werde dich zu Nationen machen, und Könige werden aus dir hervorgehen*.", footnotes: ["℘ Kap. 13,16; 28,3", "℘ V. 16; Kap. 28,3.14; 35,11; 48,3.4"] },
      { number: 7, text: "Und ich werde meinen Bund aufrichten zwischen mir und dir und deinen Nachkommen nach dir durch alle ihre Generationen zu einem ewigen Bund*, um dir Gott zu sein* und deinen Nachkommen nach dir*.", footnotes: ["℘ Kap. 9,16; Ri 2,1; Ps 105,8.9; Röm 9,4", "℘ Kap. 26,24", "℘ Kap. 28,13; 3Mo 26,44; 1Chr 16,13.14; Lk 1,54.55"] },
      { number: 8, text: "Und ich werde dir und deinen Nachkommen nach dir das Land deiner Fremdlingschaft geben*, das ganze Land Kanaan, zum ewigen Besitz*, und ich werde ihnen Gott sein*.", footnotes: ["℘ Kap. 23,4; 28,4; 35,27; 37,1; 2Mo 6,4; 4Mo 10,29; 27,12; 5Mo 32,49; 34,4; Jos 1,2; Hebr 11,9", "℘ Kap. 12,7; 48,4; 2Mo 32,13; 3Mo 14,34; Hes 33,24", "℘ 2Mo 6,7; Hes 11,20; Sach 8,8; Hebr 8,10"] },
      { number: 9, text: "Und Gott sprach zu Abraham: Und du, du sollst meinen Bund halten, du und deine Nachkommen nach dir, durch ihre Generationen!" },
      { number: 10, text: "Dies ist mein Bund, den ihr halten sollt, zwischen mir und euch und deinen Nachkommen nach dir: Alles, was männlich ist, soll bei euch beschnitten werden*;", footnotes: ["℘ V. 23.27; Kap. 34,15; Jos 5,2; Joh 7,22; Apg 7,8; Röm 4,11.12"] },
      { number: 11, text: "und zwar sollt ihr am Fleisch eurer Vorhaut beschnitten werden! Das wird das Zeichen des Bundes sein zwischen mir und euch." },
      { number: 12, text: "Im Alter von acht Tagen* soll alles, was männlich ist, bei euch beschnitten werden*, durch eure Generationen, der im Haus geborene und der von irgendeinem Fremden für Geld gekaufte Sklave, der nicht von deiner Nachkommenschaft ist*;", footnotes: ["w. Als Sohn von acht Tagen", "℘ Kap. 21,4; 3Mo 12,3; Lk 1,59; 2,21", "℘ 2Mo 12,44.48.49"] },
      { number: 13, text: "beschnitten werden muss, der in deinem Haus geborene und der für dein Geld gekaufte Sklave! Und mein Bund an eurem Fleisch soll ein ewiger Bund sein*.", footnotes: ["℘ Kap. 9,16"] },
      { number: 14, text: "Ein unbeschnittener Männlicher aber, der am Fleisch seiner Vorhaut nicht beschnitten ist, diese Seele soll ausgerottet werden aus ihrem Volk*; meinen Bund hat er ungültig gemacht*!", footnotes: ["w. aus ihren Völkern; d. h. Volksgenossen\n℘ 2Mo 30,33.38", "℘ 2Mo 4,24-26"] },
      { number: 15, text: "Und Gott sprach zu Abraham: Deine Frau Sarai sollst du nicht mehr Sarai nennen, sondern Sara* soll ihr Name sein!", footnotes: ["d. h. Fürstin"] },
      { number: 16, text: "Und ich werde sie segnen, und auch von ihr gebe ich dir einen Sohn*; und ich werde sie segnen, und sie wird zu Nationen werden; Könige von Völkern sollen von ihr kommen*.", footnotes: ["℘ Kap. 15,4", "℘ V. 6"] },
      { number: 17, text: "Da fiel Abraham auf sein Angesicht und lachte und sprach in seinem Herzen: Sollte einem Hundertjährigen ein Kind geboren werden, und sollte Sara, eine Neunzigjährige, etwa gebären?*", footnotes: ["℘ Kap. 18,11.12; 21,5; Lk 1,18; Röm 4,19; Hebr 11,11"] },
      { number: 18, text: "Und Abraham sagte zu Gott: Möchte doch Ismael vor dir leben*!", footnotes: ["℘ Kap. 21,11"] },
      { number: 19, text: "Und Gott sprach: Nein, sondern Sara, deine Frau, wird dir einen Sohn gebären*. Und du sollst ihm den Namen Isaak* geben*! Und ich werde meinen Bund mit ihm aufrichten zu einem ewigen Bund* für seine Nachkommen nach ihm*.", footnotes: ["℘ Kap. 18,10", "hebr. jizchak; d. h. er wird lachen", "℘ Kap. 16,11; 21,2.3", "℘ Kap. 9,16", "℘ Kap. 26,3"] },
      { number: 20, text: "Aber auch für Ismael habe ich dich erhört: Siehe, ich werde ihn segnen und werde ihn fruchtbar machen und ihn sehr, sehr mehren*. Zwölf Fürsten wird er zeugen*, und ich werde ihn zu einer großen Nation machen*.", footnotes: ["℘ Kap. 16,10", "℘ Kap. 25,13-15", "℘ Kap. 12,2; 21,18"] },
      { number: 21, text: "Aber meinen Bund werde ich mit Isaak aufrichten, den Sara dir im nächsten Jahr um diese Zeit gebären wird*. —", footnotes: ["℘ Kap. 21,1.2"] },
      { number: 22, text: "Und er hörte auf, mit ihm zu reden; und Gott fuhr auf von Abraham*.", footnotes: ["℘ Kap. 18,33; 35,13"] },
      { number: 23, text: "Und Abraham nahm seinen Sohn Ismael und alle in seinem Haus geborenen und alle mit seinem Geld gekauften Sklaven, alles, was unter den Leuten des Hauses Abraham männlich war, und beschnitt das Fleisch ihrer Vorhaut an ebendiesem Tag, wie Gott zu ihm geredet hatte*.", footnotes: ["℘ V. 10"] },
      { number: 24, text: "Abraham war 99 Jahre alt*, als er am Fleisch seiner Vorhaut beschnitten wurde.", footnotes: ["℘ Kap. 18,11.12; 21,5; Lk 1,18; Röm 4,19; Hebr 11,11"] },
      { number: 25, text: "Und sein Sohn Ismael war dreizehn Jahre alt, als er am Fleisch seiner Vorhaut beschnitten wurde." },
      { number: 26, text: "So wurden an ebendiesem Tag Abraham und sein Sohn Ismael beschnitten" },
      { number: 27, text: "und alle Männer seines Hauses, der im Haus geborene und der von einem Fremden für Geld gekaufte Sklave wurden mit ihm beschnitten*.", footnotes: ["℘ V. 10"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und der HERR erschien* ihm bei den Terebinthen von Mamre*, als er bei der Hitze des Tages am Eingang des Zeltes saß.", heading: "Gottes Besuch bei Abraham", footnotes: ["℘ Kap. 12,7", "℘ Kap. 13,18"] },
      { number: 2, text: "Und er erhob seine Augen und sah: Und siehe, drei Männer standen vor ihm*; sobald er sie sah, lief er ihnen vom Eingang des Zeltes entgegen und verneigte sich zur Erde*", footnotes: ["℘ Jos 5,13", "℘ Kap. 33,3; 42,6"] },
      { number: 3, text: "und sagte: Herr, wenn ich denn Gunst gefunden habe in deinen Augen, so geh doch nicht an deinem Knecht vorüber!" },
      { number: 4, text: "Man hole doch ein wenig Wasser, dann wascht eure Füße*, und ruht euch aus* unter dem Baum!", footnotes: ["℘ Kap. 24,32; 43,24; Ri 19,21", "w. und lagert aufgestützt"] },
      { number: 5, text: "Ich will indessen einen Bissen Brot holen, dass ihr euer Herz stärkt*; danach mögt ihr weitergehen; wozu wäret ihr sonst* bei eurem Knecht vorbeigekommen? Und sie sprachen: Tu so, wie du geredet hast!", footnotes: ["℘ Ri 19,5", "o. darum seid ihr"] },
      { number: 6, text: "Da eilte Abraham ins Zelt zu Sara und sagte: Nimm schnell drei Maß Mehl, Weizengrieß, knete und mache Kuchen*!", footnotes: ["Das sind Brotfladen, die in heißer Asche rasch gebacken werden konnten.\n℘ Kap. 19,3; Ri 6,19; 1Sam 28,24; Ps 119,60"] },
      { number: 7, text: "Und Abraham lief zu den Rindern und nahm ein Kalb, zart und gut, und gab es dem Knecht; und der beeilte sich, es zuzubereiten." },
      { number: 8, text: "Und er holte Rahm und Milch und das Kalb, das er zubereitet hatte, und setzte es ihnen vor; und er stand vor ihnen* unter dem Baum, und sie aßen*.", footnotes: ["d. h. er bediente sie", "℘ Hebr 13,1.2"] },
      { number: 9, text: "Und sie sagten zu ihm: Wo ist deine Frau Sara? Und er sagte: Dort im Zelt." },
      { number: 10, text: "Da sprach er: Wahrlich, übers Jahr um diese Zeit komme ich wieder zu dir, siehe, dann hat Sara, deine Frau, einen Sohn*. Und Sara horchte am Eingang des Zeltes, der hinter ihm war.", footnotes: ["℘ Kap. 17,16.21; 21,2; Ri 13,3; 2Kö 4,16; Röm 9,9"] },
      { number: 11, text: "Abraham und Sara aber waren alt, hochbetagt*; es erging Sara nicht mehr nach der Frauen Weise.", footnotes: ["℘ Kap. 17,17.24; 24,1.36; Jos 13,1"] },
      { number: 12, text: "Und Sara lachte* in ihrem Innern und sagte: Nachdem ich alt geworden* bin, sollte ich noch Liebeslust haben? Und auch mein Herr* ist ja alt!", footnotes: ["℘ Kap. 17,17; 21,6", "w. verbraucht", "℘ 1Kor 11,3; 1Petr 3,6"] },
      { number: 13, text: "Da sprach der HERR zu Abraham: Warum hat Sara denn gelacht und gesagt: Sollte ich wirklich noch gebären, da ich doch alt bin?" },
      { number: 14, text: "Sollte für den HERRN eine Sache zu wunderbar sein*? Zur bestimmten Zeit komme ich wieder zu dir, übers Jahr um diese Zeit, dann hat Sara einen Sohn*.", footnotes: ["℘ Jer 32,17.27; Sach 8,6; Mt 19,26", "℘ Kap. 17,16.21; 21,2; Ri 13,3; 2Kö 4,16; Röm 9,9"] },
      { number: 15, text: "Doch Sara leugnete und sagte: Ich habe nicht gelacht! Denn sie fürchtete sich. Er aber sprach: Nein, du hast doch gelacht*!", footnotes: ["℘ Ps 44,22"] },
      { number: 16, text: "Und die Männer erhoben sich von dort und blickten auf die Fläche von Sodom hinab; und Abraham ging mit ihnen, sie zu begleiten.", heading: "Abrahams Bitte für Sodom" },
      { number: 17, text: "Der HERR aber sprach bei sich: Sollte ich vor Abraham verbergen, was ich tun will*?", footnotes: ["℘ 2Kö 4,27; Ps 25,14; Am 3,7"] },
      { number: 18, text: "Abraham soll doch zu einer großen und mächtigen Nation werden, und in ihm sollen gesegnet werden* alle Nationen der Erde*!", footnotes: ["o. sich Segen wünschen", "℘ Kap. 12,3"] },
      { number: 19, text: "Denn ich habe ihn erkannt, damit er seinen Söhnen und seinem Haus* nach ihm befehle, dass sie den Weg des HERRN bewahren, Gerechtigkeit und Recht zu üben*, damit der HERR auf Abraham kommen lasse, was er über ihn geredet hat.", footnotes: ["℘ Kap. 35,2", "o. indem sie Gerechtigkeit und Recht üben\n℘ 5Mo 4,9.10; 2Chr 14,3.4; Ps 78,5; 1Tim 3,4.5"] },
      { number: 20, text: "Und der HERR sprach: Das Klagegeschrei über Sodom und Gomorra, wahrlich, es ist groß, und ihre Sünde, wahrlich, sie ist sehr schwer*.", footnotes: ["℘ Kap. 13,13; Jes 3,9; Mt 11,23; Jud 7"] },
      { number: 21, text: "Ich will doch hinabgehen und sehen*, ob sie ganz nach ihrem Geschrei*, das vor mich gekommen ist*, getan haben*; und wenn nicht, so will ich es wissen*.", footnotes: ["℘ Kap. 6,12; 11,5", "d. i. nach dem Geschrei über die Stadt", "℘ Jon 1,2; Offb 18,5", "Das ist die wohl ursprüngliche Aussage des Textes; Mas. T. w. ob sie nach ihrem Geschrei Vernichtung gewirkt haben", "o. erkennen"] },
      { number: 22, text: "Und die Männer wandten sich von dort und gingen nach Sodom*; Abraham aber blieb noch vor dem HERRN stehen*.", footnotes: ["℘ Kap. 19,1", "Die alten Abschreiber merken hier an, dass sie den Text geändert haben; der ursprüngliche Text lautete: »Der HERR aber blieb noch vor Abraham stehen.«\n℘ Kap. 19,27"] },
      { number: 23, text: "Und Abraham trat hinzu und sagte: Willst du wirklich den Gerechten mit dem Ungerechten* wegraffen?*", footnotes: ["o. Gottlosen", "℘ 4Mo 16,22; 2Sam 24,17; Mt 13,29"] },
      { number: 24, text: "Vielleicht gibt es fünfzig Gerechte innerhalb der Stadt. Willst du sie denn wegraffen und dem Ort nicht vergeben wegen der fünfzig Gerechten, die darin sind?" },
      { number: 25, text: "Fern sei es von dir, so etwas zu tun, den Gerechten mit dem Ungerechten* zu töten, so dass der Ungerechte wäre wie der Gerechte; fern sei es von dir! Sollte der Richter der ganzen Erde nicht Recht üben*?", footnotes: ["o. Gottlosen", "℘ 4Mo 16,22; 1Chr 16,33; 2Chr 19,7; Hi 34,10-12; Ps 7,12; 50,6; 58,12; 75,3; Röm 3,5.6; Hebr 6,10; 12,23"] },
      { number: 26, text: "Da sprach der HERR: Wenn ich in Sodom fünfzig Gerechte in der Stadt finde, so will ich ihretwegen* dem ganzen Ort vergeben*.", footnotes: ["o. in ihrem Interesse", "℘ Jes 65,8; Jer 5,1"] },
      { number: 27, text: "Und Abraham antwortete und sagte: Siehe doch, ich habe mich erdreistet, zu dem Herrn zu reden*, obwohl ich Staub und Asche bin.", footnotes: ["℘ 2Mo 32,11-13; Jak 5,16"] },
      { number: 28, text: "Vielleicht fehlen an den fünfzig Gerechten nur fünf. Willst du wegen der fünf die ganze Stadt vernichten? Da sprach er: Ich will sie nicht vernichten, wenn ich dort 45 finde." },
      { number: 29, text: "Und er fuhr fort, weiter zu ihm zu reden, und sagte: Vielleicht werden dort vierzig gefunden. Und er sprach: Ich will es nicht tun wegen* der vierzig.", footnotes: ["o. im Interesse"] },
      { number: 30, text: "Und er sagte: Der Herr möge doch nicht zürnen*, dass ich noch einmal rede!* Vielleicht werden dort dreißig gefunden. Und er sprach: Ich will es nicht tun, wenn ich dort dreißig finde.", footnotes: ["℘ Kap. 44,18", "℘ Ri 6,39"] },
      { number: 31, text: "Da sagte er: Siehe doch, ich habe mich erdreistet, zu dem Herrn zu reden; vielleicht werden dort zwanzig gefunden. Und er sprach: Ich will nicht vernichten wegen* der zwanzig willen.", footnotes: ["o. im Interesse"] },
      { number: 32, text: "Da sagte er: Der Herr möge doch nicht zürnen*, ich will nur noch dieses Mal reden. Vielleicht werden dort zehn gefunden. Und er sprach: Ich will nicht vernichten wegen* der zehn*.", footnotes: ["℘ Kap. 44,18", "o. im Interesse", "℘ Jak 5,16"] },
      { number: 33, text: "Und der HERR ging weg, als er mit Abraham ausgeredet hatte*; und Abraham kehrte zurück an seinen Ort*.", footnotes: ["℘ Kap. 17,22", "℘ Kap. 32,1"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und die beiden Engel kamen am Abend nach Sodom*, als Lot gerade im Tor von Sodom saß*. Und als Lot sie sah, stand er auf, ging ihnen entgegen und verneigte sich mit dem Gesicht zur Erde;", heading: "Das Gericht über Sodom und Gomorra — Rettung Lots", footnotes: ["℘ Kap. 18,22", "℘ Kap. 13,12; Rt 4,1; Hi 29,7"] },
      { number: 2, text: "und er sprach: Ach, siehe, meine Herren! Kehrt doch ein in das Haus eures Knechtes, und übernachtet, und wascht eure Füße*; morgen früh mögt ihr dann eures Weges ziehen!* Aber sie sagten: Nein, sondern wir wollen auf dem Platz* übernachten.", footnotes: ["℘ 2Sam 11,8; Ri 19,20", "℘ Hi 31,32", "d. i. der Marktplatz am Stadttor"] },
      { number: 3, text: "Als er jedoch sehr in sie drang, kehrten sie bei ihm ein und kamen in sein Haus. Und er machte ihnen ein Mahl, backte ungesäuertes Brot, und sie aßen*.", footnotes: ["℘ Kap. 18,6.8"] },
      { number: 4, text: "Noch hatten sie sich nicht niedergelegt, da umringten die Männer der Stadt, die Männer von Sodom, das Haus, vom Knaben bis zum Greis, das ganze Volk von allen Enden* der Stadt.", footnotes: ["w. vom äußersten Ende"] },
      { number: 5, text: "Und sie riefen nach Lot und sagten zu ihm: Wo sind die Männer, die diese Nacht zu dir gekommen sind? Führe sie zu uns heraus, dass wir sie erkennen*!", footnotes: ["℘ 3Mo 18,22; 20,13; Ri 19,22; Röm 1,24.27; Jud 7"] },
      { number: 6, text: "Da trat Lot zu ihnen hinaus an den Eingang und schloss die Tür hinter sich zu;" },
      { number: 7, text: "und er sagte: Tut doch nichts Böses, meine Brüder!" },
      { number: 8, text: "Seht doch, ich habe zwei Töchter, die keinen Mann erkannt haben; die will ich zu euch herausbringen. Tut ihnen, wie es gut ist in euren Augen! Nur diesen Männern tut nichts, da sie nun einmal unter den Schatten meines Daches* gekommen sind!*", footnotes: ["w. Gebälks", "℘ Ri 19,23.24"] },
      { number: 9, text: "Aber sie sagten: Zurück da! Und sie sagten: Da ist einer allein gekommen, sich als Fremder hier aufzuhalten, und will sich schon als Richter aufspielen*! Nun, wir wollen dir Schlimmeres antun als jenen. Und sie drangen hart ein auf den Mann, auf Lot, und machten sich daran, die Tür aufzubrechen.", footnotes: ["w. will richten, ja richten\n℘ 2Mo 2,14; Spr 9,7"] },
      { number: 10, text: "Da streckten die Männer ihre Hand aus und brachten Lot zu sich herein ins Haus; und die Tür verschlossen sie." },
      { number: 11, text: "Die Männer aber, die am Eingang des Hauses waren, schlugen sie mit Blindheit*, vom kleinsten bis zum größten, so dass sie sich vergeblich mühten*, den Eingang zu finden.", footnotes: ["℘ 2Kö 6,18", "w. dass sie müde wurden"] },
      { number: 12, text: "Und die Männer sagten zu Lot: Hast du hier noch jemanden? Einen Schwiegersohn und deine Söhne und deine Töchter oder einen, der sonst noch in der Stadt zu dir gehört? Führe sie hinaus* aus diesem Ort!*", footnotes: ["o. Wen du hier noch hast — einen Schwiegersohn und Söhne und Töchter von dir und wer sonst in der Stadt zu dir gehören mag —, führe ihn hinaus", "℘ 4Mo 16,26"] },
      { number: 13, text: "Denn wir werden diesen Ort vernichten, weil das Geschrei über sie* groß geworden ist vor dem HERRN*; und der HERR hat uns gesandt, die Stadt* zu vernichten*.", footnotes: ["d. i. über die Einwohner", "℘ Kap. 18,20", "w. sie", "℘ 4Mo 16,21"] },
      { number: 14, text: "Da ging Lot hinaus und redete zu seinen Schwiegersöhnen, die seine Töchter nehmen sollten, und sagte: Macht euch auf, geht aus diesem Ort! Denn der HERR wird die Stadt vernichten. Aber er war in den Augen seiner Schwiegersöhne wie einer, der Scherz treibt." },
      { number: 15, text: "Und sobald die Morgenröte aufging, drängten die Engel Lot zur Eile und sagten: Mache dich auf, nimm deine Frau und deine beiden Töchter, die hier sind*, damit du nicht weggerafft wirst durch die Schuld* der Stadt*!", footnotes: ["w. die gefunden werden", "o. in der Bestrafung", "℘ Offb 18,4"] },
      { number: 16, text: "Als er aber zögerte, ergriffen die Männer seine Hand und die Hand seiner Frau und die Hand seiner beiden Töchter, weil der HERR ihn verschonen wollte, und führten ihn hinaus und ließen ihn außerhalb der Stadt." },
      { number: 17, text: "Und es geschah, als sie sie ins Freie hinausgeführt hatten, da sprach er: Rette dich, es geht um dein Leben! Sieh nicht hinter dich*, und bleib nicht stehen in der ganzen Ebene* des Jordan; rette dich auf das Gebirge, damit du nicht weggerafft wirst*!", footnotes: ["℘ Lk 17,31", "w. in der ganzen Umgebung, o. in dem ganzen Umkreis", "℘ Jer 48,6; Mt 24,16"] },
      { number: 18, text: "Da sagte Lot zu ihnen: Ach, nein, Herr!" },
      { number: 19, text: "Siehe doch, dein Knecht hat Gunst gefunden in deinen Augen*, und du hast deine Gnade, die du an mir erwiesen hast, groß gemacht, meine Seele am Leben zu erhalten. Aber ich kann mich nicht auf das Gebirge retten, es könnte das Unheil mich ereilen*, dass ich sterbe.", footnotes: ["℘ Kap. 6,8", "w. sich an mich heften"] },
      { number: 20, text: "Siehe doch, diese Stadt da ist nahe, dahin zu fliehen, sie ist ja nur klein*; ich könnte mich doch dahin retten — ist sie nicht klein*? —, damit meine Seele am Leben bleibt.", footnotes: ["w. gering an Einwohnerzahl", "w. gering an Einwohnerzahl"] },
      { number: 21, text: "Da sprach er zu ihm: Siehe, auch darin habe ich Rücksicht auf dich genommen*, dass ich die Stadt nicht umkehre, von der du geredet hast*.", footnotes: ["w. auch in dieser Sache habe ich dein Gesicht erhoben", "℘ 2Mo 33,17"] },
      { number: 22, text: "Schnell, rette dich dorthin! Denn ich kann nichts tun, bis du dorthin gekommen bist. Daher nennt man die Stadt Zoar*.", footnotes: ["d. h. gering, klein sein\n℘ 5Mo 34,3; Jes 15,5"] },
      { number: 23, text: "Die Sonne ging über der Erde auf, als Lot nach Zoar kam." },
      { number: 24, text: "Da ließ der HERR auf Sodom und auf Gomorra Schwefel und Feuer regnen von dem HERRN aus dem Himmel*", footnotes: ["℘ 5Mo 29,22; Hi 18,15; Ps 11,6; Jes 1,9; 13,19; Kla 4,6; Am 4,11; Lk 17,29; 2Petr 2,6; Offb 14,10"] },
      { number: 25, text: "und kehrte diese Städte um und die ganze Ebene* des Jordan und alle Bewohner der Städte und das Gewächs des Erdbodens*.", footnotes: ["w. die ganze Umgebung, o. den ganzen Umkreis", "℘ Kap. 13,10; Jer 20,16; 23,14; Zef 2,9; Mt 10,15"] },
      { number: 26, text: "Aber seine Frau sah sich hinter ihm um; da wurde sie zu einer Salzsäule*.", footnotes: ["℘ Lk 17,31.32"] },
      { number: 27, text: "Und Abraham machte sich früh am Morgen auf an den Ort, wo er vor dem HERRN gestanden hatte*.", footnotes: ["℘ Kap. 18,22"] },
      { number: 28, text: "Und er blickte hinab auf die Fläche von Sodom und Gomorra und auf die ganze Fläche des Landes in der Ebene* des Jordan, und er sah: Und siehe, Rauch stieg vom Land auf, wie der Rauch eines Schmelzofens*.", footnotes: ["w. in der ganzen Umgebung, o. in dem ganzen Umkreis", "℘ 2Mo 19,18; Mal 3,2; Offb 9,2"] },
      { number: 29, text: "Und es geschah, als Gott die Städte der Ebene* des Jordan vernichtete, da dachte Gott an Abraham und geleitete Lot mitten aus der Umkehrung, als er die Städte umkehrte, in denen Lot gewohnt hatte*.", footnotes: ["w. Umgebung, o. des Umkreises", "℘ Kap. 8,1; 2Petr 2,7"] },
      { number: 30, text: "Lot aber zog von Zoar hinauf und wohnte im Gebirge, er und seine beiden Töchter mit ihm; denn er fürchtete sich in Zoar zu wohnen. Und er wohnte in einer Höhle, er und seine beiden Töchter.", heading: "Lot und seine Töchter" },
      { number: 31, text: "Und die Erstgeborene sprach zu der Jüngeren: Unser Vater ist alt, und es gibt keinen Mann im Land, der zu uns eingehen könnte nach der Weise aller Welt." },
      { number: 32, text: "Komm, lass uns unserem Vater Wein zu trinken geben und bei ihm liegen, damit wir von unserem Vater Nachkommenschaft am Leben erhalten*!*", footnotes: ["o. ins Leben rufen", "℘ 3Mo 18,7"] },
      { number: 33, text: "Und sie gaben ihrem Vater in jener Nacht Wein zu trinken, und die Erstgeborene ging hinein und legte sich zu ihrem Vater; er aber merkte* weder etwas von ihrem Niederlegen noch von ihrem Aufstehen.", footnotes: ["o. erkannte"] },
      { number: 34, text: "Und es geschah am Morgen, da sprach die Erstgeborene zu der Jüngeren: Siehe, ich habe mich gestern Abend zu meinem Vater gelegt. Lass uns ihm auch diese Nacht Wein zu trinken geben, dann geh hinein, liege bei ihm, damit wir von unserem Vater Nachkommenschaft am Leben erhalten*!", footnotes: ["o. ins Leben rufen"] },
      { number: 35, text: "Da gaben sie auch in dieser Nacht ihrem Vater Wein zu trinken, und die Jüngere stand auf und lag bei ihm; und er merkte* weder etwas von ihrem Niederlegen noch von ihrem Aufstehen.", footnotes: ["o. erkannte"] },
      { number: 36, text: "Und die beiden Töchter Lots wurden von ihrem Vater schwanger." },
      { number: 37, text: "Und die Erstgeborene gebar einen Sohn, und sie gab ihm den Namen Moab*; der ist der Vater der Moabiter* bis auf diesen Tag*.", footnotes: ["Moab klingt an hebr. mi-ab an; d. h. vom Vater", "w. Vater Moabs", "℘ 5Mo 2,9"] },
      { number: 38, text: "Und die Jüngere, auch sie gebar einen Sohn, und sie gab ihm den Namen Ben-Ammi*. Der ist der Vater der Söhne Ammon bis auf diesen Tag*.", footnotes: ["d. h. Sohn meines Blutsverwandten", "℘ 5Mo 2,19; 1Sam 14,47; Ps 83,9; Zef 2,8"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und Abraham brach von dort auf* ins Land des Südens* und wohnte zwischen Kadesch und Schur*. Als er sich in Gerar als Fremder aufhielt*,", heading: "Abraham und Sara bei Abimelech", footnotes: ["o. zog weiter; w. riss die Zeltpflöcke heraus", "℘ Kap. 12,9", "℘ Kap. 16,7", "℘ Kap. 21,34; 26,1.6"] },
      { number: 2, text: "sagte Abraham von seiner Frau Sara: Sie ist meine Schwester*. Da sandte Abimelech*, der König von Gerar, hin und ließ Sara holen*.", footnotes: ["℘ Kap. 12,13.15", "Abimelech war Titel vieler kanaanäischer Stadtkönige.", "w. nahm Sara\n℘ Kap. 44,18"] },
      { number: 3, text: "Und Gott kam zu Abimelech im Traum der Nacht* und sprach zu ihm: Siehe, du bist des Todes wegen der Frau, die du genommen hast; denn sie ist eine verheiratete Frau*.", footnotes: ["℘ Kap. 28,12; 31,24; 37,5.9; 40,5; 46,2; Hi 4,13; 33,15-17; Mt 1,20", "w. eine Frau, die einem Eheherrn gehört"] },
      { number: 4, text: "Abimelech aber hatte sich ihr nicht genaht; und er sprach: Herr, willst du denn eine gerechte Nation erschlagen?" },
      { number: 5, text: "Hat er nicht selbst zu mir gesagt: Sie ist meine Schwester? Und sie, auch sie selbst hat gesagt: Er ist mein Bruder. In Lauterkeit meines Herzens und in Unschuld meiner Hände habe ich das getan*.", footnotes: ["℘ Ps 7,9"] },
      { number: 6, text: "Da sprach Gott im Traum zu ihm: Auch ich weiß*, dass du in Lauterkeit deines Herzens dies getan hast, und so habe ich selbst dich auch davon abgehalten, gegen mich zu sündigen*; darum habe ich dir nicht gestattet, sie zu berühren*.", footnotes: ["o. erkenne", "℘ 1Sam 25,26; Spr 6,29", "℘ Kap. 31,7"] },
      { number: 7, text: "Und nun, gib die Frau des Mannes zurück! Denn er ist ein Prophet* und wird für dich bitten, dass du am Leben bleibst*! Wenn du sie aber nicht zurückgibst, so wisse*, dass du sterben musst, du und alles, was zu dir gehört.", footnotes: ["℘ Ps 105,14.15", "℘ 2Chr 30,18", "o. erkenne"] },
      { number: 8, text: "Und Abimelech stand früh am Morgen auf und rief alle seine Knechte und redete alle diese Worte vor ihren Ohren; da fürchteten sich die Männer sehr." },
      { number: 9, text: "Und Abimelech rief Abraham und sagte zu ihm: Was hast du uns angetan*! Und was habe ich an dir gesündigt, dass du über mich und über mein Königreich eine so große Sünde gebracht hast? Dinge*, die nicht getan werden dürfen, hast du mir angetan.", footnotes: ["℘ Kap. 12,18", "w. Taten"] },
      { number: 10, text: "Und Abimelech sagte zu Abraham: Was hast du damit beabsichtigt, dass du dies getan hast?" },
      { number: 11, text: "Und Abraham sprach: Weil ich mir sagte: Gewiss gibt es keine Gottesfurcht an diesem Ort, und sie werden mich erschlagen um meiner Frau willen*.", footnotes: ["℘ Kap. 12,12"] },
      { number: 12, text: "Und sie ist auch wirklich meine Schwester; die Tochter meines Vaters ist sie, nur nicht die Tochter meiner Mutter; so ist sie meine Frau geworden." },
      { number: 13, text: "Und es geschah, als Gott mich aus meines Vaters Haus ziehen und umherirren ließ, da sagte ich zu ihr: Das sei deine Gefälligkeit*, die du mir erweisen mögest: An jedem Ort, wohin wir kommen, sage von mir: Er ist mein Bruder!", footnotes: ["w. Gnade"] },
      { number: 14, text: "Da nahm Abimelech Schafe und Rinder und Knechte und Mägde* und gab sie dem Abraham; und auch Sara, seine Frau, gab er ihm zurück.", footnotes: ["℘ Kap. 12,16"] },
      { number: 15, text: "Und Abimelech sagte: Siehe, mein Land liegt vor dir*; wohne, wo es gut ist in deinen Augen*!", footnotes: ["℘ Kap. 13,9", "℘ Kap. 34,10; 42,34"] },
      { number: 16, text: "Und zu Sara sagte er: Siehe, ich habe deinem Bruder tausend Silberschekel gegeben; siehe, das sei zu deinen Gunsten eine Augendecke* für alle, die bei dir sind, und du bist in allem gerechtfertigt*.", footnotes: ["Das bedeutete die Bestätigung unverletzter Frauenehre.", "so mit anderer Wortabtrennung; Mas. T.: und alles und eine Gerechtfertigte"] },
      { number: 17, text: "Und Abraham betete zu Gott; und Gott heilte Abimelech und seine Frau und seine Mägde, so dass sie wieder Kinder gebaren*.", footnotes: ["℘ Kap. 12,17; Hi 42,9; Jak 5,16"] },
      { number: 18, text: "Denn der HERR hatte jeden Mutterleib dem Haus Abimelech vollständig verschlossen um Saras willen, der Frau Abrahams." },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und der HERR suchte Sara heim*, wie er gesagt hatte, und der HERR tat an Sara, wie er geredet hatte*.", heading: "Die Geburt Isaaks", footnotes: ["℘ 1Sam 2,21", "℘ Kap. 17,21; 2Kö 4,17"] },
      { number: 2, text: "Und Sara wurde schwanger und gebar dem Abraham einen Sohn* in seinem Alter, zu der bestimmten Zeit, die Gott ihm gesagt hatte*.", footnotes: ["℘ Gal 4,22", "℘ Kap. 18,10.14; Gal 4,28; Hebr 6,15; 11,11"] },
      { number: 3, text: "Und Abraham gab seinem Sohn, der ihm geboren worden war, den Sara ihm geboren hatte, den Namen Isaak*.", footnotes: ["℘ Kap. 17,19; 25,19; Jos 24,3; Mt 1,2; Lk 3,34"] },
      { number: 4, text: "Und Abraham beschnitt seinen Sohn Isaak, als er acht Tage alt war, wie Gott ihm geboten hatte*.", footnotes: ["℘ Kap. 17,10-14; Apg 7,8"] },
      { number: 5, text: "Abraham aber war hundert Jahre alt, als ihm sein Sohn Isaak geboren wurde*.", footnotes: ["℘ Kap. 16,16; 17,17; 25,26"] },
      { number: 6, text: "Und Sara sagte: Gott hat mir ein Lachen bereitet*; jeder, der es hört, wird mir zulachen*.", footnotes: ["s. Anm. zu Kap. 17,19", "w. mir lachen; das kann heißen »mit mir« o. »über mich lachen«\n℘ Kap. 18,12"] },
      { number: 7, text: "Und sie sagte: Wer hätte je dem Abraham verkündet: Sara stillt einen Sohn*! Denn ich habe ihm in seinem Alter einen Sohn geboren.", footnotes: ["w. Söhne"] },
      { number: 8, text: "Und das Kind wuchs und wurde entwöhnt*; und an dem Tag, als Isaak entwöhnt wurde, bereitete Abraham ein großes Mahl.", heading: "Ausweisung Hagars mit Ismael", footnotes: ["℘ 1Sam 1,24"] },
      { number: 9, text: "Und Sara sah den Sohn der Ägypterin Hagar, den diese dem Abraham geboren hatte*, scherzen*.", footnotes: ["℘ Kap. 16,15", "o. sich lustig machen. — LXX und Vulg. lesen: mit ihrem Sohn Isaak spielen"] },
      { number: 10, text: "Da sagte sie zu Abraham: Vertreibe diese Magd und ihren Sohn, denn der Sohn dieser Magd soll nicht mit meinem Sohn Erbe werden, mit Isaak*!", footnotes: ["℘ Ri 11,2; Gal 4,29.30"] },
      { number: 11, text: "Und dieses Wort* war sehr übel in Abrahams Augen um seines Sohnes willen*.", footnotes: ["o. Und diese Sache", "℘ Kap. 17,18"] },
      { number: 12, text: "Aber Gott sprach zu Abraham: Lass es nicht übel sein in deinen Augen, wegen des Jungen und wegen deiner Magd; in allem, was Sara zu dir sagt, höre auf ihre Stimme! Denn nach Isaak soll dir die Nachkommenschaft genannt werden*.", footnotes: ["℘ Röm 9,7; Hebr 11,18"] },
      { number: 13, text: "Doch auch den Sohn der Magd werde ich zu einer Nation machen, weil er dein Nachkomme ist*.", footnotes: ["℘ Kap. 16,10"] },
      { number: 14, text: "Und Abraham machte sich früh am Morgen auf*, und er nahm Brot und einen Schlauch Wasser und gab es der Hagar, legte es auf ihre Schulter und gab ihr das Kind* und schickte sie fort. Da ging sie hin und irrte in der Wüste von Beerscheba umher.", footnotes: ["℘ Kap. 22,3; 28,18; Jos 3,1; 1Sam 15,12; 2Chr 29,20", "Andere üs. mit LXX und der syr. Üs.: gab es der Hagar, das Kind aber setzte er auf ihre Schulter"] },
      { number: 15, text: "Als aber das Wasser im Schlauch zu Ende war, warf sie das Kind unter einen der Sträucher;" },
      { number: 16, text: "und sie ging und setzte sich gegenüber hin, einen Bogenschuss weit entfernt, denn sie sagte sich: Ich kann das Sterben des Kindes nicht ansehen. So setzte sie sich gegenüber hin, erhob ihre Stimme* und weinte.", footnotes: ["LXX: und das Kind erhob seine Stimme"] },
      { number: 17, text: "Gott aber hörte die Stimme des Jungen*. Da rief der Engel Gottes der Hagar vom Himmel zu und sprach zu ihr: Was ist dir, Hagar?* Fürchte dich nicht! Denn Gott hat auf die Stimme des Jungen gehört, dort wo er ist*.", footnotes: ["℘ Kap. 16,11; Ps 10,14", "℘ Kap. 16,8", "℘ Kap. 44,18"] },
      { number: 18, text: "Steh auf, nimm den Jungen, und fasse ihn mit deiner Hand! Denn ich will ihn zu einer großen Nation machen*.", footnotes: ["℘ Kap. 17,20"] },
      { number: 19, text: "Und Gott öffnete ihre Augen, und sie sah einen Wasserbrunnen; da ging sie hin und füllte den Schlauch mit Wasser und gab dem Jungen zu trinken." },
      { number: 20, text: "Gott aber war mit dem Jungen*, und er wurde groß und wohnte in der Wüste; und er wurde ein Bogenschütze.", footnotes: ["℘ Kap. 39,2"] },
      { number: 21, text: "Und er wohnte in der Wüste Paran*, und seine Mutter nahm ihm eine Frau aus dem Land Ägypten*.", footnotes: ["℘ 4Mo 10,12; 1Sam 25,1", "℘ Kap. 16,3"] },
      { number: 22, text: "Und es geschah zu dieser Zeit, da sagten Abimelech und Pichol, sein Heeroberster*, zu Abraham: Gott ist mit dir in allem, was du tust*.", heading: "Abrahams Vertrag mit Abimelech", footnotes: ["℘ Kap. 26,26", "℘ Kap. 26,28; 39,3; 1Sam 24,22"] },
      { number: 23, text: "So schwöre mir nun hier bei Gott*, dass du weder an mir noch an meinem Spross noch an meinen Nachkommen betrügerisch handeln wirst! Nach der Gnade, die ich dir erwiesen habe, sollst du an mir tun und an dem Land, in dem du dich als Fremder aufhältst.", footnotes: ["℘ Kap. 26,28; 39,3; 1Sam 24,22"] },
      { number: 24, text: "Da sprach Abraham: Ich will schwören." },
      { number: 25, text: "Abraham aber stellte Abimelech zur Rede wegen eines Wasserbrunnens, den Abimelechs Knechte mit Gewalt weggenommen hatten*.", footnotes: ["℘ Kap. 26,20.21"] },
      { number: 26, text: "Da sagte Abimelech: Ich weiß* nicht, wer das getan hat; weder hast du es mir berichtet, noch habe ich davon gehört, außer heute.", footnotes: ["o. erkenne"] },
      { number: 27, text: "Da nahm Abraham Schafe und Rinder und gab sie Abimelech, und die beiden schlossen einen Bund*.", footnotes: ["℘ Kap. 26,31"] },
      { number: 28, text: "Und Abraham stellte sieben Schaflämmer der Herde beiseite." },
      { number: 29, text: "Da sagte Abimelech zu Abraham: Was sollen diese sieben Schaflämmer, die du beiseite gestellt hast?" },
      { number: 30, text: "Und er sagte: Die sieben Schaflämmer sollst du von meiner Hand annehmen, damit mir das zum Zeugnis sei, dass ich diesen Brunnen gegraben habe*.", footnotes: ["℘ Kap. 26,18"] },
      { number: 31, text: "Daher nennt man diesen Ort Beerscheba*, weil sie beide dort geschworen hatten*.", footnotes: ["d. h. Sieben-Brunnen, o. Schwurbrunnen\n℘ Kap. 26,23; 46,1; Jos 15,28; 2Sam 24,7; 1Kö 19,3", "℘ Kap. 26,33"] },
      { number: 32, text: "So schlossen sie einen Bund in Beerscheba. Dann machten Abimelech und sein Heeroberster Pichol sich auf und kehrten in das Land der Philister zurück." },
      { number: 33, text: "Und Abraham* pflanzte eine Tamariske in Beerscheba und rief dort den Namen des HERRN*, des ewigen Gottes*, an.", footnotes: ["w. er", "℘ Kap. 12,8", "hebr. el olam\n℘ Jes 40,28; Jer 10,10"] },
      { number: 34, text: "Und Abraham hielt sich noch lange Zeit* als Fremder im Land der Philister auf*.", footnotes: ["w. viele Tage", "℘ Kap. 20,1"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Und es geschah nach diesen Dingen*, da prüfte* Gott den Abraham. Und er sprach zu ihm: Abraham! Und er sagte: Hier bin ich!*", heading: "Abrahams Opfer", footnotes: ["℘ Kap. 15,1", "o. versuchte; o. stellte . . . auf die Probe", "℘ Kap. 37,13; 46,2; 2Mo 3,4; 1Sam 3,4; Jes 6,8; Apg 9,10"] },
      { number: 2, text: "Und er sprach: Nimm deinen Sohn, deinen einzigen, den du lieb hast*, den Isaak*, und ziehe hin in das Land Morija*, und opfere ihn dort als Brandopfer* auf einem der Berge, den ich dir nennen werde!", footnotes: ["℘ Mt 3,17", "℘ Kap. 21,3", "℘ 2Chr 3,1", "℘ 2Kö 3,27"] },
      { number: 3, text: "Da machte sich Abraham früh am Morgen auf*, sattelte seinen Esel und nahm seine beiden Knechte mit sich und seinen Sohn Isaak. Er spaltete Holz zum Brandopfer und machte sich auf und ging an den Ort, den Gott ihm genannt hatte.", footnotes: ["℘ Kap. 21,14"] },
      { number: 4, text: "Am dritten Tag erhob Abraham seine Augen und sah den Ort von fern." },
      { number: 5, text: "Da sagte Abraham zu seinen Knechten: Bleibt ihr mit dem Esel hier! Ich aber und der Junge wollen dorthin gehen und anbeten und zu euch zurückkehren." },
      { number: 6, text: "Und Abraham nahm das Holz zum Brandopfer und legte es auf seinen Sohn Isaak, und in seine Hand nahm er das Feuer und das Messer. Und sie gingen beide miteinander*.", footnotes: ["℘ 2Kö 2,6"] },
      { number: 7, text: "Da sprach Isaak zu seinem Vater Abraham und sagte: Mein Vater! Und er sprach: Hier bin ich, mein Sohn. Und er sagte: Siehe, das Feuer und das Holz! Wo aber ist das Schaf zum Brandopfer?" },
      { number: 8, text: "Da sagte Abraham: Gott wird sich das Schaf zum Brandopfer ersehen, mein Sohn. Und sie gingen beide miteinander*.", footnotes: ["℘ 2Kö 2,6"] },
      { number: 9, text: "Und sie kamen an den Ort, den Gott ihm genannt hatte. Und Abraham baute dort den Altar und schichtete das Holz auf. Dann band er seinen Sohn Isaak und legte ihn auf den Altar oben auf das Holz." },
      { number: 10, text: "Und Abraham streckte seine Hand aus und nahm das Messer, um seinen Sohn zu schlachten*.", footnotes: ["℘ Hebr 11,17; Jak 2,21"] },
      { number: 11, text: "Da rief ihm der Engel des HERRN* vom Himmel her zu und sprach: Abraham, Abraham! Und er sagte: Hier bin ich*!", footnotes: ["℘ Ri 2,1", "℘ Kap. 37,13; 46,2; 2Mo 3,4; 1Sam 3,4; Jes 6,8; Apg 9,10"] },
      { number: 12, text: "Und er sprach: Strecke deine Hand nicht aus nach dem Jungen, und tu ihm nichts! Denn nun habe ich erkannt, dass du Gott fürchtest, da du deinen Sohn, deinen einzigen, mir nicht vorenthalten hast." },
      { number: 13, text: "Und Abraham erhob seine Augen und sah; und siehe, da war ein Widder hinten im Gestrüpp an seinen Hörnern festgehalten. Da ging Abraham hin, nahm den Widder und opferte ihn anstelle seines Sohnes als Brandopfer." },
      { number: 14, text: "Und Abraham gab diesem Ort den Namen »Der HERR wird ersehen*«, von dem man heute noch sagt: Auf dem Berg des HERRN wird ersehen*.", footnotes: ["hebr. jahwe jireh", "o. Auf dem Berg, wo der HERR sich sehen lässt. — LXX: Auf dem Berg »Der HERR lässt sich sehen«"] },
      { number: 15, text: "Und der Engel des HERRN* rief Abraham ein zweites Mal vom Himmel her zu", footnotes: ["℘ Kap. 31,11; 48,16"] },
      { number: 16, text: "und sprach: Ich schwöre bei mir selbst, spricht der HERR*, deshalb, weil du das getan und deinen Sohn, deinen einzigen, mir nicht vorenthalten hast,", footnotes: ["w. ist der Ausspruch des HERRN\n℘ Jes 45,23; Jer 22,5; Mi 7,20; Lk 1,73"] },
      { number: 17, text: "darum werde ich dich reichlich segnen und deine Nachkommen überaus zahlreich machen* wie die Sterne des Himmels* und wie der Sand, der am Ufer des Meeres ist*; und deine Nachkommenschaft wird das Tor ihrer Feinde in Besitz nehmen*.", footnotes: ["℘ 5Mo 13,18; Hebr 6,13.14.17", "℘ Kap. 15,5; 26,4; 2Mo 32,13; 5Mo 1,10; 1Chr 27,23; Neh 9,23", "℘ Kap. 13,16; 15,5; 32,13; 2Sam 17,11; 1Kö 4,20; Jes 48,19; Hos 2,1; Hebr 11,12", "℘ Kap. 24,60; 27,29; Lk 1,73.74"] },
      { number: 18, text: "Und in deinem Samen* werden sich segnen alle Nationen der Erde* dafür, dass du meiner Stimme gehorcht hast*.", footnotes: ["o. mit deiner Nachkommenschaft\n℘ Gal 3,16", "℘ Kap. 12,2.3; 26,4; Jer 4,2; Apg 3,25; Röm 4,13", "℘ Kap. 26,5"] },
      { number: 19, text: "Dann kehrte Abraham zu seinen Knechten zurück, und sie machten sich auf und zogen miteinander nach Beerscheba; und Abraham ließ sich in Beerscheba nieder." },
      { number: 20, text: "Und es geschah nach diesen Dingen*, da wurde dem Abraham berichtet: Siehe, Milka, auch sie hat deinem Bruder Nahor Söhne geboren*:", heading: "Nachkommen Nahors", footnotes: ["℘ Kap. 15,1", "℘ Kap. 11,27.29"] },
      { number: 21, text: "Uz*, seinen Erstgeborenen, und dessen Bruder Bus* und Kemuël, den Vater Arams,", footnotes: ["℘ Jer 25,20.23", "℘ Kap. 37,13; 46,2; 2Mo 3,4; 1Sam 3,4; Jes 6,8; Apg 9,10"] },
      { number: 22, text: "und Kesed und Haso und Pildasch und Jidlaf und Betuël." },
      { number: 23, text: "Betuël aber zeugte Rebekka*. Diese acht gebar Milka dem Nahor, Abrahams Bruder.", footnotes: ["℘ Kap. 24,15.24; 25,20"] },
      { number: 24, text: "Und seine Nebenfrau, namens Rehuma, auch sie gebar, nämlich Tebach und Gaham und Tahasch und Maacha." },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und die Lebenszeit Saras betrug 127 Jahre; das waren die Lebensjahre Saras.", heading: "Saras Tod und Begräbnis" },
      { number: 2, text: "Und Sara starb zu Kirjat-Arba, das ist Hebron*, im Land Kanaan. Und Abraham ging hin, um über Sara zu klagen und sie zu beweinen*.", footnotes: ["℘ Kap. 13,18; 24,67", "℘ Kap. 50,1.3; 4Mo 20,29; 1Sam 25,1"] },
      { number: 3, text: "Dann stand Abraham auf und ging weg von seiner Toten und redete zu den Söhnen Het*:", footnotes: ["℘ Kap. 10,15"] },
      { number: 4, text: "Ein Fremder und Beisasse* bin ich bei euch. Gebt mir ein Erbbegräbnis* bei euch*, dass ich meine Tote von meinem Angesicht hinwegbringe und begrabe!", footnotes: ["d. i. ein Ansässiger ohne Bürgerrecht", "w. Grab-Grundbesitz", "℘ Kap. 17,8; 1Chr 29,15; Apg 7,5; Hebr 11,9.13"] },
      { number: 5, text: "Da antworteten die Söhne Het dem Abraham und sagten zu ihm:" },
      { number: 6, text: "Höre uns an, mein Herr! Du bist ein Fürst Gottes unter uns, begrabe deine Tote in dem auserlesensten unserer Gräber! Keiner von uns wird dir sein Grab verweigern, deine Tote zu begraben." },
      { number: 7, text: "Da erhob sich Abraham und verneigte sich vor dem Volk des Landes, vor den Söhnen Het." },
      { number: 8, text: "Und er redete zu ihnen und sagte: Wenn es euer Wille ist, dass ich meine Tote begrabe von meinem Angesicht hinweg, so hört mich an und legt Fürsprache für mich ein bei Efron, dem Sohn Zohars," },
      { number: 9, text: "dass er mir die Höhle Machpela gebe, die ihm gehört, die am Ende seines Feldes liegt; zum vollen Kaufpreis* gebe er sie mir* zu einem Erbbegräbnis* in eurer Mitte!*", footnotes: ["w. um volles Silber", "℘ 1Chr 21,22", "w. Grab-Grundbesitz", "℘ Kap. 25,10; 49,29-32; 50,13; Apg 7,16"] },
      { number: 10, text: "Efron aber saß* mitten unter den Söhnen Het. Und Efron, der Hetiter, antwortete dem Abraham vor den Ohren der Söhne Het, vor allen, die ins Tor seiner Stadt gekommen waren*, und sagte:", footnotes: ["o. wohnte", "℘ Kap. 34,24"] },
      { number: 11, text: "Nein, mein Herr, höre mir zu! Das Feld schenke* ich dir; und die Höhle, die darauf ist, dir schenke* ich sie; vor den Augen der Kinder meines Volkes* schenke* ich sie dir. Begrabe deine Tote!", footnotes: ["w. gebe", "w. gebe", "℘ Rt 4,4.9", "w. gebe"] },
      { number: 12, text: "Da verneigte sich Abraham vor dem Volk des Landes;" },
      { number: 13, text: "und er redete zu Efron vor den Ohren des Volkes des Landes und sagte: Ach, wenn du doch auf mich hören wolltest! Ich gebe dir den Kaufpreis* des Feldes. Nimm ihn von mir an, dass ich meine Tote dort begraben kann!", footnotes: ["w. das Silber"] },
      { number: 14, text: "Da antwortete Efron dem Abraham und sagte zu ihm:" },
      { number: 15, text: "Mein Herr, höre mich an! Ein Land von vierhundert Schekel Silber, was ist das zwischen mir und dir?* So begrabe deine Tote!", footnotes: ["℘ Kap. 33,19"] },
      { number: 16, text: "Und Abraham hörte auf Efron; und Abraham wog dem Efron das Geld* dar, von dem er vor den Ohren der Söhne Het geredet hatte*, vierhundert Schekel Silber, wie es beim Händler gängig ist*.", footnotes: ["w. das Silber", "℘ Jer 32,9.10", "℘ 2Sam 24,24"] },
      { number: 17, text: "So fiel das Feld Efrons, das bei Machpela gegenüber von* Mamre liegt, das Feld und die Höhle, die darauf war, und alle Bäume auf dem Feld innerhalb seiner ganzen Grenze ringsum", footnotes: ["d. h. östlich von"] },
      { number: 18, text: "als Besitz an Abraham vor den Augen der Söhne Het, vor allen, die ins Tor seiner Stadt gekommen waren*.", footnotes: ["℘ Kap. 34,24"] },
      { number: 19, text: "Und danach begrub Abraham seine Frau Sara in der Höhle des Feldes von Machpela, gegenüber von Mamre, das ist Hebron, im Land Kanaan*.", footnotes: ["℘ Kap. 25,9"] },
      { number: 20, text: "So fiel das Feld und die Höhle, die darauf war, von den Söhnen Het an Abraham als Erbbegräbnis*.", footnotes: ["w. Grab-Grundbesitz\n℘ Kap. 25,10; 49,29-32; 50,13; Apg 7,16"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Und Abraham war alt, hochbetagt*, und der HERR hatte Abraham in allem gesegnet*.", heading: "Werbung um Rebekka als Frau für Isaak", footnotes: ["℘ Kap. 18,11", "℘ Kap. 12,2; 13,2; Jes 51,2"] },
      { number: 2, text: "Da sagte Abraham zu seinem Knecht, dem Ältesten seines Hauses, der alles verwaltete, was er hatte: Lege doch deine Hand unter meine Hüfte*!", footnotes: ["o. meinen Schenkel\n℘ Kap. 47,29"] },
      { number: 3, text: "Ich will dich schwören lassen bei dem HERRN*, dem Gott des Himmels und dem Gott der Erde*, dass du meinem Sohn nicht eine Frau von den Töchtern der Kanaaniter nimmst, in deren Mitte ich wohne*.", footnotes: ["℘ 5Mo 6,13; Jos 2,12; 1Sam 30,15", "℘ Kap. 14,19.22; Esr 5,11", "℘ Kap. 28,1; 34,9; 2Mo 34,16; 5Mo 7,3; 2Kor 6,14"] },
      { number: 4, text: "Sondern du sollst in mein Land und zu meiner Verwandtschaft gehen* und dort eine Frau für meinen Sohn, für Isaak, nehmen!", footnotes: ["℘ Kap. 28,2; Ri 14,3"] },
      { number: 5, text: "Der Knecht aber sagte zu ihm: Vielleicht wird die Frau mir nicht in dieses Land folgen wollen. Soll ich dann deinen Sohn in das Land zurückbringen, aus dem du ausgezogen bist?" },
      { number: 6, text: "Da sagte Abraham zu ihm: Hüte dich wohl, meinen Sohn dorthin zurückzubringen!" },
      { number: 7, text: "Der HERR, der Gott des Himmels*, der mich aus dem Haus meines Vaters und aus dem Land meiner Verwandtschaft genommen* und der zu mir geredet und der mir dies geschworen hat: Deinen Nachkommen will ich dieses Land geben*, der wird seinen Engel vor dir hersenden*, dass du eine Frau für meinen Sohn von dort holen kannst*.", footnotes: ["℘ Jon 1,9", "℘ Kap. 12,1", "℘ Kap. 12,7; Apg 7,5", "℘ 2Mo 23,20; 33,2", "℘ V. 40"] },
      { number: 8, text: "Wenn aber die Frau dir nicht folgen will, so bist du frei von diesem Schwur*.* Nur sollst du meinen Sohn nicht dorthin zurückbringen!", footnotes: ["w. von diesem meinem Schwur", "℘ Jos 2,17"] },
      { number: 9, text: "Und der Knecht legte seine Hand unter die Hüfte Abrahams, seines Herrn, und schwor ihm in Hinsicht auf dieses Wort*.", footnotes: ["o. diese Sache"] },
      { number: 10, text: "Dann nahm der Knecht zehn Kamele von den Kamelen seines Herrn und zog hin und nahm allerlei Gut seines Herrn mit sich. Und er machte sich auf und zog nach Aram-Naharajim*, zu der Stadt Nahors*.", footnotes: ["d. i. ein Gebiet am mittleren Euphrat, das zentrale Mesopotamien; w. Aram der zwei Ströme", "℘ Kap. 11,26.27; 22,20; Ri 3,8"] },
      { number: 11, text: "Und er ließ die Kamele niederknien draußen vor der Stadt am Wasserbrunnen* um die Abendzeit, zur Zeit, da die Schöpferinnen herauskommen*.", footnotes: ["℘ Kap. 29,2", "℘ 2Mo 2,16; 1Sam 9,11"] },
      { number: 12, text: "Und er sagte: HERR, Gott meines Herrn Abraham*, lass es mir doch heute begegnen*, und erweise Gnade an meinem Herrn Abraham!", footnotes: ["℘ Kap. 32,10", "℘ Ps 37,5"] },
      { number: 13, text: "Siehe, ich stehe an der Wasserquelle, und die Töchter der Leute der Stadt kommen heraus, um Wasser zu schöpfen." },
      { number: 14, text: "Möge es nun geschehen: Das Mädchen, zu dem ich sagen werde: »Neige doch deinen Krug, dass ich trinke!«, und das dann sagt: »Trinke! Und auch deine Kamele will ich tränken«, das soll es sein, das du für deinen Knecht Isaak bestimmt hast! Und daran werde ich erkennen*, dass du an meinem Herrn Gnade erwiesen hast.", footnotes: ["℘ Ri 6,37; 1Sam 14,10"] },
      { number: 15, text: "Und es geschah — er hatte noch nicht ausgeredet* —, und siehe, da kam Rebekka* heraus, die dem Betuël geboren war, dem Sohn der Milka, der Frau Nahors, des Bruders Abrahams*; sie trug ihren Krug auf ihrer Schulter.", footnotes: ["℘ Jes 65,24", "℘ Kap. 22,23", "℘ Kap. 11,29"] },
      { number: 16, text: "Und das Mädchen war sehr schön von Aussehen*, eine Jungfrau, und kein Mann hatte sie erkannt. Sie stieg zur Quelle hinab, füllte ihren Krug und stieg wieder herauf.", footnotes: ["℘ Kap. 12,11"] },
      { number: 17, text: "Da lief ihr der Knecht entgegen und sagte: Lass mich doch ein wenig Wasser aus deinem Krug schlürfen!" },
      { number: 18, text: "Und sie sagte: Trinke, mein Herr! Und eilends ließ sie ihren Krug auf ihre Hand herunter und gab ihm zu trinken." },
      { number: 19, text: "Und als sie ihm genug zu trinken gegeben hatte, sagte sie: Auch für deine Kamele will ich schöpfen, bis sie genug getrunken haben." },
      { number: 20, text: "Und sie eilte und goss ihren Krug aus in die Tränkrinne, lief noch einmal zum Brunnen, um zu schöpfen, und schöpfte so für alle seine Kamele." },
      { number: 21, text: "Der Mann aber sah ihr zu, schweigend, um zu erkennen, ob der HERR seine Reise würde gelingen lassen oder nicht." },
      { number: 22, text: "Und es geschah, als die Kamele genug getrunken hatten, da nahm der Mann einen goldenen Ring*, ein halber Schekel sein Gewicht, und zwei Spangen für ihre Handgelenke*, zehn Schekel Gold ihr Gewicht;", footnotes: ["w. Nasenring", "℘ Hes 16,11"] },
      { number: 23, text: "und er sagte: Wessen Tochter bist du? Sage es mir doch! Gibt es im Haus deines Vaters Platz für uns zu übernachten?" },
      { number: 24, text: "Da sagte sie zu ihm: Ich bin die Tochter Betuëls, des Sohnes der Milka, den sie dem Nahor geboren hat*.", footnotes: ["℘ Kap. 11,29"] },
      { number: 25, text: "Und sie sagte weiter zu ihm: Sowohl Stroh als auch Futter ist bei uns in Menge, auch Platz zum Übernachten." },
      { number: 26, text: "Da verneigte sich der Mann und warf sich nieder vor dem HERRN*", footnotes: ["℘ V. 52; 2Mo 4,31; Ri 7,15; 2Chr 20,18"] },
      { number: 27, text: "und sprach: Gepriesen* sei der HERR, der Gott meines Herrn Abraham, der seine Gnade und Treue* gegenüber meinem Herrn nicht hat aufhören lassen!* Mich hat der HERR den Weg zum Haus der Brüder meines Herrn geführt.", footnotes: ["w. Gesegnet", "℘ 2Mo 34,6", "℘ Kap. 32,11"] },
      { number: 28, text: "Das Mädchen aber lief und berichtete diese Dinge dem Haus ihrer Mutter." },
      { number: 29, text: "Nun hatte Rebekka einen Bruder, der hieß Laban*. Und Laban lief zu dem Mann hinaus an die Quelle.", footnotes: ["℘ Kap. 27,43; 28,2; 29,5"] },
      { number: 30, text: "Und es geschah, als er den Ring* sah und die Spangen an den Handgelenken seiner Schwester und als er die Worte seiner Schwester Rebekka hörte, die sagte: »So hat der Mann zu mir geredet«, da kam er zu dem Mann; und siehe, er stand noch bei den Kamelen an der Quelle.", footnotes: ["w. Nasenring"] },
      { number: 31, text: "Und er sprach: Komm herein, du Gesegneter des HERRN!* Warum stehst du draußen? Habe ich doch schon das Haus aufgeräumt, und auch für die Kamele ist Platz da.", footnotes: ["℘ Kap. 26,29"] },
      { number: 32, text: "Da kam der Mann ins Haus*; und man sattelte die Kamele ab und gab den Kamelen Stroh und Futter, ihm aber Wasser, um seine Füße zu waschen und die Füße der Männer, die bei ihm waren*.", footnotes: ["℘ Kap. 29,13", "℘ Kap. 18,4"] },
      { number: 33, text: "Dann wurde ihm zu essen vorgesetzt. Er aber sagte: Ich will nicht essen, bis ich meine Worte geredet habe. Und er sagte: Rede!" },
      { number: 34, text: "Da sagte er: Ich bin Abrahams Knecht." },
      { number: 35, text: "Der HERR hat meinen Herrn sehr gesegnet, so dass er groß geworden ist*. Er hat ihm Schafe und Rinder gegeben, Silber und Gold, dazu Knechte und Mägde, Kamele und Esel*.", footnotes: ["℘ Kap. 12,2; 25,11; Spr 10,22", "℘ Kap. 13,2; Hi 1,3"] },
      { number: 36, text: "Und Sara, die Frau meines Herrn, hat meinem Herrn einen Sohn geboren, nachdem sie schon alt geworden war*; dem hat er alles, was er hat, übergeben*.", footnotes: ["℘ Kap. 18,11", "℘ Kap. 25,5"] },
      { number: 37, text: "Mein Herr aber hat mich schwören lassen und gesagt: Du sollst für meinen Sohn nicht eine Frau von den Töchtern der Kanaaniter nehmen, in deren Land ich wohne;" },
      { number: 38, text: "*sondern zu dem Haus meines Vaters und zu meiner Sippe sollst du gehen und dort für meinen Sohn eine Frau nehmen!*", footnotes: ["so mit SamPent; Mas. T.: Wenn du nicht . . . gehst und . . . eine Frau nimmst! — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde. Er knüpft an V. 37 an: Mein Herr aber hat mich schwören lassen", "so mit SamPent; Mas. T.: Wenn du nicht . . . gehst und . . . eine Frau nimmst! — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde. Er knüpft an V. 37 an: Mein Herr aber hat mich schwören lassen"] },
      { number: 39, text: "Und ich sagte zu meinem Herrn: Vielleicht will die Frau mir nicht folgen." },
      { number: 40, text: "Da sagte er zu mir: Der HERR, vor dessen Angesicht ich gelebt habe*, wird seinen Engel mit dir senden und wird deine Reise gelingen lassen, dass du für meinen Sohn eine Frau aus meiner Sippe und aus dem Haus meines Vaters nimmst*.", footnotes: ["w. beständig gegangen bin\n℘ Kap. 17,1; 48,15; 1Kö 3,6", "℘ V. 7"] },
      { number: 41, text: "Dann bist du frei von dem Schwur*: Wenn du zu meiner Sippe kommst und wenn sie sie dir nicht geben, dann bist du entlastet von dem Schwur*.", footnotes: ["w. von meinem Fluch", "w. von meinem Fluch"] },
      { number: 42, text: "So kam ich heute zu der Quelle und sprach: HERR, Gott meines Herrn Abraham, wenn du doch Gelingen geben wolltest zu meinem Weg, auf dem ich gehe!" },
      { number: 43, text: "Siehe, ich stehe bei der Wasserquelle. Möge es nun geschehen, dass das Mädchen, das herauskommt, um zu schöpfen, und zu dem ich sage: »Gib mir doch ein wenig Wasser aus deinem Krug zu trinken!«," },
      { number: 44, text: "und das dann zu mir sagt: »Trinke du, und auch für deine Kamele will ich schöpfen«, dass dies die Frau sei, die der HERR für den Sohn meines Herrn bestimmt hat!*", footnotes: ["℘ Spr 19,14"] },
      { number: 45, text: "Ich hatte in meinem Herzen* noch nicht ausgeredet*, siehe, da kam Rebekka heraus mit ihrem Krug auf ihrer Schulter; und sie stieg zur Quelle hinab und schöpfte. Da sagte ich zu ihr: Gib mir doch zu trinken!", footnotes: ["℘ 1Sam 1,13", "℘ V. 15"] },
      { number: 46, text: "Und eilends ließ sie ihren Krug von ihrer Schulter* herunter und sagte: Trinke, und auch deine Kamele will ich tränken. Da trank ich, und sie tränkte auch die Kamele.", footnotes: ["w. von auf sich"] },
      { number: 47, text: "Und ich fragte sie und sprach: Wessen Tochter bist du? Und sie sagte: Die Tochter Betuëls, des Sohnes Nahors, den Milka ihm geboren hat. Und ich legte den Ring an ihre Nase* und die Spangen an ihre Handgelenke.", footnotes: ["℘ Jes 3,21"] },
      { number: 48, text: "Dann verneigte ich mich und warf mich vor dem HERRN nieder und dankte* dem HERRN, dem Gott meines Herrn Abraham, der mich den rechten Weg* geführt hatte, die Tochter des Bruders meines Herrn für seinen Sohn zu nehmen*.", footnotes: ["o. segnete", "w. den Weg der Treue o. der Wahrheit", "℘ Ps 32,8"] },
      { number: 49, text: "Und nun, wenn ihr Gnade und Treue an meinem Herrn erweisen wollt*, so teilt es mir mit; und wenn nicht, so teilt es mir auch mit! Und ich werde mich zur Rechten oder zur Linken wenden.", footnotes: ["℘ Jos 2,14"] },
      { number: 50, text: "Da antworteten Laban und Betuël und sagten: Vom HERRN ist die Sache ausgegangen*; wir können dir nichts sagen, weder Böses noch Gutes*.", footnotes: ["℘ 1Kö 12,24", "℘ Kap. 31,24.29"] },
      { number: 51, text: "Siehe, Rebekka ist vor dir: Nimm sie und geh hin, dass sie die Frau des Sohnes deines Herrn werde, wie der HERR geredet hat!" },
      { number: 52, text: "Und es geschah, als Abrahams Knecht ihre Worte hörte, da warf er sich zur Erde nieder vor dem HERRN*.", footnotes: ["℘ V. 26"] },
      { number: 53, text: "Und der Knecht holte silbernes Geschmeide und goldenes Geschmeide und Kleider hervor und gab sie der Rebekka; und Kostbarkeiten gab er ihrem Bruder und ihrer Mutter." },
      { number: 54, text: "Dann aßen und tranken sie, er und die Männer, die bei ihm waren, und übernachteten. Aber am Morgen standen sie auf, und er sagte: Entlasst mich zu meinem Herrn!" },
      { number: 55, text: "Da sagten ihr Bruder und ihre Mutter: Lass das Mädchen noch einige Tage oder zehn bei uns bleiben, danach magst du* gehen.", footnotes: ["o. mag sie"] },
      { number: 56, text: "Er aber sagte zu ihnen: Haltet mich nicht auf, da der HERR meine Reise hat gelingen lassen; entlasst mich, dass ich zu meinem Herrn ziehe!" },
      { number: 57, text: "Da sagten sie: Lasst uns das Mädchen rufen und ihren Mund befragen." },
      { number: 58, text: "Und sie riefen Rebekka und sagten zu ihr: Willst du mit diesem Mann gehen? Sie sagte: Ich will gehen." },
      { number: 59, text: "So entließen sie ihre Schwester Rebekka mit ihrer Amme* und den Knecht Abrahams und seine Männer.", footnotes: ["℘ Kap. 35,8"] },
      { number: 60, text: "Und sie segneten* Rebekka und sprachen zu ihr: Du, unsere Schwester, werde zu tausendmal Zehntausenden*, und deine Nachkommen mögen das Tor ihrer Hasser in Besitz nehmen!*", footnotes: ["℘ Kap. 32,1", "℘ Kap. 28,3", "℘ Kap. 22,17"] },
      { number: 61, text: "Und Rebekka machte sich mit ihren Mädchen auf, und sie bestiegen die Kamele und folgten dem Mann. Und der Knecht nahm Rebekka und zog hin. —" },
      { number: 62, text: "Isaak aber war von einem Gang* zum Brunnen Lachai-Roi* gekommen; er wohnte nämlich im Land des Südens.*", footnotes: ["SamPent und LXX lesen: war durch die Wüste; die Üs. und Mas. T. sind unsicher", "℘ Kap. 16,14", "℘ Kap. 12,9"] },
      { number: 63, text: "Und Isaak war hinausgegangen, um auf dem Feld zu sinnen* beim Anbruch des Abends. Und er erhob seine Augen und sah, und siehe, Kamele kamen.", footnotes: ["o. um sich zu ergehen. — Die Bedeutung des Wortes, das nur hier vorkommt, kann nur vermutet werden."] },
      { number: 64, text: "Und auch Rebekka erhob ihre Augen und sah Isaak. Da glitt sie vom Kamel" },
      { number: 65, text: "und sagte zu dem Knecht: Wer ist dieser Mann, der uns da auf dem Feld entgegenkommt? Und der Knecht sagte: Das ist mein Herr. Da nahm sie den Schleier und verhüllte sich*.", footnotes: ["℘ Kap. 38,14"] },
      { number: 66, text: "Der Knecht aber erzählte Isaak all die Dinge, die er ausgerichtet hatte." },
      { number: 67, text: "Dann führte Isaak sie in das Zelt seiner Mutter Sara; und er nahm Rebekka, und sie wurde seine Frau*, und er gewann sie lieb. Und Isaak tröstete sich nach dem Tod seiner Mutter*.", footnotes: ["℘ Kap. 25,20", "℘ Kap. 23,2"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "*Und Abraham nahm wieder eine Frau, die hieß Ketura.", heading: "Abrahams neue Ehe, Tod und Begräbnis", footnotes: ["℘ V. 1-4: 1Chr 1,32.33"] },
      { number: 2, text: "Und sie gebar ihm Simran und Jokschan, Medan und Midian, Jischbak und Schuach*.", footnotes: ["℘ Hi 2,11"] },
      { number: 3, text: "Jokschan aber zeugte Saba und Dedan*; und die Söhne Dedans waren die Aschuriter und Letuschiter und Lëummiter.", footnotes: ["℘ Jes 21,13; Hes 27,15"] },
      { number: 4, text: "Und die Söhne Midians: Efa* und Efer, Henoch, Abida und Eldaa. Diese alle sind Söhne der Ketura. —", footnotes: ["℘ Jes 60,6"] },
      { number: 5, text: "Und Abraham gab dem Isaak alles, was er hatte*.", footnotes: ["℘ Kap. 24,36"] },
      { number: 6, text: "Und den Söhnen der Nebenfrauen, die Abraham hatte, gab Abraham Geschenke; und er schickte sie, während er noch lebte, von seinem Sohn Isaak weg, nach Osten in das Land des Ostens*. —", footnotes: ["℘ Kap. 29,1; Ri 6,3"] },
      { number: 7, text: "Und dies sind die Tage der Lebensjahre Abrahams, die er lebte: 175 Jahre*.", footnotes: ["℘ Kap. 35,28; 47,28; 50,26"] },
      { number: 8, text: "Und Abraham verschied und starb in gutem Alter*, alt und der Tage satt*, und wurde versammelt zu seinen Völkern*.", footnotes: ["℘ Ri 8,32", "℘ Kap. 15,15; 35,29; 1Chr 23,1; 2Chr 24,15; Hi 42,17", "d. h. zu seinen Vorfahren\n℘ V. 17; Kap. 49,33; 4Mo 20,24"] },
      { number: 9, text: "Und seine Söhne Isaak und Ismael begruben ihn* in der Höhle Machpela, auf dem Feld des Hetiters Efron, des Sohnes Zohars, das gegenüber* Mamre liegt*,", footnotes: ["℘ Kap. 35,29", "d. i. östlich von", "℘ Kap. 47,30; 49,29; 50,13"] },
      { number: 10, text: "auf dem Feld, das Abraham von den Söhnen Het gekauft hatte; dort wurden Abraham und seine Frau Sara begraben*.", footnotes: ["℘ Kap. 23,17-20; 49,31"] },
      { number: 11, text: "Und es geschah nach dem Tode Abrahams, da segnete Gott Isaak, seinen Sohn*; und Isaak wohnte bei dem Brunnen Lachai-Roi*.", footnotes: ["℘ Kap. 24,35; 26,12.24; Ps 112,2", "℘ Kap. 16,14"] },
      { number: 12, text: "*Das ist die Generationenfolge* Ismaels, des Sohnes Abrahams, den die Ägypterin Hagar, die Magd Saras, dem Abraham geboren hat*;", heading: "Nachkommen Ismaels", footnotes: ["℘ V. 12-16: 1Chr 1,29-31", "o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ Kap. 16,15; Ri 8,24"] },
      { number: 13, text: "und dies sind die Namen der Söhne Ismaels mit ihren Namen, nach ihrer Generationenfolge*: der Erstgeborene Ismaels: Nebajot*, dann Kedar* und Adbeel und Mibsam", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ Kap. 28,9; 36,3; Jes 60,7", "℘ Ps 120,5; Jes 21,16.17; Jer 2,10; Hes 27,21"] },
      { number: 14, text: "und Mischma und Duma und Massa," },
      { number: 15, text: "Hadad und Tema*, Jetur, Nafisch* und Kedma.", footnotes: ["℘ Hi 6,19", "℘ 1Chr 1,31"] },
      { number: 16, text: "Das sind die Söhne Ismaels, und das sind ihre Namen in ihren Gehöften und in ihren Zeltlagern; zwölf Fürsten nach ihren Völkerschaften*.", footnotes: ["℘ Kap. 17,20"] },
      { number: 17, text: "Und dies sind die Lebensjahre Ismaels: 137 Jahre; und er verschied und starb und wurde versammelt zu seinen Völkern*.", footnotes: ["d. h. zu seinen Vorfahren\n℘ V. 8"] },
      { number: 18, text: "Und sie wohnten von Hawila* an bis nach Schur*, das vor* Ägypten liegt, nach Assur hin. So setzte er sich allen seinen Brüdern vors Gesicht*.", footnotes: ["vielleicht in Arabien", "℘ Kap. 16,7; 2Mo 15,22", "d. i. östlich von", "℘ Kap. 16,12"] },
      { number: 19, text: "Das ist die Generationenfolge* Isaaks, des Sohnes Abrahams: Abraham zeugte Isaak*.", heading: "Nachkommen Isaaks: Esau und Jakob", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ Kap. 21,3; 1Chr 1,28"] },
      { number: 20, text: "Und Isaak war vierzig Jahre alt, als er sich Rebekka zur Frau nahm*, die Tochter des Aramäers Betuël aus Paddan-Aram*, die Schwester des Aramäers Laban*.", footnotes: ["℘ Kap. 24,67", "d. i. Haran, das zentrale Siedlungsgebiet von Aram-Naharajim; vgl. Kap. 24,10", "℘ Kap. 22,23; 27,43"] },
      { number: 21, text: "Und Isaak bat den HERRN für* seine Frau, denn sie war unfruchtbar*; da ließ der HERR sich von ihm erbitten, und Rebekka, seine Frau, wurde schwanger*.", footnotes: ["w. in Richtung auf", "℘ Kap. 11,30", "℘ Kap. 30,22.23; Röm 9,10"] },
      { number: 22, text: "Und die Kinder stießen sich in ihrem Leib. Da sagte sie: Wenn es so steht, warum trifft mich dies? Und sie ging hin, den HERRN zu befragen*.", footnotes: ["℘ 1Sam 9,9"] },
      { number: 23, text: "Der HERR aber sprach zu ihr: Zwei Nationen sind in deinem Leib, und zwei Volksstämme scheiden sich aus deinem Innern; und ein Volksstamm wird stärker sein als der andere*, und der Ältere wird dem Jüngeren dienen*.", footnotes: ["℘ Kap. 48,19", "℘ Kap. 27,29.37.40; 2Sam 8,14; Ob 21; Röm 9,12"] },
      { number: 24, text: "Und als ihre Tage erfüllt waren, dass sie gebären sollte, siehe, da waren Zwillinge in ihrem Leib*.", footnotes: ["℘ Kap. 38,27"] },
      { number: 25, text: "Und der erste kam heraus, rötlich, ganz und gar wie ein haariger Mantel*; und man gab ihm den Namen Esau*.", footnotes: ["℘ Kap. 27,11.23", "d. h. rauh, behaart\n℘ 1Chr 1,34"] },
      { number: 26, text: "Und danach kam sein Bruder heraus, und seine Hand hielt die Ferse Esaus*. Da gab man ihm den Namen Jakob*. Und Isaak war sechzig Jahre alt, als sie geboren wurden*.", footnotes: ["℘ Hos 12,4", "d. h. Fersenhalter, Betrüger\n℘ Kap. 27,36; 4Mo 20,14; 5Mo 23,8; Mal 1,2; Mt 1,2; Lk 3,34; Apg 7,8", "℘ Kap. 21,5; Jos 24,4"] },
      { number: 27, text: "Und die Jungen wuchsen heran. Esau wurde ein jagdkundiger Mann*, ein Mann des freien Feldes; Jakob aber war ein gesitteter Mann, der bei den Zelten blieb.", footnotes: ["w. ein Mann, der die Jagd erkannt hat; d. h. ein Mann, der in der Jagd kundig ist"] },
      { number: 28, text: "Und Isaak hatte Esau lieb, denn Wildbret war nach seinem Mund*; Rebekka aber hatte Jakob lieb.", footnotes: ["℘ Kap. 27,3.4"] },
      { number: 29, text: "Einst kochte Jakob ein Gericht. Da kam Esau vom Feld, und er war erschöpft.", heading: "Esau verkauft sein Erstgeburtsrecht" },
      { number: 30, text: "Und Esau sagte zu Jakob: Lass mich doch schnell essen von dem Roten*, dem Roten* da, denn ich bin erschöpft! Darum gab man ihm den Namen Edom*.", footnotes: ["w. herunterschlingen das Rote", "hebr. adôm", "℘ Kap. 32,4; 36,1.8.19; Ob 1"] },
      { number: 31, text: "Da sagte Jakob: Verkaufe mir heute* dein Erstgeburtsrecht!*", footnotes: ["o. zuerst", "℘ 5Mo 21,17"] },
      { number: 32, text: "Esau sagte: Siehe, ich gehe ja doch dem Sterben entgegen*. Was soll mir da das Erstgeburtsrecht?", footnotes: ["o. ich sterbe fast vor Hunger; w. ich gehe zu sterben\n℘ 1Kor 15,32"] },
      { number: 33, text: "Jakob aber sagte: Schwöre mir heute*! Da schwor er ihm und verkaufte sein Erstgeburtsrecht an Jakob*.", footnotes: ["o. zuvor", "℘ Kap. 27,36"] },
      { number: 34, text: "Und Jakob gab Esau Brot und ein Gericht Linsen; und er aß und trank und stand auf und ging davon. So verachtete Esau das Erstgeburtsrecht*.", footnotes: ["℘ Hebr 12,16"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Und es entstand eine Hungersnot im Lande, nach der vorigen Hungersnot, die in den Tagen Abrahams gewesen war*. Da ging Isaak zu Abimelech*, dem König der Philister, nach Gerar*.", heading: "Isaak und Abimelech", footnotes: ["℘ Kap. 12,10", "s. Anm. zu Kap. 20,2", "℘ Kap. 20,1"] },
      { number: 2, text: "Und der HERR erschien ihm und sprach: Zieh nicht hinab nach Ägypten; bleibe in dem Land, das ich dir sage*!", footnotes: ["℘ Ps 25,12"] },
      { number: 3, text: "Halte dich als Fremder auf in diesem Land*! Und ich werde mit dir sein* und dich segnen; denn dir und deinen Nachkommen werde ich alle diese Länder geben*, und ich werde den Schwur aufrechterhalten*, den ich deinem Vater Abraham geschworen habe*.", footnotes: ["℘ Ps 37,3; Hebr 11,9", "℘ V. 24.28; 2Mo 3,12", "℘ Kap. 12,7", "o. erfüllen", "℘ Kap. 17,19; 2Mo 2,24; 4Mo 23,19; Ps 105,8.9"] },
      { number: 4, text: "Und ich werde deine Nachkommen* zahlreich machen wie die Sterne des Himmels* und deinen Nachkommen alle diese Länder geben; und mit deinen Nachkommen werden sich segnen* alle Nationen der Erde*", footnotes: ["w. deinen Samen; entsprechend nachher", "℘ Kap. 22,17", "o. sich Segen wünschen", "℘ Kap. 12,3"] },
      { number: 5, text: "dafür, dass Abraham meiner Stimme gehorcht und meine Vorschriften gehalten hat*, meine Gebote, meine Ordnungen und meine Gesetze*.", footnotes: ["w. mein zu Bewahrendes bewahrt hat", "o. Weisungen\n℘ Kap. 22,18"] },
      { number: 6, text: "So blieb Isaak in Gerar*.", footnotes: ["℘ Kap. 20,1"] },
      { number: 7, text: "Als nun die Männer des Ortes sich nach seiner Frau erkundigten, da sagte er: Sie ist meine Schwester. Denn er fürchtete sich zu sagen: meine Frau. Er dachte nämlich: Die Männer des Ortes könnten mich sonst wegen Rebekka erschlagen; denn sie ist schön von Aussehen*.", footnotes: ["℘ Kap. 12,11-13"] },
      { number: 8, text: "Und es geschah, als er längere Zeit dort war, da blickte Abimelech*, der König der Philister, durchs Fenster herab und er sah, und siehe, Isaak koste mit Rebekka, seiner Frau*.", footnotes: ["s. Anm. zu Kap. 20,2", "℘ Pred 9,9"] },
      { number: 9, text: "Da rief Abimelech den Isaak und sagte: Siehe, sie ist ja deine Frau! Wie konntest du sagen: Sie ist meine Schwester? Da sagte Isaak zu ihm: Weil ich mir sagte: Ich könnte sonst ihretwegen sterben." },
      { number: 10, text: "Und Abimelech sprach: Was hast du uns da angetan!* Wie leicht hätte einer aus dem Volk bei deiner Frau liegen können, und du hättest Schuld über uns gebracht.", footnotes: ["℘ Kap. 12,18"] },
      { number: 11, text: "Und Abimelech befahl allem Volk: Wer diesen Mann und seine Frau antastet, muss getötet werden*.", footnotes: ["℘ Ps 105,15"] },
      { number: 12, text: "Und Isaak säte in diesem Land und gewann in jenem Jahr das Hundertfache; so segnete ihn der HERR*.", footnotes: ["℘ Kap. 25,11; Spr 10,22"] },
      { number: 13, text: "Und der Mann wurde reich* und wurde immer reicher*, bis er sehr reich* war.", footnotes: ["o. groß", "o. größer", "o. größer"] },
      { number: 14, text: "Und er hatte Schafherden und Rinderherden und eine große Dienerschaft*. Da beneideten ihn die Philister*.", footnotes: ["℘ Kap. 13,2", "℘ Pred 4,4"] },
      { number: 15, text: "Und alle Brunnen, die die Knechte seines Vaters in den Tagen seines Vaters Abraham gegraben hatten, die verstopften die Philister und füllten sie mit Erde." },
      { number: 16, text: "Und Abimelech sagte zu Isaak: Zieh weg von uns, denn du bist uns viel zu mächtig geworden!" },
      { number: 17, text: "Da zog Isaak von dort weg und schlug sein Lager im Tal Gerar auf und blieb dort." },
      { number: 18, text: "Und Isaak grub die Wasserbrunnen wieder auf, die sie in den Tagen seines Vaters Abraham gegraben* und die die Philister nach Abrahams Tod verstopft hatten; und er gab ihnen dieselben Namen wie die Namen, die ihnen sein Vater gegeben hatte.", footnotes: ["℘ Kap. 21,30"] },
      { number: 19, text: "Und die Knechte Isaaks gruben im Tal und fanden dort einen Brunnen mit lebendigem Wasser*.", footnotes: ["d. h. hier: Quellwasser (im Gegensatz zu den Brunnen, in denen Regenwasser gesammelt wurde)"] },
      { number: 20, text: "Da stritten sich die Hirten von Gerar mit den Hirten Isaaks und sagten: Uns gehört das Wasser! Da gab er dem Brunnen den Namen Esek*, weil sie mit ihm gezankt hatten*.", footnotes: ["d. h. Zank", "℘ Kap. 21,25"] },
      { number: 21, text: "Dann gruben sie einen anderen Brunnen, aber auch um den stritten sie sich. Da gab er ihm den Namen Sitna*.", footnotes: ["d. h. Anfeindung\n℘ Kap. 21,25"] },
      { number: 22, text: "Und er brach von dort auf und grub noch einen anderen Brunnen, und um den stritten sie sich nicht. Da gab er ihm den Namen Rechobot* und sagte: Denn jetzt hat der HERR uns weiten Raum geschafft*, und wir werden fruchtbar sein im Land.", footnotes: ["d. h. weiter Raum", "℘ Ps 119,32"] },
      { number: 23, text: "Dann zog er von dort hinauf nach Beerscheba*.", footnotes: ["℘ Kap. 21,31; Am 5,5"] },
      { number: 24, text: "Und der HERR erschien ihm in jener Nacht und sprach: Ich bin der Gott deines Vaters Abraham*. Fürchte dich nicht*! Denn ich bin mit dir*, und ich werde dich segnen und deine Nachkommen vermehren wegen meines Knechtes Abraham*.", footnotes: ["℘ Kap. 17,7", "℘ Kap. 15,1; 2Mo 14,13; Rt 3,11; 1Kö 17,13; Kla 3,57; Apg 18,9.10", "℘ V. 3; Kap. 31,5; 39,2.21; 5Mo 31,6.8; Jes 41,10", "℘ 3Mo 26,42"] },
      { number: 25, text: "Und der baute dort einen Altar und rief den Namen des HERRN an* und schlug dort sein Zelt auf*. Und die Knechte Isaaks gruben dort einen Brunnen.", footnotes: ["℘ Kap. 12,7.8", "℘ Hebr 11,9"] },
      { number: 26, text: "Und Abimelech kam zu ihm aus Gerar mit seinem Freund Ahusat und seinem Heerobersten Pichol." },
      { number: 27, text: "Da sagte Isaak zu ihnen: Warum kommt ihr zu mir, da ihr mich doch hasst und mich von euch weggeschickt habt*?", footnotes: ["℘ Ri 11,7"] },
      { number: 28, text: "Sie aber sagten: Wir haben deutlich gesehen, dass der HERR mit dir ist*; und wir haben uns gesagt: Es soll ein Schwur* zwischen uns sein, zwischen uns und dir*; wir wollen einen Bund mit dir schließen*,", footnotes: ["℘ Kap. 21,22; 1Sam 18,28; 2Chr 15,9", "w. eine Verfluchung (als Sicherung gegen Vertragsbruch)", "℘ Kap. 21,23", "℘ Kap. 31,44"] },
      { number: 29, text: "dass du uns nichts Böses antust, so wie wir dich nicht angetastet haben und wie wir dir nur Gutes erwiesen und dich haben in Frieden ziehen lassen. Du bist nun einmal ein Gesegneter des HERRN*.", footnotes: ["℘ Kap. 12,3; 24,31"] },
      { number: 30, text: "Da machte er ihnen ein Mahl, und sie aßen und tranken*.", footnotes: ["℘ Kap. 31,54; 2Mo 18,12"] },
      { number: 31, text: "Und sie standen früh am Morgen auf und schworen einer dem andern*. Dann entließ Isaak sie, und sie gingen in Frieden von ihm fort. —", footnotes: ["℘ Kap. 21,27.31"] },
      { number: 32, text: "Und es geschah an jenem Tag, da kamen Isaaks Knechte und berichteten ihm von dem Brunnen, den sie gegraben hatten, und sagten zu ihm: Wir haben Wasser gefunden." },
      { number: 33, text: "Da nannte er ihn Schibea*; daher lautet der Name der Stadt Beerscheba* bis auf diesen Tag*.", footnotes: ["d. h. Schwur", "d. h. Schwur-Brunnen, o. Sieben-Brunnen", "℘ Kap. 21,31; Am 5,5"] },
      { number: 34, text: "Und Esau war vierzig Jahre alt, da nahm er Jehudit, die Tochter des Hetiters Beeri, zur Frau und Basemat, die Tochter des Hetiters Elon*.", heading: "Die beiden ersten Frauen Esaus", footnotes: ["℘ Kap. 28,9; 36,2.3"] },
      { number: 35, text: "Und sie waren ein Herzeleid für Isaak und Rebekka*.", footnotes: ["℘ Kap. 27,46; 28,8"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Und es geschah, als Isaak alt geworden und seine Augen trübe waren, so dass er nicht mehr sehen konnte*, da rief er seinen älteren Sohn Esau und sagte zu ihm: Mein Sohn! Und er sagte zu ihm: Hier bin ich!", heading: "Jakobs Betrug — Isaaks Segen", footnotes: ["℘ Kap. 48,10; 1Sam 3,2; 1Kö 14,4; Pred 12,3"] },
      { number: 2, text: "Und er sagte: Siehe doch, ich bin alt geworden, ich kenne nicht den Tag meines Todes." },
      { number: 3, text: "Und nun nimm doch dein Jagdgerät, deinen Köcher und deinen Bogen, und gehe hinaus aufs Feld und erjage mir ein Wildbret*;", footnotes: ["℘ Kap. 25,28"] },
      { number: 4, text: "und bereite mir einen Leckerbissen, wie ich ihn liebe, und bring ihn mir her, dass ich esse, damit meine Seele dich segnet*, bevor ich sterbe!", footnotes: ["℘ Kap. 48,9"] },
      { number: 5, text: "Rebekka aber hatte gehört, wie Isaak zu seinem Sohn Esau redete. Und Esau ging aufs Feld, um ein Wildbret zu erjagen, um es heimzubringen." },
      { number: 6, text: "Da sagte Rebekka zu ihrem Sohn Jakob: Siehe, ich habe deinen Vater zu deinem Bruder Esau so reden hören:" },
      { number: 7, text: "Bring mir ein Wildbret und bereite mir einen Leckerbissen, dass ich esse und dass ich dich vor dem HERRN segne, bevor ich sterbe!" },
      { number: 8, text: "Und nun, mein Sohn, höre auf meine Stimme in dem, was ich dir auftrage!" },
      { number: 9, text: "Geh doch zur Herde, und hole mir von dort zwei gute Ziegenböckchen! Und ich will sie zu einem Leckerbissen für deinen Vater zubereiten, wie er es liebt." },
      { number: 10, text: "Dann sollst du es deinem Vater bringen, dass er isst, damit er dich vor seinem Tod segnet." },
      { number: 11, text: "Da sagte Jakob zu Rebekka, seiner Mutter: Siehe, mein Bruder Esau ist ein behaarter Mann*, und ich bin ein glatter Mann.", footnotes: ["℘ V. 23; Kap. 25,25"] },
      { number: 12, text: "Vielleicht betastet mich mein Vater; dann wäre ich in seinen Augen wie einer, der Spott mit ihm treibt, und würde Fluch auf mich bringen und nicht Segen*.", footnotes: ["℘ 5Mo 27,18"] },
      { number: 13, text: "Seine Mutter aber sagte zu ihm: Dein Fluch komme auf mich, mein Sohn! Höre nur auf meine Stimme, und geh, hole mir!*", footnotes: ["℘ 2Chr 22,3"] },
      { number: 14, text: "Und er ging und holte und brachte sie seiner Mutter. Und seine Mutter bereitete einen Leckerbissen, wie sein Vater es gern hatte." },
      { number: 15, text: "Dann nahm Rebekka die guten* Kleider ihres älteren Sohnes Esau, die bei ihr im Haus waren, und zog sie ihrem jüngeren Sohn Jakob an.", footnotes: ["w. die kostbaren"] },
      { number: 16, text: "Die Felle der Ziegenböckchen aber zog sie über seine Hände und über die Glätte seines Halses," },
      { number: 17, text: "und sie gab den Leckerbissen und das Brot, das sie bereitet hatte, in die Hand ihres Sohnes Jakob." },
      { number: 18, text: "So ging er zu seinem Vater hinein und sagte: Mein Vater! Und er sagte: Hier bin ich. Wer bist du, mein Sohn?" },
      { number: 19, text: "Da sagte Jakob zu seinem Vater: Ich bin Esau, dein Erstgeborener; ich habe getan, wie du zu mir geredet hast. Richte dich doch auf, setze dich, und iss von meinem Wildbret, damit deine Seele mich segnet!" },
      { number: 20, text: "Isaak aber sagte zu seinem Sohn: Wie hast du es denn so schnell gefunden, mein Sohn? Er sagte: Weil der HERR, dein Gott, es mir begegnen ließ*.", footnotes: ["℘ 2Mo 20,7"] },
      { number: 21, text: "Da sagte Isaak zu Jakob: Tritt doch heran, dass ich dich betaste, mein Sohn, ob du wirklich mein Sohn Esau bist oder nicht!" },
      { number: 22, text: "Und Jakob trat zu seinem Vater Isaak heran; und er betastete ihn und sagte: Die Stimme ist Jakobs Stimme, aber die Hände sind Esaus Hände." },
      { number: 23, text: "Und er erkannte ihn nicht, weil seine Hände behaart waren wie die Hände seines Bruders Esau*. Da segnete er ihn.", footnotes: ["℘ V. 11"] },
      { number: 24, text: "Und er sagte: Bist du wirklich mein Sohn Esau? Er aber sagte: Ich bin's*.", footnotes: ["℘ 1Kö 13,18"] },
      { number: 25, text: "Da sagte er: Reiche es mir her! Ich will von dem Wildbret meines Sohnes essen, damit meine Seele dich segnet. Und er reichte es ihm hin, so dass er aß. Auch brachte er ihm Wein, und er trank." },
      { number: 26, text: "Dann sagte sein Vater Isaak zu ihm: Tritt doch heran und küss mich, mein Sohn!" },
      { number: 27, text: "Da trat er heran und küsste ihn. Und als er den Geruch seiner Kleider roch, da segnete er ihn* und sprach: Siehe, der Geruch meines Sohnes ist wie der Geruch eines Feldes, das der HERR gesegnet hat.", footnotes: ["℘ V. 39; Kap. 48,15; Hebr 11,20"] },
      { number: 28, text: "So gebe dir Gott vom Tau des Himmels* und vom Fett der Erde* und von Korn und Most die Fülle!", footnotes: ["℘ 5Mo 11,11; 33,13.28", "℘ Kap. 45,18"] },
      { number: 29, text: "Völker sollen dir dienen und Völkerschaften sich vor dir niederbeugen*! Sei Herr über deine Brüder*, und vor dir sollen sich niederbeugen die Söhne deiner Mutter! Die dir fluchen, seien verflucht, und die dich segnen, seien gesegnet*!", footnotes: ["℘ Kap. 22,17", "℘ V. 40; Kap. 25,23", "℘ Kap. 12,3"] },
      { number: 30, text: "Und es geschah, sobald Isaak geendet hatte, Jakob zu segnen, ja, es geschah, als Jakob gerade eben von seinem Vater Isaak hinausgegangen war, da kam sein Bruder Esau von seiner Jagd." },
      { number: 31, text: "Und auch er bereitete einen Leckerbissen, brachte ihn zu seinem Vater und sagte zu seinem Vater: Mein Vater richte sich auf und esse von dem Wildbret seines Sohnes, damit deine Seele mich segne!" },
      { number: 32, text: "Da sagte sein Vater Isaak zu ihm: Wer bist du? Er sagte: Ich bin dein erstgeborener Sohn Esau." },
      { number: 33, text: "Da erschrak Isaak mit großem Schrecken über alle Maßen und sagte: Wer war denn der, der ein Wildbret erjagt und mir gebracht hat, dass ich von allem gegessen habe, bevor du kamst, und ich ihn gesegnet habe? Er wird auch gesegnet bleiben*.", footnotes: ["℘ Kap. 28,1.3.4"] },
      { number: 34, text: "Als Esau die Worte seines Vaters hörte, da schrie er mit lautem und erbittertem Geschrei über alle Maßen* und sagte zu seinem Vater: Segne mich, auch mich, mein Vater!*", footnotes: ["℘ Est 4,1", "℘ Hebr 12,17"] },
      { number: 35, text: "Er aber sagte: Dein Bruder ist mit Betrug* gekommen* und hat deinen Segen weggenommen.", footnotes: ["o. Hinterlist", "℘ Kap. 29,25"] },
      { number: 36, text: "Da sagte er: Heißt er darum Jakob*, weil er mich nun schon zweimal betrogen* hat? Mein Erstgeburtsrecht hat er genommen, und siehe, jetzt hat er auch meinen Segen genommen*! Und er sagte: Hast du mir keinen Segen aufbehalten?", footnotes: ["hebr. jaakob\n℘ Kap. 25,26", "hebr. jaakebeni; vgl. die Anm. zu Kap. 25,26", "℘ Kap. 25,33.34"] },
      { number: 37, text: "Da antwortete Isaak und sagte zu Esau: Siehe, ich habe ihn zum Herrn über dich gesetzt* und alle seine Brüder ihm zu Knechten gegeben, und mit Korn und Most habe ich ihn versehen, und nun, was kann ich da noch für dich tun, mein Sohn?", footnotes: ["℘ Kap. 25,23; 1Kö 22,48"] },
      { number: 38, text: "Da sagte Esau zu seinem Vater: Hast du nur diesen einen Segen, mein Vater? Segne mich, auch mich, mein Vater! Und Esau erhob seine Stimme und weinte*.", footnotes: ["℘ Hebr 12,17"] },
      { number: 39, text: "Da antwortete sein Vater Isaak und sagte zu ihm*: Siehe, fern vom Fett der Erde wird dein Wohnsitz sein und fern vom Tau des Himmels oben.", footnotes: ["℘ V. 27"] },
      { number: 40, text: "Von deinem Schwert wirst du leben, und deinem Bruder wirst du dienen. Doch wird es geschehen, wenn du dich losmachst*, wirst du sein Joch von deinem Hals wegreißen*.", footnotes: ["Andere lesen mit Änderung des Mas. T.: wenn du durchhältst; LXX: wenn du niederwirfst", "℘ 2Kö 8,20"] },
      { number: 41, text: "Und Esau war dem Jakob feind wegen des Segens, mit dem sein Vater ihn gesegnet hatte; und Esau sagte in seinem Herzen: Es nahen die Tage der Trauer um meinen Vater, dann werde ich meinen Bruder Jakob erschlagen*.", heading: "Esaus Rachegedanken", footnotes: ["℘ Kap. 37,18.20; Spr 18,19; Am 1,11; 1Jo 3,15"] },
      { number: 42, text: "Als nun der Rebekka die Worte ihres älteren Sohnes Esau berichtet wurden, da sandte sie hin, rief ihren jüngeren Sohn Jakob und sagte zu ihm: Siehe, dein Bruder Esau will an dir Rache nehmen und dich erschlagen." },
      { number: 43, text: "Und nun, mein Sohn, höre auf meine Stimme, und mache dich auf, flieh zu meinem Bruder Laban, nach Haran*;", footnotes: ["℘ Kap. 11,31; 24,29; 25,20"] },
      { number: 44, text: "und bleib einige Tage bei ihm, bis der Grimm deines Bruders sich wendet," },
      { number: 45, text: "bis der Zorn deines Bruders sich von dir abwendet und er vergisst, was du ihm angetan hast! Dann will ich hinsenden und dich von dort holen lassen. Warum sollte ich euch beide an einem Tag verlieren?" },
      { number: 46, text: "Und Rebekka sagte zu Isaak: Ich bin des Lebens überdrüssig wegen der Töchter Hets*. Wenn Jakob auch eine Frau wie diese nimmt, von den Töchtern Hets, von den Töchtern des Landes, was sollte mir dann noch das Leben?", footnotes: ["℘ Kap. 26,35"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Da rief Isaak den Jakob und segnete ihn*. Und er befahl ihm und sagte zu ihm: Nimm dir nicht eine Frau von den Töchtern Kanaans!*", heading: "Jakobs Flucht nach Haran", footnotes: ["℘ Kap. 27,33", "℘ Kap. 24,3"] },
      { number: 2, text: "Mache dich auf, geh nach Paddan-Aram* zum Haus Betuëls, des Vaters deiner Mutter*, und nimm dir von dort eine Frau von den Töchtern Labans, des Bruders deiner Mutter!", footnotes: ["s. Anm. zu Kap. 25,20\n℘ Hos 12,13", "℘ Kap. 22,23; 24,4.29"] },
      { number: 3, text: "Gott, der Allmächtige*, segne dich* und mache dich fruchtbar und vermehre dich, dass du zu einer Schar von Völkern werdest*;", footnotes: ["hebr. el schaddai", "℘ Rt 2,4", "℘ Kap. 17,4-6; 24,60"] },
      { number: 4, text: "und er gebe dir den Segen Abrahams, dir und deiner Nachkommenschaft mit dir, damit du das Land deiner Fremdlingschaft, das Gott dem Abraham gegeben hat*, in Besitz nehmest!", footnotes: ["℘ Kap. 12,2.7; 17,8"] },
      { number: 5, text: "So entließ Isaak den Jakob, und er ging nach Paddan-Aram* zu Laban, dem Sohn des Aramäers Betuël*, dem Bruder Rebekkas, der Mutter Jakobs und Esaus.", footnotes: ["s. Anm. zu Kap. 25,20", "℘ 5Mo 26,5"] },
      { number: 6, text: "Und als Esau sah, dass Isaak den Jakob gesegnet und ihn nach Paddan-Aram* entlassen hatte, sich von dort eine Frau zu nehmen, indem er ihn segnete und ihm gebot: Nimm ja nicht eine Frau von den Töchtern Kanaans!,", heading: "Esaus dritte Frau", footnotes: ["s. Anm. zu Kap. 25,20"] },
      { number: 7, text: "und dass Jakob seinem Vater und seiner Mutter gehorchte und nach Paddan-Aram* ging,", footnotes: ["s. Anm. zu Kap. 25,20"] },
      { number: 8, text: "da sah Esau, dass die Töchter Kanaans übel waren in den Augen seines Vaters Isaak*,", footnotes: ["℘ Kap. 26,35"] },
      { number: 9, text: "und Esau ging zu Ismael und nahm sich Mahalat zur Frau, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajots*, zu seinen anderen Frauen hinzu*.", footnotes: ["℘ Kap. 25,13", "℘ Kap. 26,34"] },
      { number: 10, text: "Und Jakob zog aus von Beerscheba und ging nach Haran*.", heading: "Jakobs Traum und Gelübde", footnotes: ["℘ Kap. 11,31; 35,1.7"] },
      { number: 11, text: "Und er gelangte an eine Stätte und übernachtete dort; denn die Sonne war schon untergegangen. Und er nahm einen von den Steinen der Stätte und legte ihn an sein Kopfende und legte sich nieder an jener Stätte." },
      { number: 12, text: "Und er träumte*: Und siehe, eine Leiter war auf die Erde gestellt, und ihre Spitze berührte den Himmel; und siehe, Engel Gottes stiegen darauf auf und nieder*.", footnotes: ["℘ Kap. 20,3", "℘ Joh 1,51"] },
      { number: 13, text: "Und siehe, der HERR stand über ihr* und sprach: Ich bin der HERR, der Gott deines Vaters Abraham und der Gott Isaaks*; das Land, auf dem du liegst, dir will ich es geben und deiner Nachkommenschaft*.", footnotes: ["o. vor ihm, ihm gegenüber\n℘ Kap. 35,1; 48,3", "℘ Kap. 17,7; 32,10; 46,3; 2Mo 3,6.15", "℘ Kap. 12,7; 2Mo 2,24; Hes 28,25"] },
      { number: 14, text: "Und deine Nachkommenschaft soll wie der Staub der Erde werden*, und du wirst dich ausbreiten nach Westen und nach Osten und nach Norden und nach Süden hin; und in dir und in deiner Nachkommenschaft sollen gesegnet werden alle Geschlechter* der Erde*.", footnotes: ["℘ Kap. 13,16; 2Mo 32,13", "o. sich Segen wünschen alle Sippen", "℘ Kap. 12,3"] },
      { number: 15, text: "Und siehe, ich bin mit dir*, und ich will dich behüten überall, wohin du gehst*, und dich in dieses Land zurückbringen*; denn ich werde dich nicht verlassen*, bis ich getan, was ich zu dir geredet habe*.", footnotes: ["℘ Kap. 31,3.5; Apg 18,10", "℘ Ps 91,11; 121,7", "℘ Kap. 30,25; 35,6.27; 46,4; Jer 16,15", "℘ 5Mo 31,6.8; Hebr 13,5", "℘ Kap. 35,3; 3Mo 26,42"] },
      { number: 16, text: "Da erwachte Jakob aus seinem Schlaf* und sagte: Fürwahr, der HERR ist an dieser Stätte, und ich habe es nicht erkannt!", footnotes: ["℘ 4Mo 12,6"] },
      { number: 17, text: "Und er fürchtete sich* und sagte: Wie furchtbar ist diese Stätte! Dies ist nichts anderes als das Haus Gottes* und dies die Pforte des Himmels.", footnotes: ["℘ 2Mo 3,6", "℘ Kap. 35,7.14.15"] },
      { number: 18, text: "Und Jakob stand früh am Morgen auf* und nahm den Stein, den er an sein Kopfende gelegt hatte, und stellte ihn auf als Gedenkstein* und goss Öl auf seine Spitze*.", footnotes: ["℘ Kap. 21,14", "℘ Kap. 31,45; Jos 24,26; 1Sam 7,12", "℘ Kap. 31,13; 35,14"] },
      { number: 19, text: "Und er gab dieser Stätte den Namen Bethel*. Im Anfang jedoch war Lus der Name der Stadt*.", footnotes: ["d. h. Haus Gottes\n℘ Kap. 12,8; 35,1.7.15; Jos 18,13.22; Ri 20,26; 1Sam 7,16; 1Kö 12,29; 2Kö 2,2; 2Chr 13,19", "℘ Kap. 48,3; Jos 16,2"] },
      { number: 20, text: "Und Jakob legte ein Gelübde ab* und sagte: Wenn Gott mit mir ist und mich behütet auf diesem Weg, den ich gehe, und mir Brot zu essen und Kleidung anzuziehen gibt", footnotes: ["℘ Kap. 31,13; 4Mo 21,2; Ri 11,30; 1Sam 1,11"] },
      { number: 21, text: "und ich in Frieden zurückkehre zum Haus meines Vaters, dann soll der HERR mein Gott* sein*.", footnotes: ["w. mir zum Gott", "℘ 5Mo 26,17; 2Sam 15,8; 1Chr 4,10"] },
      { number: 22, text: "Und dieser Stein, den ich als Gedenkstein aufgestellt habe, soll ein Haus Gottes werden*; und alles, was du mir geben wirst, werde ich dir treu verzehnten*.", footnotes: ["℘ Kap. 35,7.14.15", "℘ Kap. 14,20; 3Mo 27,32; Mal 3,10"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Und Jakob machte sich auf* und ging in das Land der Söhne des Ostens*.", heading: "Jakobs Ankunft und Dienst bei Laban", footnotes: ["w. hob seine Füße", "℘ Kap. 25,6; 35,1.7"] },
      { number: 2, text: "Und er sah, und siehe, da war ein Brunnen auf dem Feld*; und siehe, drei Schafherden lagerten dort an ihm, denn aus diesem Brunnen tränkte man* die Herden; und der Stein auf der Öffnung des Brunnens war groß.", footnotes: ["℘ Kap. 24,11", "w. tränkten sie; das sind die Hirten"] },
      { number: 3, text: "Und waren alle Herden dort versammelt*, dann wälzte man den Stein von der Öffnung des Brunnens und tränkte die Schafe; dann brachte man den Stein wieder auf die Öffnung des Brunnens an seine Stelle.", footnotes: ["d. h. zu den Hirten"] },
      { number: 4, text: "Und Jakob sagte zu ihnen: Meine Brüder, woher seid ihr? Und sie sagten: Wir sind von Haran*.", footnotes: ["℘ Kap. 11,31"] },
      { number: 5, text: "Da sagte er zu ihnen: Kennt ihr Laban, den Sohn Nahors*? Sie sagten: Wir kennen ihn.", footnotes: ["℘ Kap. 24,15.29"] },
      { number: 6, text: "Und er sagte zu ihnen: Geht es ihm gut*? Sie sagten: Es geht ihm gut*; doch siehe, da kommt seine Tochter Rahel* mit den Schafen.", footnotes: ["w. Hat er Frieden", "w. Sie sagten: Frieden", "hebr. rachel; d. h. Mutterschaf"] },
      { number: 7, text: "Da sagte er: Siehe, es ist noch hoch am Tag, es ist nicht Zeit, das Vieh zu sammeln. Tränkt die Schafe, und geht hin, weidet sie!" },
      { number: 8, text: "Sie aber sagten: Wir können nicht, bis alle Herden sich versammelt haben; dann wälzt man den Stein von der Öffnung des Brunnens und wir tränken die Schafe." },
      { number: 9, text: "Noch redete er mit ihnen, da kam Rahel* mit den Schafen, die ihrem Vater gehörten; denn sie war eine Hirtin.", footnotes: ["hebr. rachel; d. h. Mutterschaf"] },
      { number: 10, text: "Und es geschah, als Jakob die Rahel* sah, die Tochter Labans, des Bruders seiner Mutter, und die Schafe Labans, des Bruders seiner Mutter, da trat Jakob hinzu und wälzte den Stein von der Öffnung des Brunnens und tränkte die Schafe Labans, des Bruders seiner Mutter*.", footnotes: ["hebr. rachel; d. h. Mutterschaf", "℘ 2Mo 2,17"] },
      { number: 11, text: "Und Jakob küsste Rahel und erhob seine Stimme und weinte." },
      { number: 12, text: "Und Jakob berichtete Rahel, dass er ein Neffe* ihres Vaters und dass er der Sohn Rebekkas sei. Da lief sie und berichtete es ihrem Vater.", footnotes: ["w. Bruder"] },
      { number: 13, text: "Und es geschah, als Laban die Nachricht von Jakob, dem Sohn seiner Schwester, hörte, da lief er ihm entgegen und umarmte ihn und küsste ihn und führte ihn in sein Haus*. Und er erzählte dem Laban alle diese Dinge.", footnotes: ["℘ Kap. 24,32"] },
      { number: 14, text: "Und Laban sagte zu ihm: Fürwahr, du bist mein Bein und mein Fleisch*. Und er blieb bei ihm einen Monat lang.", footnotes: ["℘ Kap. 37,27; Ri 9,2; 2Sam 5,1; Eph 5,30"] },
      { number: 15, text: "Und Laban sagte zu Jakob: Solltest du, weil du mein Neffe* bist, mir umsonst dienen? Sag mir, was soll dein Lohn sein?*", footnotes: ["w. Bruder", "℘ Kap. 30,28"] },
      { number: 16, text: "Laban aber hatte zwei Töchter; der Name der älteren war Lea* und der Name der jüngeren Rahel*.", footnotes: ["Der Name Lea wird im AT von einem Verb abgeleitet, das »müde werden« bedeutet.", "hebr. rachel; d. h. Mutterschaf\n℘ Rt 4,11"] },
      { number: 17, text: "Leas Augen waren matt*; Rahel aber war schön von Gestalt und schön von Aussehen*.", footnotes: ["o. zart, schwach", "℘ Kap. 12,11"] },
      { number: 18, text: "Und Jakob liebte Rahel; so sagte er: Ich will dir sieben Jahre für deine jüngere Tochter Rahel dienen." },
      { number: 19, text: "Da sagte Laban: Besser, ich gebe sie dir, als dass ich sie einem andern* Mann gebe. Bleibe bei mir!", footnotes: ["o. fremden"] },
      { number: 20, text: "So diente Jakob für Rahel sieben Jahre*; und sie waren in seinen Augen wie einige wenige* Tage, weil er sie liebte*.", footnotes: ["℘ V. 27.30; Kap. 30,26; 31,15.41; Hos 12,13", "o. einzelne", "℘ Kap. 34,19"] },
      { number: 21, text: "Und Jakob sagte zu Laban: Gib mir nun meine Frau! Denn meine Tage sind erfüllt, dass ich zu ihr eingehe.", heading: "Jakobs Heirat" },
      { number: 22, text: "Da versammelte Laban alle Männer des Ortes und veranstaltete ein Mahl*.", footnotes: ["℘ Ri 14,10; Est 2,18"] },
      { number: 23, text: "Und es geschah am Abend, da nahm er seine Tochter Lea und brachte sie zu ihm; und er ging zu ihr ein." },
      { number: 24, text: "Und Laban gab ihr, seiner Tochter Lea, seine Magd Silpa als Magd*.", footnotes: ["℘ Kap. 30,9; 35,26; 46,18"] },
      { number: 25, text: "Und es geschah am Morgen, siehe, da war es Lea. Da sagte er zu Laban: Was hast du mir da angetan?* Habe ich nicht für Rahel bei dir gedient? Warum hast du mich betrogen?*", footnotes: ["℘ Kap. 12,18; 31,26", "℘ Kap. 27,35"] },
      { number: 26, text: "Laban aber sagte: Das tut man an unserm Ort nicht, die Jüngere vor der Erstgeborenen zu geben." },
      { number: 27, text: "Vollende die Hochzeitswoche* mit dieser! Dann wollen wir dir auch jene geben, für den Dienst, den du bei mir noch weitere sieben Jahre dienen sollst*.", footnotes: ["℘ Ri 14,12", "℘ V. 20"] },
      { number: 28, text: "Und Jakob tat so und vollendete die Hochzeitswoche mit dieser. Dann gab er ihm seine Tochter Rahel zur Frau." },
      { number: 29, text: "Und Laban gab seiner Tochter Rahel seine Magd Bilha als ihre Magd*.", footnotes: ["℘ Kap. 30,4; 35,25; 46,25"] },
      { number: 30, text: "Da ging er auch zu Rahel ein. Und er liebte auch Rahel, mehr als Lea*. Und er diente bei ihm noch weitere sieben Jahre*.", footnotes: ["℘ 5Mo 21,15", "℘ V. 20"] },
      { number: 31, text: "Und als der HERR sah, dass Lea zurückgesetzt* war, da öffnete er ihren Mutterleib; Rahel aber war unfruchtbar*.", heading: "Jakobs Kinder", footnotes: ["o. ungeliebt; w. gehasst", "℘ Kap. 11,30"] },
      { number: 32, text: "Und Lea wurde schwanger und gebar einen Sohn, und sie gab ihm den Namen Ruben*, denn sie sagte: Ja, der HERR hat mein Elend angesehen*. Denn jetzt wird mein Mann mich lieben.", footnotes: ["d. h. Seht, ein Sohn!\n℘ 1Chr 5,1", "℘ Kap. 31,42; 2Mo 3,7; 1Sam 1,11; 2Sam 16,12"] },
      { number: 33, text: "Und sie wurde wieder schwanger und gebar einen Sohn; und sie sagte: Ja, der HERR hat gehört, dass ich zurückgesetzt bin, so hat er mir auch den gegeben. Und sie gab ihm den Namen Simeon*.", footnotes: ["Simeon wird hier von »hören« abgeleitet: Erhörung"] },
      { number: 34, text: "Und sie wurde wieder schwanger und gebar einen Sohn; da sagte sie: Diesmal endlich wird sich mein Mann an mich anschließen*, denn ich habe ihm drei Söhne geboren.* Darum gab man ihm den Namen Levi*.", footnotes: ["o. an mich gebunden sein\n℘ 4Mo 18,2", "℘ Kap. 30,20", "Levi wird hier von »sich anschließen« abgeleitet: Anhänglichkeit"] },
      { number: 35, text: "Dann wurde sie noch einmal schwanger und gebar einen Sohn; und sie sagte: Diesmal will ich den HERRN preisen! Darum gab sie ihm den Namen Juda*. Und sie hörte auf zu gebären*.", footnotes: ["Juda wird hier von »preisen« abgeleitet: Lobpreis\n℘ Mt 1,2; Lk 3,33", "℘ Kap. 30,9"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Und als Rahel sah, dass sie dem Jakob nicht gebar, da war Rahel auf ihre Schwester eifersüchtig und sagte zu Jakob: Gib mir Kinder! Und wenn nicht, dann sterbe ich*.", footnotes: ["℘ 1Sam 1,10; Spr 30,16"] },
      { number: 2, text: "Da entbrannte Jakobs Zorn gegen Rahel, und er sagte: Bin ich an Gottes Stelle*, der dir Leibesfrucht vorenthalten hat?", footnotes: ["℘ Kap. 50,19; 2Kö 5,7"] },
      { number: 3, text: "Sie sagte: Siehe, da ist meine Magd Bilha. Geh zu ihr ein, dass sie auf meinen Knien* gebäre* und auch ich aus ihr erbaut werde*!", footnotes: ["o. auf meine Knie; o. mir zugut; d. h., dass das Kind als Kind der Rahel gilt", "℘ Kap. 50,23", "℘ Kap. 16,2"] },
      { number: 4, text: "Und sie gab ihm ihre Magd Bilha zur Frau*; und Jakob ging zu ihr ein.", footnotes: ["℘ Kap. 16,3"] },
      { number: 5, text: "Da wurde Bilha schwanger und gebar Jakob einen Sohn." },
      { number: 6, text: "Rahel aber sagte: Gott hat mir Recht verschafft und auch auf meine Stimme gehört und mir einen Sohn gegeben. Darum gab sie ihm den Namen Dan*.", footnotes: ["d. h. er hat gerichtet, er hat Recht verschafft"] },
      { number: 7, text: "Und Rahels Magd Bilha wurde noch einmal schwanger und gebar dem Jakob einen zweiten Sohn." },
      { number: 8, text: "Da sprach Rahel: Kämpfe Gottes habe ich mit meiner Schwester gekämpft, habe auch gesiegt. Und sie gab ihm den Namen Naftali*.", footnotes: ["Der Name klingt an hebr. naftulim an: Kämpfe"] },
      { number: 9, text: "Und als Lea sah, dass sie aufhörte zu gebären*, da nahm sie ihre Magd Silpa und gab sie Jakob zur Frau*.", footnotes: ["℘ Kap. 29,35", "℘ Kap. 16,3"] },
      { number: 10, text: "Und Silpa, die Magd Leas, gebar dem Jakob einen Sohn." },
      { number: 11, text: "Da sagte Lea: Zum Glück*! Und sie gab ihm den Namen Gad*.", footnotes: ["mit der Leseform des Mas. T.: Glück ist gekommen", "d. h. Glück"] },
      { number: 12, text: "Und Silpa, die Magd Leas, gebar dem Jakob einen zweiten Sohn." },
      { number: 13, text: "Da sprach Lea: Zu meiner Glückseligkeit! Denn glückselig preisen mich die Töchter*. Und sie gab ihm den Namen Asser*.", footnotes: ["℘ Lk 1,48", "Der Name Asser klingt an das hebr. oscher an: Glück"] },
      { number: 14, text: "Und Ruben ging aus in den Tagen der Weizenernte und fand Dudaim* auf dem Feld*; und er brachte sie seiner Mutter Lea. Da sagte Rahel zu Lea: Gib mir doch von den Dudaim* deines Sohnes!", footnotes: ["Das sind die Früchte der Alraune, die als Liebesäpfel galten.", "℘ Hl 7,14", "Das sind die Früchte der Alraune, die als Liebesäpfel galten."] },
      { number: 15, text: "Sie aber sagte zu ihr: Ist es dir zu wenig, meinen Mann zu nehmen, dass du auch die Dudaim* meines Sohnes nehmen willst? Da sagte Rahel: So mag er denn diese Nacht bei dir liegen als Entgelt für die Dudaim* deines Sohnes.", footnotes: ["s. Anm. zu V. 14", "s. Anm. zu V. 14"] },
      { number: 16, text: "Und als Jakob am Abend vom Feld kam, da ging Lea hinaus, ihm entgegen, und sagte: Zu mir sollst du eingehen, denn gekauft habe ich dich, gekauft mit den Dudaim* meines Sohnes. Da lag er in dieser Nacht bei ihr.", footnotes: ["s. Anm. zu V. 14"] },
      { number: 17, text: "Und Gott hörte auf Lea, so dass sie schwanger wurde und dem Jakob einen fünften Sohn gebar." },
      { number: 18, text: "Da sagte Lea: Gott hat mir meinen Lohn gegeben dafür, dass ich meinem Mann meine Magd gegeben habe. Und sie gab ihm den Namen Issaschar*.", footnotes: ["Issaschar wird hier von »Lohn« abgeleitet: Es gibt Lohn, o. Mann des Lohnes"] },
      { number: 19, text: "Und Lea wurde noch einmal schwanger und gebar dem Jakob einen sechsten Sohn." },
      { number: 20, text: "Da sagte Lea: Mir hat Gott ein schönes Geschenk geschenkt; diesmal wird mein Mann mich erheben*, denn ich habe ihm sechs Söhne geboren*. Und sie gab ihm den Namen Sebulon*.", footnotes: ["d. h. zur vollgültigen Ehefrau machen; andere Üs.: bei mir wohnen, o. mich ertragen", "℘ Kap. 29,34", "vom hebr. sabal abgeleitet: zur rechtmäßigen Ehefrau erheben"] },
      { number: 21, text: "Und danach gebar sie eine Tochter und gab ihr den Namen Dina*.", footnotes: ["℘ Kap. 34,1"] },
      { number: 22, text: "Und Gott dachte an Rahel, und Gott hörte auf sie und öffnete ihren Mutterleib*.", footnotes: ["℘ Kap. 25,21; 1Sam 1,19"] },
      { number: 23, text: "Und sie wurde schwanger und gebar einen Sohn. Da sagte sie: Gott hat meine Schmach weggenommen*.", footnotes: ["℘ Jes 4,1; Lk 1,25"] },
      { number: 24, text: "Und sie gab ihm den Namen Josef* und sagte: Der HERR füge mir einen anderen Sohn hinzu!*", footnotes: ["Josef bedeutet: Er füge hinzu", "℘ Kap. 35,17"] },
      { number: 25, text: "Und es geschah, als Rahel den Josef geboren hatte, da sagte Jakob zu Laban: Entlass mich, dass ich an meinen Ort und in mein Land ziehe*!", heading: "Jakobs listiger Vermögenserwerb", footnotes: ["℘ Kap. 28,15"] },
      { number: 26, text: "Gib mir meine Frauen und meine Kinder, für die ich dir gedient habe, damit ich wegziehe! Du selbst kennst ja meinen Dienst, mit dem ich dir gedient habe*.", footnotes: ["℘ Kap. 29,20.30; 31,6.41"] },
      { number: 27, text: "Laban aber sagte zu ihm: Wenn ich doch Gunst gefunden habe in deinen Augen — ich habe durch Wahrsagung erfahren, dass der HERR mich deinetwegen gesegnet hat*.", footnotes: ["o. ich habe unter einem bösen Zeichen gestanden, aber der HERR hat mich deinetwegen gesegnet\n℘ Kap. 39,5"] },
      { number: 28, text: "Und er sagte: Bestimme mir deinen Lohn, so will ich ihn dir geben*!", footnotes: ["℘ Kap. 29,15"] },
      { number: 29, text: "Da sagte er zu ihm: Du weißt* ja selbst, wie ich dir gedient habe und was aus deinem Vieh bei mir geworden ist*.", footnotes: ["o. erkennst", "℘ Kap. 31,38.39"] },
      { number: 30, text: "Denn wenig war, was du vor mir hattest, und es hat sich zu einer Menge ausgebreitet, und der HERR hat dich gesegnet auf jedem meiner Tritte. Nun aber, wann soll ich auch für mein Haus schaffen?" },
      { number: 31, text: "Da sagte er: Was soll ich dir geben? Und Jakob sagte: Du sollst mir gar nichts geben; wenn du mir diese eine Sache zugestehst, dann will ich wieder deine Schafe weiden und hüten." },
      { number: 32, text: "Ich will heute durch deine ganze Herde gehen und daraus aussondern jedes gesprenkelte und gefleckte Tier und jedes dunkelfarbige Tier* unter den Schafen und das Gefleckte und Gesprenkelte unter den Ziegen: Das sei mein Lohn*!", footnotes: ["o. (Tier) von unbestimmter Farbe", "℘ Kap. 31,8"] },
      { number: 33, text: "Und meine Gerechtigkeit soll an einem künftigen Tag* für mich zeugen, wenn du herkommst wegen meines Lohnes vor dir: Alles, was nicht gesprenkelt und gefleckt ist unter den Ziegen und dunkelfarbig* unter den Schafen, das gelte als gestohlen bei mir.", footnotes: ["w. an einem Tag, nämlich morgen", "o. (Tier) von unbestimmter Farbe"] },
      { number: 34, text: "Da sagte Laban: Siehe, es geschehe nach deinem Wort!" },
      { number: 35, text: "So sonderte er an jenem Tag die gestreiften und gefleckten Böcke aus und alle gesprenkelten und gefleckten Ziegen, alles, woran etwas Weißes war, und alles Dunkelfarbige* unter den Schafen, und gab sie in die Hand seiner Söhne.", footnotes: ["o. (Tier) von unbestimmter Farbe"] },
      { number: 36, text: "Und er legte einen Weg von drei Tagereisen zwischen sich und Jakob; und Jakob weidete die übrige Herde Labans." },
      { number: 37, text: "Und Jakob nahm sich frische Stäbe von Storaxbaum, Mandelbaum und Platane und schälte an ihnen weiße Streifen heraus, indem er das Weiße, das an den Stäben war, bloßlegte." },
      { number: 38, text: "Und er legte die Stäbe, die er geschält hatte, in die Tränkrinnen, in die Wassertränken, wohin die Tiere zum Trinken kamen, vor die Tiere hin; und sie waren brünstig, wenn sie zum Trinken kamen." },
      { number: 39, text: "So waren die Tiere vor den Stäben brünstig, und die Tiere warfen gestreifte, gesprenkelte und gefleckte Lämmer*.", footnotes: ["℘ Kap. 31,9.10"] },
      { number: 40, text: "Und Jakob sonderte die Lämmer aus, und er richtete das Gesicht der Tiere auf das Gestreifte und alles Dunkelfarbige* unter den Tieren Labans; und so legte er eigene Herden an für sich besonders und tat sie nicht zu den Tieren Labans.", footnotes: ["o. von unbestimmter Farbe"] },
      { number: 41, text: "Und es geschah, sooft die kräftigen Tiere brünstig waren, legte Jakob die Stäbe vor die Augen der Tiere in die Tränkrinnen, damit sie bei den Stäben brünstig würden;" },
      { number: 42, text: "wenn aber die Tiere schwächlich waren, legte er sie nicht hin. So wurden die schwächlichen dem Laban zuteil und die kräftigen dem Jakob*.", footnotes: ["℘ Kap. 31,12"] },
      { number: 43, text: "Und der Mann breitete sich mehr und mehr aus, und er bekam viele Tiere, Mägde und Knechte, Kamele und Esel*.", footnotes: ["℘ Kap. 13,2"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Und er hörte die Reden der Söhne Labans, die sagten: Jakob hat alles an sich genommen, was unserem Vater gehörte; und von dem, was unserem Vater gehört, hat er sich all diesen Reichtum verschafft*.", heading: "Jakobs Flucht aus Haran — Übereinkunft mit Laban", footnotes: ["℘ Pred 4,4"] },
      { number: 2, text: "Und Jakob sah das Gesicht Labans, und siehe, es* war ihm gegenüber nicht wie früher*.", footnotes: ["so mit SamPent; Mas. T.: er", "w. wie gestern und vorgestern\n℘ 1Sam 18,9"] },
      { number: 3, text: "Und der HERR sprach zu Jakob: Kehre zurück in das Land deiner Väter und zu deiner Verwandtschaft! Ich werde mit dir sein*.", footnotes: ["℘ Kap. 28,15; 32,10"] },
      { number: 4, text: "Da sandte Jakob hin und rief Rahel und Lea aufs Feld zu seinen Tieren." },
      { number: 5, text: "Und er sagte zu ihnen: Ich sehe das Gesicht eures Vaters, dass es* zu mir nicht wie früher* ist; aber der Gott meines Vaters ist mit mir gewesen*.", footnotes: ["so mit SamPent; Mas. T.: er", "w. wie gestern und vorgestern", "℘ Kap. 26,24"] },
      { number: 6, text: "Ihr selbst wisst* ja, dass ich mit all meiner Kraft eurem Vater gedient habe*.", footnotes: ["o. erkennt", "℘ Kap. 30,26.29"] },
      { number: 7, text: "Und euer Vater hat mich betrogen und hat meinen Lohn zehnmal* verändert*; aber Gott hat ihm nicht gestattet, mir Böses zu tun*.", footnotes: ["℘ 4Mo 14,22", "℘ V. 41", "℘ Kap. 20,6.7"] },
      { number: 8, text: "Wenn er so sagte: Die Gesprenkelten sollen dein Lohn sein, dann gebaren alle Tiere Gesprenkelte; und wenn er so sagte: Die Gestreiften sollen dein Lohn sein, dann gebaren alle Tiere Gestreifte*.", footnotes: ["℘ Kap. 30,32"] },
      { number: 9, text: "Und Gott hat eurem Vater das Vieh entzogen und mir gegeben." },
      { number: 10, text: "Und es geschah zur Brunstzeit der Tiere, da erhob ich meine Augen und sah im Traum; und siehe, die Böcke, die die Tiere besprangen, waren gestreift, gesprenkelt und scheckig*.", footnotes: ["℘ Kap. 30,39"] },
      { number: 11, text: "Und der Engel Gottes* sprach im Traum zu mir: Jakob! Und ich sagte: Hier bin ich!", footnotes: ["℘ Kap. 22,15"] },
      { number: 12, text: "Und er sprach: Erheb doch deine Augen und sieh: Alle Böcke, die die Tiere bespringen, sind gestreift, gesprenkelt und scheckig*; denn ich habe alles gesehen, was Laban dir antut*.", footnotes: ["℘ Kap. 30,42", "℘ 2Mo 3,7.9; Ps 10,14"] },
      { number: 13, text: "Ich bin der Gott von Bethel, wo du einen Gedenkstein gesalbt, wo du mir ein Gelübde abgelegt hast*. Mache dich jetzt auf, zieh aus diesem Land und kehre zurück in das Land deiner Verwandtschaft!", footnotes: ["℘ Kap. 28,18-22"] },
      { number: 14, text: "Da antworteten Rahel und Lea und sagten zu ihm: Haben wir noch einen Anteil und ein Erbe im Haus unseres Vaters?" },
      { number: 15, text: "Haben wir ihm nicht als Fremde gegolten? Denn er hat uns verkauft* und hat sogar unseren Kaufpreis* völlig verzehrt.", footnotes: ["℘ Kap. 29,20.27", "w. unser Silber"] },
      { number: 16, text: "Denn aller Reichtum, den Gott unserem Vater entzogen hat, uns gehört er und unseren Kindern. So tu nun alles, was Gott zu dir gesagt hat!" },
      { number: 17, text: "Da machte Jakob sich auf und hob seine Kinder und seine Frauen auf die Kamele" },
      { number: 18, text: "und trieb all sein Vieh weg und all seine Habe, die er erworben, das Vieh seines Eigentums, das er in Paddan-Aram* erworben hatte, um zu seinem Vater Isaak in das Land Kanaan zu kommen.", footnotes: ["s. Anm. zu Kap. 25,20\n℘ Kap. 32,6"] },
      { number: 19, text: "Laban aber war gegangen, um seine Schafe zu scheren*; da stahl Rahel den Terafim*, der ihrem Vater gehörte*.", footnotes: ["℘ Kap. 38,13; 1Sam 25,2; 2Sam 13,23.24", "d. i. den Hausgötzen\n℘ Ri 17,5; 1Sam 19,13; 2Kö 23,24", "℘ Kap. 35,2; Jos 24,2"] },
      { number: 20, text: "Und Jakob täuschte Laban, den Aramäer*, weil er ihm nicht mitteilte, dass er fliehen wollte.", footnotes: ["w. stahl das Herz des Aramäers"] },
      { number: 21, text: "Und er floh, er und alles, was er hatte; und er machte sich auf und setzte über den Strom* und richtete sein Gesicht auf das Gebirge Gilead.", footnotes: ["d. i. der Euphrat"] },
      { number: 22, text: "Am dritten Tag aber wurde dem Laban berichtet, dass Jakob geflohen sei." },
      { number: 23, text: "Da nahm er seine Brüder mit sich und jagte ihm sieben Tagereisen weit nach und holte ihn auf dem Gebirge Gilead ein." },
      { number: 24, text: "Gott aber kam zu Laban, dem Aramäer, in einem Traum der Nacht* und sprach zu ihm: Hüte dich davor, dass du mit Jakob Gutes oder Böses* redest!*", footnotes: ["℘ Kap. 20,3", "w. vom Guten bis zum Bösen", "℘ Kap. 24,50; 2Sam 13,22"] },
      { number: 25, text: "Und Laban erreichte Jakob, als Jakob sein Zelt auf dem Gebirge aufgeschlagen hatte; und auch Laban schlug es mit seinen Brüdern auf dem Gebirge Gilead auf." },
      { number: 26, text: "Und Laban sagte zu Jakob: Was hast du getan*, dass du mich getäuscht* und meine Töchter wie Kriegsgefangene weggeführt hast?", footnotes: ["℘ Kap. 29,25", "w. mein Herz gestohlen"] },
      { number: 27, text: "Warum bist du heimlich geflohen und hast mich getäuscht* und hast es mir nicht mitgeteilt? Ich hätte dich ja begleitet mit Freude und mit Gesängen, mit Tamburin und Zither!", footnotes: ["w. bestohlen"] },
      { number: 28, text: "Und du hast mich nicht einmal meine Söhne* und meine Töchter küssen lassen*! Nun, du hast töricht gehandelt*.", footnotes: ["Gemeint sind die Enkel.", "℘ Kap. 32,1; Rt 1,9.14; 1Kö 19,20; Apg 20,37", "℘ 1Sam 13,13; 2Chr 16,9"] },
      { number: 29, text: "Es stünde in der Macht meiner Hand, übel mit euch zu verfahren. Aber der Gott eures Vaters hat gestern Nacht zu mir geredet und gesagt: Hüte dich, mit Jakob Gutes oder Böses zu reden*!", footnotes: ["℘ Kap. 24,50; 2Sam 13,22"] },
      { number: 30, text: "Nun denn — du bist nun einmal weggegangen, weil du dich so sehr nach dem Haus deines Vaters sehntest. Warum aber hast du meinen Gott gestohlen*?", footnotes: ["℘ Ri 18,24"] },
      { number: 31, text: "Da antwortete Jakob und sagte zu Laban: Ja, ich fürchtete mich; denn ich sagte mir, du würdest deine Töchter von mir reißen." },
      { number: 32, text: "Doch bei wem du deinen Gott findest, der soll nicht am Leben bleiben*. Untersuche hier vor unseren Brüdern, was bei mir ist, und nimm es dir! Jakob aber wusste* nicht, dass Rahel ihn gestohlen hatte.", footnotes: ["℘ Kap. 44,9", "o. erkannte"] },
      { number: 33, text: "Da ging Laban in das Zelt Jakobs und in das Zelt Leas und in das Zelt der beiden Mägde und fand nichts; und er kam aus Leas Zelt und ging in das Zelt Rahels." },
      { number: 34, text: "Rahel aber hatte den Terafim* genommen* und ihn in den Kamelsattel gelegt und sich daraufgesetzt. Und Laban tastete das ganze Zelt ab und fand nichts.", footnotes: ["d. i. den Hausgötzen", "℘ Ri 18,24"] },
      { number: 35, text: "Da sagte sie zu ihrem Vater: Mein Herr, zürne nicht*, dass ich nicht vor dir aufstehen kann; denn es geht mir nach der Weise der Frauen. Und er durchsuchte alles und fand den Terafim nicht.", footnotes: ["w. es werde nicht heiß in den Augen meines Herrn"] },
      { number: 36, text: "Da wurde Jakob zornig und stritt mit Laban. Und Jakob antwortete und sprach zu Laban: Was ist mein Verbrechen, was meine Sünde, dass du so hitzig hinter mir her bist?" },
      { number: 37, text: "Da du all meine Sachen durchtastet hast, was hast du gefunden von allen Sachen deines Hauses? Lege es hierher vor meine Brüder und deine Brüder, sie sollen zwischen uns beiden entscheiden!" },
      { number: 38, text: "Zwanzig Jahre bin ich nun bei dir gewesen; deine Mutterschafe und deine Ziegen haben nicht fehlgeboren*, und die Widder deiner Herde habe ich nicht gegessen.", footnotes: ["℘ Kap. 30,29"] },
      { number: 39, text: "Das Zerrissene habe ich nicht zu dir gebracht, ich habe es ersetzen müssen; von meiner Hand hast du es gefordert, mochte es gestohlen sein bei Tag, mochte es gestohlen sein bei Nacht*.", footnotes: ["℘ 2Mo 22,9-12"] },
      { number: 40, text: "So erging es mir: Am Tag verzehrte mich die Hitze und der Frost in der Nacht, und mein Schlaf floh von meinen Augen." },
      { number: 41, text: "Zwanzig Jahre bin ich nun in deinem Haus gewesen; vierzehn Jahre habe ich dir für deine beiden Töchter gedient* und sechs Jahre für deine Herde, und du hast meinen Lohn zehnmal verändert*.", footnotes: ["℘ Kap. 29,27", "℘ V. 6.7"] },
      { number: 42, text: "Wenn nicht der Gott meines Vaters, der Gott Abrahams, und der Schrecken Isaaks für mich gewesen wäre, gewiss, du hättest mich jetzt mit leeren Händen entlassen. Mein Elend* und die Arbeit meiner Hände hat Gott angesehen und hat gestern Nacht entschieden*.", footnotes: ["℘ Kap. 29,32", "℘ Ps 124,1-3.7"] },
      { number: 43, text: "Da antwortete Laban und sagte zu Jakob: Die Töchter sind meine Töchter, und die Söhne* sind meine Söhne, und die Tiere sind meine Tiere, und alles, was du hier siehst, mir gehört es! Aber meinen Töchtern gegenüber, was könnte ich ihnen heute tun, oder ihren Söhnen, die sie geboren haben?", footnotes: ["Gemeint sind die Enkel."] },
      { number: 44, text: "Und nun komm, lass uns einen Bund schließen*, ich und du, der sei zum Zeugnis zwischen mir und dir!", footnotes: ["℘ Kap. 26,28"] },
      { number: 45, text: "Da nahm Jakob einen Stein und richtete ihn als Gedenkstein* auf.", footnotes: ["℘ Kap. 28,18.22"] },
      { number: 46, text: "Und Jakob* sagte zu seinen Brüdern: Sammelt Steine! Da nahmen sie Steine und machten daraus einen Haufen und aßen dort auf dem Haufen.", footnotes: ["Die alte lat. Üs. liest: Laban; vgl. V. 51"] },
      { number: 47, text: "Und Laban nannte ihn Jegar-Sahaduta*, und Jakob nannte ihn Gal-Ed*.", footnotes: ["d. h. Steinhaufen des Zeugen (aramäische Form)", "d. h. Steinhaufen des Zeugen (hebr. Form)"] },
      { number: 48, text: "Und Laban sagte: Dieser Haufen sei heute Zeuge* zwischen mir und dir! Darum gab man ihm den Namen Gal-Ed", footnotes: ["℘ Jos 22,27"] },
      { number: 49, text: "und Mizpa*, weil er sagte: Der HERR halte Wache zwischen mir und dir, wenn wir uns nicht mehr sehen*!", footnotes: ["d. h. Warte\n℘ Ri 10,17", "w. wenn einer vor dem anderen verborgen ist"] },
      { number: 50, text: "Wenn du meine Töchter unterdrücken* und wenn du noch andere Frauen zu meinen Töchtern hinzunehmen solltest — kein Mensch ist bei uns, siehe, Gott ist Zeuge* zwischen mir und dir.", footnotes: ["o. demütigen; wie Kap. 16,6", "℘ Ri 11,10; 1Sam 12,5; Jer 42,5; Mal 2,14; 1Thes 2,5"] },
      { number: 51, text: "Und Laban sagte zu Jakob: Siehe, dieser Haufen, und siehe, der Gedenkstein, den ich errichtet habe zwischen mir und dir," },
      { number: 52, text: "dieser Haufen sei Zeuge* und der Gedenkstein ein Zeugnis, dass ich nicht über diesen Haufen zu dir hinausgehe und dass du über diesen Haufen und diesen Gedenkstein nicht zu mir hinausgehst zum Bösen.", footnotes: ["℘ Jos 22,27"] },
      { number: 53, text: "Der Gott Abrahams und der Gott Nahors soll* zwischen uns richten*, der Gott ihres Vaters! Da schwor Jakob bei dem Schrecken seines Vaters Isaak.", footnotes: ["o. sollen", "℘ Kap. 16,5"] },
      { number: 54, text: "Und Jakob opferte ein Schlachtopfer auf dem Berg und lud seine Brüder ein zu essen*; und sie aßen* und übernachteten auf dem Berg.", footnotes: ["℘ Kap. 26,30; 1Sam 9,12", "w. Brot zu essen; und sie aßen Brot"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "Und Laban stand früh am Morgen auf, küsste seine Söhne und seine Töchter* und segnete sie*; und Laban ging und kehrte an seinen Ort zurück*.", footnotes: ["℘ Kap. 31,28", "℘ Kap. 24,60", "℘ Kap. 18,33"] },
      { number: 2, text: "Und Jakob zog seiner Wege. Da begegneten ihm Engel Gottes.", heading: "Jakobs Begegnung mit Engeln" },
      { number: 3, text: "Und Jakob sagte, als er sie sah: Das ist das Heerlager Gottes*. Und er gab dieser Stätte den Namen Mahanajim*.", footnotes: ["℘ 2Kö 6,17; 1Chr 12,23; Lk 2,13", "d. h. Doppellager\n℘ Jos 13,30; 2Sam 2,8; Hl 7,1"] },
      { number: 4, text: "Und Jakob sandte Boten vor sich her zu seinem Bruder Esau in das Land Seïr*, das Gebiet Edom*.", heading: "Jakobs Furcht vor Esau", footnotes: ["℘ Kap. 33,14; 36,8.9; Ri 5,4; Jes 21,11", "℘ Kap. 25,30"] },
      { number: 5, text: "Und er befahl ihnen: So sollt ihr zu meinem Herrn, zu Esau, sagen: So spricht dein Knecht Jakob: Bei Laban habe ich mich als Fremder aufgehalten und bin bis jetzt geblieben*;", footnotes: ["℘ Kap. 31,3.21"] },
      { number: 6, text: "und ich habe Rinder und Esel, Schafe und Knechte und Mägde*; und ich sende Boten, es meinem Herrn mitzuteilen, um Gunst zu finden in deinen Augen*.", footnotes: ["℘ Kap. 31,18", "℘ Kap. 33,8.15; 34,11; 47,25; Rt 2,2.13; 1Sam 1,18"] },
      { number: 7, text: "Und die Boten kehrten zu Jakob zurück und sagten: Wir sind zu deinem Bruder, zu Esau, gekommen, und er zieht dir auch schon entgegen und vierhundert Mann mit ihm*.", footnotes: ["℘ Kap. 33,1"] },
      { number: 8, text: "Da fürchtete sich Jakob sehr, und ihm wurde angst; und er teilte das Volk, das bei ihm war, die Schafe, die Rinder und die Kamele in zwei Lager." },
      { number: 9, text: "Er sagte sich nämlich: Wenn Esau über das eine Lager kommt und es schlägt, dann wird das übrig gebliebene Lager entkommen können." },
      { number: 10, text: "Und Jakob sprach: Gott meines Vaters Abraham und Gott meines Vaters Isaak*, HERR, der du zu mir geredet hast: »Kehre zurück* in dein Land und zu deiner Verwandtschaft, und ich will dir Gutes tun!«", heading: "Jakobs Gebet und Vorbereitungen zur Begegnung mit Esau", footnotes: ["℘ Kap. 28,13", "℘ Kap. 31,3.13"] },
      { number: 11, text: "Ich bin zu gering für alle Gnadenerweise und all die Treue, die du deinem Knecht erwiesen hast*; denn mit meinem Stab bin ich über diesen Jordan gegangen, und nun bin ich zu zwei Lagern geworden.", footnotes: ["℘ Kap. 24,27; 2Sam 7,18"] },
      { number: 12, text: "Rette mich doch vor der Hand meines Bruders, vor der Hand Esaus — denn ich fürchte ihn —, dass er nicht etwa komme und mich schlage, die Mutter samt den Kindern!" },
      { number: 13, text: "Du hast doch selbst gesagt: Gutes, ja Gutes will ich dir tun und deine Nachkommenschaft zahlreich machen wie den Sand des Meeres, den man vor Menge nicht zählen kann*.", footnotes: ["℘ Kap. 13,16; 15,5"] },
      { number: 14, text: "Und er übernachtete dort in jener Nacht; und er nahm von dem, was in seine Hand gekommen war, ein Geschenk* für seinen Bruder Esau:", footnotes: ["℘ Kap. 33,11; 43,11; Spr 17,8"] },
      { number: 15, text: "zweihundert Ziegen und zwanzig Böcke, zweihundert Mutterschafe und zwanzig Widder," },
      { number: 16, text: "dreißig säugende Kamele mit ihren Fohlen, vierzig Kühe und zehn Stiere, zwanzig Eselinnen und zehn Eselhengste." },
      { number: 17, text: "Und er gab sie in die Hand seiner Knechte, Herde für Herde besonders, und sagte zu seinen Knechten: Zieht vor mir her, und lasst einen Abstand zwischen Herde und Herde!" },
      { number: 18, text: "Und er befahl dem ersten und sagte: Wenn mein Bruder Esau dir begegnet und dich fragt: »Wem gehörst du an, und wohin gehst du, und wem gehören diese da vor dir?«," },
      { number: 19, text: "dann sollst du sagen: »Deinem Knecht Jakob; es ist ein Geschenk, gesandt an meinen Herrn, an Esau; und siehe, er selbst ist hinter uns*.«", footnotes: ["℘ 1Sam 25,19"] },
      { number: 20, text: "Und auch dem zweiten, auch dem dritten, auch allen, die hinter den Herden hergingen, befahl er: Nach diesem Wort sollt ihr zu Esau reden, wenn ihr ihn trefft," },
      { number: 21, text: "und sollt sagen: »Siehe, dein Knecht Jakob ist selbst hinter uns*.« Denn er sagte sich: Ich will ihn versöhnen* durch das Geschenk*, das vor mir hergeht, danach erst will ich sein Gesicht sehen; vielleicht wird er mich annehmen*.", footnotes: ["℘ Kap. 33,11; 43,11; Spr 17,8", "w. sein Angesicht bedecken", "℘ Kap. 33,11; 43,11; Spr 17,8", "w. wird er mein Gesicht erheben"] },
      { number: 22, text: "So zog das Geschenk vor ihm her, er aber übernachtete in jener Nacht im Lager." },
      { number: 23, text: "Und er stand in jener Nacht auf, nahm seine beiden Frauen, seine beiden Mägde und seine elf Söhne und zog über die Furt des Jabbok;", heading: "Jakobs Ringen mit Gott — Neuer Name" },
      { number: 24, text: "und er nahm sie und führte sie über den Fluss und führte hinüber, was er hatte." },
      { number: 25, text: "Und Jakob blieb allein zurück. Da rang ein Mann mit ihm, bis die Morgenröte heraufkam*.", footnotes: ["℘ Hos 12,4"] },
      { number: 26, text: "Und als er sah, dass er ihn nicht überwältigen konnte*, berührte er sein Hüftgelenk; und das Hüftgelenk Jakobs wurde verrenkt, während er mit ihm rang.", footnotes: ["o. ihm nicht überlegen war; wie Hos 12,5"] },
      { number: 27, text: "Da sagte er: Lass mich los, denn die Morgenröte ist aufgegangen! Er aber sagte: Ich lasse dich nicht los*, es sei denn, du hast mich vorher gesegnet*.", footnotes: ["℘ 2Kö 4,30", "℘ 1Chr 4,10"] },
      { number: 28, text: "Da sprach er zu ihm: Was ist dein Name? Er sagte: Jakob." },
      { number: 29, text: "Da sprach er: Nicht mehr Jakob soll dein Name heißen, sondern Israel*; denn du hast mit Gott und mit Menschen gekämpft und hast überwältigt*.", footnotes: ["d. h. Kämpfer Gottes\n℘ Kap. 17,5; 35,10; 1Kö 18,31; 2Kö 17,34; 1Chr 1,34", "o. warst überlegen"] },
      { number: 30, text: "Und Jakob fragte und sagte: Teile mir doch deinen Namen mit! Er aber sagte: Warum fragst du denn nach meinem Namen?* Und er segnete ihn dort*.", footnotes: ["℘ Ri 13,17.18; Jes 9,5", "℘ Kap. 35,9"] },
      { number: 31, text: "Und Jakob gab der Stätte den Namen Pnuël*; denn ich habe Gott von Angesicht zu Angesicht gesehen*, und meine Seele ist gerettet worden*!", footnotes: ["d. h. Angesicht Gottes", "℘ Kap. 16,13", "℘ 2Mo 24,10.11; 5Mo 5,24; Ri 6,22.23; Jes 6,5-7"] },
      { number: 32, text: "Und die Sonne ging ihm auf, als er an Pnuël* vorüberkam; und er hinkte an seiner Hüfte.", footnotes: ["d. h. Angesicht Gottes\n℘ Ri 8,8; 1Kö 12,25"] },
      { number: 33, text: "Darum essen die Söhne Israel bis zum heutigen Tag nicht den Hüftmuskel*, der über dem Hüftgelenk ist, weil er das Hüftgelenk Jakobs, den Hüftmuskel*, berührt hat.", footnotes: ["w. Hüftnerv", "w. Hüftnerv"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Und Jakob erhob seine Augen und sah; und siehe, Esau kam und mit ihm vierhundert Mann*. Da verteilte er die Kinder auf Lea und auf Rahel und auf die beiden Mägde;", heading: "Jakobs Versöhnung mit Esau", footnotes: ["℘ Kap. 32,7"] },
      { number: 2, text: "und er stellte die Mägde und ihre Kinder vornan und Lea und ihre Kinder dahinter und Rahel und Josef zuletzt." },
      { number: 3, text: "Er selbst aber ging vor ihnen her und warf sich siebenmal zur Erde nieder*, bis er nahe an seinen Bruder herangekommen war.", footnotes: ["℘ Kap. 18,2"] },
      { number: 4, text: "Esau aber lief ihm entgegen, umarmte ihn und fiel ihm um den Hals und küsste ihn; und sie weinten*.", footnotes: ["℘ Kap. 45,14.15; 46,29; 1Sam 20,41"] },
      { number: 5, text: "Und er erhob seine Augen und sah die Frauen und die Kinder und sagte: Wer sind diese bei dir? Er sagte: Die Kinder, die Gott deinem Knecht aus Gnaden geschenkt hat*.", footnotes: ["℘ Kap. 48,9"] },
      { number: 6, text: "Da traten die Mägde heran, sie und ihre Kinder, und verneigten sich." },
      { number: 7, text: "Und auch Lea trat heran und ihre Kinder, und sie verneigten sich. Und danach traten Josef und Rahel heran und verneigten sich." },
      { number: 8, text: "Und er sagte: Was willst du mit diesem ganzen Lager, dem ich begegnet bin? Er sagte: Um Gunst zu finden in den Augen meines Herrn*.", footnotes: ["℘ Kap. 32,6"] },
      { number: 9, text: "Da sagte Esau: Ich habe genug, mein Bruder; es sei dein, was du hast." },
      { number: 10, text: "Jakob aber sagte: Nicht doch; wenn ich überhaupt Gunst gefunden habe in deinen Augen, dann nimm mein Geschenk aus meiner Hand! Denn ich habe ja doch dein Angesicht gesehen, wie man das Angesicht Gottes sieht, und du hast Gefallen an mir gehabt." },
      { number: 11, text: "Nimm doch mein Geschenk*, das dir überbracht worden ist! Denn Gott hat es mir aus Gnaden geschenkt, und ich habe alles. Und als er in ihn drang*, da nahm er es.", footnotes: ["w. meinen Segen; wie 1Sam 25,27\n℘ Kap. 32,14; 1Sam 25,27", "℘ 2Kö 5,23"] },
      { number: 12, text: "Und Esau* sagte: Lass uns aufbrechen und weiterziehen, und ich will vor* dir herziehen.", footnotes: ["w. er", "o. neben"] },
      { number: 13, text: "Er aber sagte zu ihm: Mein Herr weiß*, dass die Kinder zart sind und dass säugende Schafe und Kühe bei mir sind*; wenn man sie nur einen Tag zu schnell triebe, so würde die ganze Herde sterben*.", footnotes: ["o. erkennt", "o. mir obliegen", "℘ Spr 12,10"] },
      { number: 14, text: "Mein Herr ziehe doch vor seinem Knecht hin! Ich aber, ich will einherziehen nach meiner Gemächlichkeit, nach dem Schritt des Viehs, das vor mir ist, und nach dem Schritt der Kinder, bis ich zu meinem Herrn nach Seïr komme*.", footnotes: ["℘ Kap. 32,4"] },
      { number: 15, text: "Da sagte Esau: Ich will doch von dem Volk, das bei mir ist, einige bei dir zurücklassen. Er aber sagte: Wozu das? Möchte ich nur Gunst finden in den Augen meines Herrn*!", footnotes: ["℘ Kap. 32,6"] },
      { number: 16, text: "So kehrte Esau an diesem Tag auf seinem Weg nach Seïr zurück." },
      { number: 17, text: "Und Jakob brach auf nach Sukkot* und baute sich ein Haus, und seinem Vieh machte er Hütten; darum gab er dem Ort den Namen Sukkot*.", heading: "Jakob in Sichem", footnotes: ["℘ Ri 8,5; 1Kö 7,46", "o. nennt man den Ort Sukkot. — Sukkot heißt »Hütten«."] },
      { number: 18, text: "Und Jakob kam wohlbehalten* zur Stadt Sichem*, die im Land Kanaan ist, als er aus Paddan-Aram kam, und lagerte vor der Stadt.", footnotes: ["o. friedlich; d. h. in friedlicher Absicht", "℘ Kap. 12,6"] },
      { number: 19, text: "Und er kaufte das Feldstück, wo er sein Zelt aufgeschlagen hatte, von der Hand der Söhne Hamors, des Vaters Sichems*, für hundert Kesita*.", footnotes: ["℘ Ri 9,28", "℘ Kap. 23,13-18; Jos 24,32; Joh 4,5"] },
      { number: 20, text: "Und er richtete dort einen Altar auf und nannte ihn: Gott, der Gott Israels*.", footnotes: ["℘ Kap. 12,7; 1Chr 29,10"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "Und Dina, die Tochter Leas*, die sie dem Jakob geboren hatte, ging aus, die Töchter des Landes zu sehen.", heading: "Dina und Sichem — Betrug und Rache durch Jakobs Söhne", footnotes: ["℘ Kap. 30,21"] },
      { number: 2, text: "Da sah Sichem sie, der Sohn des Hewiters Hamor, des Fürsten des Landes; und er nahm sie und legte sich zu ihr und tat ihr Gewalt an*.", footnotes: ["℘ 2Sam 11,4.13.14"] },
      { number: 3, text: "Und seine Seele hing an Dina, der Tochter Jakobs, und er liebte das Mädchen und redete zum Herzen des Mädchens*.", footnotes: ["℘ Kap. 50,21; Ri 19,3; Hos 2,16"] },
      { number: 4, text: "Und Sichem sagte zu seinem Vater Hamor: Nimm mir dieses Mädchen zur Frau*!", footnotes: ["℘ Ri 14,2"] },
      { number: 5, text: "Und Jakob hatte gehört, dass er seine Tochter Dina entehrt hatte, seine Söhne aber waren mit seinem Vieh auf dem Feld; so schwieg Jakob, bis sie kamen." },
      { number: 6, text: "Und Hamor, der Vater Sichems, kam heraus zu Jakob, um mit ihm zu reden." },
      { number: 7, text: "Und die Söhne Jakobs kamen vom Feld. Als sie aber davon hörten, fühlten sich die Männer gekränkt und wurden sehr zornig*, weil er eine Schandtat in Israel verübt hatte*, bei der Tochter Jakobs zu liegen. Denn so etwas hätte nicht geschehen dürfen.", footnotes: ["℘ 2Sam 13,21", "℘ 5Mo 22,21; Ri 19,23; 20,6; 2Sam 13,12"] },
      { number: 8, text: "Und Hamor redete mit ihnen und sagte: Mein Sohn Sichem — seine Seele hängt an eurer Tochter. Gebt sie ihm doch zur Frau," },
      { number: 9, text: "und verschwägert euch mit uns: gebt uns eure Töchter, und nehmt euch unsere Töchter*;", footnotes: ["℘ Kap. 24,3"] },
      { number: 10, text: "und bleibt bei uns wohnen, und das Land soll offen vor euch liegen! Bleibt, verkehrt darin, und macht euch darin ansässig!*", footnotes: ["℘ Kap. 20,15"] },
      { number: 11, text: "Und Sichem sprach zu ihrem Vater und zu ihren Brüdern: Lasst mich Gunst finden in euren Augen*! Was ihr mir sagt, will ich geben.", footnotes: ["℘ Kap. 32,6"] },
      { number: 12, text: "Legt mir sehr viel auf als Heiratsgeld und als Geschenk, ich will es geben, so wie ihr es mir sagt; nur gebt mir das Mädchen zur Frau*!", footnotes: ["℘ 2Mo 22,15; 1Sam 18,25"] },
      { number: 13, text: "Da antworteten die Söhne Jakobs dem Sichem und seinem Vater Hamor mit Hinterlist* und redeten, weil er ihre Schwester Dina entehrt hatte;", footnotes: ["o. mit Betrug\n℘ Spr 26,24-26"] },
      { number: 14, text: "und sie sagten zu ihnen: Wir können das nicht tun, unsere Schwester einem unbeschnittenen Mann geben, denn das wäre eine Schande für uns*.", footnotes: ["℘ Jos 5,7.9; Ri 14,3"] },
      { number: 15, text: "Nur* unter der Bedingung wollen wir euch zu Willen sein, wenn ihr werdet wie wir, indem sich alles Männliche bei euch beschneiden lässt*;", footnotes: ["o. Doch", "℘ Kap. 17,10"] },
      { number: 16, text: "dann wollen wir euch unsere Töchter geben und uns eure Töchter nehmen, und wir wollen bei euch wohnen bleiben und zu einem Volk werden." },
      { number: 17, text: "Wenn ihr aber nicht auf uns hört, euch beschneiden zu lassen, dann nehmen wir unsere Tochter und ziehen weg." },
      { number: 18, text: "Und ihre Worte waren gut in den Augen Hamors und in den Augen Sichems, des Sohnes Hamors." },
      { number: 19, text: "Und der junge Mann zögerte nicht, dies* zu tun, denn er hatte Gefallen an der Tochter Jakobs*. Und er genoss mehr Ansehen als alle im Haus seines Vaters.", footnotes: ["w. die Sache", "℘ Kap. 29,20"] },
      { number: 20, text: "Und Hamor und sein Sohn Sichem kamen in das Tor ihrer Stadt*, und sie redeten zu den Männern ihrer Stadt und sagten:", footnotes: ["℘ Rt 4,1; Hi 29,7"] },
      { number: 21, text: "Diese Männer sind friedlich gegen uns gesinnt, so mögen sie im Land wohnen bleiben und darin verkehren; und das Land, siehe, nach beiden Seiten ausgedehnt liegt es vor ihnen. Wir wollen uns ihre Töchter als Frauen nehmen und ihnen unsere Töchter geben." },
      { number: 22, text: "Nur* unter der Bedingung wollen die Männer uns zu Willen sein, bei uns zu wohnen und ein Volk mit uns zu werden, dass sich bei uns alles Männliche beschneiden lässt*, so wie sie beschnitten sind.", footnotes: ["o. Doch", "℘ Kap. 17,10"] },
      { number: 23, text: "Ihre Herden und ihr Besitz und all ihr Vieh, werden die nicht uns gehören? Nur* lasst uns ihnen zu Willen sein, und sie werden bei uns wohnen.", footnotes: ["o. Doch"] },
      { number: 24, text: "Da hörten auf Hamor und auf seinen Sohn Sichem alle, die zum Tor seiner Stadt ein- und ausgingen*. So ließ sich alles Männliche beschneiden, alle, die zum Tor seiner Stadt ein- und ausgingen.", footnotes: ["℘ Kap. 23,10.18"] },
      { number: 25, text: "Und es geschah am dritten Tag, als sie in Schmerzen waren*, da nahmen die beiden Söhne Jakobs, Simeon und Levi, die Brüder Dinas, jeder sein Schwert und kamen ungehindert gegen die Stadt* und erschlugen alles Männliche*.", footnotes: ["℘ Jos 5,8", "o. kamen gegen die sorglose Stadt", "℘ Kap. 49,5-7"] },
      { number: 26, text: "Auch Hamor und seinen Sohn Sichem erschlugen sie mit der Schärfe des Schwertes und nahmen Dina aus dem Haus Sichems und gingen davon." },
      { number: 27, text: "Die Söhne Jakobs kamen über die Erschlagenen und plünderten die Stadt, weil sie ihre Schwester entehrt hatten." },
      { number: 28, text: "Ihre Schafe und ihre Rinder und ihre Esel und alles, was in der Stadt und was auf dem Feld war, nahmen sie;" },
      { number: 29, text: "und all ihr Vermögen und alle ihre Kinder und ihre Frauen führten sie weg und plünderten auch alles, was in den Häusern war*.", footnotes: ["℘ 4Mo 31,9.11"] },
      { number: 30, text: "Da sagte Jakob zu Simeon und Levi: Ihr habt mich ins Unglück gebracht*, indem ihr mich stinkend macht* bei den Bewohnern des Landes, bei den Kanaanitern und bei den Perisitern*. Ich aber bin ein geringes Häuflein*. Wenn sie sich gegen mich versammeln, werden sie mich schlagen, und ich werde vernichtet, ich und mein Haus.", footnotes: ["℘ Jos 7,25", "℘ 2Mo 5,21; 1Sam 13,4; 2Sam 16,21", "℘ Kap. 12,6; 13,7", "w. gezählte Männer\n℘ Ps 105,12"] },
      { number: 31, text: "Sie aber sagten: Durfte er unsere Schwester wie eine Hure behandeln?" },
    ]},
    { number: 35, verses: [
      { number: 1, text: "Und Gott sprach zu Jakob: Mache dich auf, zieh hinauf nach Bethel* und wohne dort, und mache dort einen Altar dem Gott, der dir erschienen ist*, als du vor deinem Bruder Esau flohst*!", heading: "Jakob in Bethel", footnotes: ["℘ V. 15; Kap. 28,19", "℘ Kap. 28,13; 31,13", "℘ Kap. 28,10.17; 29,1"] },
      { number: 2, text: "Da sagte Jakob zu seinem Haus* und zu allen, die bei ihm waren: Schafft die fremden Götter weg, die in eurer Mitte sind*, reinigt euch*, und wechselt eure Kleider*!", footnotes: ["℘ Kap. 18,19", "℘ Kap. 31,19; Jos 24,14.23; 1Sam 7,3; 1Kor 10,7.14", "℘ 2Kor 7,1", "℘ 2Mo 19,10.14"] },
      { number: 3, text: "Dann wollen wir uns aufmachen und nach Bethel hinaufziehen, dort werde ich dem Gott einen Altar machen, der mir am Tag meiner Not geantwortet* hat und der mit mir gewesen ist auf dem Weg, den ich gegangen bin*.", footnotes: ["o. mich . . . erhört", "℘ Kap. 28,15; 48,15"] },
      { number: 4, text: "Und sie gaben Jakob alle fremden Götter*, die in ihrer Hand waren, und die Ringe, die an ihren Ohren hingen*, und Jakob vergrub sie unter der Terebinthe, die bei Sichem ist*.", footnotes: ["℘ Jes 2,20", "d. h. die sie als Amulette trugen", "℘ Jos 24,25.26"] },
      { number: 5, text: "Und sie brachen auf. Und der Schrecken Gottes* kam über die Städte, die rings um sie her waren, so dass sie den Söhnen Jakobs nicht nachjagten.", footnotes: ["℘ 2Mo 23,27; 1Sam 14,15; 2Chr 14,13"] },
      { number: 6, text: "So kam Jakob nach Lus, das im Land Kanaan liegt, das ist Bethel, er und alles Volk, das bei ihm war*.", footnotes: ["℘ Kap. 28,15.19"] },
      { number: 7, text: "Und er baute dort einen Altar* und nannte den Ort El-Bethel*; denn dort hatte Gott sich ihm offenbart*, als er vor seinem Bruder floh*.", footnotes: ["℘ Kap. 12,7", "d. h. Gott des Gotteshauses, o. Gott von Bethel\n℘ Kap. 28,10.17; 29,1", "℘ Kap. 28,10.17; 29,1", "℘ Kap. 28,10.17; 29,1"] },
      { number: 8, text: "Und Debora, die Amme Rebekkas*, starb, und sie wurde unterhalb von Bethel begraben unter der Eiche; und er gab ihr den Namen Allon Bachut*.", footnotes: ["℘ Kap. 24,59", "d. h. Eiche des Weinens"] },
      { number: 9, text: "Und Gott erschien dem Jakob noch einmal, als er aus Paddan-Aram* kam, und segnete ihn*.", footnotes: ["s. Anm. zu Kap. 25,20", "℘ Kap. 32,30; 48,3; Hos 12,5"] },
      { number: 10, text: "Und Gott sprach zu ihm: Dein Name ist Jakob. Dein Name soll nicht mehr Jakob heißen, sondern Israel soll dein Name sein*! So gab er ihm den Namen Israel.", footnotes: ["℘ Kap. 32,29"] },
      { number: 11, text: "Und Gott sprach zu ihm: Ich bin Gott, der Allmächtige*, sei fruchtbar und mehre dich; eine Nation und eine Schar von Nationen soll aus dir entstehen, und Könige sollen aus deinen Lenden hervorkommen*!", footnotes: ["hebr. el schaddaj\n℘ Kap. 17,1", "d. h. von dir abstammen; die Lenden galten als Sitz der Zeugungskraft\n℘ Kap. 17,6"] },
      { number: 12, text: "Und das Land, das ich Abraham und Isaak gegeben habe, dir will ich es geben*, und deinen Nachkommen nach dir will ich das Land geben.", footnotes: ["℘ Kap. 12,7; 2Mo 2,24; Hebr 11,9"] },
      { number: 13, text: "Und Gott fuhr von ihm auf an dem Ort, an dem er mit ihm geredet hatte*.", footnotes: ["℘ Kap. 17,22"] },
      { number: 14, text: "Und Jakob richtete einen Gedenkstein auf an dem Ort, an dem er mit ihm geredet hatte, ein Denkmal aus Stein, und spendete darauf ein Trankopfer und goss Öl darauf*.", footnotes: ["℘ Kap. 28,18"] },
      { number: 15, text: "Und Jakob gab dem Ort, wo Gott mit ihm geredet hatte, den Namen Bethel*.", footnotes: ["℘ V. 1.7"] },
      { number: 16, text: "Und sie brachen von Bethel auf. Und es war noch eine Strecke Landes, um nach Efrata zu kommen, da gebar Rahel; und sie hatte es schwer mit ihrem Gebären*.", heading: "Rahels Tod bei der Geburt Benjamins", footnotes: ["℘ Kap. 3,16"] },
      { number: 17, text: "Und es geschah, als sie es schwer hatte mit ihrem Gebären, da sagte die Hebamme zu ihr: Fürchte dich nicht, denn auch der wird dir ein Sohn*!", footnotes: ["℘ Kap. 30,24"] },
      { number: 18, text: "Und es geschah, als ihre Seele ausging — denn sie musste sterben* —, da gab sie ihm den Namen Ben-Oni*; sein Vater aber nannte ihn Ben-Jamin*.", footnotes: ["℘ 1Sam 4,20", "d. h. Sohn meiner Trauer", "d. h. Sohn des Glücks\n℘ Kap. 49,27"] },
      { number: 19, text: "Und Rahel starb und wurde begraben am Weg nach Efrata, das ist Bethlehem*.", footnotes: ["℘ Kap. 48,7; Rt 1,2; 4,11; 1Sam 16,4; 2Sam 23,14; 2Chr 11,6; Mi 5,1"] },
      { number: 20, text: "Und Jakob richtete über ihrem Grab einen Gedenkstein auf, das ist das Grabmal Rahels bis auf diesen Tag*.", footnotes: ["℘ 1Sam 10,2"] },
      { number: 21, text: "Und Israel brach auf und schlug sein Zelt auf* jenseits von Migdal-Eder.", heading: "Jakobs Söhne", footnotes: ["℘ Hebr 11,9"] },
      { number: 22, text: "Und es geschah, als Israel in jenem Land wohnte, ging Ruben hin und lag bei Bilha, der Nebenfrau seines Vaters*. Und Israel hörte es*. *Die Söhne Jakobs waren zwölf.", footnotes: ["℘ Kap. 49,4; 3Mo 18,8; 5Mo 27,20; 2Sam 16,22; 1Chr 5,1; 1Kor 5,1", "℘ 1Sam 2,22-25; 2Sam 13,21", "℘ V. 23-26: Kap. 46,8-24; 49,3-27; 2Mo 2,1-5; 4Mo 1,5-15.20-42; 2,3-29; 7,12-78; 10,14-27; 13,4-15; 26,5-57; 34,19-28; 5Mo 27,12-14; 33,6-24; Jos 13-19; Ri 5,14-18; 1Chr 2,1.2; 4-7; 12,25-38; 27,16-22; Hes 48,31-34; Offb 7,4-8"] },
      { number: 23, text: "Die Söhne Leas*: Ruben*, der Erstgeborene Jakobs, und Simeon*, Levi*, Juda*, Issaschar* und Sebulon*.", footnotes: ["℘ Rt 4,11", "℘ Kap. 29,32-35", "℘ Kap. 28,10.17; 29,1", "℘ Kap. 28,10.17; 29,1", "℘ Kap. 28,10.17; 29,1", "℘ Kap. 30,18.20", "℘ Kap. 30,18.20"] },
      { number: 24, text: "Die Söhne Rahels*: Josef* und Benjamin*.", footnotes: ["℘ Rt 4,11", "℘ Kap. 30,24", "℘ Kap. 35,18; 43,29"] },
      { number: 25, text: "Die Söhne Bilhas, der Magd Rahels: Dan* und Naftali*.", footnotes: ["℘ Kap. 30,6.8", "℘ Rt 4,11"] },
      { number: 26, text: "Und die Söhne Silpas, der Magd Leas: Gad* und Asser*. Das sind die Söhne Jakobs*, die ihm in Paddan-Aram* geboren wurden.", footnotes: ["℘ Kap. 30,11.13", "℘ Rt 4,11", "℘ Apg 7,8", "s. Anm. zu Kap. 25,20"] },
      { number: 27, text: "Und Jakob kam zu seinem Vater Isaak nach Mamre*, nach Kirjat-Arba, das ist Hebron*, wo Abraham und Isaak sich als Fremde aufgehalten hatten*.", heading: "Isaaks Tod", footnotes: ["℘ Kap. 13,18; 23,19; 49,29-31", "℘ Kap. 37,14; Jos 14,15", "℘ Kap. 17,8; 37,14"] },
      { number: 28, text: "Und die Tage Isaaks waren 180 Jahre*.", footnotes: ["℘ Kap. 25,7-9"] },
      { number: 29, text: "Und Isaak verschied und starb und wurde versammelt zu seinen Völkern*, alt und der Tage satt. Und seine Söhne Esau und Jakob begruben ihn*.", footnotes: ["d. h. zu seinen Vorfahren", "℘ Kap. 25,7-9"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "Und dies ist die Generationenfolge* Esaus, das ist Edom*.", heading: "Esaus Nachkommen", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ Kap. 25,30; 1Sam 14,47"] },
      { number: 2, text: "Esau hatte sich seine Frauen von den Töchtern Kanaans genommen: Ada, die Tochter des Hetiters Elon, und Oholibama, die Tochter Anas, der Tochter* Zibons, des Horiters*,", footnotes: ["SamPent, LXX und die syr. Üs. lesen: des Sohnes", "In Kap. 36,20 gilt Ana als Horiter, weshalb hier Horiter statt Mas. T. »Hewiter« zu lesen ist.\n℘ Kap. 26,34"] },
      { number: 3, text: "und Basemat, die Tochter Ismaels, die Schwester Nebajots*.", footnotes: ["℘ Kap. 25,13"] },
      { number: 4, text: "*Und Ada gebar dem Esau Elifas, und Basemat gebar Reguël.", footnotes: ["℘ V. 4-14: 1Chr 1,35-37"] },
      { number: 5, text: "Oholibama aber gebar Jëusch, Jalam und Korach. Das sind die Söhne Esaus, die ihm im Land Kanaan geboren wurden*.", footnotes: ["℘ V. 14.18"] },
      { number: 6, text: "Und Esau nahm seine Frauen, seine Söhne und seine Töchter und alle Seelen seines Hauses und seine Herden und all sein Vieh und all sein Besitztum, das er im Land Kanaan erworben hatte, und zog in ein Land*, von seinem Bruder Jakob hinweg.", footnotes: ["SamPent und LXX lesen: zog aus dem Land Kanaan; die syr. Üs. liest: zog ins Land Seïr"] },
      { number: 7, text: "Denn ihre Habe war zu groß, um beieinander zu wohnen, und das Land ihrer Fremdlingschaft konnte sie wegen der Menge ihrer Herden nicht tragen*.", footnotes: ["℘ Kap. 13,6.11"] },
      { number: 8, text: "So ließ sich Esau auf dem Gebirge Seïr* nieder; Esau, das ist Edom*.", footnotes: ["℘ V. 43; Kap. 32,4; 5Mo 2,5; Jos 24,4; Ob 1.3.21", "℘ Kap. 25,30; 1Sam 14,47"] },
      { number: 9, text: "Dies ist die Generationenfolge* Esaus, des Vaters von Edom, auf dem Gebirge Seïr*.", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu Kap. 5,1", "℘ V. 43; Kap. 32,4; 5Mo 2,5; Jos 24,4; Ob 1.3.21"] },
      { number: 10, text: "Dies sind die Namen der Söhne Esaus: Elifas, der Sohn Adas, der Frau Esaus; Reguël, der Sohn Basemats, der Frau Esaus." },
      { number: 11, text: "Und die Söhne des Elifas waren: Teman, Omar, Zefo und Gatam und Kenas." },
      { number: 12, text: "Und Timna war eine Nebenfrau von Elifas, des Sohnes Esaus, die gebar dem Elifas Amalek. Das sind die Söhne Adas, der Frau Esaus." },
      { number: 13, text: "Und dies sind die Söhne Reguëls: Nahat und Serach, Schamma und Misa. Das waren die Söhne von Basemat, der Frau Esaus." },
      { number: 14, text: "Und dies waren die Söhne von Oholibama, der Tochter Anas, der Tochter* Zibons, der Frau Esaus: Sie gebar dem Esau Jëusch, Jalam und Korach.", footnotes: ["SamPent, LXX und die syr. Üs. lesen: des Sohnes"] },
      { number: 15, text: "Dies sind die Fürsten* der Söhne Esaus. Die Söhne des Elifas, des Erstgeborenen Esaus: der Fürst* Teman, der Fürst Omar, der Fürst Zefo, der Fürst Kenas,", footnotes: ["w. Tausend-Männer; damit sind die Stammeshäuptlinge der Edomiter gemeint (so in der ganzen Aufzählung der Generationenfolge)", "w. der Tausend-Mann; vgl. vorige Anm."] },
      { number: 16, text: "der Fürst Korach, der Fürst Gatam, der Fürst Amalek. Das sind die Fürsten des Elifas im Land Edom*; es sind die Söhne Adas.", footnotes: ["℘ 2Mo 15,15"] },
      { number: 17, text: "Und dies sind die Söhne Reguëls, des Sohnes Esaus: der Fürst Nahat, der Fürst Serach, der Fürst Schamma, der Fürst Misa. Das sind die Fürsten des Reguël im Land Edom; es sind die Söhne der Basemat, der Frau Esaus." },
      { number: 18, text: "Und dies sind die Söhne Oholibamas, der Frau Esaus: der Fürst Jëusch, der Fürst Jalam, der Fürst Korach. Das sind die Fürsten Oholibamas, der Tochter Anas, der Frau Esaus." },
      { number: 19, text: "Das sind die Söhne Esaus und das ihre Fürsten; das ist Edom*.", footnotes: ["℘ Kap. 25,30; 1Sam 14,47"] },
      { number: 20, text: "*Dies sind die Söhne des Horiters Seïr*, die Bewohner des Landes: Lotan, Schobal, Zibon und Ana,", footnotes: ["℘ V. 20-43: 1Chr 1,38-54", "℘ Kap. 14,6; 5Mo 2,12.22"] },
      { number: 21, text: "Dischon und Ezer und Dischan. Das sind die Fürsten der Horiter, Söhne Seïrs, im Land Edom." },
      { number: 22, text: "Und die Söhne Lotans waren: Hori und Hemam, Lotans Schwester aber war Timna." },
      { number: 23, text: "Und dies sind die Söhne Schobals: Alwan, Manahat und Ebal, Schefo* und Onam.", footnotes: ["1Chr 1,40 lautet der Name Schefi."] },
      { number: 24, text: "Und dies sind die Söhne Zibons: Aja und Ana. Das ist der Ana, der die warmen Quellen* in der Wüste fand, als er die Esel seines Vaters Zibon weidete.", footnotes: ["so die lat. Üs.; die aram. Üs.: Maultiere. — Mit Einfügung eines Buchstabens lesen andere »Wasser«. Die Bedeutung des hebr. Wortes lässt sich nicht genau bestimmen."] },
      { number: 25, text: "Und dies sind die Söhne des Ana: Dischon und Oholibama, die Tochter des Ana." },
      { number: 26, text: "Und dies sind die Söhne Dischons*: Hemdan, Eschban, Jitran und Keran.", footnotes: ["Mas. T.: Dischans"] },
      { number: 27, text: "Dies sind die Söhne Ezers: Bilhan, Saawan und Akan." },
      { number: 28, text: "Dies sind die Söhne Dischans: Uz und Aran." },
      { number: 29, text: "Dies sind die Fürsten der Horiter: der Fürst Lotan, der Fürst Schobal, der Fürst Zibon, der Fürst Ana," },
      { number: 30, text: "der Fürst Dischon, der Fürst Ezer, der Fürst Dischan. Das sind die Fürsten der Horiter, nach ihren Fürsten*, im Land Seïr.", footnotes: ["LXX: Fürstentümern, Herrschaften"] },
      { number: 31, text: "Und dies sind die Könige, die im Land Edom herrschten*, bevor ein König über die Söhne Israel regierte:", footnotes: ["℘ 4Mo 20,14"] },
      { number: 32, text: "König in Edom war Bela, der Sohn Beors; und der Name seiner Stadt war Dinhaba." },
      { number: 33, text: "Und Bela starb, und König wurde an seiner Stelle Jobab, der Sohn Serachs, aus Bozra*.", footnotes: ["℘ Jes 63,1; Jer 48,24; Am 1,12"] },
      { number: 34, text: "Und Jobab starb, und König wurde an seiner Stelle Huscham, aus dem Land der Temaniter*.", footnotes: ["℘ Hi 2,11"] },
      { number: 35, text: "Und Huscham starb, und König wurde an seiner Stelle Hadad, der Sohn Bedads, der Midian schlug im Gebiet Moabs; und der Name seiner Stadt war Awit." },
      { number: 36, text: "Und Hadad starb, und König wurde an seiner Stelle Samla aus Masreka." },
      { number: 37, text: "Und Samla starb, und König wurde an seiner Stelle Schaul aus Rehobot am Strom." },
      { number: 38, text: "Und Schaul starb, und König wurde an seiner Stelle Baal-Hanan, der Sohn Achbors." },
      { number: 39, text: "Und Baal-Hanan, der Sohn Achbors, starb, und König wurde an seiner Stelle Hadar; und der Name seiner Stadt war Pagu und der Name seiner Frau Mehetabel, die Tochter Matreds, der Tochter* des Me-Sahab.", footnotes: ["LXX und syr. Üs. lesen: des Sohnes"] },
      { number: 40, text: "Und dies sind die Namen der Fürsten Esaus, nach ihren Sippen, nach ihren Ortschaften, mit ihren Namen: der Fürst Timna, der Fürst Alwa, der Fürst Jetet," },
      { number: 41, text: "der Fürst Oholibama, der Fürst Ela, der Fürst Pinon," },
      { number: 42, text: "der Fürst Kenas, der Fürst Teman, der Fürst Mibzar," },
      { number: 43, text: "der Fürst Magdiël, der Fürst Iram. Das sind die Fürsten von Edom nach ihren Wohnsitzen, im Land ihres Eigentums*. Das ist Esau, der Vater Edoms.", footnotes: ["℘ V. 8.9"] },
    ]},
    { number: 37, verses: [
      { number: 1, text: "Und Jakob wohnte im Land der Fremdlingschaft seines Vaters, im Land Kanaan*.", heading: "Josefs Träume — Neid seiner Brüder", footnotes: ["℘ Kap. 17,8"] },
      { number: 2, text: "Dies ist die Geschichte* Jakobs: Josef, siebzehn Jahre alt, war als Hirte mit seinen Brüdern bei den Schafen — als er noch ein Junge war —, mit den Söhnen Bilhas und mit den Söhnen Silpas, der Frauen seines Vaters*. Und Josef hinterbrachte ihrem Vater die üble Nachrede über sie.", footnotes: ["o. die Entstehung, die Entstehungsgeschichte, die Generationenfolge; vgl. Anm. zu Kap. 5,1", "℘ Kap. 35,25.26"] },
      { number: 3, text: "Und Israel liebte Josef mehr als all seine Söhne, weil er der Sohn seines Alters war*; und er machte ihm einen bunten* Leibrock.", footnotes: ["℘ Kap. 44,20", "Die Bedeutung des Wortes ist nicht gesichert. Andere nehmen die Bedeutung an: einen knöchellangen Leibrock, o. einen Leibrock mit Ärmeln, die bis an die Hände reichen; dasselbe Wort wie 2Sam 13,18"] },
      { number: 4, text: "Als aber seine Brüder sahen, dass ihr Vater ihn mehr liebte als alle seine Brüder; da hassten sie ihn und konnten ihn nicht mehr grüßen*.", footnotes: ["o. konnten nicht mehr friedlich zu ihm reden\n℘ 1Sam 17,28"] },
      { number: 5, text: "Und Josef hatte einen Traum*, den erzählte er seinen Brüdern; da hassten sie ihn noch mehr.", footnotes: ["℘ Kap. 20,3; 4Mo 12,6"] },
      { number: 6, text: "Und er sagte zu ihnen: Hört doch diesen Traum, den ich gehabt habe:" },
      { number: 7, text: "Siehe, wir banden Garben mitten auf dem Feld, und siehe, meine Garbe richtete sich auf und blieb auch aufrecht stehen; und siehe, eure Garben stellten sich ringsum auf und verneigten sich vor meiner Garbe*.", footnotes: ["℘ Kap. 42,6-9; 43,26; 44,14; 50,18"] },
      { number: 8, text: "Da sagten seine Brüder zu ihm: Willst du etwa König über uns werden, willst du gar über uns herrschen? Und sie hassten ihn noch mehr wegen seiner Träume und wegen seiner Reden*.", footnotes: ["℘ 2Mo 2,14; Lk 19,14"] },
      { number: 9, text: "Und er hatte noch einen anderen Traum*, auch den erzählte er seinen Brüdern und sagte: Siehe, noch einen Traum hatte ich, und siehe, die Sonne und der Mond und elf Sterne beugten sich vor mir nieder*.", footnotes: ["℘ Kap. 42,6-9; 43,26; 44,14; 50,18", "℘ Kap. 42,6-9; 43,26; 44,14; 50,18"] },
      { number: 10, text: "Und er erzählte es seinem Vater und seinen Brüdern. Da schalt ihn sein Vater* und sagte zu ihm: Was ist das für ein Traum, den du gehabt hast? Sollen wir etwa kommen, ich und deine Mutter und deine Brüder, um uns vor dir zur Erde niederzubeugen?", footnotes: ["w. Da schrie ihn sein Vater an"] },
      { number: 11, text: "Und seine Brüder waren eifersüchtig auf ihn*; aber sein Vater bewahrte das Wort*.", footnotes: ["℘ 1Sam 18,8; Apg 7,9", "℘ Kap. 42,9; Dan 7,28; Lk 2,19.51"] },
      { number: 12, text: "Und seine Brüder gingen fort, um die Schafe ihres Vaters bei Sichem zu weiden.", heading: "Josefs Verkauf nach Ägypten — Jakobs Trauer" },
      { number: 13, text: "Da sagte Israel zu Josef: Weiden nicht deine Brüder bei Sichem? Komm, ich will dich zu ihnen senden! Er aber sagte zu ihm: Hier bin ich*.", footnotes: ["℘ Kap. 22,1.11"] },
      { number: 14, text: "Da sagte er zu ihm: Geh doch hin, sieh nach dem Wohlergehen deiner Brüder und nach dem Wohlergehen der Schafe, und bring mir Antwort*. So sandte er ihn aus dem Tal von Hebron*, und er kam nach Sichem.", footnotes: ["℘ 1Sam 17,18.22", "℘ Kap. 35,27"] },
      { number: 15, text: "Da fand ihn ein Mann, und siehe, er irrte auf dem Feld umher; und der Mann fragte ihn: Was suchst du?" },
      { number: 16, text: "Und er sagte: Ich suche meine Brüder. Teile mir doch mit, wo sie weiden*!", footnotes: ["℘ Hl 1,7"] },
      { number: 17, text: "Da sagte der Mann: Sie sind von hier aufgebrochen, denn ich hörte sie sagen: »Lasst uns nach Dotan* gehen!« Da ging Josef seinen Brüdern nach und fand sie bei Dotan.", footnotes: ["℘ 2Kö 6,13"] },
      { number: 18, text: "Als sie ihn von ferne sahen und bevor er sich ihnen genähert hatte, da ersannen sie gegen ihn den Anschlag, ihn zu töten*.", footnotes: ["℘ Kap. 50,15.20; 1Sam 19,1; Ps 31,14; Mt 21,38; 27,1"] },
      { number: 19, text: "Und sie sagten einer zum andern: Siehe, da kommt dieser Träumer*!", footnotes: ["w. dieser Herr der Träume"] },
      { number: 20, text: "So kommt nun und lasst uns ihn erschlagen und ihn in eine der Zisternen werfen*, und wir wollen sagen: Ein böses Tier hat ihn gefressen*! Dann werden wir sehen, was aus seinen Träumen wird.", footnotes: ["℘ Spr 1,10.11.16", "℘ Jes 28,15"] },
      { number: 21, text: "Als Ruben das hörte, wollte er ihn aus ihrer Hand retten* und sagte: Lasst uns ihn nicht totschlagen*!", footnotes: ["w. rettete er ihn aus ihrer Hand", "℘ Kap. 42,22"] },
      { number: 22, text: "Und Ruben sagte zu ihnen: Vergießt nicht Blut, werft ihn in diese Zisterne, die in der Wüste ist, aber legt nicht Hand an ihn! Das sagte er, damit er ihn aus ihrer Hand rettete, um ihn zu seinem Vater zurückzubringen." },
      { number: 23, text: "Und es geschah, als Josef zu seinen Brüdern kam, da zogen sie Josef seinen Leibrock aus, den bunten* Leibrock, den er anhatte.", footnotes: ["s. Anm. zu V. 3"] },
      { number: 24, text: "Und sie nahmen ihn und warfen ihn in die Zisterne*; die Zisterne aber war leer, es war kein Wasser darin.", footnotes: ["℘ Kap. 42,21; Jer 38,6"] },
      { number: 25, text: "Dann setzten sie sich, um zu essen*. Und sie erhoben ihre Augen und sahen: Und siehe, eine Karawane von Ismaelitern kam von Gilead her; und ihre Kamele trugen Tragakant* und Balsamharz* und Ladanum*; sie zogen hin, um es nach Ägypten hinabzubringen.", footnotes: ["℘ Est 3,15; Am 6,4.6", "d. i. wohlriechendes Harz", "℘ Hl 5,1; Jer 8,22", "d. i. wohlriechendes Harz\n℘ Kap. 43,11"] },
      { number: 26, text: "Da sagte Juda zu seinen Brüdern: Was für ein Gewinn ist es, dass wir unseren Bruder erschlagen und sein Blut zudecken?*", footnotes: ["℘ Kap. 4,9"] },
      { number: 27, text: "Kommt, lasst uns ihn an die Ismaeliter verkaufen; aber unsere Hand sei nicht an ihm, denn unser Bruder, unser Fleisch ist er!* Und seine Brüder hörten darauf.", footnotes: ["℘ Kap. 29,14"] },
      { number: 28, text: "Da kamen midianitische Männer vorüber, Händler*, und sie zogen ihn heraus und holten Josef aus der Zisterne herauf*. Und sie verkauften Josef an die Ismaeliter für zwanzig Silberschekel*. Und sie brachten Josef nach Ägypten*.", footnotes: ["w. im Land Umherziehende", "℘ Jer 38,13", "℘ 2Mo 21,16; 3Mo 27,5; Mt 26,15", "℘ Kap. 40,15; 45,4; Ps 105,17; Apg 7,9"] },
      { number: 29, text: "Als nun Ruben zur Zisterne zurückkam, und siehe, Josef war nicht in der Zisterne, da zerriss er seine Kleider*.", footnotes: ["℘ Kap. 44,13; Ri 11,35; Hi 1,20"] },
      { number: 30, text: "Und er kehrte zu seinen Brüdern zurück und sagte: Der Junge ist nicht mehr da! Ich aber, wohin soll ich jetzt gehen?*", footnotes: ["℘ Kap. 42,13.36"] },
      { number: 31, text: "Da nahmen sie den Leibrock Josefs und schlachteten einen Ziegenbock* und tauchten den Leibrock in das Blut.", footnotes: ["w. Haarigen der Ziegen"] },
      { number: 32, text: "Dann schickten sie den bunten* Leibrock hin und ließen ihn ihrem Vater bringen und sagen: Das haben wir gefunden. Untersuche doch, ob es der Leibrock deines Sohnes ist oder nicht!*", footnotes: ["s. Anm. zu V. 3", "℘ Kap. 38,25"] },
      { number: 33, text: "Da untersuchte er ihn und sagte: Der Leibrock meines Sohnes! Ein böses Tier hat ihn gefressen; zerrissen, zerrissen ist Josef*!", footnotes: ["℘ Kap. 44,28"] },
      { number: 34, text: "Und Jakob zerriss seine Kleider* und legte Sacktuch um seine Hüften*, und er trauerte um seinen Sohn viele Tage.", footnotes: ["℘ Kap. 44,13; Ri 11,35; Hi 1,20", "℘ 1Kö 20,31.32; 2Kö 19,1; Est 4,1"] },
      { number: 35, text: "Und alle seine Söhne und alle seine Töchter machten sich auf, um ihn zu trösten*; er aber weigerte sich, sich trösten zu lassen*, und sagte: Nein, sondern in Trauer werde ich zu meinem Sohn in den Scheol hinabfahren*. So beweinte ihn sein Vater*.", footnotes: ["℘ 1Chr 7,22; Hi 2,11", "℘ 2Sam 12,17; 19,1.5; Ps 77,3; Jer 31,15", "℘ Kap. 42,38; 44,29.31", "℘ Kap. 48,11"] },
      { number: 36, text: "Und die Midianiter* verkauften ihn nach Ägypten, an Potifar, einen Kämmerer des Pharao, den Obersten der Leibwächter*.", footnotes: ["so mit den alten Üs.; Mas. T.: Medaniter", "℘ Kap. 39,1"] },
    ]},
    { number: 38, verses: [
      { number: 1, text: "Und es geschah in jener Zeit, dass Juda von seinen Brüdern hinabzog und zu einem Mann von Adullam* einkehrte, dessen Name war Hira.", heading: "Juda und seine Schwiegertochter Tamar", footnotes: ["℘ 1Sam 22,1; Mi 1,15"] },
      { number: 2, text: "Dort sah Juda die Tochter eines kanaanitischen Mannes, mit Namen Schua; und er nahm sie zur Frau* und ging zu ihr ein.", footnotes: ["℘ Kap. 24,3; 28,1"] },
      { number: 3, text: "Und sie wurde schwanger und gebar einen Sohn, dem gab er den Namen Er*.", footnotes: ["℘ Kap. 46,12; 4Mo 26,19.20; 1Chr 2,3"] },
      { number: 4, text: "Und sie wurde wieder schwanger und gebar einen Sohn, dem gab sie den Namen Onan*.", footnotes: ["℘ Kap. 46,12; 4Mo 26,19.20; 1Chr 2,3"] },
      { number: 5, text: "Und noch einmal gebar sie einen Sohn, dem gab sie den Namen Schela*; Juda* war aber zu Kesib, als sie ihn gebar.", footnotes: ["℘ Kap. 46,12; 4Mo 26,19.20; 1Chr 2,3", "w. er; LXX: sie"] },
      { number: 6, text: "Und Juda nahm für seinen Erstgeborenen Er eine Frau, deren Name war Tamar." },
      { number: 7, text: "Aber Er, der Erstgeborene Judas, war böse in den Augen des HERRN, so ließ der HERR ihn sterben*.", footnotes: ["℘ 1Sam 2,25; 1Kö 17,20; 1Chr 2,3"] },
      { number: 8, text: "Da sagte Juda zu Onan: Geh zu der Frau deines Bruders ein, und geh mit ihr die Schwagerehe ein, und lass deinem Bruder Nachkommen* erstehen*!", footnotes: ["w. Samen; entsprechend nachher", "℘ Rt 4,5; Mt 22,24"] },
      { number: 9, text: "Da aber Onan wusste*, dass die Nachkommen nicht ihm gehören würden*, geschah es, wenn er zu der Frau seines Bruders einging, dass er den Samen auf die Erde fallen und verderben ließ, um seinem Bruder keine Nachkommen zu geben.", footnotes: ["o. erkannte", "℘ 5Mo 25,5.6"] },
      { number: 10, text: "Und es war böse in den Augen des HERRN, was er tat; so ließ er auch ihn sterben*.", footnotes: ["℘ 1Sam 2,25; 1Kö 17,20; 1Chr 2,3"] },
      { number: 11, text: "Da sagte Juda zu seiner Schwiegertochter Tamar: Bleibe Witwe im Haus deines Vaters, bis mein Sohn Schela groß sein wird! Denn er sagte sich: Dass nicht auch er sterbe wie seine Brüder! So ging Tamar hin und blieb im Haus ihres Vaters*.", footnotes: ["℘ 3Mo 22,13; Rt 1,11.13"] },
      { number: 12, text: "Als nun viele Tage vergangen waren, da starb die Tochter Schuas, Judas Frau. Und als Juda getröstet war*, ging er zu seinen Schafscherern hinauf nach Timna*, er und sein Freund Hira, der Adullamiter.", footnotes: ["℘ 2Sam 13,39", "℘ Ri 14,1"] },
      { number: 13, text: "Und es wurde der Tamar berichtet: Siehe, dein Schwiegervater geht nach Timna hinauf, um seine Schafe zu scheren*.", footnotes: ["℘ Kap. 31,19"] },
      { number: 14, text: "Da legte sie die Kleider ihrer Witwenschaft von sich ab, bedeckte sich mit einem Schleier und verhüllte sich*. Dann setzte sie sich an den Eingang von Enajim, das am Weg nach Timna liegt; denn sie hatte gesehen, dass Schela groß geworden war und sie ihm doch nicht zur Frau gegeben wurde.", footnotes: ["℘ Kap. 24,65"] },
      { number: 15, text: "Und Juda sah sie und hielt sie für eine Hure, denn sie hatte ihr Gesicht bedeckt*.", footnotes: ["℘ Spr 7,10"] },
      { number: 16, text: "Und er bog zu ihr ab an den Weg und sagte: Auf, lass mich zu dir eingehen! Denn er erkannte nicht, dass sie seine Schwiegertochter war. Sie aber sagte: Was gibst du mir, wenn du zu mir eingehst?*", footnotes: ["℘ Hes 16,33"] },
      { number: 17, text: "Da sagte er: Ich will dir ein Ziegenböckchen von der Herde senden. Sie sagte: Wenn du ein Pfand gibst, bis du es sendest!" },
      { number: 18, text: "Da sagte er: Was für ein Pfand soll ich dir geben? Sie sagte: Deinen Siegelring und deine Schnur und deinen Stab, der in deiner Hand ist. Da gab er es ihr und ging zu ihr ein, und sie wurde schwanger von ihm*.", footnotes: ["℘ 3Mo 18,15"] },
      { number: 19, text: "Dann stand sie auf und ging hin, sie legte ihren Schleier von sich ab und zog die Kleider ihrer Witwenschaft wieder an*.", footnotes: ["℘ 2Sam 14,2"] },
      { number: 20, text: "Juda aber sandte das Ziegenböckchen durch die Hand seines Freundes, des Adullamiters, um das Pfand aus der Hand der Frau zu holen; aber er fand sie nicht." },
      { number: 21, text: "Da fragte er die Leute ihres Ortes: Wo ist jene Geweihte*, die zu Enajim am Weg war? Sie aber sagten: Hier ist keine Geweihte gewesen.", footnotes: ["Das sind weibliche und männliche Tempelprostituierte im Dienst der Fruchtbarkeitsgöttin Astarte."] },
      { number: 22, text: "Da kehrte er zu Juda zurück und sagte: Ich habe sie nicht gefunden, auch sagten die Leute des Ortes: »Hier ist keine Geweihte* gewesen.«", footnotes: ["Das sind weibliche und männliche Tempelprostituierte im Dienst der Fruchtbarkeitsgöttin Astarte."] },
      { number: 23, text: "Da sagte Juda: Sie soll es bei sich behalten, damit wir nicht zum Gespött werden; siehe, ich habe ja dieses Böckchen gesandt, und du hast sie nicht gefunden." },
      { number: 24, text: "Und es geschah nach etwa drei Monaten, da wurde dem Juda berichtet: Deine Schwiegertochter Tamar hat Hurerei getrieben, und siehe, sie ist sogar schwanger von Hurerei. Da sagte Juda: Führt sie hinaus, sie soll verbrannt werden*!", footnotes: ["℘ 3Mo 21,9; 5Mo 22,21"] },
      { number: 25, text: "Als sie nun hinausgeführt wurde, da sandte sie zu ihrem Schwiegervater und ließ ihm sagen: Von einem Mann, dem dies gehört, bin ich schwanger. Und sie sagte: Untersuche doch, wem dieser Siegelring und diese Schnur und dieser Stab gehört*!", footnotes: ["℘ Kap. 37,32"] },
      { number: 26, text: "Da untersuchte es Juda und sagte: Sie ist im Recht mir gegenüber*, deswegen weil ich sie meinem Sohn Schela nicht gegeben habe. Und er erkannte sie künftig nicht mehr*.", footnotes: ["o. gerechter als ich\n℘ 1Sam 24,18", "℘ Hi 34,32"] },
      { number: 27, text: "Und es geschah zur Zeit, als sie gebären sollte, siehe, da waren Zwillinge in ihrem Leib*.", footnotes: ["℘ Kap. 25,24"] },
      { number: 28, text: "Und es geschah, während sie gebar, da streckte einer die Hand heraus, und die Hebamme nahm sie und band eine rote Schnur um seine Hand und sagte: Der ist zuerst herausgekommen." },
      { number: 29, text: "Und es geschah, als er seine Hand zurückzog, siehe, da kam sein Bruder heraus; und sie sagte: Was für einen Riss hast du deinetwegen gerissen! Und man gab ihm den Namen Perez*.", footnotes: ["d. h. Riss\n℘ Rt 4,12.18; Lk 3,33"] },
      { number: 30, text: "Und danach kam sein Bruder heraus, um dessen Hand die rote Schnur war. Dem gab man den Namen Serach*.", footnotes: ["d. h. Sonnenaufgang\n℘ Kap. 46,12; 1Chr 2,4; Mt 1,3"] },
    ]},
    { number: 39, verses: [
      { number: 1, text: "Und Josef war nach Ägypten hinabgeführt worden. Und Potifar, ein Kämmerer des Pharao, der Oberste der Leibwächter, ein Ägypter, kaufte ihn aus der Hand der Ismaeliter, die ihn dorthin hinabgeführt hatten*.", heading: "Josef im Haus des Potifar", footnotes: ["℘ Kap. 37,28.36"] },
      { number: 2, text: "Der HERR aber war mit Josef*, und er war ein Mann, dem alles gelang*; und er blieb im Haus seines ägyptischen Herrn.", footnotes: ["℘ V. 21.23; Kap. 21,20; 26,24; Jos 1,9; 1Sam 3,19; 2Kö 18,7; 1Chr 9,20; 2Chr 1,1; Apg 7,9", "w. ein Mann des Gelingens"] },
      { number: 3, text: "Als nun sein Herr sah, dass der HERR mit ihm war* und dass der HERR alles, was er tat, in seiner Hand gelingen ließ*,", footnotes: ["℘ V. 21.23; Kap. 21,20; 26,24; Jos 1,9; 1Sam 3,19; 2Kö 18,7; 1Chr 9,20; 2Chr 1,1; Apg 7,9", "℘ Kap. 21,22; 5Mo 2,7; Ps 1,3"] },
      { number: 4, text: "da fand Josef Gunst in seinen Augen*, und er bediente ihn persönlich. Und er bestellte ihn über sein Haus, und alles, was er besaß, gab er in seine Hand*.", footnotes: ["℘ V. 21; 1Sam 2,26; 16,22; Est 2,9; Spr 3,4", "℘ Kap. 41,40"] },
      { number: 5, text: "Und es geschah, seitdem er ihn über sein Haus bestellt hatte und über alles, was er besaß, da segnete der HERR das Haus des Ägypters um Josefs willen; und der Segen des HERRN war auf allem, was er hatte, im Haus und auf dem Feld*.", footnotes: ["℘ Kap. 30,27"] },
      { number: 6, text: "Und er überließ alles, was er hatte, der Hand Josefs und kümmerte sich bei ihm um gar nichts, außer um das Brot*, das er aß. Josef aber war schön von Gestalt und schön von Aussehen*.", footnotes: ["o. und kannte bei ihm gar nichts außer dem Brot", "℘ 1Sam 16,12"] },
      { number: 7, text: "Und es geschah nach diesen Dingen, da warf die Frau seines Herrn ihre Augen auf Josef und sagte: Liege bei mir!*", footnotes: ["℘ Spr 6,26; 2Petr 2,14"] },
      { number: 8, text: "Er aber weigerte sich* und sagte zu der Frau seines Herrn: Siehe, mein Herr kümmert sich um* nichts bei mir im Haus; und alles, was er besitzt, hat er in meine Hand gegeben.", footnotes: ["℘ Spr 2,16", "o. kennt"] },
      { number: 9, text: "Er selbst ist in diesem Haus nicht größer als ich, und er hat mir gar nichts vorenthalten als nur dich, weil du seine Frau bist. Wie sollte ich dieses große Unrecht tun und gegen Gott sündigen*?", footnotes: ["℘ 2Mo 20,14; Pred 7,26"] },
      { number: 10, text: "Und es geschah, obwohl sie Tag für Tag auf Josef einredete, hörte er nicht auf sie, bei ihr zu liegen, mit ihr zusammen zu sein*.", footnotes: ["℘ Spr 23,27.28"] },
      { number: 11, text: "Da geschah es an einem solchen Tag*, dass er ins Haus kam, um sein Geschäft zu besorgen, als gerade kein Mensch von den Leuten des Hauses dort im Haus war,", footnotes: ["o. um diese Zeit"] },
      { number: 12, text: "da ergriff sie ihn bei seinem Gewand und sagte: Liege bei mir!* Er aber ließ sein Gewand in ihrer Hand, floh und lief hinaus*.", footnotes: ["℘ 2Sam 13,11", "℘ 2Tim 2,22"] },
      { number: 13, text: "Und es geschah, als sie sah, dass er sein Gewand in ihrer Hand gelassen hatte und hinausgeflohen war," },
      { number: 14, text: "da rief sie die Leute ihres Hauses und sagte zu ihnen: Seht, er hat uns einen hebräischen Mann hergebracht, Mutwillen* mit uns zu treiben. Er ist zu mir gekommen, um bei mir zu liegen, aber ich habe mit lauter Stimme gerufen.", footnotes: ["w. Scherz"] },
      { number: 15, text: "Und es geschah, als er hörte, dass ich meine Stimme erhob und rief, da ließ er sein Gewand neben mir und floh und lief hinaus*.", footnotes: ["℘ Ps 64,6.7"] },
      { number: 16, text: "Und sie ließ sein Gewand neben sich liegen, bis sein Herr nach Hause kam." },
      { number: 17, text: "Da redete sie zu ihm mit* denselben Worten: Der hebräische Sklave, den du uns hergebracht hast, ist zu mir gekommen, um Mutwillen* mit mir zu treiben*;", footnotes: ["w. nach", "w. Scherz", "℘ 2Mo 23,1"] },
      { number: 18, text: "und es geschah, als ich meine Stimme erhob und rief, da ließ er sein Gewand neben mir und floh hinaus." },
      { number: 19, text: "Und es geschah, als sein Herr die Worte seiner Frau hörte, die sie zu ihm redete, indem sie sagte: Nach diesen Worten hat mir dein Sklave getan; da entbrannte sein Zorn*.", heading: "Josef im Gefängnis — Träume der beiden Kämmerer", footnotes: ["℘ Spr 6,34"] },
      { number: 20, text: "Und Josefs Herr nahm ihn und legte ihn ins Gefängnis, an den Ort, wo die Gefangenen des Königs gefangen lagen; und er war dort im Gefängnis*.", footnotes: ["℘ Kap. 40,3.15; Ps 105,18; 1Petr 2,19"] },
      { number: 21, text: "Der HERR aber war mit Josef* und wandte sich ihm in Treue zu* und gab ihm Gunst in den Augen des Obersten des Gefängnisses*.", footnotes: ["℘ V. 2", "mit geringfügiger Änderung: wandte ihm Treue (o. Huld) zu", "℘ V. 4; Dan 1,9"] },
      { number: 22, text: "Und der Oberste des Gefängnisses übergab alle Gefangenen, die im Gefängnis waren, der Hand Josefs; und alles, was man dort tat, das veranlasste er*.", footnotes: ["w. und alles, was sie dort taten, er war es, der es tat\n℘ Kap. 40,4"] },
      { number: 23, text: "Der Oberste des Gefängnisses sah nicht nach dem Geringsten, das unter seiner Hand war, weil der HERR mit ihm war; und was er tat, ließ der HERR gelingen." },
    ]},
    { number: 40, verses: [
      { number: 1, text: "Und es geschah nach diesen Dingen, da versündigten sich der Mundschenk des Königs von Ägypten und der Bäcker gegen ihren Herrn, den König von Ägypten*.", footnotes: ["℘ Kap. 41,9.10"] },
      { number: 2, text: "Und der Pharao wurde zornig über seine beiden Kämmerer, über den Obersten der Mundschenke und über den Obersten der Bäcker*;", footnotes: ["℘ Spr 16,14"] },
      { number: 3, text: "und er gab sie in Gewahrsam, in das Haus des Obersten der Leibwächter, ins Gefängnis, an den Ort, wo Josef gefangen lag*.", footnotes: ["℘ Kap. 39,20"] },
      { number: 4, text: "Und der Oberste der Leibwächter gab ihnen Josef bei, und er bediente sie; und sie waren eine Zeit lang in Gewahrsam*.", footnotes: ["℘ Kap. 39,22"] },
      { number: 5, text: "Und sie hatten beide einen Traum*, jeder seinen Traum in einer Nacht, jeder mit* einer besonderen Deutung seines Traumes*, der Mundschenk und der Bäcker des Königs von Ägypten, die im Gefängnis gefangen lagen.", footnotes: ["℘ Kap. 20,3; 41,1.5", "w. nach", "℘ Kap. 41,11"] },
      { number: 6, text: "Als Josef am Morgen zu ihnen kam und sie sah, siehe, da waren sie traurig*.", footnotes: ["o. abgemagert\n℘ Kap. 41,8"] },
      { number: 7, text: "Und er fragte die Kämmerer des Pharao, die mit ihm im Haus seines Herrn in Gewahrsam waren: Warum sind eure Gesichter heute so traurig?*", footnotes: ["℘ Neh 2,2"] },
      { number: 8, text: "Da sagten sie zu ihm: Wir haben einen Traum gehabt, aber es gibt keinen, der ihn deute. Da sagte Josef zu ihnen: Sind die Deutungen nicht Gottes Sache*? Erzählt mir doch!", footnotes: ["℘ Kap. 41,15.16.25; Dan 2,28"] },
      { number: 9, text: "Da erzählte der Oberste der Mundschenke dem Josef seinen Traum und sagte zu ihm: In meinem Traum, siehe, da war ein Weinstock vor mir" },
      { number: 10, text: "und an dem Weinstock drei Ranken; und sowie er Knospen trieb, kam sein Blütenstand hervor, und seine Traubenkämme reiften zu Trauben." },
      { number: 11, text: "Und der Becher des Pharao war in meiner Hand, und ich nahm die Trauben und presste sie in den Becher des Pharao aus und gab den Becher in die Hand des Pharao." },
      { number: 12, text: "Da sagte Josef zu ihm: Das ist seine Deutung*: Die drei Ranken, sie bedeuten drei Tage.", footnotes: ["℘ Kap. 41,12.28; Dan 2,36"] },
      { number: 13, text: "Noch drei Tage, dann wird der Pharao dein Haupt erheben und dich wieder in deine Stellung einsetzen, und du wirst den Becher des Pharao in seine Hand geben nach der früheren Weise*, als du sein Mundschenk warst*.", footnotes: ["o. nach dem früheren Recht", "℘ 2Kö 25,27"] },
      { number: 14, text: "Aber denke an mich bei dir*, wenn es dir gut geht, und erweise doch Treue* an mir*, und erwähne mich beim Pharao, und bring mich aus diesem Haus heraus*!", footnotes: ["℘ 1Sam 25,31; Lk 23,42", "o. Gnade", "℘ Jos 2,12; 1Sam 20,14.15", "℘ Apg 7,10"] },
      { number: 15, text: "Denn gestohlen bin ich aus dem Land der Hebräer*, und auch hier habe ich gar nichts getan*, dass sie mich in den Kerker* gesetzt haben*.", footnotes: ["℘ Kap. 14,13; 37,28", "℘ Ps 59,4.5; 109,2", "w. in die Grube", "℘ Kap. 39,20"] },
      { number: 16, text: "Als nun der Oberste der Bäcker sah, dass er gut gedeutet hatte, sagte er zu Josef: Auch ich sah in meinem Traum, und siehe, drei Körbe mit Weißbrot waren auf meinem Kopf" },
      { number: 17, text: "und im obersten Korb allerlei Esswaren des Pharao, Backwerk, und die Vögel fraßen sie aus dem Korb auf meinem Kopf weg." },
      { number: 18, text: "Da antwortete Josef und sagte: Das ist seine Deutung*: Die drei Körbe, sie bedeuten drei Tage.", footnotes: ["℘ Kap. 41,12.28; Dan 2,36"] },
      { number: 19, text: "Noch drei Tage, dann wird der Pharao dein Haupt erheben* und dich an ein Holz hängen*, und die Vögel werden dein Fleisch von dir wegfressen*.", footnotes: ["w. weg von dir erheben, o. von dir wegnehmen", "℘ 5Mo 21,22", "℘ 1Sam 17,46; Offb 19,21"] },
      { number: 20, text: "Und es geschah am dritten Tag, dem Geburtstag des Pharao, da machte er für all seine Knechte ein Mahl*; und er erhob das Haupt des Obersten der Mundschenke und das Haupt des Obersten der Bäcker unter seinen Knechten.", footnotes: ["℘ 1Kö 3,15; Est 1,3; Mk 6,21"] },
      { number: 21, text: "Und er setzte den Obersten der Mundschenke wieder in sein Schenkamt ein, dass er den Becher in die Hand des Pharao gab," },
      { number: 22, text: "den Obersten der Bäcker aber ließ er hängen, so wie es ihnen Josef gedeutet hatte*.", footnotes: ["℘ Kap. 41,13"] },
      { number: 23, text: "Aber der Oberste der Mundschenke dachte nicht mehr an Josef und vergaß ihn*.", footnotes: ["℘ Est 6,3; Ps 31,13; Pred 9,15"] },
    ]},
    { number: 41, verses: [
      { number: 1, text: "Es geschah aber am Ende von zwei vollen Jahren, da träumte der Pharao*: Und siehe, er stand am Strom.", heading: "Träume des Pharao — Deutung durch Josef", footnotes: ["℘ Kap. 40,5"] },
      { number: 2, text: "Und siehe, aus dem Strom stiegen sieben Kühe herauf, schön von Aussehen und fett an Fleisch, und sie weideten im Riedgras." },
      { number: 3, text: "Und siehe, sieben andere Kühe stiegen nach ihnen aus dem Strom herauf, hässlich von Aussehen und mager an Fleisch, und sie stellten sich neben die Kühe ans Ufer des Stromes." },
      { number: 4, text: "Und die Kühe, die hässlich von Aussehen und mager an Fleisch waren, fraßen die sieben Kühe, die schön von Aussehen und fett waren. Da erwachte der Pharao." },
      { number: 5, text: "Und er schlief wieder ein und träumte* zum zweiten Mal: Und siehe, sieben Ähren wuchsen auf an einem Halm, fett und schön.", footnotes: ["℘ Kap. 40,5"] },
      { number: 6, text: "Und siehe, sieben Ähren, mager und vom Ostwind versengt*, sprossten nach ihnen auf.", footnotes: ["℘ Hes 17,10; Jon 4,8"] },
      { number: 7, text: "Und die mageren Ähren verschlangen die sieben fetten und vollen Ähren. Da erwachte der Pharao, und siehe, es war ein Traum*.", footnotes: ["℘ 1Kö 3,15"] },
      { number: 8, text: "Und es geschah am Morgen, da war sein Geist voller Unruhe*, und er sandte hin und ließ alle Wahrsagepriester Ägyptens und alle seine* Weisen rufen*; und der Pharao erzählte ihnen seine Träume*, aber da war keiner, der sie dem Pharao deutete*.", footnotes: ["℘ Kap. 40,6; Dan 2,1", "d. i. Ägyptens", "℘ 2Mo 7,11; 1Sam 6,2; Dan 2,1.2", "so mit SamPent; Mas. T.: seinen Traum", "℘ V. 24; Dan 2,11"] },
      { number: 9, text: "Da redete der Oberste der Mundschenke den Pharao an: Ich bringe heute meine Sünde in Erinnerung*.", footnotes: ["℘ Kap. 40,1.14"] },
      { number: 10, text: "Der Pharao war einst sehr zornig über seine Knechte und gab mich in Gewahrsam in das Haus des Obersten der Leibwächter, mich und den Obersten der Bäcker." },
      { number: 11, text: "Da hatten wir einen Traum in einer Nacht, ich und er; wir träumten jeder mit* einer besonderen Deutung seines Traumes*.", footnotes: ["w. nach", "℘ Kap. 40,5"] },
      { number: 12, text: "Aber dort bei uns war ein junger Hebräer, ein Sklave des Obersten der Leibwächter, und wir erzählten ihm die Träume. Da deutete er uns unsere Träume, jeden deutete er nach seinem Traum*.", footnotes: ["℘ Dan 1,17"] },
      { number: 13, text: "Und es geschah, wie er uns deutete, also ist es geschehen: Mich hat man wieder in meine Stellung eingesetzt, und ihn hat man gehängt*.", footnotes: ["℘ Kap. 40,21.22"] },
      { number: 14, text: "Da sandte der Pharao hin und ließ Josef rufen; da ließen sie ihn schnell aus dem Kerker* holen. Und er schor sich, wechselte seine Kleider* und kam zum Pharao*.", footnotes: ["w. der Grube", "℘ 2Kö 25,29", "℘ Ps 105,19.20; Dan 2,25"] },
      { number: 15, text: "Und der Pharao sprach zu Josef: Ich habe einen Traum gehabt, aber es gibt keinen, der ihn deute; ich habe nun von dir sagen hören, du verstehst es, einen Traum* zu deuten*.", footnotes: ["o. du brauchst einen Traum nur zu hören, um ihn", "℘ 2Chr 26,5; Dan 5,14-16"] },
      { number: 16, text: "Da antwortete Josef dem Pharao: Das steht nicht bei mir; Gott wird antworten*, was dem Pharao zum Heil ist.", footnotes: ["℘ Kap. 40,8"] },
      { number: 17, text: "Da redete der Pharao zu Josef: In meinem Traum, siehe, da stand ich am Ufer des Stromes." },
      { number: 18, text: "Und siehe, aus dem Strom stiegen sieben Kühe herauf, fett an Fleisch und schön von Gestalt, und sie weideten im Riedgras." },
      { number: 19, text: "Und siehe, sieben andere Kühe stiegen nach ihnen herauf, dürr* und sehr hässlich von Gestalt und mager an Fleisch; ich habe im ganzen Land Ägypten nie so hässliche gesehen wie diese.", footnotes: ["o. schwach; o. gering"] },
      { number: 20, text: "Und die mageren und hässlichen Kühe fraßen die sieben ersten fetten Kühe." },
      { number: 21, text: "Und als sie in ihren Bauch gekommen waren, da merkte man nichts davon, dass sie in ihren Bauch gekommen waren, sondern ihr Aussehen war hässlich wie im Anfang. Und ich erwachte." },
      { number: 22, text: "Dann sah ich in meinem zweiten Traum, und siehe, sieben Ähren wuchsen auf an einem Halm, voll und schön." },
      { number: 23, text: "Und siehe, sieben Ähren, dürr, mager und vom Ostwind versengt, sprossten nach ihnen auf;" },
      { number: 24, text: "und die mageren Ähren verschlangen die sieben schönen Ähren. Und ich habe es den Wahrsagepriestern gesagt; aber es gibt keinen, der es mir erklärt*.", footnotes: ["℘ V. 8"] },
      { number: 25, text: "Da sprach Josef zum Pharao: Der Traum des Pharao ist einer. Gott hat dem Pharao mitgeteilt*, was er tun will.", footnotes: ["℘ Kap. 40,8"] },
      { number: 26, text: "Die sieben schönen Kühe sind sieben Jahre, und die sieben schönen Ähren sind sieben Jahre; nur ein Traum ist es*.", footnotes: ["℘ Kap. 40,12.18; Dan 2,45"] },
      { number: 27, text: "Und die sieben mageren und hässlichen Kühe, die nach ihnen heraufstiegen, auch sie sind sieben Jahre, so auch die sieben leeren, vom Ostwind versengten Ähren: Es werden sieben Jahre der Hungersnot sein*.", footnotes: ["℘ 2Kö 8,1"] },
      { number: 28, text: "Das ist das Wort, das ich zu dem Pharao geredet habe: Gott hat den Pharao sehen lassen, was er tun will*.", footnotes: ["℘ Kap. 40,12.18; Dan 2,45"] },
      { number: 29, text: "Siehe, sieben Jahre kommen, großer Überfluss wird herrschen im ganzen Land Ägypten." },
      { number: 30, text: "Nach ihnen aber werden sieben Jahre der Hungersnot aufkommen, und aller Überfluss wird im Land Ägypten vergessen sein, und die Hungersnot wird das Land erschöpfen*.", footnotes: ["℘ Kap. 47,13"] },
      { number: 31, text: "Und man wird nichts mehr von dem Überfluss im Land erkennen angesichts dieser Hungersnot danach, denn sie wird sehr schwer sein." },
      { number: 32, text: "Und dass der Traum zweimal an den Pharao erging, bedeutet, dass die Sache bei Gott fest beschlossen ist und dass Gott eilt, sie zu tun*.", footnotes: ["℘ Jes 14,24"] },
      { number: 33, text: "Und nun sehe der Pharao nach einem verständigen und weisen Mann und setze ihn über das Land Ägypten*.", footnotes: ["℘ 5Mo 1,13"] },
      { number: 34, text: "Dies tue der Pharao, dass er Aufseher über das Land bestelle und den Fünften vom Land Ägypten erhebe* in den sieben Jahren des Überflusses.", footnotes: ["℘ Kap. 47,24"] },
      { number: 35, text: "Und sie sollen alle Nahrungsmittel dieser kommenden guten Jahre einsammeln und unter der Obhut* des Pharao Getreide aufspeichern als Nahrungsmittel in den Städten und es dort aufbewahren.", footnotes: ["o. im Auftrag; o. zur Verfügung; w. unter der Hand"] },
      { number: 36, text: "So soll die eingesammelte Nahrung zum Vorrat für das Land dienen für die sieben Jahre der Hungersnot, die im Land Ägypten sein werden, damit das Land durch die Hungersnot nicht zugrunde geht*.", footnotes: ["℘ Kap. 47,15.19"] },
      { number: 37, text: "Und das Wort war gut in den Augen des Pharao und in den Augen aller seiner Diener*.", heading: "Josefs hohe Stellung und Heirat — Maßnahmen gegen die Hungersnot", footnotes: ["℘ Kap. 45,16"] },
      { number: 38, text: "Und der Pharao sagte zu seinen Dienern: Werden wir einen finden wie diesen, einen Mann, in dem der Geist Gottes* ist*?", footnotes: ["o. der Götter", "℘ 4Mo 27,18; Hi 32,8; Spr 14,35; Dan 6,4"] },
      { number: 39, text: "Und zu Josef sagte der Pharao: Nachdem dich Gott dies alles hat erkennen lassen, ist keiner so verständig und weise wie du*.", footnotes: ["℘ Esr 7,25; Spr 12,8"] },
      { number: 40, text: "Du sollst über mein Haus sein, und deinem Mund soll mein ganzes Volk sich fügen*; nur um den Thron will ich größer sein als du*.", footnotes: ["w. und mein ganzes Volk soll auf deinen Mund küssen. — LXX: auf deinen Mund hören; die syr. Üs.: durch deinen Mund gerichtet werden", "℘ Kap. 39,4; Est 3,1; 10,3; Ps 105,21"] },
      { number: 41, text: "Und der Pharao sagte zu Josef: Siehe, ich habe dich über das ganze Land Ägypten gesetzt*.", footnotes: ["℘ Kap. 45,8.26; Pred 4,14; Dan 2,48; Apg 7,10"] },
      { number: 42, text: "Und der Pharao nahm seinen Siegelring von seiner Hand und steckte ihn an Josefs Hand, und er kleidete ihn in Kleider aus Byssus* und legte die goldene Kette um seinen Hals*.", footnotes: ["d. i. feinstes, ägyptisches Gewebe, wohl feines Leinen", "℘ Est 3,10; Dan 5,29"] },
      { number: 43, text: "Und er ließ ihn auf dem zweiten Wagen fahren, den er hatte, und man rief vor ihm her: Werft euch nieder*! So setzte er ihn über das ganze Land Ägypten*.", footnotes: ["℘ Est 3,2", "℘ Kap. 45,8.26; Pred 4,14; Dan 2,48; Apg 7,10"] },
      { number: 44, text: "Und der Pharao sprach zu Josef: Ich bin der Pharao, aber ohne dich soll kein Mensch im ganzen Land Ägypten seine Hand oder seinen Fuß erheben!*", footnotes: ["℘ Ps 105,22"] },
      { number: 45, text: "Und der Pharao gab Josef den Namen* Zafenat-Paneach* und gab ihm Asenat, die Tochter Potiferas, des Priesters von On*, zur Frau*. Dann zog Josef aus über das ganze Land Ägypten.", footnotes: ["℘ Dan 1,7", "ägyptisch de-pnute-ef-onch; d. h. Gott spricht: Er lebt", "ägyptisch An; der alte Name der Stadt Heliopolis, nördlich des heutigen Kairo\n℘ Jer 43,13; Hes 30,17", "℘ Kap. 46,20"] },
      { number: 46, text: "Und Josef war dreißig Jahre alt*, als er vor dem Pharao, dem König von Ägypten, stand*. Und Josef ging vom Pharao weg und zog durch das ganze Land Ägypten.", footnotes: ["℘ 2Sam 5,4; Lk 3,23", "℘ 1Sam 16,21; Dan 1,19"] },
      { number: 47, text: "Und das Land trug in den sieben Jahren des Überflusses haufenweise*.", footnotes: ["w. händevollweise"] },
      { number: 48, text: "Und er sammelte alle Nahrungsmittel der sieben Jahre, in denen im Land Ägypten Überfluss war*, und brachte die Nahrungsmittel in die Städte; die Nahrungsmittel der Felder, die im Umkreis der Stadt lagen, brachte er in sie hinein.", footnotes: ["so mit SamPent und LXX; Mas. T.: Jahre, die im Land Ägypten waren"] },
      { number: 49, text: "Und Josef speicherte Getreide auf wie Sand des Meeres, über die Maßen viel, bis man aufhörte zu zählen, denn es war ohne Zahl." },
      { number: 50, text: "Und dem Josef wurden zwei Söhne geboren, ehe das Jahr der Hungersnot kam, die Asenat ihm gebar, die Tochter Potiferas, des Priesters von On*.", footnotes: ["℘ Kap. 46,20"] },
      { number: 51, text: "Und Josef gab dem Erstgeborenen den Namen Manasse*. Denn Gott hat mich vergessen lassen all meine Mühe* und das ganze Haus meines Vaters.", footnotes: ["d. h. der vergessen lässt\n℘ Kap. 48,5; 4Mo 26,28; Jos 14,4; 17,1", "℘ Hi 11,16"] },
      { number: 52, text: "Und dem zweiten gab er den Namen Ephraim*. Denn Gott hat mich fruchtbar gemacht im Land meines Elends.", footnotes: ["d. h. Fruchtland, Weideland\n℘ Kap. 48,5; 4Mo 26,28; Jos 14,4; 17,1"] },
      { number: 53, text: "Und die sieben Jahre des Überflusses, der im Land Ägypten gewesen war, gingen zu Ende," },
      { number: 54, text: "und die sieben Jahre der Hungersnot begannen zu kommen, so wie es Josef gesagt hatte*. Und in allen Ländern war Hungersnot, aber im ganzen Land Ägypten war Brot*.", footnotes: ["℘ Ps 105,16", "℘ Apg 7,11"] },
      { number: 55, text: "Als nun das ganze Land Ägypten hungerte und das Volk zum Pharao um Brot schrie*, da sagte der Pharao zu allen Ägyptern: Geht zu Josef; tut, was er euch sagt!*", footnotes: ["℘ 2Kö 6,25.26", "℘ Joh 2,5"] },
      { number: 56, text: "Und die Hungersnot war auf der ganzen Erde; und Josef öffnete alles, worin Getreide war, und verkaufte* den Ägyptern Getreide*; und die Hungersnot war stark im Land Ägypten*.", footnotes: ["so mit geringfügiger Änderung; Mas. T.: kaufte", "℘ Kap. 42,6; 43,1.2; 47,14", "℘ Kap. 12,10; Mt 24,7; Apg 7,11"] },
      { number: 57, text: "Und alle Welt* kam nach Ägypten zu Josef, um Getreide zu kaufen*; denn die Hungersnot war stark auf der ganzen Erde*.", footnotes: ["w. die ganze Erde", "℘ Kap. 12,10; Mt 24,7; Apg 7,11", "℘ Kap. 12,10; Mt 24,7; Apg 7,11"] },
    ]},
    { number: 42, verses: [
      { number: 1, text: "Als Jakob sah, dass Getreide in Ägypten war, da sagte Jakob zu seinen Söhnen: Was seht ihr einander an?", heading: "Erste Reise der Brüder Josefs nach Ägypten ohne Benjamin" },
      { number: 2, text: "Und er sagte: Siehe, ich habe gehört, dass es in Ägypten Getreide gibt. Zieht hinab und kauft uns von da Getreide, damit wir am Leben bleiben und nicht sterben!*", footnotes: ["℘ Kap. 43,2.8; Apg 7,12"] },
      { number: 3, text: "Da zogen die zehn Brüder Josefs hinab, um Getreide aus Ägypten zu kaufen." },
      { number: 4, text: "Aber Benjamin, Josefs Bruder, sandte Jakob nicht mit seinen Brüdern; denn er sagte: Dass ihm nicht etwa ein Unfall begegne!*", footnotes: ["℘ V. 38; Kap. 44,29"] },
      { number: 5, text: "Und so kamen die Söhne Israels unter den Ankommenden, um Getreide zu kaufen; denn die Hungersnot war auch im Land Kanaan*.", footnotes: ["℘ Kap. 41,54-57"] },
      { number: 6, text: "Und Josef, er war der Machthaber über das Land, er war es, der allem Volk des Landes Getreide verkaufte*. Als nun die Brüder Josefs kamen, beugten sie sich vor ihm nieder, mit dem Gesicht zur Erde*.", footnotes: ["℘ Kap. 41,54-57", "℘ Kap. 18,2; 37,7.9; 1Sam 20,41"] },
      { number: 7, text: "Als Josef seine Brüder sah, da erkannte er sie; aber er stellte sich fremd gegen sie und redete hart mit ihnen und sagte zu ihnen: Woher kommt ihr? Sie sagten: Aus dem Land Kanaan, um Nahrungsmittel zu kaufen." },
      { number: 8, text: "Und Josef hatte seine Brüder erkannt, sie aber erkannten ihn nicht." },
      { number: 9, text: "Da dachte Josef an die Träume, die er von ihnen gehabt hatte*, und er sagte zu ihnen: Ihr seid Kundschafter*; die Blöße des Landes auszuspähen, seid ihr gekommen.", footnotes: ["℘ Kap. 37,5-9", "℘ V. 30; Jos 2,1"] },
      { number: 10, text: "Sie aber sagten zu ihm: Nein, mein Herr; sondern deine Knechte sind gekommen, um Nahrungsmittel zu kaufen." },
      { number: 11, text: "Wir alle — Söhne eines Mannes sind wir! Redliche Männer sind wir! Deine Knechte sind keine Kundschafter." },
      { number: 12, text: "Er aber sagte zu ihnen: Nein, sondern die Blöße des Landes zu erspähen, seid ihr gekommen." },
      { number: 13, text: "Da sagten sie: Zwölf an der Zahl sind deine Knechte, Brüder sind wir, Söhne eines Mannes im Land Kanaan; und siehe, der jüngste ist heute bei unserm Vater geblieben*, und der eine — er ist nicht mehr*.", footnotes: ["℘ Kap. 43,29", "℘ Kap. 37,30; 43,7"] },
      { number: 14, text: "Josef aber sagte zu ihnen: Das ist es, was ich zu euch gesagt habe: Kundschafter seid ihr!" },
      { number: 15, text: "Daran sollt ihr geprüft werden: So wahr der Pharao lebt! Ihr werdet von hier nicht weggehen*, es sei denn, dass euer jüngster Bruder hierher kommt*!", footnotes: ["w. Wenn ihr von hier weggeht, dann . . .! — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ V. 34; Kap. 43,3-5; 44,23.26"] },
      { number: 16, text: "Sendet einen von euch hin, dass er euren Bruder hole! Ihr aber bleibt gefangen, und eure Worte sollen geprüft werden, ob Wahrheit bei euch ist; und wenn nicht — so wahr der Pharao lebt! —, dann seid ihr Kundschafter*.", footnotes: ["℘ V. 30; Jos 2,1"] },
      { number: 17, text: "Und er setzte sie zusammen drei Tage in Gewahrsam." },
      { number: 18, text: "Am dritten Tag aber sagte Josef zu ihnen: Tut Folgendes! Dann sollt ihr leben; ich fürchte Gott*:", footnotes: ["℘ 2Mo 1,17; 3Mo 25,17; Neh 5,9.15"] },
      { number: 19, text: "Wenn ihr redlich seid, so bleibe einer eurer Brüder gefangen im Haus eures Gewahrsams; ihr aber, zieht hin, bringt Getreide für den Hunger eurer Häuser!" },
      { number: 20, text: "Euren jüngsten Bruder aber sollt ihr zu mir bringen*, dass eure Worte sich als zuverlässig erweisen und ihr nicht sterbt! Und sie taten so.", footnotes: ["℘ V. 34; Kap. 43,3-5; 44,23.26"] },
      { number: 21, text: "Da sagten sie einer zum anderen: Fürwahr, wir sind schuldbeladen wegen unseres Bruders, dessen Seelenangst wir sahen, als er uns um Gnade anflehte, wir aber nicht hörten*. Darum ist diese Not über uns gekommen*.", footnotes: ["℘ Kap. 37,24", "℘ Kap. 44,16"] },
      { number: 22, text: "Und Ruben antwortete ihnen: Habe ich nicht zu euch gesagt: Versündigt euch nicht an dem Jungen*? Aber ihr habt nicht gehört; doch siehe, sein Blut wird gefordert*!", footnotes: ["℘ Kap. 37,21.22; 1Sam 19,4", "℘ Kap. 9,5; 1Kö 2,32"] },
      { number: 23, text: "Sie aber erkannten nicht, dass Josef es verstand, denn der Dolmetscher war zwischen ihnen*.", footnotes: ["℘ Kap. 45,12"] },
      { number: 24, text: "Und er wandte sich von ihnen ab und weinte*. Dann kehrte er zu ihnen zurück und redete zu ihnen; und er nahm von ihnen Simeon und band ihn vor ihren Augen.", footnotes: ["℘ Kap. 43,30; 45,2"] },
      { number: 25, text: "Und Josef befahl, dass man ihre Gefäße mit Getreide fülle und ihr Geld jedem in seinen Sack zurücklege* und ihnen Wegzehrung auf den Weg mitgebe. Und man tat ihnen so*.", footnotes: ["℘ Kap. 43,12; 44,1", "℘ Kap. 44,2"] },
      { number: 26, text: "Dann luden sie ihr Getreide auf ihre Esel und zogen davon." },
      { number: 27, text: "Als nun einer seinen Sack öffnete, um seinem Esel in der Herberge Futter zu geben, da sah er sein Geld, und siehe, es war oben in seinem Sack*.", footnotes: ["w. es war in der Öffnung seines Sackes\n℘ V. 35; Kap. 43,21"] },
      { number: 28, text: "Und er sagte zu seinen Brüdern: Mein Geld ist zurückgegeben worden, siehe, da ist es in meinem Sack. Da entfiel ihnen das Herz, und sie sahen einander erschrocken an und sagten: Was hat Gott uns da angetan!" },
      { number: 29, text: "Und sie kamen in das Land Kanaan zu ihrem Vater Jakob und berichteten ihm alles, was ihnen widerfahren war*, und sagten:", footnotes: ["℘ Kap. 45,25.26"] },
      { number: 30, text: "Der Mann, der Herr des Landes, redete hart mit uns und behandelte uns wie Kundschafter des Landes*.", footnotes: ["℘ V. 9.16"] },
      { number: 31, text: "Wir sagten zwar zu ihm: »Redliche Männer sind wir, wir sind keine Kundschafter;" },
      { number: 32, text: "zwölf Brüder sind wir, Söhne unseres Vaters; der eine ist nicht mehr, und der jüngste ist heute bei unserem Vater im Land Kanaan geblieben.«" },
      { number: 33, text: "Aber der Mann, der Herr des Landes, sagte zu uns: »Daran werde ich erkennen, dass ihr redlich seid: Einen eurer Brüder lasst bei mir, nehmt das Getreide für den Hunger eurer Häuser, und zieht hin;" },
      { number: 34, text: "aber bringt euren jüngsten Bruder zu mir*, so werde ich erkennen, dass ihr nicht Kundschafter, sondern redliche Männer seid! Dann werde ich euch euren Bruder wiedergeben, und ihr könnt das Land durchziehen*.«", footnotes: ["℘ V. 15.20", "℘ Kap. 20,15"] },
      { number: 35, text: "Und es geschah, als sie ihre Säcke leerten, siehe, da hatte jeder sein Geldbündel in seinem Sack*; und sie sahen ihre Geldbündel, sie und ihr Vater, und sie fürchteten sich.", footnotes: ["℘ Kap. 43,12; 44,1"] },
      { number: 36, text: "Ihr Vater Jakob aber sagte zu ihnen: Ihr habt mich der Kinder beraubt*: Josef ist nicht mehr*, und Simeon ist nicht mehr; und Benjamin wollt ihr wegnehmen! Das alles kommt über mich!", footnotes: ["℘ Kap. 43,14", "℘ Kap. 37,30"] },
      { number: 37, text: "Da sagte Ruben zu seinem Vater: Meine beiden Söhne darfst du töten, wenn ich ihn dir nicht wiederbringe. Gib ihn in meine Hand, und ich werde ihn zu dir zurückbringen*.", footnotes: ["℘ Kap. 43,9"] },
      { number: 38, text: "Er aber sagte: Mein Sohn zieht nicht mit euch hinab; denn sein Bruder ist tot, und er allein ist übrig geblieben. Begegnete ihm ein Unfall auf dem Weg, auf dem ihr zieht, so würdet ihr mein graues Haar mit Kummer in den Scheol hinabbringen*.", footnotes: ["℘ V. 4; Kap. 37,35"] },
    ]},
    { number: 43, verses: [
      { number: 1, text: "Die Hungersnot aber war schwer im Land*.", heading: "Juda als Bürge für Benjamin", footnotes: ["℘ Kap. 12,10"] },
      { number: 2, text: "Und es geschah, als sie das Getreide völlig aufgezehrt hatten, das sie aus Ägypten gebracht hatten, da sagte ihr Vater zu ihnen: Geht zurück, kauft uns ein wenig Nahrung!*", footnotes: ["℘ Kap. 42,2; 44,25"] },
      { number: 3, text: "Da sagte Juda zu ihm: Der Mann hat uns nachdrücklich gewarnt und gesagt: Ihr sollt mein Gesicht nicht sehen, es sei denn euer Bruder ist bei euch*.", footnotes: ["℘ Kap. 42,15.20.34"] },
      { number: 4, text: "Wenn du unseren Bruder mit uns senden willst, dann wollen wir hinabziehen und dir Nahrung kaufen;" },
      { number: 5, text: "wenn du ihn aber nicht sendest, ziehen wir nicht hinab; denn der Mann hat zu uns gesagt: Ihr sollt mein Gesicht nicht sehen, es sei denn euer Bruder ist bei euch*.", footnotes: ["℘ Kap. 42,15.20.34"] },
      { number: 6, text: "Da sagte Israel: Warum habt ihr mir das Leid angetan, dem Mann zu berichten, dass ihr noch einen Bruder habt?" },
      { number: 7, text: "Sie aber sagten: Der Mann erkundigte sich genau nach uns und unserer Verwandtschaft und sagte: Lebt euer Vater noch? Habt ihr noch einen Bruder?* Da berichteten wir ihm, wie es sich verhält*. Konnten wir denn wissen*, dass er sagen würde: Bringt euren Bruder herab?", footnotes: ["℘ Kap. 44,19", "w. gemäß diesen Dingen, o. gemäß diesen Worten\n℘ Kap. 42,11.13", "o. erkennen"] },
      { number: 8, text: "Da sagte Juda zu seinem Vater Israel: Schicke den Jungen mit mir, so wollen wir uns aufmachen und hinziehen, dass wir leben und nicht sterben, sowohl wir als du als auch unsere Kinder*.", footnotes: ["Das hebr. Wort bezeichnet die nicht Marschfähigen eines wandernden Stammes."] },
      { number: 9, text: "Ich will Bürge für ihn sein, von meiner Hand sollst du ihn fordern; wenn ich ihn nicht zu dir bringe und ihn vor dein Gesicht stelle, will ich alle Tage vor dir schuldig sein*.", footnotes: ["℘ Kap. 42,37; 44,32.33"] },
      { number: 10, text: "Denn hätten wir nicht gezögert, gewiss, wir wären jetzt schon zweimal zurückgekehrt." },
      { number: 11, text: "Da sagte ihr Vater Israel zu ihnen: Wenn es denn so ist, dann tut Folgendes: Nehmt vom besten Ertrag des Landes in eure Gefäße, und bringt dem Mann ein Geschenk hinab*: ein wenig Balsamharz* und ein wenig Traubenhonig*, Tragakant und Ladanum*, Pistazien und Mandeln!", footnotes: ["℘ Kap. 32,14.21; Spr 18,16", "℘ Hes 27,17", "℘ 2Mo 3,8.17", "℘ Kap. 37,25"] },
      { number: 12, text: "Und nehmt doppeltes Geld in eure Hand, und bringt das Geld, das oben in eure Säcke zurückgegeben worden ist, in eurer Hand zurück*! Vielleicht war es ein Irrtum.", footnotes: ["℘ Kap. 42,25.35"] },
      { number: 13, text: "Und nehmt euren Bruder und macht euch auf, kehrt zu dem Mann zurück!" },
      { number: 14, text: "Und Gott, der Allmächtige*, gebe euch Barmherzigkeit vor dem Mann*, dass er euch euren andern Bruder und Benjamin wieder mit zurückschicke. Und ich, wie ich die Kinder verlieren soll, muss ich die Kinder verlieren*!*", footnotes: ["hebr. el schaddaj\n℘ Kap. 17,1", "℘ Neh 1,11", "o. wie ich kinderlos war, werde ich kinderlos sein", "℘ Kap. 42,36; Est 4,16"] },
      { number: 15, text: "Da nahmen die Männer dieses Geschenk und nahmen doppeltes Geld in ihre Hand und Benjamin, und machten sich auf und zogen nach Ägypten hinab. Und sie traten vor Josef.", heading: "Zweite Reise der Brüder Josefs nach Ägypten mit Benjamin" },
      { number: 16, text: "Als Josef den Benjamin bei ihnen sah, sagte er zu dem, der über sein Haus war: Führe die Männer ins Haus, und schlachte Schlachtvieh und richte zu! Denn die Männer sollen mit mir zu Mittag essen." },
      { number: 17, text: "Und der Mann tat, wie Josef gesagt hatte; und der Mann führte die Männer in Josefs Haus." },
      { number: 18, text: "Da fürchteten sich die Männer, dass sie in Josefs Haus geführt wurden, und sagten: Um des Geldes willen, das im Anfang wieder in unsere Säcke gekommen ist*, werden wir hineingebracht; man will über uns herstürzen und über uns herfallen und uns als Sklaven nehmen, samt unseren Eseln.", footnotes: ["℘ Kap. 42,27.35; 44,8"] },
      { number: 19, text: "Und sie traten zu dem Mann, der über Josefs Haus war, und redeten zu ihm am Eingang des Hauses;" },
      { number: 20, text: "und sie sagten: Bitte, mein Herr! Wir sind im Anfang wirklich nur herabgezogen, um Nahrung zu kaufen." },
      { number: 21, text: "Es geschah aber, als wir in die Herberge kamen und unsere Säcke öffneten, siehe, da war das Geld eines jeden oben in seinem Sack, unser Geld nach seinem Gewicht. Das haben wir in unserer Hand zurückgebracht*.", footnotes: ["℘ Kap. 42,27.35; 44,8"] },
      { number: 22, text: "Auch anderes Geld haben wir in unserer Hand herabgebracht, um Nahrungsmittel zu kaufen. Wir wissen* nicht, wer unser Geld in unsere Säcke gelegt hat.", footnotes: ["o. erkennen"] },
      { number: 23, text: "Und er sprach: Friede euch!* Fürchtet euch nicht! Euer Gott und der Gott eures Vaters hat euch einen Schatz in eure Säcke gegeben; euer Geld ist mir zugekommen. Und er führte Simeon zu ihnen heraus.", footnotes: ["℘ Ri 19,20; 1Sam 25,6; 1Chr 12,19; Joh 20,19.26"] },
      { number: 24, text: "Und der Mann führte die Männer in Josefs Haus und gab ihnen Wasser, und sie wuschen ihre Füße; und er gab ihren Eseln Futter*.", footnotes: ["℘ Kap. 18,4; 24,32"] },
      { number: 25, text: "Und sie bereiteten das Geschenk zu, bis Josef am Mittag käme; denn sie hatten gehört, dass sie dort essen sollten." },
      { number: 26, text: "Als Josef nach Hause kam, da brachten sie ihm das Geschenk, das in ihrer Hand war, ins Haus und warfen sich vor ihm zur Erde nieder*.", footnotes: ["℘ Kap. 37,7.9"] },
      { number: 27, text: "Er aber fragte nach ihrem Wohlergehen und sagte: Geht es eurem alten Vater wohl*, von dem ihr spracht? Lebt er noch?", footnotes: ["℘ Kap. 37,14; 2Mo 18,7; 2Kö 4,26"] },
      { number: 28, text: "Sie sagten: Es geht deinem Knecht, unserem Vater, wohl; er lebt noch. Und sie verneigten sich und warfen sich nieder*.", footnotes: ["℘ Kap. 37,7.9"] },
      { number: 29, text: "Und er erhob seine Augen und sah seinen Bruder Benjamin, den Sohn seiner Mutter*, und sagte: Ist das euer jüngster Bruder, von dem ihr zu mir gesprochen habt?* Und er sprach: Gott sei dir gnädig*, mein Sohn!", footnotes: ["℘ Kap. 35,24", "℘ Kap. 42,13", "℘ 4Mo 6,25"] },
      { number: 30, text: "Und Josef eilte hinaus, denn sein Innerstes wurde erregt über seinen Bruder, und er suchte einen Ort, zu weinen. Und er ging in das innere Gemach und weinte dort*.", footnotes: ["℘ Kap. 42,24"] },
      { number: 31, text: "Dann wusch er sein Gesicht und kam heraus, bezwang sich und sagte: Tragt das Essen auf!" },
      { number: 32, text: "Da trug man für ihn besonders auf und für sie besonders und für die Ägypter, die mit ihm aßen, besonders; denn die Ägypter können nicht mit den Hebräern essen, denn ein Gräuel ist das für Ägypter*.", footnotes: ["℘ Kap. 46,34"] },
      { number: 33, text: "Und sie saßen vor ihm, der Erstgeborene nach seiner Erstgeburt und der Jüngste nach seiner Jugend*. Da sahen die Männer einander staunend an.", footnotes: ["℘ Kap. 44,12"] },
      { number: 34, text: "Und er ließ ihnen von den Ehrengerichten vor ihm auftragen. Das Ehrengericht Benjamins aber war fünfmal größer als die Ehrengerichte von ihnen allen*. Und sie tranken mit ihm und berauschten sich.", footnotes: ["℘ Kap. 45,22; 1Sam 1,5"] },
    ]},
    { number: 44, verses: [
      { number: 1, text: "Dann befahl er dem, der über sein Haus war: Fülle die Säcke der Männer mit Nahrungsmitteln, so viel sie tragen können, und lege das Geld eines jeden oben in seinen Sack*!", heading: "Josefs harte Behandlung seiner Brüder", footnotes: ["w. in die Öffnung seines Sackes\n℘ Kap. 42,25"] },
      { number: 2, text: "Meinen Kelch aber, den silbernen Kelch, sollst du oben in den Sack des Jüngsten legen mit dem Geld für sein Getreide! Und er tat nach Josefs Wort, das er geredet hatte*.", footnotes: ["℘ Kap. 42,25"] },
      { number: 3, text: "Der Morgen wurde hell, da entließ man die Männer, sie und ihre Esel." },
      { number: 4, text: "Sie waren eben zur Stadt hinausgegangen und noch nicht weit gekommen, da sagte Josef zu dem, der über sein Haus war: Mache dich auf, jage den Männern nach, und hast du sie erreicht, so sage zu ihnen: Warum habt ihr Gutes mit Bösem vergolten?" },
      { number: 5, text: "Ist es nicht der, aus dem mein Herr trinkt und aus dem er zu wahrsagen pflegt? Ihr habt schlecht daran getan, dass ihr so gehandelt habt!" },
      { number: 6, text: "Und er erreichte sie und redete diese Worte zu ihnen." },
      { number: 7, text: "Da sagten sie zu ihm: Warum redet mein Herr solche Worte? Fern sei es von deinen Knechten, eine solche Sache zu tun!" },
      { number: 8, text: "Siehe, das Geld, das wir oben in unseren Säcken fanden, haben wir dir aus dem Land Kanaan zurückgebracht! Und wie sollten wir aus dem Haus deines Herrn Silber oder Gold stehlen?*", footnotes: ["℘ Kap. 43,21"] },
      { number: 9, text: "Derjenige von deinen Knechten, bei dem er gefunden wird, der soll sterben*; und dazu wollen wir meinem Herrn zu Knechten werden.", footnotes: ["℘ Kap. 31,32; Ps 7,4-6"] },
      { number: 10, text: "Da sagte er: Nun gut, nach euren Worten, so sei es: Bei wem er gefunden wird, der sei mein Knecht, ihr aber sollt schuldlos* sein.", footnotes: ["o. frei"] },
      { number: 11, text: "Darauf hoben sie schnell jeder seinen Sack auf die Erde herab und öffneten jeder seinen Sack." },
      { number: 12, text: "Und er durchsuchte: Beim Ältesten fing er an, und beim Jüngsten hörte er auf*. Und der Kelch fand sich im Sack Benjamins.", footnotes: ["℘ Kap. 43,33"] },
      { number: 13, text: "Da zerrissen sie ihre Kleider*, jeder belud seinen Esel, und sie kehrten in die Stadt zurück.", footnotes: ["℘ Kap. 37,29.34"] },
      { number: 14, text: "Und Juda und seine Brüder kamen in das Haus Josefs; und er war noch dort. Und sie fielen vor ihm nieder zur Erde*.", footnotes: ["℘ Kap. 37,7.9"] },
      { number: 15, text: "Josef sagte zu ihnen: Was ist das für eine Tat, die ihr getan habt! Wusstet ihr nicht, dass ein Mann wie ich wahrsagen kann?" },
      { number: 16, text: "Da sagte Juda: Was sollen wir meinem Herrn sagen?* Was sollen wir reden und wie uns rechtfertigen? Gott hat die Schuld deiner Knechte gefunden*; siehe, wir sind die Knechte meines Herrn, sowohl wir als auch der, in dessen Hand der Kelch gefunden worden ist.", footnotes: ["℘ Esr 9,10", "℘ Kap. 42,21; 4Mo 32,23; 1Kö 17,18; Lk 12,2"] },
      { number: 17, text: "Er aber sagte: Fern sei es von mir, so etwas zu tun! Der Mann, in dessen Hand der Kelch gefunden worden ist, der soll mein Knecht sein. Ihr aber zieht in Frieden hinauf zu eurem Vater." },
      { number: 18, text: "Da trat Juda zu ihm und sagte: Bitte, mein Herr, lass doch deinen Knecht ein Wort reden zu den Ohren meines Herrn, und es entbrenne nicht dein Zorn gegen deinen Knecht*, denn du bist dem Pharao gleich.", footnotes: ["℘ Kap. 18,30.32; 2Mo 32,22"] },
      { number: 19, text: "Mein Herr fragte seine Knechte: »Habt ihr noch einen Vater oder einen Bruder?«*", footnotes: ["℘ Kap. 43,7"] },
      { number: 20, text: "Und wir sagten zu meinem Herrn: »Wir haben einen alten Vater und einen kleinen Jungen, der ihm im Alter geboren wurde; dessen Bruder aber ist tot. So ist er allein von seiner Mutter übrig geblieben, und sein Vater liebt ihn*.«", footnotes: ["℘ Kap. 37,3"] },
      { number: 21, text: "Da sagtest du zu deinen Knechten: »Bringt ihn zu mir herab, dass ich mein Auge auf ihn richte*!«", footnotes: ["℘ Kap. 42,15.20.34"] },
      { number: 22, text: "Wir aber sagten zu meinem Herrn: »Der Junge kann seinen Vater nicht verlassen; verließe er seinen Vater, so würde der sterben.«" },
      { number: 23, text: "Da sprachst du zu deinen Knechten: »Wenn euer jüngster Bruder nicht mit euch herabkommt, dann sollt ihr mein Gesicht nicht mehr sehen*.«", footnotes: ["℘ Kap. 42,15.20.34"] },
      { number: 24, text: "Und es geschah, als wir hinaufgezogen waren zu deinem Knecht, meinem Vater, da berichteten wir ihm die Worte meines Herrn." },
      { number: 25, text: "Als nun unser Vater sagte: »Kehrt zurück, kauft uns ein wenig Nahrung!*«,", footnotes: ["℘ Kap. 43,2"] },
      { number: 26, text: "da sagten wir: »Wir können nicht hinabziehen. Wenn unser jüngster Bruder bei uns ist, dann ziehen wir hinab. Denn wir können das Gesicht des Mannes nicht sehen, ohne dass unser jüngster Bruder bei uns ist*.«", footnotes: ["℘ Kap. 42,15.20.34"] },
      { number: 27, text: "Da sagte dein Knecht, mein Vater, zu uns: »Ihr wisst*, dass meine Frau mir zwei geboren hat*.", footnotes: ["o. habt erkannt", "℘ Kap. 46,19"] },
      { number: 28, text: "Der eine ist von mir weggegangen, und ich sagte: Fürwahr, er ist wirklich zerrissen worden; und ich habe ihn bis jetzt nicht mehr wiedergesehen*.", footnotes: ["℘ Kap. 37,33"] },
      { number: 29, text: "Und nehmt ihr auch den von mir weg und es begegnet ihm ein Unfall*, dann bringt ihr mein graues Haar mit Unglück in den Scheol hinab*.«", footnotes: ["℘ Kap. 42,4.38", "℘ Kap. 37,35"] },
      { number: 30, text: "Und nun, wenn ich zu deinem Knecht, meinem Vater, käme und der Junge wäre nicht bei uns — hängt doch seine Seele an dessen Seele* —,", footnotes: ["w. und seine Seele ist angebunden (o. gefesselt) an dessen Seele\n℘ 1Sam 18,1"] },
      { number: 31, text: "dann würde es geschehen, dass er stirbt, wenn er sähe, dass der Junge nicht da ist. Dann hätten deine Knechte das graue Haar deines Knechtes, unseres Vaters, mit Kummer in den Scheol hinabgebracht*.", footnotes: ["℘ Kap. 37,35"] },
      { number: 32, text: "Denn dein Knecht ist für den Jungen Bürge geworden bei meinem Vater und hat gesagt: »Wenn ich ihn nicht zu dir bringe, will ich alle Tage vor meinem Vater schuldig sein*.«", footnotes: ["℘ Kap. 43,9"] },
      { number: 33, text: "Und nun, lass doch deinen Knecht anstelle des Jungen hier bleiben als Knecht meines Herrn, der Junge aber ziehe hinauf mit seinen Brüdern*!", footnotes: ["℘ 2Sam 24,17"] },
      { number: 34, text: "Denn wie könnte ich zu meinem Vater hinaufziehen, ohne dass der Junge bei mir ist? — Dass ich nicht das Unglück mit ansehen muss, das meinen Vater dann trifft*.", footnotes: ["℘ Est 8,6"] },
    ]},
    { number: 45, verses: [
      { number: 1, text: "Da konnte Josef sich nicht mehr bezwingen vor all denen, die um ihn her standen, und er rief: Lasst jedermann von mir hinausgehen! So stand niemand bei ihm, als Josef sich seinen Brüdern zu erkennen gab*.", heading: "Josef gibt sich seinen Brüdern zu erkennen", footnotes: ["℘ Kap. 42,24; Sach 12,10-14"] },
      { number: 2, text: "Und er erhob seine Stimme mit Weinen*, dass die Ägypter es hörten, und auch das Haus des Pharao hörte es.", footnotes: ["℘ Kap. 42,24; Sach 12,10-14"] },
      { number: 3, text: "Und Josef sagte zu seinen Brüdern: Ich bin Josef. Lebt mein Vater noch? Seine Brüder aber konnten ihm nicht antworten, denn sie waren bestürzt* vor ihm*.", footnotes: ["o. schraken zurück", "℘ Apg 7,13"] },
      { number: 4, text: "Da sagte Josef zu seinen Brüdern: Tretet doch zu mir heran! Und sie traten heran. Und er sagte: Ich bin Josef, euer Bruder, den ihr nach Ägypten verkauft habt*.", footnotes: ["℘ Kap. 37,28"] },
      { number: 5, text: "Und nun seid nicht bekümmert*, und werdet nicht zornig auf euch selbst*, dass ihr mich hierher verkauft habt! Denn zur Erhaltung des Lebens hat Gott mich vor euch hergesandt*.", footnotes: ["℘ Kap. 50,19.21; 2Kor 2,7", "w. es werde nicht heiß in euren Augen", "℘ Kap. 50,20; Est 4,14; Ps 105,17"] },
      { number: 6, text: "Denn schon zwei Jahre ist die Hungersnot im Land, und es dauert noch fünf Jahre, dass es kein Pflügen und Ernten gibt." },
      { number: 7, text: "Doch Gott hat mich vor euch hergesandt, um euch einen Rest zu setzen auf Erden und euch am Leben zu erhalten für eine große Rettung*.", footnotes: ["℘ Kap. 47,12"] },
      { number: 8, text: "Und nun, nicht ihr habt mich hierhergesandt, sondern Gott; und er hat mich zum Vater des Pharao gemacht* und zum Herrn seines ganzen Hauses und zum Herrscher über das ganze Land Ägypten*.", footnotes: ["℘ Ri 17,10; Jes 22,21", "℘ V. 26; Kap. 41,41.43"] },
      { number: 9, text: "Eilt und zieht hinauf zu meinem Vater, und sagt zu ihm: »So spricht dein Sohn Josef: Gott hat mich zum Herrn von ganz Ägypten gemacht. Komm zu mir herab, zögere nicht!" },
      { number: 10, text: "Du sollst im Land Goschen wohnen* und nahe bei mir sein, du und deine Söhne und die Söhne deiner Söhne, deine Schafe und deine Rinder und alles, was du hast.", footnotes: ["℘ Kap. 46,28.34; 47,1.6.27"] },
      { number: 11, text: "Und ich will dich dort versorgen* — denn noch fünf Jahre dauert die Hungersnot —, dass du nicht verarmst, du und dein Haus und alles, was du hast*.«", footnotes: ["℘ Kap. 50,21; Est 10,3", "℘ Kap. 47,12"] },
      { number: 12, text: "Und siehe, eure Augen und die Augen meines Bruders Benjamin sehen es, dass mein Mund es ist, der zu euch redet*.", footnotes: ["℘ Kap. 42,23; Lk 24,39; 1Jo 1,1.2"] },
      { number: 13, text: "Und berichtet meinem Vater alle meine Herrlichkeit in Ägypten und alles, was ihr gesehen habt; und eilt und bringt meinen Vater hierher herab!" },
      { number: 14, text: "Und er fiel seinem Bruder Benjamin um den Hals und weinte; und Benjamin weinte an seinem Hals*.", footnotes: ["℘ Kap. 33,4"] },
      { number: 15, text: "Und herzlich küsste er alle seine Brüder und weinte an ihnen. Danach redeten seine Brüder mit ihm." },
      { number: 16, text: "Und das Gerücht wurde im Haus des Pharao gehört, dass man sagte: Josefs Brüder sind gekommen. Und es war gut in den Augen des Pharao und in den Augen seiner Diener*.", footnotes: ["℘ Kap. 41,37; Apg 7,13"] },
      { number: 17, text: "Und der Pharao sprach zu Josef: Sage deinen Brüdern: »Tut dies: Beladet eure Tiere, und zieht hin, geht ins Land Kanaan," },
      { number: 18, text: "und nehmt euren Vater und eure Familien*, und kommt zu mir! Ich will euch das Beste des Landes Ägypten geben*, und ihr sollt das Fett des Landes essen*.«", footnotes: ["w. Häuser", "℘ Kap. 47,6; Apg 7,14", "℘ Kap. 27,28"] },
      { number: 19, text: "Du aber hast den Befehl zu sagen: »Tut dies: Nehmt euch aus dem Land Ägypten Wagen für eure Kinder und für eure Frauen, und holt euren Vater und kommt!*", footnotes: ["℘ Kap. 46,5"] },
      { number: 20, text: "Und seid nicht betrübt wegen eures Hausrates*, denn das Beste des ganzen Landes Ägypten soll euch gehören*.«", footnotes: ["w. euer Auge soll nicht fließen wegen eurer Geräte", "℘ Kap. 47,6; Apg 7,14"] },
      { number: 21, text: "Da taten die Söhne Israels so. Und Josef gab ihnen auf den Befehl des Pharao Wagen und gab ihnen Wegzehrung mit auf den Weg." },
      { number: 22, text: "Er gab ihnen allen, einem jeden, Wechselkleider, aber Benjamin gab er dreihundert Silberschekel und fünf Wechselkleider*.", footnotes: ["℘ Kap. 43,34; Ri 14,12"] },
      { number: 23, text: "Ebenso sandte er seinem Vater zehn Esel, beladen mit dem Besten Ägyptens, und zehn Eselinnen, beladen mit Getreide und Brot und Nahrung für seinen Vater auf den Weg." },
      { number: 24, text: "Und er entließ seine Brüder, und sie zogen hin, und er sagte zu ihnen: Ereifert euch nicht* auf dem Weg!", footnotes: ["o. Habt keine Angst"] },
      { number: 25, text: "So zogen sie aus Ägypten hinauf und kamen ins Land Kanaan zu ihrem Vater Jakob*.", footnotes: ["℘ Kap. 42,29"] },
      { number: 26, text: "Und sie berichteten ihm*: Josef lebt noch, ja, er ist Herrscher über das ganze Land Ägypten*. Aber sein Herz blieb kalt, denn er glaubte ihnen nicht*.", footnotes: ["℘ Kap. 42,29", "℘ V. 8", "℘ Lk 24,11"] },
      { number: 27, text: "Da redeten sie zu ihm alle Worte Josefs, die er zu ihnen geredet hatte. Und als er die Wagen sah, die Josef gesandt hatte, um ihn zu holen, da lebte der Geist ihres Vaters Jakob auf*.", footnotes: ["℘ Spr 25,25"] },
      { number: 28, text: "Und Israel sprach: Genug! Mein Sohn Josef lebt noch! Ich will hinziehen und ihn sehen, bevor ich sterbe*.", footnotes: ["℘ Kap. 46,30"] },
    ]},
    { number: 46, verses: [
      { number: 1, text: "Und Israel brach auf und alles, was er hatte, und kam nach Beerscheba*; und er opferte dem Gott seines Vaters Isaak Schlachtopfer.", heading: "Jakobs Ausreise nach Ägypten", footnotes: ["℘ Kap. 21,31; 1Sam 8,2"] },
      { number: 2, text: "Und Gott sprach zu Israel in einer nächtlichen Erscheinung* und sagte: Jakob! Jakob! Und er sagte: Hier bin ich*.", footnotes: ["w. in Erscheinungen der Nacht (im Hebr. Mehrzahl mit Einzahlbedeutung)\n℘ Kap. 15,1; 20,3; Ri 7,2; Sach 1,8", "℘ Kap. 22,1"] },
      { number: 3, text: "Und er sprach: Ich bin Gott, der Gott deines Vaters*. Fürchte dich nicht, nach Ägypten hinabzuziehen, denn zu einer großen Nation will ich dich dort machen*!", footnotes: ["℘ Kap. 28,13", "℘ Kap. 12,2; 47,27; 2Mo 1,7.9"] },
      { number: 4, text: "Ich selbst ziehe mit dir nach Ägypten hinab, und ich, ich führe dich auch wieder herauf*. Und Josef wird seine Hand auf deine Augen legen*.", footnotes: ["℘ Kap. 28,15; 50,13.24", "d. h. vielleicht: ihm nach seinem Tod die Augen schließen"] },
      { number: 5, text: "Da machte sich Jakob von Beerscheba auf, und die Söhne Israels hoben ihren Vater Jakob und ihre Kinder und ihre Frauen auf die Wagen, die der Pharao gesandt hatte, um ihn zu holen*.", footnotes: ["℘ Kap. 45,19.21; Apg 7,14.15"] },
      { number: 6, text: "Und sie nahmen ihr Vieh und ihre Habe, die sie im Land Kanaan erworben hatten, und kamen nach Ägypten, Jakob und all seine Nachkommenschaft mit ihm*:", footnotes: ["℘ 4Mo 20,15; 5Mo 26,5; Jos 24,4; Ps 105,23; Jes 52,4"] },
      { number: 7, text: "seine Söhne und die Söhne seiner Söhne mit ihm, seine Töchter und die Töchter seiner Söhne, und seine ganze Nachkommenschaft brachte er mit sich nach Ägypten*.", footnotes: ["℘ 4Mo 20,15; 5Mo 26,5; Jos 24,4; Ps 105,23; Jes 52,4"] },
      { number: 8, text: "*Und dies sind die Namen der Söhne Israels, die nach Ägypten kamen, Jakob und seine Söhne: der Erstgeborene Jakobs: Ruben.", heading: "Jakobs Nachkommen", footnotes: ["℘ V. 8-25: Kap. 35,23-26"] },
      { number: 9, text: "Und die Söhne Rubens: Henoch und Pallu und Hezron und Karmi*.", footnotes: ["℘ 1Chr 5,3"] },
      { number: 10, text: "Und die Söhne Simeons: Jemuël und Jamin und Ohad und Jachin und Zohar und Schaul, der Sohn der Kanaaniterin*.", footnotes: ["℘ 1Chr 4,24.25"] },
      { number: 11, text: "Und die Söhne Levis: Gerschon, Kehat und Merari*.", footnotes: ["℘ 2Mo 6,14-16; 4Mo 3,17; 1Chr 6,1"] },
      { number: 12, text: "Und die Söhne Judas: Er und Onan und Schela und Perez* und Serach*; Er und Onan aber starben im Land Kanaan*. Und die Söhne des Perez waren Hezron und Hamul*.", footnotes: ["℘ 1Chr 4,1", "℘ 1Chr 9,4.6; Neh 11,24", "℘ Kap. 38,3-6.29.30", "℘ 4Mo 26,21; 1Chr 2,3-5"] },
      { number: 13, text: "Und die Söhne Issaschars: Tola und Puwa und Job* und Schimron*.", footnotes: ["SamPent u. LXX lesen mit 4Mo 26,24 und 1Chr 7,1: Jaschub", "℘ 1Chr 7,1"] },
      { number: 14, text: "Und die Söhne Sebulons: Sered und Elon und Jachleel." },
      { number: 15, text: "Das sind die Söhne der Lea, die sie dem Jakob in Paddan-Aram* geboren hatte, und seine Tochter Dina*. Die Zahl aller Seelen seiner Söhne und seiner Töchter betrug 33. —", footnotes: ["s. Anm. zu Kap. 25,20", "℘ Kap. 30,21"] },
      { number: 16, text: "Und die Söhne Gads: Zifjon und Haggi, Schuni und Ezbon, Eri und Arod und Areli." },
      { number: 17, text: "Und die Söhne Assers: Jimna und Jischwa und Jischwi und Beri und ihre Schwester Serach. Und die Söhne Berias: Heber und Malkiël*.", footnotes: ["℘ 1Chr 7,30.31"] },
      { number: 18, text: "Das sind die Söhne der Silpa, die Laban seiner Tochter Lea gegeben hatte*; und sie gebar diese dem Jakob*, sechzehn Seelen. —", footnotes: ["℘ Kap. 29,24", "℘ Kap. 30,9-13"] },
      { number: 19, text: "Die Söhne der Rahel, der Frau Jakobs: Josef und Benjamin*.", footnotes: ["℘ Kap. 44,27"] },
      { number: 20, text: "Und dem Josef wurden im Land Ägypten Manasse und Ephraim geboren, die ihm Asenat gebar, die Tochter Potiferas, des Priesters von On*.", footnotes: ["℘ Kap. 41,45.50-52"] },
      { number: 21, text: "Und die Söhne Benjamins: Bela und Becher und Aschbel, Gera und Naaman, Ehi und Rosch, Muppim und Huppim und Ard*.", footnotes: ["℘ 1Chr 7,6; 8,1"] },
      { number: 22, text: "Das sind die Söhne der Rahel, die Jakob geboren wurden, zusammen vierzehn Seelen*. —", footnotes: ["℘ Kap. 44,27"] },
      { number: 23, text: "Und die Söhne Dans: Schuham*.", footnotes: ["Diese Namensschreibung richtet sich nach 4Mo 26,42; Mas. T.: Huschim"] },
      { number: 24, text: "Und die Söhne Naftalis: Jachzeel und Guni und Jezer und Schillem*.", footnotes: ["℘ 1Chr 7,13"] },
      { number: 25, text: "Das sind die Söhne der Bilha, die Laban seiner Tochter Rahel gegeben hatte*; und sie gebar diese dem Jakob*, insgesamt sieben Seelen. —", footnotes: ["℘ Kap. 29,29", "℘ Kap. 30,4-8"] },
      { number: 26, text: "Alle dem Jakob angehörigen Seelen, die nach Ägypten kamen, die aus seinem Schoß hervorgegangen waren*, ausgenommen die Frauen der Söhne Jakobs, alle Seelen waren 66*.", footnotes: ["d. h. die von ihm abstammten", "℘ 2Mo 1,1.5; 5Mo 10,22; Apg 7,14"] },
      { number: 27, text: "Und die Söhne Josefs, die ihm in Ägypten geboren wurden, waren zwei Seelen. Alle Seelen des Hauses Jakob, die nach Ägypten kamen, waren siebzig*.", footnotes: ["LXX fügt entsprechend 4Mo 26,29.35f in V. 20 noch einen Sohn und einen Enkel von Manasse und zwei Söhne und einen Enkel von Ephraim hinzu — insgesamt fünf Personen, so dass die Familie Jakobs 75 Seelen umfasste.\n℘ 2Mo 1,1.5; 5Mo 10,22; Apg 7,14"] },
      { number: 28, text: "Und er sandte Juda vor sich her zu Josef, dass er vor ihm her Weisung gebe nach Goschen*. Und sie kamen in das Land Goschen.", heading: "Jakobs Wiedersehen mit Josef", footnotes: ["d. h. vielleicht: den Weg nach Goschen weise; SamPent und die syr. Üs. lesen: dass er . . . in Goschen erscheine\n℘ Kap. 45,10"] },
      { number: 29, text: "Da spannte Josef seinen Wagen an und zog hinauf, seinem Vater Israel entgegen nach Goschen; und als er vor ihm erschien, fiel er ihm um den Hals und weinte lange* an seinem Hals*.", footnotes: ["o. ununterbrochen", "℘ Kap. 33,4"] },
      { number: 30, text: "Und Israel sagte zu Josef: Nun kann ich sterben, nachdem ich dein Gesicht gesehen habe, dass du noch lebst*!", footnotes: ["℘ Kap. 45,28; Lk 2,29.30"] },
      { number: 31, text: "Und Josef sagte zu seinen Brüdern und zum Haus seines Vaters: Ich will hinaufziehen und dem Pharao berichten und zu ihm sagen: »Meine Brüder und das Haus meines Vaters, die im Land Kanaan waren, sind zu mir gekommen*.", footnotes: ["℘ Kap. 47,1"] },
      { number: 32, text: "Und die Männer sind Schafhirten — denn sie haben Viehzucht getrieben —, und sie haben ihre Schafe und ihre Rinder und alles, was sie haben, mitgebracht.«" },
      { number: 33, text: "Und geschieht es, dass der Pharao euch ruft und spricht: »Was ist eure Tätigkeit*?« —", footnotes: ["℘ Kap. 47,3"] },
      { number: 34, text: "dann sagt: »Deine Knechte haben Viehzucht getrieben von unserer Jugend an bis jetzt, sowohl wir als auch unsere Väter«*, damit ihr im Land Goschen bleiben könnt*; denn alle Schafhirten sind den Ägyptern ein Gräuel*.", footnotes: ["℘ Kap. 30,35; 34,5; 37,12", "℘ Kap. 45,10", "℘ Kap. 43,32; 2Mo 8,22"] },
    ]},
    { number: 47, verses: [
      { number: 1, text: "Und Josef kam und berichtete dem Pharao und sagte: Mein Vater und meine Brüder, ihre Schafe und ihre Rinder und alles, was sie haben, sind aus dem Land Kanaan gekommen*; und siehe, sie sind im Land Goschen*.", heading: "Jakob und seine Söhne vor Pharao", footnotes: ["℘ Kap. 46,31", "℘ Kap. 45,10"] },
      { number: 2, text: "Und er nahm aus der Gesamtheit seiner Brüder fünf Männer und stellte sie vor den Pharao." },
      { number: 3, text: "Und der Pharao sprach zu seinen Brüdern: Was ist eure Tätigkeit? Und sie sagten zum Pharao: Deine Knechte sind Schafhirten, sowohl wir als auch unsere Väter*.", footnotes: ["℘ Kap. 46,33.34"] },
      { number: 4, text: "Und sie sagten zum Pharao: Wir sind gekommen, um uns im Land als Fremde aufzuhalten; denn es gibt keine Weide für die Schafe, die deine Knechte haben, denn die Hungersnot ist schwer im Land Kanaan. Und nun lass doch deine Knechte im Land Goschen wohnen!*", footnotes: ["℘ Kap. 45,10"] },
      { number: 5, text: "Da sagte der Pharao zu Josef: Dein Vater und deine Brüder sind zu dir gekommen." },
      { number: 6, text: "Das Land Ägypten ist vor dir: Lass deinen Vater und deine Brüder im besten Teil des Landes wohnen*; sie sollen im Land Goschen wohnen*. Und wenn du erkennst, dass tüchtige Männer unter ihnen sind, setze sie als Oberhirten* ein über das, was ich habe!", footnotes: ["℘ Kap. 45,18.20", "℘ Kap. 45,10", "w. Oberste des Viehs"] },
      { number: 7, text: "Und Josef brachte seinen Vater Jakob und ließ ihn vor den Pharao treten. Und Jakob segnete* den Pharao*.", footnotes: ["℘ Kap. 14,19; Jos 14,13", "o. grüßte den Pharao; o. dankte dem Pharao"] },
      { number: 8, text: "Und der Pharao sprach zu Jakob: Wie viele sind die Tage deiner Lebensjahre?" },
      { number: 9, text: "Und Jakob sprach zum Pharao: Die Tage der Jahre meiner Fremdlingschaft* sind 130 Jahre*; wenig* und böse waren die Tage meiner Lebensjahre, und sie erreichen nicht die Tage der Lebensjahre meiner Väter in den Tagen ihrer Fremdlingschaft*.", footnotes: ["℘ Hebr 11,13", "℘ V. 28", "℘ Hi 14,1; Jak 4,14", "℘ 1Chr 29,15; Ps 39,13"] },
      { number: 10, text: "Und Jakob segnete* den Pharao* und ging von dem Pharao hinaus.", footnotes: ["℘ Kap. 14,19; Jos 14,13", "o. grüßte den Pharao; o. dankte dem Pharao"] },
      { number: 11, text: "Josef aber wies seinem Vater und seinen Brüdern Wohnsitze an und gab ihnen Grundbesitz im Land Ägypten, im besten Teil des Landes, im Land Ramses*, wie der Pharao befohlen hatte.", footnotes: ["℘ 2Mo 1,11; 12,37; 4Mo 33,3"] },
      { number: 12, text: "Und Josef versorgte seinen Vater und seine Brüder und das ganze Haus seines Vaters mit Brot nach der Zahl der Kinder*.", footnotes: ["℘ Kap. 45,10.11; Jes 22,24"] },
      { number: 13, text: "Und es gab kein Brot im ganzen Land, denn die Hungersnot war sehr schwer; und das Land Ägypten und das Land Kanaan verschmachteten vor Hunger*.", heading: "Josefs Verwaltung des Landes Ägypten", footnotes: ["℘ Kap. 41,30"] },
      { number: 14, text: "Und Josef brachte alles Geld zusammen, das sich im Land Ägypten und im Land Kanaan vorfand, für das Getreide, das man kaufte*. Und Josef brachte das Geld in das Haus des Pharao.", footnotes: ["℘ Kap. 41,56; Spr 11,26"] },
      { number: 15, text: "Und als das Geld im Land Ägypten und im Land Kanaan ausging, da kamen alle Ägypter zu Josef und sagten: Bring uns Brot her! Warum sollen wir denn vor dir sterben? Denn das Geld ist zu Ende." },
      { number: 16, text: "Da sagte Josef: Bringt euer Vieh her! Dann gebe ich euch Brot für euer Vieh, wenn das Geld zu Ende ist." },
      { number: 17, text: "Da brachten sie ihr Vieh zu Josef, und Josef gab ihnen Brot für die Pferde und für die Schafherden und für die Rinderherden und für die Esel; und so versorgte er sie* mit Brot für all ihr Vieh in jenem Jahr.", footnotes: ["w. so geleitete er sie sorglich"] },
      { number: 18, text: "Als jenes Jahr zu Ende war, da kamen sie im zweiten Jahr zu ihm und sagten zu ihm: Wir wollen es meinem Herrn nicht verschweigen, dass das Geld ausgegangen ist, und die Viehherden sind* bei meinem Herrn. Nichts ist vor meinem Herrn übrig geblieben als nur unser Leib und unser Land.", footnotes: ["o. der Besitz an Vieh ist"] },
      { number: 19, text: "Warum sollen wir vor deinen Augen sterben, sowohl wir als auch unser Land? Kaufe uns und unser Land für Brot, dann wollen wir und unser Land dem Pharao fronpflichtig sein; und gib Samen, dass wir leben und nicht sterben und das Land nicht verödet daliegt!*", footnotes: ["℘ Kap. 41,36; Neh 5,2; Hi 2,4"] },
      { number: 20, text: "Da kaufte Josef das ganze Land Ägypten für den Pharao; denn die Ägypter verkauften jeder sein Feld, weil die Hungersnot schwer auf ihnen lag. Und so kam das Land an den Pharao." },
      { number: 21, text: "Und das Volk, das versetzte er in die verschiedenen Städte*, von einem Ende der Grenze Ägyptens bis zu ihrem anderen Ende.", footnotes: ["w. je nach den Städten. — SamPent und LXX lesen: Und das Volk machte er ihm dienstbar, zu Sklaven"] },
      { number: 22, text: "Nur das Land der Priester kaufte er nicht, denn die Priester hatten ein festgesetztes Einkommen* vom Pharao, und sie lebten von ihrem festgesetzten Einkommen*, das der Pharao ihnen gab; deshalb verkauften sie ihr Land nicht*.", footnotes: ["w. die Priester hatten eine Ordnung", "w. aßen ihre Ordnung", "℘ Esr 7,24"] },
      { number: 23, text: "Und Josef sagte zum Volk: Siehe, ich habe euch und euer Land heute für den Pharao gekauft. Da habt ihr Samen! Besät nun das Land!" },
      { number: 24, text: "Und es soll beim Ernten geschehen, dass ihr* den Fünften dem Pharao gebt*; die vier Teile aber sollen für euch sein zum Besäen des Feldes und zur Nahrung für euch und für die, die in euren Häusern sind, und zur Nahrung für eure Kinder.", footnotes: ["w. bei den Erträgen geschehen . . .; andere lesen mit Veränderung eines Buchstabens: Aber es soll geschehen, dass ihr von den Erträgen", "℘ Kap. 14,20; 28,22; 41,34; 3Mo 27,30; 4Mo 18,21-32; 5Mo 14,22; 26,12"] },
      { number: 25, text: "Da sagten sie: Du hast uns am Leben erhalten; finden wir Gunst in den Augen meines Herrn, dann wollen wir Knechte des Pharao sein*.", footnotes: ["℘ Kap. 32,6"] },
      { number: 26, text: "Und Josef legte es dem Land Ägypten bis zu diesem Tag als Ordnung auf, dass dem Pharao der Fünfte gehöre*. Nur das Land der Priester allein kam nicht an den Pharao*.", footnotes: ["℘ Esr 7,24", "℘ Esr 7,24"] },
      { number: 27, text: "Und Israel wohnte im Land Ägypten, im Land Goschen; und sie machten sich darin ansässig und waren fruchtbar und vermehrten sich sehr*.", heading: "Jakobs Anweisung für sein Begräbnis", footnotes: ["℘ Kap. 46,3"] },
      { number: 28, text: "Und Jakob lebte im Lande Ägypten siebzehn Jahre; und die Tage Jakobs, die Jahre seines Lebens, betrugen 147 Jahre*.", footnotes: ["℘ V. 9; Kap. 25,7"] },
      { number: 29, text: "Und als die Tage Israels nahten, dass er sterben sollte*, rief er seinen Sohn Josef und sprach zu ihm: Wenn ich nun Gunst gefunden habe in deinen Augen, dann lege doch deine Hand unter meine Hüfte* und erweise Gnade und Treue an mir*: Begrabe mich doch nicht in Ägypten!", footnotes: ["℘ Kap. 48,21; 50,24; 5Mo 31,14; Jos 23,14; 1Kö 2,1", "o. meinen Schenkel\n℘ Kap. 24,2; 50,5.25", "℘ Jos 2,14"] },
      { number: 30, text: "Wenn ich mich zu meinen Vätern gelegt habe, dann führe mich aus Ägypten und begrabe mich in ihrem Grab*! Und er sprach: Ich werde tun nach deinem Wort.", footnotes: ["℘ Kap. 25,9.10"] },
      { number: 31, text: "Er aber sagte: Schwöre mir! Da schwor er ihm*. Und Israel neigte sich anbetend nieder am Kopfende des Bettes*.", footnotes: ["℘ Kap. 24,2; 50,5.25", "LXX: betete an über seinem Stab\n℘ 1Kö 1,47; Hebr 11,21"] },
    ]},
    { number: 48, verses: [
      { number: 1, text: "Und es geschah nach diesen Dingen, dass man dem Josef sagte: Siehe, dein Vater ist krank*. Da nahm er seine beiden Söhne, Manasse und Ephraim*, mit sich.", heading: "Jakobs Segen über seine Enkel Ephraim und Manasse", footnotes: ["℘ 2Kö 13,14", "℘ Kap. 46,20"] },
      { number: 2, text: "Und man berichtete dem Jakob und sagte: Siehe, dein Sohn Josef kommt zu dir. Da machte Israel sich stark und setzte sich im Bett auf." },
      { number: 3, text: "Und Jakob sagte zu Josef: Gott, der Allmächtige*, erschien mir in Lus im Land Kanaan, und er segnete mich*", footnotes: ["hebr. el schaddaj\n℘ Kap. 17,1", "℘ Kap. 28,13.19; 35,6.9"] },
      { number: 4, text: "und sprach zu mir: »Siehe, ich will dich fruchtbar machen und dich vermehren, und ich will dich zu einer Schar von Völkern machen und dieses Land deiner Nachkommenschaft nach dir zum ewigen Besitz geben*.«", footnotes: ["℘ Kap. 17,6.8; Hes 37,25"] },
      { number: 5, text: "Und nun, deine beiden Söhne, die dir im Land Ägypten geboren wurden, bevor ich zu dir nach Ägypten kam, sollen mir gehören; Ephraim und Manasse sollen mir gehören wie Ruben und Simeon*.", footnotes: ["℘ Kap. 41,50-52; 4Mo 1,32-35; Jos 14,4; Ps 77,16; Hes 47,13"] },
      { number: 6, text: "Aber deine Kinder*, die du nach ihnen gezeugt hast, sollen dir gehören. Nach dem Namen ihrer Brüder sollen sie genannt werden in ihrem Erbteil.", footnotes: ["o. deine Verwandtschaft"] },
      { number: 7, text: "Denn ich — als ich aus Paddan* kam, starb Rahel bei mir im Land Kanaan, auf dem Weg, als es noch eine Strecke Landes war, um nach Efrata zu kommen; und ich begrub sie dort am Weg nach Efrata, das ist Bethlehem*.", footnotes: ["s. Anm. zu Kap. 25,20", "℘ Kap. 35,19"] },
      { number: 8, text: "Als Israel die Söhne Josefs sah, sagte er: Wer sind diese?" },
      { number: 9, text: "Und Josef sagte zu seinem Vater: Das sind meine Söhne, die Gott mir hier gegeben hat*. Da sagte er: Bring sie doch zu mir her, dass ich sie segne!*", footnotes: ["℘ Kap. 33,5", "℘ Kap. 27,4"] },
      { number: 10, text: "Die Augen Israels aber waren schwer vor Alter, er konnte nicht sehen. Und als er sie zu ihm gebracht hatte, küsste er sie und umarmte sie*.", footnotes: ["℘ Kap. 27,1"] },
      { number: 11, text: "Und Israel sprach zu Josef: Ich hatte nicht gedacht, dein Gesicht noch einmal zu sehen*; und siehe, Gott hat mich sogar deine Nachkommen sehen lassen*!", footnotes: ["℘ Kap. 37,33.35; 45,26", "℘ Ps 128,6"] },
      { number: 12, text: "Und Josef nahm sie von seinen Knien weg und beugte sich auf sein Gesicht zur Erde nieder." },
      { number: 13, text: "Und Josef nahm sie beide, Ephraim mit seiner Rechten zur Linken Israels und Manasse mit seiner Linken zur Rechten Israels, und brachte sie zu ihm." },
      { number: 14, text: "Da streckte Israel seine Rechte aus und legte sie auf Ephraims Kopf — obwohl er der Jüngere war — und seine Linke auf Manasses Kopf; er legte seine Hände über Kreuz. Denn Manasse war der Erstgeborene." },
      { number: 15, text: "Und er segnete Josef* und sprach: Der Gott, vor dessen Angesicht meine Väter, Abraham und Isaak, gelebt haben*, der Gott, der mich geweidet hat, seitdem ich bin, bis zu diesem Tag*,", footnotes: ["℘ Kap. 27,27; 49,22-26", "w. gegangen, umhergezogen sind\n℘ Kap. 24,40", "℘ Kap. 35,3"] },
      { number: 16, text: "der Engel*, der mich von allem Übel erlöst hat*, segne die Knaben; und in ihnen werde mein Name genannt und der Name meiner Väter, Abraham und Isaak, und sie sollen sich vermehren zu einer Menge mitten im Land*!*", footnotes: ["℘ Kap. 22,15; Jes 63,9", "℘ 2Sam 4,9; 1Kö 1,29; Ps 34,8", "o. auf der Erde", "℘ 4Mo 26,34.37"] },
      { number: 17, text: "Und als Josef sah, dass sein Vater seine rechte Hand auf Ephraims Kopf legte, war es schlecht in seinen Augen; und er fasste die Hand seines Vaters, um sie von Ephraims Kopf wegzuwenden auf Manasses Kopf." },
      { number: 18, text: "Und Josef sagte zu seinem Vater: Nicht so, mein Vater! Denn dieser ist der Erstgeborene. Lege deine Rechte auf seinen Kopf!" },
      { number: 19, text: "Aber sein Vater weigerte sich und sprach: Ich weiß es*, mein Sohn, ich weiß es*. Auch er wird zu einem Volk werden, und auch er wird groß sein. Jedoch wird sein jüngerer Bruder größer sein als er*, und seine Nachkommenschaft wird eine Fülle von Nationen werden.", footnotes: ["o. habe es erkannt", "o. habe es erkannt", "℘ Kap. 25,23; 4Mo 1,33.35; 5Mo 33,17"] },
      { number: 20, text: "Und er segnete sie* an jenem Tag und sprach: Mit dir wird Israel segnen und sagen: Gott mache dich wie Ephraim und wie Manasse*! So setzte er Ephraim vor Manasse.", footnotes: ["℘ Hebr 11,21", "℘ Jos 17,14"] },
      { number: 21, text: "Und Israel sprach zu Josef: Siehe, ich sterbe*; aber Gott wird mit euch sein und euch in das Land eurer Väter zurückbringen*.", footnotes: ["℘ Kap. 47,29", "℘ Kap. 15,14.16"] },
      { number: 22, text: "Und ich gebe dir einen Bergrücken über deine Brüder hinaus, den ich aus der Hand der Amoriter mit meinem Schwert und mit meinem Bogen genommen habe*.", footnotes: ["℘ Jos 24,32"] },
    ]},
    { number: 49, verses: [
      { number: 1, text: "Und Jakob rief seine Söhne und sprach: Versammelt euch, und ich will euch verkünden, was euch begegnen wird in künftigen Tagen*.", heading: "Jakobs Segen über seine Söhne — Sein Tod", footnotes: ["o. am Ende der Tage\n℘ 4Mo 24,14; Dan 10,14"] },
      { number: 2, text: "Kommt zusammen und hört, ihr Söhne Jakobs, und hört auf Israel, euren Vater!*", footnotes: ["℘ Ps 34,12; Spr 4,1; Jes 48,14"] },
      { number: 3, text: "*Ruben, mein Erstgeborener bist du, meine Stärke und der Erstling meiner Kraft! Vorrang an Hoheit und Vorrang an Macht!*", footnotes: ["℘ V. 3-27: Kap. 35,23-26; vgl. 5Mo 33,6-25", "℘ 5Mo 21,17"] },
      { number: 4, text: "Du bist übergewallt* wie das Wasser, du sollst keinen Vorrang haben, denn du hast das Lager deines Vaters bestiegen*; da hast du es entweiht. Mein Bett hat er bestiegen!", footnotes: ["w. ein Überwallen", "℘ Kap. 35,22"] },
      { number: 5, text: "Die Brüder Simeon und Levi, Werkzeuge der Gewalttat sind ihre Waffen*.", footnotes: ["o. Ratschläge; nach anderen: Beschneidungsmesser\n℘ Kap. 34,25-29"] },
      { number: 6, text: "Meine Seele komme nicht in ihren geheimen Rat, meine Ehre* vereinige sich nicht mit ihrer Versammlung! Denn in ihrem Zorn erschlugen sie den Mann, in ihrem Mutwillen lähmten sie den Stier.", footnotes: ["LXX: meine Leber; was auch so viel wie »meine Seele« o. »mein Herz« bedeuten kann"] },
      { number: 7, text: "Verflucht sei ihr Zorn, weil er so gewalttätig*, und ihr Grimm, weil er so grausam ist! Ich werde sie verteilen in Jakob und sie zerstreuen in Israel*.", footnotes: ["℘ Spr 29,22", "℘ 4Mo 35,8; Jos 19,1.9; 21,3.8.41"] },
      { number: 8, text: "Juda, du, dich werden deine Brüder preisen*! Deine Hand wird auf dem Nacken deiner Feinde sein*. Vor dir werden sich niederbeugen die Söhne deines Vaters*.", footnotes: ["s. Anm. zu Kap. 29,35", "℘ Ri 1,2", "℘ 1Chr 5,2"] },
      { number: 9, text: "Juda ist ein junger Löwe; vom Raub, mein Sohn, bist du hochgekommen. Er kauert, er lagert sich wie ein Löwe* und wie eine Löwin. Wer will ihn aufreizen*?", footnotes: ["℘ Offb 5,5", "℘ 4Mo 24,9"] },
      { number: 10, text: "Nicht weicht das Zepter von Juda* noch der Herrscherstab zwischen seinen Füßen weg, bis dass der Schilo kommt*, dem gehört der Gehorsam der Völker*.", footnotes: ["℘ 4Mo 24,17.19; 2Sam 7,16; 1Chr 12,24.39; Ps 60,9; 78,68; Jes 55,3; Jer 33,26; Hebr 7,14", "d. i. der Herrscherstab; die aram. und syr. Üs. lesen: bis dass der kommt, dem er (der Stab) gehört; andere üs. mit geringfügiger Änderung: bis sein Herrscher kommt\n℘ Hes 21,32", "℘ Jes 42,4; Mi 5,1"] },
      { number: 11, text: "An den Weinstock bindet er sein Eselsfüllen, an die Edelrebe das Junge seiner Eselin; er wäscht im Wein sein Kleid und im Blut der Trauben sein Gewand*;", footnotes: ["℘ Jes 63,1-3; Joe 4,13-17; Offb 14,17-20"] },
      { number: 12, text: "die Augen sind dunkel* von Wein und weiß die Zähne von Milch*.", footnotes: ["LXX: seine Augen funkeln", "o. die Augen sind dunkler als Wein, und weißer die Zähne als Milch"] },
      { number: 13, text: "Sebulon wohnt an der Küste der Meere, und an der Küste der Schiffe liegt er, seine Seite nach Sidon hin." },
      { number: 14, text: "Issaschar ist ein knochiger Esel, der sich lagert zwischen den Hürden*.", footnotes: ["o. der zwischen den beiden Sattelkörben liegt"] },
      { number: 15, text: "Und als er sah, dass die Ruhe* gut und dass das Land lieblich war, da beugte er seine Schulter zum Lasttragen und wurde zum fronpflichtigen Knecht.", footnotes: ["o. der Ruheplatz"] },
      { number: 16, text: "Dan richtet* sein Volk wie einer der Stämme Israels*.", footnotes: ["s. Anm. zu Kap. 30,6", "℘ Ri 13,2; 15,20"] },
      { number: 17, text: "Dan ist eine Schlange am Weg, eine Hornotter am Pfad, die in die Fersen des Pferdes beißt, und rücklings fällt sein Reiter." },
      { number: 18, text: "Auf deine Rettung, HERR, harre ich!*", footnotes: ["℘ Ps 25,5; 119,166; Jes 25,9; Hos 12,7"] },
      { number: 19, text: "Gad*, Räuberscharen bedrängen ihn, und er, er drängt ihnen nach auf der Ferse*.", footnotes: ["Gad klingt im Hebr. auch an das Wort für »bedrängen« an.", "℘ 1Chr 12,9"] },
      { number: 20, text: "Von Asser: Fettes ist sein Brot; und er, königliche Leckerbissen gibt er." },
      { number: 21, text: "Naftali ist eine flüchtige* Hirschkuh; er gibt schöne Worte*.", footnotes: ["w. losgelassene", "Andere lesen mit Einfügung eines Buchstabens: Naftali ist eine flüchtige Hirschkuh, die schöne Kälber wirft."] },
      { number: 22, text: "Ein junger Fruchtbaum ist Josef*, ein junger Fruchtbaum an der Quelle; seine Zweige ranken über die Mauer*.", footnotes: ["℘ Kap. 41,52", "w. seine Töchter steigen auf über die Mauer\n℘ Hos 13,15"] },
      { number: 23, text: "Und es reizen ihn die Bogenschützen* und schießen und feinden ihn an;", footnotes: ["w. die Herren der Pfeile"] },
      { number: 24, text: "aber sein Bogen bleibt fest*, und gelenkig sind die Arme* seiner Hände, durch die Hände des Mächtigen Jakobs*, von dort, dem Hirten, dem Stein Israels,", footnotes: ["℘ Hi 29,20", "o. ist die Kraft", "℘ Jos 17,18; Ri 1,22; Ps 132,2"] },
      { number: 25, text: "von dem Gott deines Vaters — der helfe dir — und von Gott, dem Allmächtigen* — der segne dich mit Segnungen des Himmels droben, mit Segnungen der Tiefe*, die unten liegt, mit Segnungen der Brüste und des Mutterleibes.", footnotes: ["so mit SamPent, LXX und der syr. Üs.; Mas. T.: der helfe dir und dem Allmächtigen", "o. der Flut; dasselbe Wort wie Kap. 1,2 »Tiefe«"] },
      { number: 26, text: "Die Segnungen deines Vaters überragen die Segnungen der uralten Berge*, das begehrenswerte Gut der ewigen Hügel. Sie seien auf dem Haupt Josefs und auf dem Scheitel des Abgesonderten* unter seinen Brüdern.", footnotes: ["Die Üs. folgt LXX, die hier wohl den besseren Text bewahrt hat. Mas. T.: die Segnungen meiner Erzeuger der Urzeit", "o. des Geweihten; o. des Fürsten; hebr. nasir; die syr. Üs. liest: auf die Krone seiner Brüder"] },
      { number: 27, text: "Benjamin ist ein Wolf, der zerreißt*; am Morgen verzehrt er Raub, und am Abend verteilt er Beute.", footnotes: ["℘ Ri 20,21.25"] },
      { number: 28, text: "Alle diese sind die zwölf Stämme Israels, und das ist es, was ihr Vater zu ihnen redete. Und er segnete sie, jeden nach seinem Segen, mit dem er sie segnete*.", footnotes: ["℘ 5Mo 33,1"] },
      { number: 29, text: "Und er befahl ihnen und sagte zu ihnen: Bin ich versammelt zu meinem Volk*, dann begrabt mich bei meinen Vätern in der Höhle, die auf dem Feld des Hetiters Efron liegt*;", footnotes: ["d. h. zu seinen Vorfahren", "℘ Kap. 25,9.10"] },
      { number: 30, text: "in der Höhle, die auf dem Feld Machpela gegenüber von Mamre ist, im Land Kanaan, auf dem Feld, das Abraham von dem Hetiter Efron zum Erbbegräbnis gekauft hat*.", footnotes: ["℘ Kap. 23,17-20"] },
      { number: 31, text: "Dort haben sie Abraham begraben und seine Frau Sara*; dort haben sie Isaak begraben* und seine Frau Rebekka; und dort habe ich Lea begraben.", footnotes: ["℘ Kap. 25,9.10", "℘ Kap. 35,29"] },
      { number: 32, text: "Das Feld und die Höhle, die darauf ist, sind Besitz, gekauft von den Söhnen* Het*.", footnotes: ["w. Kaufbesitz vonseiten der Söhne", "℘ Kap. 23,17-20"] },
      { number: 33, text: "Und als Jakob damit geendet hatte, seinen Söhnen Befehle zu geben, zog er seine Füße aufs Bett herauf und verschied* und wurde zu seinen Völkern versammelt*.", footnotes: ["℘ 2Kö 13,14.20", "℘ Kap. 25,8.17; Apg 7,15"] },
    ]},
    { number: 50, verses: [
      { number: 1, text: "Da fiel Josef auf das Angesicht seines Vaters und weinte über ihm* und küsste ihn.", heading: "Jakobs Begräbnis in Hebron", footnotes: ["℘ Kap. 23,2; 2Kö 13,14"] },
      { number: 2, text: "Und Josef befahl seinen Dienern, den Ärzten, seinen Vater einzubalsamieren. Und die Ärzte balsamierten Israel ein*.", footnotes: ["℘ 2Chr 16,14"] },
      { number: 3, text: "Darüber wurden vierzig Tage für ihn voll, denn so lange währt die Zeit* des Einbalsamierens. Und die Ägypter beweinten ihn siebzig Tage*.", footnotes: ["w. so werden voll die Tage", "℘ 4Mo 20,29; 5Mo 34,8"] },
      { number: 4, text: "Und als die Tage, da man ihn beweinte, vorüber waren, redete Josef zum Haus des Pharao und sagte: Wenn ich doch Gunst gefunden habe in euren Augen, so redet doch vor den Ohren des Pharao und sagt:" },
      { number: 5, text: "Mein Vater hat mich schwören lassen und gesagt: Siehe, ich sterbe. In meinem Grab, das ich mir im Land Kanaan gegraben* habe, dort begrabe mich!* Und nun, lass mich doch hinaufziehen, dass ich meinen Vater begrabe und zurückkomme!", footnotes: ["o. gekauft; wie 5Mo 2,6", "℘ Kap. 47,29-31"] },
      { number: 6, text: "Da sagte der Pharao: Zieh hinauf und begrabe deinen Vater, wie er dich hat schwören lassen!" },
      { number: 7, text: "So zog Josef hinauf, um seinen Vater zu begraben; und mit ihm zogen hinauf alle Diener des Pharao, die Ältesten seines Hauses und alle Ältesten des Landes Ägypten" },
      { number: 8, text: "und das ganze Haus Josefs und seine Brüder und das Haus seines Vaters. Nur ihre Kinder und ihre Schafe und ihre Rinder ließen sie im Land Goschen zurück." },
      { number: 9, text: "Sogar Wagen und Reiter zogen mit ihm hinauf, und es wurde ein ganz gewaltiges Heerlager." },
      { number: 10, text: "Und sie kamen nach Goren-Atad*, das jenseits des Jordan liegt. Dort hielten sie eine sehr große und schwere Totenklage; und er veranstaltete für seinen Vater eine Trauerfeier von sieben Tagen*.", footnotes: ["d. h. Dornstrauch-Tenne", "℘ 1Sam 31,13; Hi 2,13; Apg 8,2"] },
      { number: 11, text: "Als aber die Bewohner des Landes, die Kanaaniter, die Trauerfeier bei Goren-Atad* sahen, sagten sie: Eine schwere Trauerfeier ist das für Ägypten; daher gab man ihr den Namen Abel-Mizrajim*, sie liegt* jenseits des Jordan.", footnotes: ["d. h. Dornstrauch-Tenne", "d. h. Bach Ägyptens; LXX: Trauerfeier Ägyptens", "SamPent und die syr. Üs. lesen: darum gab man ihm (dem Ort) den Namen . . ., er liegt"] },
      { number: 12, text: "Und seine Söhne taten mit ihm so, wie er ihnen befohlen hatte*;", footnotes: ["℘ Kap. 49,29"] },
      { number: 13, text: "und seine Söhne brachten ihn in das Land Kanaan* und begruben ihn in der Höhle des Feldes Machpela, des Feldes, das Abraham zum Erbbegräbnis gekauft hatte von dem Hetiter Efron, angesichts von Mamre*.", footnotes: ["℘ Kap. 46,4", "℘ Kap. 23,17.18; 25,8.9; Apg 7,16"] },
      { number: 14, text: "Dann kehrte Josef nach Ägypten zurück, nachdem er seinen Vater begraben hatte, er und seine Brüder und alle, die mit ihm hinaufgezogen waren, um seinen Vater zu begraben." },
      { number: 15, text: "Und als Josefs Brüder sahen, dass ihr Vater gestorben war, sagten sie: Wenn nun Josef uns anfeindet und uns gar all das Böse vergilt, das wir ihm angetan haben*!", heading: "Josefs brüderliche Haltung — Sein Tod", footnotes: ["℘ Kap. 27,41"] },
      { number: 16, text: "So entboten sie dem Josef und ließen sagen: Dein Vater hat vor seinem Tod befohlen und gesagt:" },
      { number: 17, text: "»So sollt ihr zu Josef sagen: Ach, vergib doch das Verbrechen deiner Brüder und ihre Sünde, dass sie dir Böses angetan haben!« Und nun vergib doch das Verbrechen der Knechte des Gottes deines Vaters! Da weinte Josef, als sie zu ihm redeten." },
      { number: 18, text: "Und auch seine Brüder gingen und fielen vor ihm nieder und sagten: Siehe, da hast du uns als Knechte*.", footnotes: ["℘ Kap. 37,7.9"] },
      { number: 19, text: "Josef aber sagte zu ihnen: Fürchtet euch nicht*! Bin ich etwa an Gottes Stelle*?", footnotes: ["℘ Kap. 45,5", "℘ Kap. 30,2; 2Kö 5,7"] },
      { number: 20, text: "Ihr zwar, ihr hattet Böses gegen mich beabsichtigt*; Gott aber hatte beabsichtigt, es zum Guten zu wenden, damit er tue, wie es an diesem Tag ist, ein großes Volk am Leben zu erhalten*.", footnotes: ["℘ Kap. 37,18", "℘ Kap. 45,5-8"] },
      { number: 21, text: "Und nun, fürchtet euch nicht*! Ich werde euch und eure Kinder versorgen*. So tröstete er sie und redete zu ihrem Herzen*.", footnotes: ["℘ Kap. 45,5", "℘ Kap. 45,11; 47,12; 1Thes 5,15", "℘ Kap. 34,3; 2Chr 30,22"] },
      { number: 22, text: "Und Josef blieb in Ägypten*, er und das Haus seines Vaters; und Josef lebte 110 Jahre.", footnotes: ["℘ 2Mo 1,5"] },
      { number: 23, text: "Und Josef sah von Ephraim Söhne der dritten Generation*; auch die Söhne Machirs, des Sohnes Manasses*, wurden auf die Knie Josefs geboren*.", footnotes: ["℘ Hi 42,16", "℘ 1Chr 7,14-17", "℘ Kap. 30,3; Jos 17,1; Spr 17,6"] },
      { number: 24, text: "Und Josef sagte zu seinen Brüdern: Ich sterbe* nun; Gott aber wird euch heimsuchen* und euch aus diesem Land hinaufführen in das Land*, das er Abraham, Isaak und Jakob zugeschworen hat*.", footnotes: ["℘ Kap. 47,29", "℘ 2Mo 4,31", "℘ Kap. 15,14; 46,4; 2Mo 12,41", "℘ Kap. 12,7; 2Mo 33,1"] },
      { number: 25, text: "Und Josef ließ die Söhne Israels schwören* und sprach: Hat Gott euch dann heimgesucht*, dann führt meine Gebeine von hier hinauf!*", footnotes: ["℘ Kap. 47,30.31", "℘ Rt 1,6", "℘ 2Mo 13,19; Jos 24,32; Hebr 11,22"] },
      { number: 26, text: "Und Josef starb*, 110 Jahre alt*; und sie balsamierten ihn ein, und man legte ihn in einen Sarg in Ägypten.", footnotes: ["℘ 2Mo 1,6", "℘ Kap. 25,7; Jos 24,29"] },
    ]},
  ]
};
